/* ÇEVİRİ pt · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("pt","olay",{
"OLAYLAR:1299-01:0":{"b": ["Fundação do beylik otomano", "9f0b7c0a"], "d": ["O início de uma ação independente de Osman Gazi, da tribo Kayı, na região de Söğüt-Domaniç é tradicionalmente considerado o começo da fundação do Estado otomano; alguns historiadores tomam a vitória de Bapheus, em 1302, como o verdadeiro ponto de viragem. Graças à sua posição na fronteira bizantina, o beylik reuniu rapidamente força através de incursões de gaza. Neste ambiente de dissolução da herança seljúcida, Osman Gazi congregou à sua volta ahis, gazis e turcomanos nómadas; o vínculo que estabeleceu com o xeique Edebali é considerado o fundamento da legitimidade espiritual do beylik. Outros lugares incorporados na mesma data: İnegöl, Yarhisar.", "9d689d45"]},
"OLAYLAR:1326-04-06:0":{"b": ["Conquista de Bursa", "98c727fa"], "d": ["Bursa, mantida sob bloqueio durante anos, rendeu-se a Orhan Gazi, que conduzia a fase final do cerco; a cidade foi feita a primeira grande capital do beylik. Conta-se que a notícia da conquista foi levada a Osman Gazi no leito de morte; por sua vontade testamentária, Osman Gazi foi sepultado em Bursa. A cidade foi rapidamente dotada de mesquitas, imarets e madraças, tornando-se o modelo do urbanismo otomano primitivo.", "9ede6ee9"]},
"OLAYLAR:1331-03-02:0":{"b": ["Conquista de İznik", "a846a811"], "d": ["İznik (Niceia), um dos mais importantes centros de Bizâncio na Anatólia, perdeu a esperança de resistir após a vitória de Pelekanon, em 1329, e rendeu-se a Orhan Gazi. A primeira madraça otomana foi aqui fundada e sábios como Dâvûd-i Kayserî começaram a lecionar; a cidade tornou-se o centro do saber do período inicial. A igreja de Santa Sofia foi convertida em mesquita, apresentando um exemplo precoce da tradição da conquista.", "8fd3bfb5"]},
"OLAYLAR:1337-01-01:0":{"b": ["Conquista de İzmit", "06a35035"], "d": ["Com a queda de İzmit (Nicomédia), a última fortaleza importante de Bizâncio na margem anatólica passou também para a administração otomana; toda a península de Kocaeli, até à margem oposta de Constantinopla, tornou-se território otomano. Assim, o beylik, senhor de toda a costa sul e leste do Mármara, preparou a infraestrutura da passagem para a Rumélia.", "f677745c"]},
"OLAYLAR:1352-03-01:0":{"b": ["Fortaleza de Çimpe — passagem para a Rumélia", "c2f0a07d"], "d": ["Süleyman Paşa, filho de Orhan Gazi, tinha feito em 1352 da fortaleza de Çimpe, que lhe fora entregue durante a guerra civil bizantina, a sua base; as fortalezas esvaziadas após o grande terramoto que arrasou Galípoli em março de 1354 foram rapidamente fortificadas, transformando a península numa cabeça de ponte otomana permanente. Este passo, apoiado pelo povoamento de população turcomana trazida da Anatólia, é o início da presença dos otomanos no continente europeu, que duraria mais de 550 anos.", "4857333a"]},
"OLAYLAR:1361-05-05:0":{"b": ["Conquista de Edirne", "2f54ebb0"], "d": ["A tomada de Edirne (Adrianópolis), cidade-chave da Trácia, determinou a base principal e a direção das conquistas balcânicas; a data da conquista é discutida nas fontes, entre 1361 e 1369. A cidade foi pouco depois feita capital, proclamando que o centro de gravidade do Estado se deslocara para a Rumélia; permaneceu capital cerca de 90 anos, até à conquista de Constantinopla.", "25bd644f"]},
"OLAYLAR:1362-03:0":{"b": ["Murad I sobe ao trono", "f8d48a26"], "d": ["Murad I (Hüdavendigâr), que subiu ao trono com a morte de Orhan Gazi, levou o Estado, durante o seu reinado de 27 anos, de um beylik de fronteira ao esqueleto de um império. Com o sistema do pençik lançou-se a base do Corpo dos Janízaros, difundiu-se a ordem do timar, criou-se o Beylerbeylik da Rumélia e reforçou-se a instituição do vizirato. As conquistas nos Balcãs tornaram-se, no seu tempo, uma política de Estado sistemática.", "d463078a"]},
"OLAYLAR:1389-06-15:0":{"b": ["I Batalha do Kosovo — martírio de Murad I", "10b8ddc9"], "d": ["A aliança balcânica liderada pelo knez Lazar foi decisivamente derrotada na planície do Kosovo; a Sérvia passou à suserania otomana. Murad I, que percorria o campo de batalha, foi apunhalado pelo nobre sérvio Miloš Obilić e morreu mártir — é o único sultão otomano morto em campo de batalha. No acampamento, Yıldırım Bayezid foi feito suceder-lhe; o seu irmão Yakub Çelebi foi estrangulado, o que foi um dos primeiros exemplos conhecidos da prática do fratricídio.", "153449fe"]},
"OLAYLAR:1396-09-25:0":{"b": ["Vitória de Niğbolu", "75716e96"], "d": ["O grande exército cruzado, reunido por apelo do rei húngaro Sigismundo e no qual participaram também cavaleiros franco-borgonheses, foi gravemente derrotado por Yıldırım Bayezid diante de Niğbolu, nas margens do Danúbio. A vitória consolidou o domínio otomano sobre a Bulgária; durante uma geração não foi possível organizar na Europa uma grande cruzada.", "0d06e36c"]},
"OLAYLAR:1402-07-28:0":{"b": ["Batalha de Ancara — começou o Fetret Devri", "b4a99d96"], "d": ["Na pesada derrota sofrida na planície de Çubuk diante do exército de Tamerlão, Yıldırım Bayezid foi feito prisioneiro e morreu no cativeiro poucos meses depois. Tamerlão fez reviver os beyliks da Anatólia; o território otomano foi repartido entre os filhos de Bayezid e começou uma luta pelo trono de 11 anos (Fetret Devri). Esta época, a mais grave crise vivida pelo Estado desde a sua fundação, gravou na memória otomana a importância da estrutura centralizada. Outros povoamentos perdidos na mesma data: Datça, Marmaris, Fethiye (Makri), Söke, Kütahya, Afyon, Isparta, Manisa, Aydın, Denizli, Muğla, Antalya, Konya, Karaman, Kayseri, Kastamonu, Bartın, Safranbolu, Samsun, Sivas, Malatya, Beyşehir, Sivrihisar, Kırşehir, Çorum, Çankırı, Yenişehir (Bursa), İnegöl, Fortaleza de Aydos, Geyve, Köprühisar (Yenişehir), Marmaracık, Akhisar (Pamukova), Mekece, Kestel, Ulubat, Harmankaya, Akyazı, Ilha de İmralı, Kandıra, Mudanya, Yalova, Karamürsel, Armutlu, Gemlik (Kios), Söğüt, Bilecik, Eskişehir, Bursa, İznik, İzmit, Balıkesir, Çanakkale, Bergama, Amasya, Tokat, Çorlu, Lüleburgaz, Malkara, Keşan, İpsala, Kilitbahir, Çirmen, Eski Zağra (Stara Zagora), Tatarpazarcığı, İhtiman, Köstendil, Petriç, Nevrokop (Gotse Delçev), Drama, Gelibolu, Çimpe, Edirne, Dimetoka, Kırklareli, Tekirdağ, Filibe, Sofya, Niş, Vidin, Tırnova, Varna, Şumnu, Silistre, Niğbolu, Rusçuk, Selanik, Serez, Kavala, Üsküp, Manastır, Ohri, Yenişehir (Larissa), Tırhala, İzdin (Lamia), Plevne, Gümülcine, Biga, Domaniç, Kulacahisar, Karacahisar, Yarhisar, Dimbos, Kite (Kete), Lefke (Osmaneli), Leblebicihisar, Karaçepüş, Karatigin, Absu (Hypsu), Adranos (Orhaneli), Pelekanon (Eskihisar), Gebze, Hereke, Samandıra, Kirmasti (M.Kemalpaşa), Mihaliç (Karacabey), Köstence, Gölyazı (Apollonia).", "d34e55d5"]},
"OLAYLAR:1413-07:0":{"b": ["Çelebi Mehmed restabeleceu a unidade", "03413dfd"], "d": ["No último ajuste de contas entre os irmãos, Mehmed I, que derrotou Mûsâ Çelebi em Çamurlu, reuniu o território do país sob uma única administração; por isso é considerado o 'segundo fundador do Estado'. Durante o seu reinado, a estrutura desgastada do Estado foi reparada, as relações com os beyliks da Anatólia foram equilibradas e seguiu-se na Rumélia uma política de paz prudente.", "d8f535c2"]},
"OLAYLAR:1416-05-01:0":{"b": ["Revolta do xeique Bedreddin", "e0a072ca"], "d": ["O movimento religioso-social que se desenvolveu em torno do xeique Bedreddin, grande jurisconsulto e místico que exercera o cargo de cadiasquer durante o Fetret Devri, irrompeu em simultâneo com as revoltas de Börklüce Mustafa em Karaburun e de Torlak Kemal em Manisa. As revoltas foram reprimidas com sangue; Bedreddin, capturado em Deliorman, foi executado em Serez. O acontecimento deixou profunda marca na literatura e na historiografia como a mais antiga grande revolta social e mahdista da história otomana.", "1cf72ec4"]},
"OLAYLAR:1444-11-10:0":{"b": ["Vitória de Varna", "f739eedc"], "d": ["O exército cruzado húngaro-polaco, que descera para sul rompendo o tratado de Szeged, foi aniquilado em Varna por Murad II, que regressara à frente do exército depois de ter abdicado; o jovem rei Ladislau III morreu no campo de batalha. A vitória eliminou a última grande hipótese de intervenção externa destinada a liquidar a presença otomana nos Balcãs e assegurou o caminho para a conquista de Constantinopla.", "43adf0fb"]},
"OLAYLAR:1448-10-17:0":{"b": ["II Batalha do Kosovo", "ebe0b662"], "d": ["O exército de János Hunyadi, que queria vingar Varna, foi decisivamente derrotado por Murad II numa árdua batalha de três dias. Foi a última grande batalha campal que os cruzados travaram nos Balcãs contra os otomanos; com a vitória, o domínio otomano a sul do Danúbio ficou assente de forma irreversível.", "ea3ae23b"]},
"OLAYLAR:1453-05-29:0":{"b": ["Conquista de Constantinopla", "583d5e3e"], "d": ["Após um cerco de cinquenta e quatro dias (6 de abril–29 de maio de 1453), na manhã de 29 de maio o exército otomano transpôs as muralhas e entrou na cidade; o último imperador, Constantino XI, morreu nos combates e o Império Romano do Oriente, com 1100 anos de história, desapareceu. O jovem sultão tomou o título de 'Fâtih' (o Conquistador), fez da cidade a capital e converteu Santa Sofia em mesquita; a cidade foi rapidamente revivificada com povoamento e obras. A fundição de canhões gigantescos, o transporte de navios por terra e a disposição do cerco diante das muralhas são considerados o auge da engenharia militar da época. Na historiografia europeia, a conquista é uma das datas simbólicas do fim da Idade Média.", "3664c5fe"]},
"OLAYLAR:1461-08-15:0":{"b": ["Conquista de Trebizonda", "15f52403"], "d": ["No termo da difícil campanha do mar Negro, conduzida por Maomé II em simultâneo por terra e por mar, o Império Grego de Trebizonda rendeu-se; com a liquidação deste último vestígio do mundo bizantino na Anatólia, toda a costa sul do mar Negro passou ao domínio otomano. O fim da dinastia dos Comnenos reforçou a pretensão do Conquistador a 'soberano dos dois mares e das duas terras'. Outros lugares incorporados na mesma data: Giresun, Rize.", "ca6ead13"]},
"OLAYLAR:1473-01-01:0":{"b": ["Conquista definitiva de Silifke — quebra da última resistência dos Karamânidas", "d988bee4"], "d": ["A fortaleza de Silifke tinha-se rendido uma vez a Gedik Ahmed Paşa em 1472, mas no mesmo ano o Karamanoğlu Kasım Bey, com o auxílio da armada cruzada no Mediterrâneo, recuperara a fortaleza. Após a vitória de Otlukbeli, Maomé II encarregou o seu filho e Gedik Ahmed Paşa de se apoderarem definitivamente da região; com a ajuda dos antigos artilheiros otomanos, o paiol de pólvora foi incendiado e a fortaleza foi rapidamente derrubada. Assim se quebrou a última resistência dos Karamânidas nas montanhas de Taşeli-İçel; a liquidação do beylik seria concluída em 1474.", "e9814184"]},
"OLAYLAR:1473-08-11:0":{"b": ["Batalha de Otlukbeli", "42c7194e"], "d": ["Uzun Hasan, soberano dos Ak Koyunlu, que se tornara uma grande potência no Oriente e se aliara a Veneza, sofreu uma pesada derrota em Otlukbeli diante do exército de Maomé II, equipado com armas de fogo. A vitória consolidou a supremacia otomana na Anatólia; foi também uma prova precoce da superioridade de um exército central que usava canhões e espingardas sobre o exército clássico.", "9c59ac50"]},
"OLAYLAR:1475-06-06:0":{"b": ["Entrada da Crimeia sob a proteção otomana", "44e3f7c8"], "d": ["A armada sob o comando de Gedik Ahmed Paşa conquistou as cidades da costa sul da Crimeia, a começar por Kefe, que estava em poder de Génova; estas costas foram feitas diretamente sanjaco otomano. O Canato da Crimeia, por seu lado, com Mengli Giray, tornou-se um Estado vassalo privilegiado que reconhecia a suserania otomana, e foi durante três séculos a pedra angular da política setentrional; o mar Negro transformou-se de facto num mar interior otomano. Outros lugares incorporados na mesma data: Bahçesaray, Kerç, Azak.", "a3448d71"]},
"OLAYLAR:1481-05-03:0":{"b": ["Morte de Maomé II — caso do sultão Cem", "190ecf01"], "d": ["Com a morte súbita de Maomé II em campanha, subiu ao trono Bajazeto II; o seu irmão, o sultão Cem, reivindicando o sultanato, mandou fazer a hutba em seu nome em Bursa e cunhar moeda. Vencido, refugiou-se primeiro junto dos mamelucos, depois junto dos cavaleiros de Rodes; Cem, que nas mãos dos cavaleiros e do papado se converteu em trunfo de negociação da diplomacia europeia, morreu em Nápoles em 1495. Este caso forçou a política externa otomana a comportar-se com prudência durante quinze anos.", "7e488d7b"]},
"OLAYLAR:1514-08:0":{"b": ["Vitória de Çaldıran", "fea64ebb"], "d": ["Querendo resolver pela raiz a ameaça criada na Anatólia pela propaganda safávida, Yavuz Sultão Selim infligiu uma pesada derrota ao exército do xá Ismail na planície de Çaldıran, com superioridade de canhões e espingardas. Entrou-se em Tabriz; a Anatólia oriental e sudeste e a linha Mossul-Diyarbakır passaram à administração otomana. A adesão dos beys curdos ao Império Otomano, graças ao empenho de İdrîs-i Bitlisî, estabeleceu o quadro da fronteira oriental, que duraria séculos.", "67b03a64"]},
"OLAYLAR:1516-08-24:0":{"b": ["Vitória de Mercidabık", "07d254d3"], "d": ["O exército mameluco foi desbaratado em poucas horas em Mercidabık, a norte de Alepo; o idoso sultão Kansu Gavri morreu durante a batalha. Com a vitória, que abriu de par em par as portas de Alepo e de Damasco, a Síria, o Líbano e a Palestina passaram à administração otomana; abriu-se o caminho da campanha do Egito, que traria o fim do Estado mameluco.", "c4b15f39"]},
"OLAYLAR:1517-01-22:0":{"b": ["Ridaniye — conquista do Egito e califado", "caf378d6"], "d": ["O exército otomano, atravessando rapidamente o deserto do Sinai, rompeu em Ridaniye a linha de defesa de Tomanbay e entrou no Cairo; Tomanbay, que prosseguia a resistência, foi capturado e executado, e o Estado mameluco desapareceu. O Egito, o Hejaz e as cidades santas passaram à administração otomana; o califa abássida e as relíquias sagradas foram levados para Istambul. Com a passagem do califado à dinastia otomana, os sultões assumiram a pretensão à liderança do mundo islâmico; o controlo da Rota das Especiarias proporcionou também grandes rendimentos ao império. Outros lugares incorporados na mesma data: Akkâ, Maan, Sayda, Kerak.", "a0cc8fdc"]},
"OLAYLAR:1520-09-30:0":{"b": ["Solimão, o Legislador, sobe ao trono", "f6512269"], "d": ["O reinado de 46 anos de Solimão I, que subiu ao trono como único filho varão após a morte de Yavuz, é considerado o apogeu político, militar, jurídico e cultural do império. Os kanunnâmes que sistematizaram o direito consuetudinário valeram-lhe o título de 'Kanunî' (o Legislador); no Ocidente foi conhecido como 'o Magnífico' (Magnificent). As obras do arquiteto Sinan, a idade de ouro da literatura do divã e a supremacia da armada no Mediterrâneo são os símbolos desta época.", "cda7a2fb"]},
"OLAYLAR:1521-08-29:0":{"b": ["Conquista de Belgrado", "59ef5cec"], "d": ["Belgrado, que Maomé II não conseguira tomar em 1456 e que era considerada a 'chave da Europa Central', caiu, na primeira campanha do Legislador, com um cerco na confluência do Danúbio e do Sava. A linha de defesa meridional da Hungria ruiu; com esta conquista abriu-se a porta da campanha da Europa Central, que se estenderia até Mohács cinco anos depois e até à anexação de Buda vinte anos depois.", "69dbb7cc"]},
"OLAYLAR:1522-12-21:0":{"b": ["Conquista de Rodes", "807bbb1e"], "d": ["Rodes, base dos cavaleiros de São João, que ameaçavam as rotas marítimas do Mediterrâneo oriental e o itinerário da peregrinação, rendeu-se por capitulação após um sangrento cerco de meses; permitiu-se aos cavaleiros deixar livremente a ilha (instalaram-se depois em Malta). Garantiu-se a segurança das costas da Anatólia e a linha marítima Istambul-Egito passou ao controlo otomano ininterrupto.", "aeedfb16"]},
"OLAYLAR:1526-08-29:0":{"b": ["Batalha de Mohács", "f3418b0d"], "d": ["O exército húngaro foi destruído na planície de Mohács em cerca de duas horas, pelo fogo dos canhões e pela superioridade de manobra; o rei Luís II morreu num pântano quando fugia. Mohács, uma das grandes batalhas campais mais rapidamente ganhas da história otomana, pôs fim de facto ao reino independente da Hungria e abriu a era da rivalidade otomano-habsburga na Europa Central.", "48967894"]},
"OLAYLAR:1529-09:0":{"b": ["I Cerco de Viena", "dc49ea4f"], "d": ["Na campanha organizada contra a apropriação do trono húngaro pelos Habsburgos, o exército otomano sitiou Viena; devido ao abandono dos canhões pesados no caminho, ao inverno que chegou cedo e às dificuldades de abastecimento, o cerco foi levantado três semanas depois. Embora a cidade não tenha sido tomada, a influência otomana sobre a Hungria foi preservada; as imediações de Viena assinalaram o limite do alcance logístico do império na Europa Central.", "a49fc760"]},
"OLAYLAR:1534-12-04:0":{"b": ["Conquista de Bagdade — Campanha dos Dois Iraques", "897092c3"], "d": ["Na campanha organizada contra os 'dois Iraques' (Iraque árabe e Iraque persa), entrou-se primeiro em Tabriz e depois, sem combate, em Bagdade; a tomada da antiga capital dos abássidas valeu ao soberano otomano grande prestígio no mundo islâmico. O mausoléu do Imam Azam Abu Hanifa foi restaurado; com a incorporação de Bagdade e de Baçorá, o território otomano alcançou o golfo Pérsico. Outros lugares incorporados na mesma data: Kerkük, Kerbelâ.", "f3f80434"]},
"OLAYLAR:1538-09:0":{"b": ["Vitória naval de Preveza", "30dc0f97"], "d": ["A armada cruzada formada sob a direção do Papa, apesar de numericamente superior, foi dispersa ao largo de Preveza pela tática de Barbarossa, que utilizou com mestria o vento e a costa; Andrea Doria abandonou o campo de batalha. A vitória estabeleceu a indiscutível supremacia naval otomana no Mediterrâneo, que duraria cerca de 33 anos; é a data simbólica do dia da armada na tradição marítima turca. Outros lugares incorporados na mesma data: Aden, Bender.", "0411d92f"]},
"OLAYLAR:1541-08-29:0":{"b": ["Anexação de Buda — Hungria província otomana", "db53b244"], "d": ["O Legislador, que partiu em campanha por causa do cerco de Buda pelos Habsburgos, depois de salvar a cidade tomou a Hungria central sob administração otomana direta e criou o Beylerbeylik de Buda; a Transilvânia foi feita um principado autónomo vassalo dos otomanos. Esta ordem tripartida da Hungria durou cerca de 150 anos e constituiu o esqueleto da administração otomana duradoura na Europa Central.", "1eb63e33"]},
"OLAYLAR:1555-05-29:0":{"b": ["Paz de Amásia", "a5afe0d1"], "d": ["É o primeiro tratado de paz oficial que pôs fim às guerras otomano-safávidas, que duravam há anos. Bagdade e o Iraque ficaram com os otomanos, a fronteira da Anatólia oriental foi pela primeira vez reconhecida mutuamente; os safávidas comprometeram-se a pôr fim à propaganda xiita no território otomano e os otomanos a garantir a segurança da passagem dos peregrinos iranianos. O tratado foi o primeiro exemplo do quadro jurídico das relações entre os dois Estados.", "220b198f"]},
"OLAYLAR:1566-09-07:0":{"b": ["Szigetvár — morte do Legislador", "e2917ed2"], "d": ["O Legislador, com 72 anos, morreu na sua tenda poucas horas antes da queda da fortaleza de Szigetvár, que sitiava na sua décima terceira campanha; Sokullu Mehmed Paşa ocultou a morte durante semanas para que o exército não se dispersasse. A fortaleza foi tomada, mas o Estado perdera o seu sultão de mais longo reinado e mais esplêndido; subiu ao trono o seu filho Selim II e o peso dos grão-vizires na governação do Estado começou a aumentar.", "62c468a1"]},
"OLAYLAR:1571-08:0":{"b": ["Conquista de Chipre", "e364a2b3"], "d": ["Desembarcou-se em 1570 em Chipre, sob administração veneziana; Nicósia caiu rapidamente, ao passo que Famagusta só se rendeu em agosto de 1571, após um cerco de onze meses. A ilha, crítica para a segurança das rotas comerciais e de peregrinação do Mediterrâneo oriental, foi organizada como beylerbeylik e povoada com população vinda da Anatólia; a conquista foi também o pretexto da grande aliança cruzada que chegaria a Lepanto.", "6dcfdc0f"]},
"OLAYLAR:1571-10-07:0":{"b": ["Derrota de Lepanto", "6a1d44a9"], "d": ["A armada cruzada, unida por causa da conquista de Chipre, apanhou a armada otomana no golfo de Lepanto e destruiu a maior parte dela; o kapudan paxá Müezzinzâde Ali Paşa morreu mártir e só se salvou a frota de Uluç Ali. Após o desastre, o grão-vizir Sokullu Mehmed Paşa nomeou Uluç Ali Paşa kapudan paxá, encarregou-o de reunir a armada dispersa e iniciou a construção de uma nova armada em todos os estaleiros, de Istambul a Alanya; contudo, a supremacia absoluta no Mediterrâneo ficara psicologicamente abalada.", "4cb5c93e"]},
"OLAYLAR:1596-10-26:0":{"b": ["Batalha de Mezőkeresztes", "da308ec5"], "d": ["Na maior batalha campal da Longa Guerra (1593–1606), o exército, a cuja frente se encontrava pessoalmente Maomé III, recompôs-se, no momento em que estava prestes a dispersar-se, por exortação de Hoca Sâdeddin Efendi, e pôs em debandada o exército habsburgo. É considerada a última grande batalha campal clássica ganha pelos otomanos; porém, o facto de não ter alterado o curso geral da guerra foi tido também como sinal do desgaste do sistema militar.", "77f2a384"]},
"OLAYLAR:1606-11-11:0":{"b": ["Paz de Zsitvatorok", "39c01142"], "d": ["Com o tratado que pôs fim a uma guerra desgastante de treze anos, o soberano habsburgo foi pela primeira vez considerado igual ao sultão com o título de 'Imperador Romano' e o tributo anual foi abolido. A perda de território foi quase nula; mas esta mudança da linguagem diplomática é lida como símbolo do fim da pretensão otomana a uma supremacia absoluta face à Europa.", "99a455e7"]},
"OLAYLAR:1639-05-17:0":{"b": ["Tratado de Kasr-ı Şirin", "c1acf3af"], "d": ["O tratado assinado após a reconquista de Bagdade por Murad IV (1638) pôs fim a mais de cem anos de guerras otomano-safávidas. Bagdade e o Iraque ficaram definitivamente com os otomanos, Erevan foi deixada aos safávidas; a linha traçada, com pequenas alterações, foi a base da atual fronteira Turquia-Irão e é considerada uma das fronteiras mais duradouras do mundo. O tratado deixou aos otomanos Bedre, Cessân, Mendelî, Derteng e Derne; a Fortaleza de Zencir, na fronteira, seria demolida, ficando as aldeias a oeste com os otomanos e as do leste com o Irão. A zona em torno da Fortaleza de Zalim, perto de Şehrizor, e Kızılca Kale ficaram com os otomanos, Avroman e Mihriban com o Irão; as fortalezas de Kotur, Mâkû e Mağazberd seriam demolidas por ambas as partes.", "c2d59f3f"]},
"OLAYLAR:1669-09-06:0":{"b": ["Concluída a conquista de Creta", "e0d85604"], "d": ["O cerco de Candia, último ato da guerra de Creta iniciada em 1645, terminou com a resoluta campanha de três anos de Fâzıl Ahmed Paşa; o comandante veneziano Morosini entregou a cidade por tratado. A luta, que durou cerca de um quarto de século, ficou registada como o mais longo cerco da história otomana; a última grande fortaleza latina do Mediterrâneo oriental passou também à administração otomana. As três pequenas fortalezas rochosas da costa norte da ilha — Suda, Spinalonga e Granbosa — permaneceram ainda com Veneza; como estão edificadas em ilhéus separados, não podem ser mostradas no mapa separadas do resto de Creta.", "314efa97"]},
"OLAYLAR:1672-10-18:0":{"b": ["Tratado de Buczacz — as fronteiras mais vastas", "b17b6e5a"], "d": ["Com o Tratado de Buczacz, assinado após a conquista de Kamieniec na campanha da Polónia, a Podólia foi incorporada no Império Otomano e uma parte da Ucrânia foi posta sob proteção. O império alcançou assim as suas fronteiras mais vastas na Europa; este ponto é considerado o apogeu da era da expansão e, ao mesmo tempo, o seu último elo.", "6d489670"]},
"OLAYLAR:1683-09-12:0":{"b": ["Desastre do II Cerco de Viena", "7d889252"], "d": ["O cerco de Viena, de dois meses, conduzido por Kara Mustafa Paşa de Merzifon, transformou-se em derrota com o golpe súbito desferido pelo rei da Polónia Jan Sobieski a partir das colinas de Kahlenberg; o exército retirou-se abandonando as bagagens, e o de Merzifon foi executado em Belgrado. Com a Santa Aliança constituída após a vitória, a guerra durou 16 anos; este desastre é apontado como o momento inicial do grande declínio na história otomana.", "88ceb19f"]},
"OLAYLAR:1692-01-01:0":{"b": ["Conquista da Fortaleza de Granbosa — uma das fortalezas rochosas de Creta que permaneceram com Veneza", "3ddf9eeb"], "d": ["Embora a conquista de Creta se considere em grande parte concluída com a entrega de Candia em 1669, a ilha-fortaleza rochosa de Granbosa, na extremidade noroeste da ilha, permaneceu mais vinte e três anos em mãos venezianas. Com a sua captura em 1692, limpou-se um dos três resquícios venezianos em Creta; Suda e Spinalonga aguardariam a campanha da Moreia de 1715.", "05e94fe9"]},
"OLAYLAR:1699-01-26:0":{"b": ["Tratado de Karlowitz — primeira grande perda de território", "8f7e2546"], "d": ["Com Karlowitz, que pôs fim a dezasseis anos de guerras da Santa Aliança, a Hungria e a Transilvânia foram cedidas à Áustria, a Podólia à Polónia, a Moreia e as costas da Dalmácia a Veneza. Pela primeira vez na história otomana, território desta escala se perdia à mesa de negociações e de forma permanente; o tratado é considerado o documento inicial da nova era em que o império passou à defensiva face à Europa e é também um ponto de viragem na história da diplomacia otomana.", "54bb2eee"]},
"OLAYLAR:1711-07-19:0":{"b": ["Vitória do Prut", "2583572f"], "d": ["Na guerra surgida por causa da questão do rei sueco que se refugiara junto dos otomanos depois da derrota de Poltava, o exército do czar Pedro I foi cercado nas margens do Prut e foi forçado a render-se. Com o tratado assinado, Azov foi recuperada; o facto de o exército não ter sido aniquilado e de o czar ter sido libertado ficou na história como uma decisão discutida desde então até hoje.", "ce9c2996"]},
"OLAYLAR:1715-01-01:0":{"b": ["Conquista das fortalezas de Suda e Spinalonga — apagamento do último vestígio veneziano em Creta", "7261f7ba"], "d": ["Vinte e três anos após a queda de Granbosa em 1692, num ramo secundário da campanha da Moreia, foram também conquistadas as fortalezas de Suda e Spinalonga, os dois últimos pontos de apoio de Veneza em Creta. Assim, a conquista de Creta, iniciada em 1645, ficou completa, ao cabo de quarenta e seis anos, até ao último centímetro da ilha.", "d2044cae"]},
"OLAYLAR:1730-09-25:0":{"b": ["Revolta de Patrona Halil", "100941a4"], "d": ["O fracasso na frente persa, os impostos e a ira contra o luxo do círculo palaciano transformaram-se numa grande revolta sob a liderança de Patrona Halil, um banhista de hamam. O grão-vizir İbrahim Paşa foi morto, Ahmed III foi deposto e a Era das Tulipas terminou; o domínio dos revoltosos sobre a cidade durante meses mostrou de forma impressionante a fragilidade da autoridade central.", "d87eea77"]},
"OLAYLAR:1739-09-18:0":{"b": ["Tratado de Belgrado — recuperação de Belgrado, Smederevo e do norte da Sérvia", "ba7f8e46"], "d": ["No fim da guerra travada em duas frentes contra a Áustria e a Rússia (1736–1739), Belgrado e o norte da Sérvia foram recuperados; a Rússia aceitou desarmar Azov e não manter armada no mar Negro. O tratado, considerado o último grande êxito da diplomacia e do exército otomanos no século XVIII, proporcionou ao império um período de paz de um quarto de século.", "5b399dd2"]},
"OLAYLAR:1770-07-06:0":{"b": ["Ataque de Çeşme", "840b30bd"], "d": ["A armada russa, que penetrou no Mediterrâneo com o apoio dos ingleses, atacou com brulotes a armada otomana abrigada no porto de Çeşme e queimou-a quase por completo. A Rússia apareceu pela primeira vez no Mediterrâneo como grande potência naval; o desastre foi um dos golpes que decidiram o destino da guerra que conduziu a Küçük Kaynarca, em 1774, e evidenciou a necessidade de uma reforma radical da armada.", "5b133a56"]},
"OLAYLAR:1774-07-21:0":{"b": ["Tratado de Küçük Kaynarca", "2776dcdb"], "d": ["Com Küçük Kaynarca, que pôs fim à guerra de 1768–1774 e é tido como um dos tratados mais pesados da história otomana, foi concedida 'independência' ao Canato da Crimeia — criando-se de facto uma esfera de influência russa. A Rússia estabeleceu-se na costa do mar Negro, obteve para os navios mercantes o direito de passagem pelos Estreitos e uma embaixada permanente em Istambul; a cláusula ambígua de proteção sobre os súbditos ortodoxos entreabriu a porta aos pretextos de intervenção do século seguinte. Pela primeira vez, um território de população muçulmana era retirado ao domínio otomano.", "b677ebfc"]},
"OLAYLAR:1783-04-19:0":{"b": ["Anexação da Crimeia pela Rússia", "bdf6faa8"], "d": ["A Crimeia 'independente' criada por Küçük Kaynarca foi anexada à Rússia por manifesto de Catarina II, tomando-se como pretexto as perturbações do tempo do último cã, Şahin Giray. A parceria otomano-crimeana de três séculos terminou; a perda das estepes setentrionais eliminou a profundidade de defesa de Istambul e deu início à primeira grande vaga de emigração de dezenas de milhares de tártaros da Crimeia para território otomano.", "8d4fcb03"]},
"OLAYLAR:1789-04:0":{"b": ["Selim III e o Nizâm-ı Cedîd", "d53aec21"], "d": ["Selim III, que subiu ao trono em plena guerra, vendo que as derrotas eram estruturais, iniciou um amplo programa de reformas com o nome de 'Nizâm-ı Cedîd' (Nova Ordem): um novo exército instruído à europeia, um tesouro separado que o financiava (Îrâd-ı Cedîd), o reforço das mühendishanes e as primeiras embaixadas permanentes nas capitais europeias. O programa é considerado o início da tradição reformista turca moderna; contudo, seria derrubado em 1807 pela resistência dos corpos e dos âyans.", "87394990"]},
"OLAYLAR:1798-06-12:0":{"b": ["Liquidação dos cavaleiros de Malta — escala da armada francesa no caminho", "d62f901d"], "d": ["A armada francesa a caminho do Egito fez escala em Malta; os cavaleiros de São João (de Malta) entregaram a ilha sem grande resistência. Chegava assim ao fim o último baluarte da ordem de cavalaria que, expulsa de Rodes em 1522, aqui se instalara. Malta passaria dois anos depois para as mãos da Inglaterra, ao passo que Napoleão se dirigiria da ilha diretamente a Alexandria.", "aac1fe49"]},
"OLAYLAR:1798-07-01:0":{"b": ["Ocupação do Egito por Napoleão", "93fede5f"], "d": ["O exército do general Bonaparte desembarcou em Alexandria e ocupou o Egito; esta expedição, que visava o caminho da Inglaterra para a Índia, foi o primeiro ataque direto de uma potência europeia ao território central otomano. O ataque de Nelson em Abukir e a defesa de Acre por Cezzâr Ahmed Paşa quebraram a marcha francesa; a ocupação terminou em 1801, mas no vazio que deixou começou a ascensão de Mehmed Ali Paşa de Kavala e a era da 'Questão do Oriente'.", "b1ca7226"]},
"OLAYLAR:1808-10-07:0":{"b": ["Sened-i İttifak", "cce49ef5"], "d": ["Documento assinado entre o palácio e as poderosas famílias de âyans das províncias, sob a liderança de Alemdar Mustafa Paşa, âyan de Rusçuk que levou Mahmud II ao trono; os âyans comprometiam-se a prestar fidelidade ao sultão e apoio militar, ao passo que o Estado reconhecia a sua existência e os seus direitos. Por ser o primeiro exemplo, na história otomana, de uma limitação da autoridade do sultão por um documento, é tido por alguns historiadores como o remoto início da tradição constitucional; de facto, tornou-se ineficaz em poucos meses.", "2d97fdfe"]},
"OLAYLAR:1821-03-25:0":{"b": ["Começou a Revolta Grega", "a7293715"], "d": ["A insurreição preparada pela organização Filiki Eteria irrompeu primeiro na Valáquia e depois, com a sua força principal, na Moreia; o Estado, ocupado com o problema de Ali Paşa de Tepelena, tardou na primeira intervenção. Graças à intensa simpatia grega na opinião pública europeia (filo-helenismo), a revolta transformou-se rapidamente numa causa internacional; assim se acendeu o rastilho do primeiro movimento de independência bem-sucedido da era do nacionalismo em território otomano. Outros povoamentos perdidos na mesma data: Atenas, Balyabadra (Patras), İstefe (Tebas), Livadya.", "316e2ac7"]},
"OLAYLAR:1826-06-15:0":{"b": ["Vak'a-i Hayriyye — abolido o Corpo dos Janízaros", "08c9372a"], "d": ["Os janízaros, que se tinham rebelado contra os exercícios do recém-criado Corpo Eşkinci, foram aniquilados nos seus quartéis do Etmeydanı pelo fogo de canhão das tropas leais previamente preparadas por Mahmud II; o corpo foi dissolvido com todos os seus ramos e com os tekkes bektaxis a ele ligados. Esta operação, que passou à história com o nome de 'Acontecimento Auspicioso', liquidando uma instituição de quatro séculos, abriu caminho ao exército Asâkir-i Mansûre-i Muhammediyye e a todas as reformas de centralização seguintes.", "9ee152dd"]},
"OLAYLAR:1827-10-20:0":{"b": ["Ataque de Navarino", "ee579e7f"], "d": ["A armada otomano-egípcia, que reprimia a revolta grega, foi queimada em Navarino pela frota combinada anglo-franco-russa, que entrou no porto sem declaração de guerra; perderam-se cerca de sessenta navios e milhares de marinheiros. O ataque, liquidado na diplomacia europeia como 'acontecimento infeliz', garantiu de facto a independência grega e abriu o caminho à guerra otomano-russa de 1828–29.", "0d4b2c6f"]},
"OLAYLAR:1839-11-03:0":{"b": ["Édito de Tanzimat", "5042ce7b"], "d": ["Com o Hatt-ı Hümâyun lido em Gülhane, a segurança da vida, dos bens e da honra de todos os súbditos, sem distinção de religião, foi posta sob a garantia do Estado; foram proclamados os princípios da justiça nos impostos, da ordem no serviço militar e da não aplicação de penas sem julgamento. O édito, obra de Mustafa Reşid Paşa, é considerado o primeiro grande documento de caráter constitucional da modernização otomana e deu o nome à era de reformas, o 'Período do Tanzimat' (1839–1876); nesse quadro foi conduzida uma reestruturação radical da administração, do direito, da educação e das finanças.", "6ace4b82"]},
"OLAYLAR:1853-10-04:0":{"b": ["Começou a Guerra da Crimeia", "3b9ca3c8"], "d": ["A crise iniciada com a questão dos lugares santos e a pretensão russa de proteção sobre os súbditos ortodoxos transformou-se em conflito aberto com a declaração de guerra otomana; após o ataque de Sinope, a Inglaterra e a França (depois o Piemonte) entraram na guerra ao lado dos otomanos. A guerra, ganha com o desembarque dos exércitos aliados na Crimeia e a tomada de Sebastopol, terminou com o Tratado de Paris de 1856; contudo, o primeiro empréstimo externo contraído nos anos de guerra (1854) lançou o império numa espiral de dependência financeira que duraria meio século.", "bae16135"]},
"OLAYLAR:1856-02-18:0":{"b": ["Édito de Reforma", "78ff234d"], "d": ["O édito, proclamado antes das negociações de paz de Paris, ampliando os princípios do Tanzimat, concedeu aos súbditos não muçulmanos amplos direitos de igualdade, incluindo o funcionalismo público, o serviço militar e a abertura de escolas; as organizações comunitárias foram reordenadas. Com o Tratado de Paris assinado em seguida, o Estado otomano foi oficialmente admitido na família do direito internacional europeu e a sua integridade territorial foi posta sob a garantia comum das grandes potências — garantia que, na prática, seria uma nova porta para intervenções.", "cfe6d847"]},
"OLAYLAR:1876-12-23:0":{"b": ["Kanûn-ı Esâsî — I Período Constitucional", "0fe052c1"], "d": ["No dia da abertura da conferência internacional reunida em Istambul para discutir a crise balcânica, foi proclamada com salvas de canhão a primeira constituição otomana; com o Kanûn-ı Esâsî, obra do movimento dos 'Jovens Otomanos' sob a liderança de Midhat Paşa, foi instituído um parlamento de duas câmaras. O Meclis-i Meb'ûsan abriu em março de 1877; contudo, Abdulhamide II, invocando a Guerra de 93, suspendeu o parlamento por tempo indeterminado em fevereiro de 1878 e a constituição ficou suspensa durante trinta anos.", "c0f01a41"]},
"OLAYLAR:1877-04:0":{"b": ["Guerra de 93 (Guerra Otomano-Russa de 1877–78)", "5bd96af7"], "d": ["Na guerra, chamada 'Guerra de 93' por coincidir com o ano 1293 do calendário rûmî, os exércitos russos atacaram em duas frentes; embora a defesa de Plevna por Gazi Osman Paşa e as batalhas do Cáucaso de Ahmed Muhtar Paşa se tenham tornado lendárias, a frente ruiu e os russos avançaram até Yeşilköy (Santo Estêvão). A guerra desencadeou as grandes vagas de migração muçulmana dos Balcãs e do Cáucaso para Istambul, cujos efeitos se prolongam até hoje; a estrutura demográfica e financeira do império nunca mais voltou ao estado anterior.", "3a2b2296"]},
"OLAYLAR:1878-07-13:0":{"b": ["Tratado de Berlim", "47f76a49"], "d": ["O Congresso de Berlim, que reviu a 'Grande Bulgária' criada por Santo Estêvão em nome do equilíbrio das grandes potências, deixou ainda assim um quadro pesado: Sérvia, Montenegro e Roménia tornaram-se independentes; foi criado o Principado autónomo da Bulgária; a Bósnia-Herzegovina foi deixada à ocupação austríaca, Chipre à administração inglesa, Kars-Ardahan-Batum à Rússia. A ordem otomana de quinhentos anos na Rumélia desfez-se em grande parte; a 'questão do Oriente' tornou-se tema permanente da diplomacia europeia. Outros povoamentos perdidos na mesma data: Filibe, Vidin, Tırnova, Varna, Şumnu, Silistre, Rusçuk, Bükreş, Yaş, Köstence.", "076697b6"]},
"OLAYLAR:1881-05-12:0":{"b": ["Ocupação da Tunísia e Düyûn-ı Umûmiyye", "c7e25598"], "d": ["A França, tomando como pretexto os incidentes na fronteira com a Argélia, ocupou a Tunísia e colocou-a sob o seu protetorado com o Tratado de Bardo; a presença otomana no Norte de África ficou reduzida à Tripolitânia. Com o Decreto de Muharrem emitido no mesmo ano, foi criada a Administração da Dívida Pública Otomana, em que estavam representados os credores, para a gestão das dívidas externas falidas: rendimentos básicos como o sal, o tabaco e a seda foram diretamente ligados a esta administração estrangeira e a soberania financeira foi gravemente limitada. Outros povoamentos perdidos na mesma data: Kayrevan, Gabes, Sfaks, Cerbe (Djerba).", "64f23b86"]},
"OLAYLAR:1882-09:0":{"b": ["Ocupação britânica do Egito", "f1269768"], "d": ["O movimento de Urâbî Paşa, que se erguia no Egito contra a falência financeira e o controlo estrangeiro, foi esmagado com a vitória de Tel el-Kebir do exército inglês desembarcado após o bombardeamento de Alexandria, e o Cairo foi ocupado. Embora o Egito tenha continuado juridicamente ligado aos otomanos, passou de facto à administração inglesa; o controlo do canal de Suez instalou-se no centro da estratégia imperial britânica.", "b7bcf2d2"]},
"OLAYLAR:1908-07-23:0":{"b": ["Proclamação do II Período Constitucional", "95ee2fd2"], "d": ["Perante o movimento que cresceu com a ida para as montanhas, na Macedónia, de oficiais ligados ao Comité de União e Progresso, Abdulhamide II repôs em vigor o Kanûn-ı Esâsî; a 'proclamação da liberdade' foi acolhida com entusiasmo e foram feitas eleições. Contudo, não veio a estabilidade: depois de reprimido o Incidente de 31 de Março (abril de 1909), Abdulhamide foi deposto; a independência da Bulgária, a anexação da Bósnia e a orientação de Creta para a Grécia ocorreram também nestes meses agitados.", "370f359f"]},
"OLAYLAR:1911-09-29:0":{"b": ["Guerra da Tripolitânia", "ed441994"], "d": ["A Itália, em busca de colónias, declarou guerra à Tripolitânia, último território otomano no Norte de África, e ocupou as costas; como o Estado, sem armada, não pôde enviar um exército regular, jovens oficiais como Mustafa Kemal e Enver Bey passaram secretamente à região e organizaram, com as tribos senussis, uma resistência eficaz. Com o Tratado de Ouchy (18 de outubro de 1912), assinado com a eclosão da Guerra dos Balcãs, a Líbia foi deixada à Itália; a Itália ocupou ainda Rodes e o Dodecaneso.", "9820482a"]},
"OLAYLAR:1913-05-30:0":{"b": ["Tratado de Londres — perda da Rumélia", "f3f976df"], "d": ["Com o Tratado de Londres, que pôs fim à I Guerra dos Balcãs, perderam-se todos os territórios a oeste da linha Midye-Enez e as ilhas do Egeu; a Albânia tornou-se independente. Da Rumélia, centro de gravidade demográfico, económico e cultural do império há mais de quinhentos anos, restaria apenas a Trácia oriental (Edirne foi recuperada na II Guerra dos Balcãs); a perda endureceu radicalmente a política de guerra e de povoamento da administração unionista.", "077da59d"]},
"OLAYLAR:1914-11-01:0":{"b": ["Entrada na Primeira Guerra Mundial", "05a0252e"], "d": ["A admissão pelo Bósforo dos couraçados Goeben e Breslau, em fuga da Inglaterra, apresentados como comprados, arrastou passo a passo o Estado para o lado da Alemanha; com o bombardeamento dos portos russos pela armada sob o comando do almirante Souchon (29 de outubro), a guerra começou de facto e as declarações recíprocas vieram no início de novembro. Apesar da proclamação da Grande Jihad, o efeito esperado não se produziu; durante quatro anos o império entrou numa guerra de existência em cinco frentes distintas, do Cáucaso à Palestina.", "a9f179e7"]},
"OLAYLAR:1915-03-18:0":{"b": ["Vitória de Çanakkale", "95d888e8"], "d": ["A armada aliada, que visava fazer cair Istambul e chegar à Rússia, foi repelida do Estreito em 18 de março pelo fogo das linhas de minas e das baterias; a linha lançada pelo navio minador Nusret decidiu o destino da batalha. A operação terrestre de Galípoli, iniciada em abril, foi também detida em Anafartalar e Conkbayırı; os aliados evacuaram totalmente a península em janeiro de 1916. O nome do tenente-coronel Mustafa Kemal foi ouvido nesta frente; a vitória, ganha com cerca de um quarto de milhão de mártires e perdas, é considerada o lugar onde nasceram os quadros e o espírito da Luta Nacional.", "005303c3"]},
"OLAYLAR:1916-06-10:0":{"b": ["Revolta do Xerife Huceine", "75f7c58c"], "d": ["O emir de Meca, Xerife Huceine, após a correspondência secreta mantida com os ingleses, levantou-se com a promessa de um reino árabe independente; a ferrovia do Hejaz foi alvo de ataques. Embora a lendária defesa de Medina por Fahreddin Paşa, que se prolongou até depois do armistício, tenha permanecido como símbolo da resistência, a revolta, combinada com o avanço inglês na frente da Palestina, acelerou a dissolução do domínio otomano nas províncias árabes. Outros povoamentos perdidos na mesma data: Tâif.", "a0e859bd"]},
"OLAYLAR:1918-10-30:0":{"b": ["Armistício de Mudros", "9e87c767"], "d": ["O Estado otomano, cujas frentes ficaram separadas com o colapso da Bulgária, retirou-se da guerra com o armistício assinado a bordo do couraçado Agamemnon. A abertura dos Estreitos e, em particular, o artigo 7, que permitia a ocupação de lugares cuja segurança fosse ameaçada, foi rapidamente tornado o invólucro jurídico de uma partilha de facto: Mossul, Alexandreta e, em seguida, Esmirna e Istambul foram ocupadas. O armistício é considerado o documento do fim de facto do império. Outros povoamentos perdidos na mesma data: Hama, Şam, Humus.", "261b57f2"]},
"OLAYLAR:1919-05-19:0":{"b": ["Mustafa Kemal em Samsun — Luta Nacional", "09a8f784"], "d": ["No clima de indignação criado pela ocupação de Esmirna, Mustafa Kemal Paşa, que desembarcou em Samsun na qualidade de inspetor do 9.º Exército, converteu a sua missão oficial na organização da resistência na Anatólia. A Circular de Amásia e os congressos de Erzurum e de Sivas são a continuação desta iniciativa; o princípio de que 'a independência da nação será salva pela determinação e pela decisão da própria nação' tornou-se o núcleo do programa político da Luta Nacional.", "330e4c51"]},
"OLAYLAR:1920-04:0":{"b": ["Abertura da TBMM e Sèvres", "2008feec"], "d": ["Com a ocupação oficial de Istambul e a dissolução do Meclis-i Meb'ûsan, a Grande Assembleia Nacional abriu em Ancara em 23 de abril de 1920; a assembleia, que concentrou em si poderes extraordinários, tornou-se o núcleo do novo Estado assente na vontade nacional. O Tratado de Sèvres, assinado em agosto pelo governo de Istambul, repartia a Anatólia; a TBMM declarou traidores à pátria os que o assinaram e Sèvres nunca pôde ser aplicado.", "9b4f7c0b"]},
"OLAYLAR:1921-09-13:0":{"b": ["Batalha do Sakarya", "f2f970a6"], "d": ["A ofensiva grega, que se aproximara até 50 quilómetros de Ancara, foi quebrada numa batalha de 22 dias e 22 noites, conduzida com a ordem de Mustafa Kemal Paşa, que assumira o comando supremo, de que 'não há linha de defesa, há superfície de defesa'. O exército grego passou pela primeira vez à defensiva estratégica; a vitória valeu a Mustafa Kemal os títulos de gazi e de müşir (marechal) e abriu a porta ao Acordo de Ancara com a França e ao reconhecimento externo.", "f3372310"]},
"OLAYLAR:1922-09-09:0":{"b": ["Grande Ofensiva e libertação de Esmirna", "172a50c4"], "d": ["A ofensiva lançada de Kocatepe na manhã de 26 de agosto culminou, em 30 de agosto, no aniquilamento das forças principais gregas em Dumlupınar, na Batalha do Comandante-em-Chefe; com a perseguição prosseguida sob a ordem 'Exércitos, o vosso primeiro objetivo é o Mediterrâneo, em frente!', Esmirna foi libertada em 9 de setembro. Com o Armistício de Mudanya (11 de outubro), a Trácia oriental foi recuperada sem combate; a vitória militar determinou a força à mesa do novo Estado que seria constituído em Lausana.", "02bd94a5"]},
"OLAYLAR:1922-11-01:0":{"b": ["Abolição do sultanato", "9f36a9f6"], "d": ["Tendo o governo de Istambul sido também convidado para as negociações de Lausana, a TBMM, em 1 de novembro de 1922, separou o sultanato do califado e aboliu o sultanato; o domínio dinástico otomano de 623 anos terminou juridicamente. Mehmed VI Vahideddin deixou o país em 17 de novembro a bordo de um couraçado inglês; para o cargo de califa foi colocado Abdulmecid Efendi por decisão da TBMM, e este cargo seria também abolido em 3 de março de 1924.", "910b763d"]},
"OLAYLAR:1923-07-24:0":{"b": ["Tratado de Lausana", "38c27f7d"], "d": ["Com o Tratado de Paz de Lausana, assinado no termo de oito meses de árduas negociações, foram reconhecidas no plano internacional as fronteiras, a plena independência e a soberania do novo Estado turco; as capitulações foram abolidas, a Düyûn-ı Umûmiyye foi posta em processo de liquidação, a troca de populações foi regulada. Lausana, que tornou Sèvres nulo de facto, é considerado a vitória diplomática da Luta Nacional e o documento externo fundador da República.", "6d498c3f"]},
"OLAYLAR:1923-10:0":{"b": ["Proclamação da República", "d5bfcdfb"], "d": ["A República foi proclamada com a aceitação pela TBMM, por alteração constitucional, da disposição de que 'a forma de governo do Estado da Turquia é a república'; Mustafa Kemal Paşa foi eleito primeiro presidente. A aventura otomana de 624 anos, iniciada em 1299 como um beylik de fronteira, ficava assim encerrada, e o novo Estado, em que a soberania pertence incondicionalmente à nação, foi edificado sobre a herança do império.", "f5cabb8c"]},
"OLAYLAR_2S0920:1387-05-08:0":{"b": ["Karaferye (Veria) entra no domínio otomano", "b0ece3f3"], "d": ["No mesmo ano em que Salónica se rendeu, em 1387, também Karaferye, no interior da Baixa Macedónia, entrou no domínio otomano. A cidade era o nó da estrada entre Salónica e a Tessália.", "4e571f7b"]},
"OLAYLAR_2S0920:1552-08-01:0":{"b": ["Conquista das fortalezas de Lugoş (Lugoj) e Karánşebeş — continuação da campanha de Timişoara", "1af5a2be"], "d": ["A fortaleza de Timişoara rendeu-se a 26 de julho de 1552, depois de três semanas de resistência. Em agosto foram também tomadas as fortalezas de Lugoş e Karánşebeş; ao longo do vale do Mureş foram tomadas quinze fortalezas e foi criado um novo beylerbeylik com centro em Timişoara.", "ecd1e532"]},
"OLAYLAR_2S0920:1912-10-22:0":{"b": ["Priştine passa para as mãos do exército sérvio", "2ef111c0"], "d": ["O exército sérvio, que entrou no Kosovo na Primeira Guerra dos Balcãs, tomou Priştine e começou na cidade uma política de nova sérvização. A queda de Priştine é um dos primeiros elos da desagregação da resistência otomana no vilaiete do Kosovo.", "96fc25ba"]},
"OLAYLAR_2S0920:1912-11-18:0":{"b": ["Ocupação de Manastır pelas forças sérvias", "db9b3353"], "d": ["Na Primeira Guerra dos Balcãs, Manastır, um dos mais importantes centros administrativos e militares da Macedónia, passou para as mãos das forças sérvias depois de cinco dias de combates. A perda da cidade significava o fim efetivo da presença do Estado Otomano na Macedónia.", "84736d79"]},
"OLAYLAR_2S0920:1912-11-28:0":{"b": ["Proclamação da independência da Albânia — İsmâil Kemali em Avlonya", "2cdbd4d9"], "d": ["Quando os exércitos da Guerra dos Balcãs entravam nas províncias albanesas, İsmâil Kemali proclamou em Avlonya a independência da Albânia. Durrës, Elbasan, Berat, Gjirokastër e Akçahisar, e a costa e o interior que se estendem até Ayasaranda, saíram assim da administração otomana e formaram o núcleo do novo Estado albanês.", "bc8dc97c"]},
"OLAYLAR_2S0920:1912-11-29:0":{"b": ["Fim do domínio otomano em Ohri e Debre", "5273f1ec"], "d": ["Onze dias depois da queda de Manastır, o exército sérvio entrou na região dos lagos da Macedónia Ocidental; em Ohri terminou o domínio otomano de cinco séculos e Debre, a norte, perdeu-se também na mesma operação.", "7cabdd2f"]},
"OLAYLAR_2S0920:1913-04-23:0":{"b": ["Ocupação de Shkodër pelos montenegrinos", "db704247"], "d": ["Um dos mais longos cercos da Primeira Guerra dos Balcãs deu-se em Shkodër; depois de meses de resistência, a cidade foi entregue às forças montenegrinas. Shkodër foi uma das últimas fortalezas otomanas que resistiram até ao fim da guerra.", "418ed9d4"]},
"OLAYLAR_2S0920:1913-05-14:0":{"b": ["O Montenegro evacua Shkodër; o corpo internacional das grandes potências entra na cidade", "8a6593e9"], "d": ["Sob a pressão das grandes potências, o Montenegro evacuou, a 14 de maio de 1913, Shkodër, que tomara a 23 de abril de 1913; o corpo internacional entrou na cidade e esta tornou-se parte da administração fundadora da Albânia.", "5ef15370"]},
"OLAYLAR_2S0920:1913-07-08:0":{"b": ["Ibn Saud toma Lahsa — fim do domínio otomano na costa do Golfo", "505f26d5"], "d": ["O emir de Najd Abdülazîz b. Suûd, expulsando a guarnição otomana, tomou a região de Lahsa e estabeleceu-se no centro, Hüfûf. A costa ocidental do Golfo, juntamente com os embarcadouros de Katîf e Ukayr, passou para a administração saudita; terminou a administração otomana de cinquenta anos na região.", "8ec53ab2"]},
"OLAYLAR_2S0920:1913-08-10:0":{"b": ["Tratado de Bucareste — a Trácia Ocidental e a bacia de Kavala passam da Bulgária para a Grécia", "56123a58"], "d": ["A Segunda Guerra dos Balcãs terminou com o Tratado de Bucareste, assinado entre a Bulgária e a Sérvia, a Grécia e o Montenegro. A bacia de Kavala, Drama e Serres, que passara para a Bulgária na primeira guerra, foi cedida à Grécia por este tratado.", "ca3eb029"]},
"OLAYLAR_2S0920:1914-11-22:0":{"b": ["Desembarque em Shatt al-Arab — queda de Baçorá e abertura da frente do Iraque", "c0a87d5d"], "d": ["Na abertura da Primeira Guerra Mundial, a força expedicionária britânica vinda da Índia desembarcou em Fâv, na foz do Shatt al-Arab, e tomou em pouco tempo Baçorá. A queda da cidade significou a abertura da frente do Iraque e a passagem da extremidade norte do Golfo para controlo britânico.", "3b98576d"]},
"OLAYLAR_2S0920:1918-05-26:0":{"b": ["A Geórgia proclama a independência — dissolve-se o Seim da Transcaucásia", "6c79a8c7"], "d": ["A Geórgia, saída do Seim da Transcaucásia constituído depois de Brest-Litovsk, proclamou a independência e foi fundada a República Democrática da Geórgia. A Geórgia ocidental, com Kutaisi, passou para a administração deste novo Estado.", "7f834f47"]},
"OLAYLAR_2S0920:1918-05-28:0":{"b": ["Proclamada a República Democrática do Azerbaijão", "8baecec3"], "d": ["Dois dias depois da separação da Geórgia, foi proclamada a República Democrática do Azerbaijão; o primeiro centro foi Gäncä. No mesmo dia, foi fundada também em Erevan a República da Arménia e a Transcaucásia ficou dividida em três Estados distintos.", "d4eb329a"]},
"OLAYLAR_2S0920:1918-10-27:0":{"b": ["Ocupação de Alepo por forças árabes e britânicas", "00efb2da"], "d": ["Depois do colapso da frente da Palestina, as forças que avançavam para norte entraram em Alepo; a cidade passou primeiro para forças árabes e depois para tropas britânicas. Esta ocupação, que se deu três dias antes do Armistício de Mudros, pôs fim de facto à administração otomana de quatro séculos na Síria.", "38b8fc55"]},
"OLAYLAR_2S0920:1920-04-27:0":{"b": ["O Exército Vermelho ocupa o Azerbaijão — fim da República Democrática", "ebbb4566"], "d": ["O Exército Vermelho entrou no Azerbaijão e dissolveu o parlamento e o governo; terminou a República Democrática do Azerbaijão, de dois anos. A bacia petrolífera de Baku e Gäncä passaram assim para a administração soviética.", "67223904"]},
"OLAYLAR_2S0920:1920-07-24:0":{"b": ["Khan Maysalun — acaba o período de Faysal, a Síria passa para o mandato francês", "80a932b0"], "d": ["Em Khan Maysalun, na estrada Beirute-Damasco, os franceses infligiram uma pesada derrota às forças sírias e terminou o Reino Árabe de Faysal em Damasco. A França estabeleceu de facto o poder de mandato que lhe fora dado em San Remo; a região que se estende de Alepo a Damasco e de Alexandreta a Deir ez-Zor ficou ligada à administração de mandato francesa.", "81c76451"]},
"OLAYLAR_2S0920:1921-02-01:0":{"b": ["Fundado o Emirado da Transjordânia — Abdullah b. Hüseyin proclama o emirado", "5ef520c2"], "d": ["Abdullah, filho do xerife Hüseyin, subindo para norte por Ma'an, proclamou o emirado da Transjordânia; a Inglaterra reconheceu pouco depois esta administração no quadro do mandato. Amã tornou-se o centro do emirado e o planalto da Jordânia, incluindo Kerak, ficou ligado a esta nova administração.", "113f01ba"]},
"OLAYLAR_2S_0918:1293-01-01:0":{"b": ["Alanya (Alâiye) passa, no período pós-seljúcida, para o controlo de um beilique local", "7b1489b3"], "d": ["Com a desagregação efetiva do Estado dos Seljúcidas da Anatólia na década de 1290, o porto de Alâiye (Alanya), no litoral mediterrânico, tornou-se independente da autoridade central e passou para o controlo dos beiliques da região (nesta época, na esfera de influência dos Karamanoğulları); a data exata e o beilique que dominava diretamente não são claros nas fontes.", "78a4ff46"]},
"OLAYLAR_2S_0918:1322-01-01:0":{"b": ["Sinope tomada por Gazi Çelebi e entra na influência dos Candaroğulları", "f107586a"], "d": ["Com o enfraquecimento do domínio ilkhânida, Gazi Çelebi, da família fundadora do beilique dos Candaroğlu (İsfendiyaroğlu), que se fortalecia na região de Kastamonu e Sinope, tomou Sinope por volta de 1322 e fez da cidade um centro portuário do beilique.", "35c2fa9c"]},
"OLAYLAR_2S_0918:1358-02-18:0":{"b": ["Tratado de Zadar — Dubrovnik passa de Veneza para a proteção da Hungria", "57fb81f9"], "d": ["O Tratado de Zadar, assinado a 18 de fevereiro de 1358, pôs fim ao domínio de 150 anos de Veneza sobre a Dalmácia; Dubrovnik (Ragusa) saiu assim da administração veneziana e adquiriu o estatuto de república semiautónoma sob a proteção do rei húngaro Luís I.", "e207c893"]},
"OLAYLAR_2S_0918:1408-01-01:0":{"b": ["A região de Erzurum e Aşkale mudou de mãos na disputa Kara Koyunlu-Timúridas", "ca64775a"], "d": ["No vazio de poder surgido depois da morte de Timur em 1405, o soberano dos Kara Koyunlu Kara Yûsuf pôs-se em movimento, entre 1406 e 1408, contra os governadores timúridas da Anatólia Oriental; Erzurum e, nos arredores, Aşkale saíram nesta luta do controlo timúrida e entraram na influência dos Kara Koyunlu.", "10b1b07c"]},
"OLAYLAR_2S_0918:1462-01-01:0":{"b": ["Uzun Hasan dos Ak Koyunlu eliminou o ramo ayubida de Hısnıkeyfâ", "2b464a1f"], "d": ["Hısnıkeyfâ (Hasankeyf) e Siirt, um dos dois últimos ramos da dinastia ayubida que subsistiam no Alto Tigre, juntamente com Hama, foram anexados em 1462 pelo soberano dos Ak Koyunlu Uzun Hasan, pondo-se fim ao domínio ayubida.", "8bf494b3"]},
"OLAYLAR_2S_0918:1515-04-01:0":{"b": ["Portugal completa o seu domínio nas costas do Estreito de Ormuz", "bef031f0"], "d": ["A expedição ao Golfo Pérsico iniciada por Afonso de Albuquerque em 1507 concluiu-se em 1515, abrangendo a Ilha de Ormuz e, na margem oposta, Qeshm e Buraymi; o Reino de Ormuz, vassalo do Irão, passou de facto para a proteção portuguesa e Portugal tomou o controlo do comércio do golfo.", "117a5c7e"]},
"OLAYLAR_2S_0918:1569-07-01:0":{"b": ["União de Lublin — os territórios ucranianos passam da Lituânia para a Polónia", "1881ceff"], "d": ["A União de Lublin, assinada a 1 de julho de 1569, juntou o Grão-Ducado da Lituânia e o Reino da Polónia num só Estado (Rzeczpospolita). Em virtude das condições do acordo, a Podólia, a Volínia e a região de Kiev (incluindo Bar, Berdychiv, Białystok e Braslav) foram transferidas administrativamente da Lituânia diretamente para o Reino da Polónia.", "184b03dd"]},
"OLAYLAR_2S_0918:1841-10-01:0":{"b": ["As forças egípcias retiram-se da região de Ahsâ (Lahsa)", "5ea75c8d"], "d": ["As forças egípcias de Mehmed Ali Paxá tinham ocupado em 1836 Najd e a Arábia Oriental (incluindo Ahsâ, Katîf, Ukayr e Cübeyl); como a Convenção dos Estreitos de Londres de 1840 fez o Egito renunciar às conquistas na península Arábica, as forças retiraram-se da região em 1841 e a administração voltou às forças locais (influência saudita/Âl-i Halîfe).", "99ff8f81"]},
"OLAYLAR_2S_0918:1853-07-28:0":{"b": ["A Fortaleza de Ak-Meçit tomada pelas forças russas — colapsa a linha do Sir Daria do Canato de Kokand", "e9f9a9c7"], "d": ["As forças russas comandadas pelo general Vasili Perovski tomaram em julho de 1853, depois de um longo cerco, a Fortaleza de Ak-Meçit, do Canato de Kokand, na margem do Sir Daria; a fortaleza tornou-se depois, com o nome de Perovsk, o posto avançado do Turquestão Russo.", "9e64a219"]},
"OLAYLAR_2S_0918:1881-01-24:0":{"b": ["Batalha de Göktepe — os turcomanos Tekke de Ahal derrotados pela Rússia", "76c7a102"], "d": ["As forças russas comandadas pelo general Mikhail Skobelev quebraram, a 24 de janeiro de 1881, a resistência dos turcomanos Tekke de Ahal ao tomar a fortaleza de Göktepe (Geok Tepe); a região turcomana transcáspica, incluindo a planície de Dihistan, Ebîverd e Nesâ, entrou em processo de incorporação no Império Russo (a Região Transcáspica foi criada em 1881).", "41bbf179"]},
"OLAYLAR_2S_0918:1881-03-26:0":{"b": ["Proclamado o Reino da Roménia — o Principado transforma-se em Reino", "4d413f0c"], "d": ["O Principado da Roménia, cuja independência fora reconhecida no Congresso de Berlim depois da Guerra Otomano-Russa de 1877-78, foi transformado em Reino a 26 de março de 1881 (14 de março no calendário juliano) com a coroação do rei Carol I; todo o país, incluindo Babadağ, Bârlad, Buzău e a capital Bucareste, passou administrativamente a fazer parte do novo reino.", "54ed49f3"]},
"OLAYLAR_2S_0918:1889-01-01:0":{"b": ["A Itália anexa o planalto da Eritreia, incluindo Asmara e Keren", "31308dc8"], "d": ["A Itália, aproveitando o vazio de poder criado pela morte do imperador da Abissínia Yohannes II em 1889, anexou de facto o planalto da Eritreia, incluindo Asmara e Keren, depois do Tratado de Uccialli (Wuchale) (2 de maio de 1889); a 1 de janeiro de 1890 foi oficialmente proclamada colónia com o nome de 'Eritreia'.", "66fdfc34"]},
"OLAYLAR_2S_0918:1895-07-01:0":{"b": ["A região nordeste do Quénia (linha Garissa-Marsabit) incorporada no Protetorado da África Oriental Britânica", "e45c6d43"], "d": ["O Protetorado da África Oriental Britânica, criado com a cedência da concessão da Companhia Britânica da África Oriental à Coroa em 1895, alargou-se de modo a abranger também regiões do nordeste como Garissa, Kitui, Marsabit e Wajir; a tomada de administração efetiva destas regiões interiores estendeu-se pela segunda metade da década de 1890.", "8cf3e473"]},
"OLAYLAR_2S_0918:1897-02-16:0":{"b": ["O Emirado de Ilorin tomado pelas forças da Royal Niger Company", "b111cb7d"], "d": ["O Emirado de Ilorin, ligado ao Califado de Sokoto, foi tomado na campanha de fevereiro de 1897 pelas forças da Royal Niger Company, comandadas por Sir George Goldie; o poder militar do emirado foi quebrado e a região entrou de facto na influência britânica (a anexação oficial concluiu-se com a fundação do Protetorado da Nigéria do Norte em 1900).", "95f49872"]},
"OLAYLAR_2S_0918:1899-04-09:0":{"b": ["O rei Kabalega de Bunyoro feito prisioneiro, o reino ligado ao Protetorado do Uganda Britânico", "62bc7c64"], "d": ["O rei de Bunyoro Kabalega, que resistia às forças britânicas desde 1894, foi capturado a 9 de abril de 1899 na região de Lango (perto de Dokolo) e enviado para o exílio nas Seicheles; os territórios do reino, incluindo a capital Hoima e Masindi, foram incorporados no Protetorado do Uganda Britânico.", "87bc3dd6"]},
"OLAYLAR_2S_0918:1900-06-26:0":{"b": ["Tratado de Toro — o Reino de Toro torna-se parte autónoma do Protetorado do Uganda Britânico", "c55340a2"], "d": ["Depois da queda de Bunyoro em 1899, o Reino vizinho de Toro oficializou, no quadro do Tratado do Uganda de 1900, a proteção britânica que durava desde 1896; o reino, incluindo a capital Fort Portal, adquiriu o estatuto de administração local autónoma dentro do Protetorado do Uganda Britânico.", "8459a73a"]},
"OLAYLAR_2S_0918:1901-09-02:0":{"b": ["O Emirado de Adamawa repartido entre a Alemanha e a Inglaterra", "b9230d3d"], "d": ["O Emirado de Adamawa (Fombina), ligado ao Califado de Sokoto, foi dividido em dois no termo das campanhas das forças coloniais alemãs e inglesas de 1899-1901: a parte oriental (incluindo Garoua, Banyo, Marua e Ngaundere) foi incorporada nos Camarões Alemães e a parte ocidental (capital Yola) na Nigéria do Norte Britânica; o emir Zübeyr foi enviado para o exílio.", "671ba3aa"]},
"OLAYLAR_2S_0918:1902-05-07:0":{"b": ["Batalha de Tit — os tuaregues do Ahaggar derrotados pelas forças francesas", "831143d6"], "d": ["Na batalha travada a 7 de maio de 1902 perto do oásis de Tit, durante a expedição Cottenest, as forças francesas derrotaram definitivamente os tuaregues Kel Ahaggar; esta região interior do Saara, incluindo o centro do Ahaggar, Abalessa, e Idelès, passou para o controlo da Argélia Francesa.", "5c1e86d4"]},
"OLAYLAR_2S_0918:1903-01-01:0":{"b": ["As forças francesas tomam o interior de Ubangui-Chari (linha Bambari-Bria)", "0b9a9f72"], "d": ["As campanhas do norte do Congo Francês puseram de facto sob controlo, no início dos anos 1900, o interior de Ubangui-Chari, que abrange Bambari, Batangafo, Bossangoa e Bria; a região foi oficialmente organizada a 29 de dezembro de 1903 como colónia de Ubangui-Chari (parte da África Equatorial Francesa).", "ebbd38e7"]},
"OLAYLAR_2S_0918:1911-01-12:0":{"b": ["O Sultanato de Dâru'l-Kûtî do sultão Mohammed es-Senûsî abolido pelas forças francesas", "644b2c3f"], "d": ["O Sultanato de Dâru'l-Kûtî, assente no comércio de escravos, com capital em Ndele, que entrara sob proteção francesa em 1897, foi de facto abolido por uma expedição organizada em 1911, quando o sultão Mohammed es-Senûsî continuou a resistir à autoridade francesa; Senûsî foi morto em combate e o sultanato foi oficialmente abolido em 1912.", "3f913340"]},
"OLAYLAR_2S_0919:1328-01-01:0":{"b": ["A Ordem da Livónia cede à ramo prussiano da Ordem Teutónica o território de Klaipėda (Memel)", "e61e5d50"], "d": ["A Ordem da Livónia cedeu ao ramo prussiano da Ordem Teutónica a fortaleza de Klaipėda (Memel), na foz do Neman, e os territórios circundantes; o bispo da Curlândia cedeu também a sua parte, em 1392, ao mesmo ramo. Klaipėda permaneceu com a Ordem pelas pazes de Toruń de 1411 e de Melno de 1422 e passou em 1525 para o Ducado da Prússia.", "cad2853d"]},
"OLAYLAR_2S_0919:1329-01-01:0":{"b": ["Umur Bey toma aos genoveses a fortaleza portuária de İzmir", "ab92d96e"], "d": ["Umur Bey dos Aydınoğulları sitiou durante dois anos e meio a fortaleza portuária de İzmir, que continuava em mãos dos latinos. O administrador genovês da fortaleza, Martino Zaccaria, entregou-a e foi para Quios.", "1bec5de9"]},
"OLAYLAR_2S_0919:1343-01-01:0":{"b": ["İbrâhim Şah, dos Sutayoğulları, domina Diyarbekir", "179196cf"], "d": ["Depois da dissolução do Estado Ilkhânida, İbrâhim Şah, dos Sutayoğulları, dominou a região de Diyarbekir, palco de lutas entre os Celayírida e os Çobanlı; o seu domínio durou até 1353.", "6143de93"]},
"OLAYLAR_2S_0919:1343-01-01:1":{"b": ["Berat passa de Bizâncio para mãos sérvias — a conquista da Albânia por Estêvão Dušan", "1eba202e"], "d": ["A fortaleza de Berat, que quebrara o cerco angevino em 1281 e era desde então o centro da última província bizantina no Adriático, passou para mãos sérvias, durante a guerra civil bizantina, com o avanço de Estêvão Dušan na Albânia. Depois da rendição de Kruja em maio ou junho de 1343, Berat, Kanina e Avlonya passaram a ser dos sérvios em dois anos; à frente da província foi posto John Komnenos Asen, cunhado de Dušan.", "21876887"]},
"OLAYLAR_2S_0919:1348-01-01:0":{"b": ["Os Abdülvâdîs (Zayyânidas) libertam-se em Tilimsan do domínio merínida", "a4aa9573"], "d": ["Os Abdülvâdîs de Tilimsan libertaram-se do domínio dos Merínidas sob a liderança de Osman II e do seu irmão Ebû Sâbit. Esta independência foi breve.", "0afdf111"]},
"OLAYLAR_2S_0919:1351-01-01:0":{"b": ["Bayram Hoca conquista a independência — nascimento do Beilique dos Kara Koyunlu", "37964815"], "d": ["Bayram Hoca, considerado o primeiro bei dos Kara Koyunlu, conquistou a independência matando Akçasakal Hüseyin Bey, soberano dos Sutay. Tomou Mossul e entregou a sua administração ao irmão Birdi Hoca.", "892dced7"]},
"OLAYLAR_2S_0919:1353-01-01:0":{"b": ["Com a morte de İbrâhim Şah, Diyarbekir passa para a administração dos Celayírida", "11c338ef"], "d": ["Com a morte de İbrâhim Şah, dos Sutayoğulları, que dominava a região de Diyarbekir desde 1343, a região passou para a administração dos Celayírida.", "155719ec"]},
"OLAYLAR_2S_0919:1355-01-01:0":{"b": ["Enez passa para a administração genovesa (família Gattilusi)", "5dc12940"], "d": ["Enez, importante cidade portuária no período bizantino, passou em 1355 para a administração genovesa e foi governada pela família Gattilusi.", "33faefdd"]},
"OLAYLAR_2S_0919:1356-01-01:0":{"b": ["O grão-duque da Lituânia Algirdas (Olgerd) toma Bryansk", "3cad9caf"], "d": ["O exército do grão-duque da Lituânia Algirdas tomou Bryansk. A cidade permaneceu ligada ao Grão-Ducado da Lituânia até 1500.", "03107c6d"]},
"OLAYLAR_2S_0919:1362-01-01:0":{"b": ["O Principado de Kiev passa para a soberania da Lituânia", "c4fda115"], "d": ["O Principado de Kiev entrou na soberania da Lituânia e tornou-se, no Estado lituano-russo, um principado subordinado governado por príncipes da linhagem de Gediminas.", "d4a2f5ec"]},
"OLAYLAR_2S_0919:1368-01-01:0":{"b": ["Os İnançoğulları reconhecem o domínio dos Germiyanoğulları", "0679db27"], "d": ["O Beilique dos İnançoğulları, que reinava nos arredores de Denizli, reconheceu provavelmente em 1368 o domínio dos Germiyanoğulları.", "55ce9f1f"]},
"OLAYLAR_2S_0919:1371-11-01:0":{"b": ["O déspota de Salónica Manuel coloca a região de Serres e Drama sob administração bizantina", "abb99c3e"], "d": ["Com a morte do rei Vukašin e do déspota de Serres Uglješa em Çirmen (26 de setembro de 1371), terminou a administração sérvia na região de Serres. O príncipe bizantino Manuel II Paleólogo, que reinava em Salónica, colocou em novembro de 1371 sob administração bizantina Serres e a região em que se inclui também Drama. A região passou para os otomanos em setembro de 1383.", "b0802648"]},
"OLAYLAR_2S_0919:1378-01-01:0":{"b": ["Com a morte de Pîr Hüseyin Bey, Erzincan e Bayburt passam para Mutahharten", "3269e55d"], "d": ["Com a morte do emir de Erzincan Pîr Hüseyin Bey, Erzincan e Bayburt passaram para as mãos de Mutahharten, um dos emires de Eretna; Mutahharten tornou-se emir de Erzincan.", "4993bac9"]},
"OLAYLAR_2S_0919:1379-01-01:0":{"b": ["Tâceddin Bey derrota o exército de Eretna em Niksar e passa a agir de modo independente", "42982ea7"], "d": ["Na primavera de 1379, Tâceddin Bey derrotou as forças de Kadı Burhâneddin e do bei de Eretna Alâeddin Ali, que atacavam Niksar. Deixou de pagar impostos ao Beilique de Eretna e passou a agir de modo independente a partir do ano 781 (1379).", "5d809820"]},
"OLAYLAR_2S_0919:1379-01-01:1":{"b": ["Timur conquista definitivamente o Khwarazm", "ef76d2c9"], "d": ["Timur, depois da primeira campanha do Khwarazm em 1371, organizou mais três campanhas. Na campanha de 1379 conquistou definitivamente a região, saqueou-a e regressou com abundante saque.", "f2ebd27a"]},
"OLAYLAR_2S_0919:1382-01-01:0":{"b": ["O rei Tvrtko I da Bósnia funda Herceg Novi", "1628221a"], "d": ["O rei Tvrtko I da Bósnia fundou uma nova povoação na baía de Topla para rivalizar com Dubrovnik no comércio do sal; a povoação foi depois designada Novi (Herceg Novi).", "b970dc7f"]},
"OLAYLAR_2S_0919:1383-01-01:0":{"b": ["Timur toma Kandahar aos Kert e entrega-a ao neto Pîr Muhammed", "84760f70"], "d": ["Kandahar, que estava desde 1281 em mãos dos Kert de Herat, vassalos dos ilkhânidas, foi tomada durante as campanhas de Timur no Horasão e entregue ao seu neto Pîr Muhammed; a cidade passou a ser governada por governadores timúridas.", "c2470eb5"]},
"OLAYLAR_2S_0919:1384-01-01:0":{"b": ["Halil Bey dos Dulkadıroğulları retoma Elbistan aos mamelucos", "ee3da686"], "d": ["Elbistan, que passara em 1381 para os mamelucos, foi retomada em 1384 por Halil Bey dos Dulkadıroğulları.", "104e231d"]},
"OLAYLAR_2S_0919:1394-04-25:0":{"b": ["Timur toma e saqueia Diyarbekir (Âmid)", "f8d200a8"], "d": ["Timur tomou Diyarbekir a 25 ou 26 de abril de 1394 e saqueou a cidade.", "b1186b21"]},
"OLAYLAR_2S_0919:1399-02-13:0":{"b": ["Gherardo Appiani cede Pisa aos Visconti e funda o senhorio de Piombino", "ac45a9dd"], "d": ["Gherardo Appiani, senhor de Pisa, cedeu a cidade por 200.000 florins a Gian Galeazzo Visconti, senhor de Milão. Reservou para si o senhorio de Piombino, composto por Piombino, Suvereto, Scarlino e pelas ilhas de Elba, Pianosa e Montecristo.", "68084c1c"]},
"OLAYLAR_2S_0919:1401-01-01:0":{"b": ["Diyarbekir dada a Karayülük Osman Bey — começa o domínio dos Ak Koyunlu", "38262401"], "d": ["Diyarbekir, que Timur tomara em 1394, foi dada em 1401 a Karayülük Osman Bey e assim começou na região o domínio dos Ak Koyunlu.", "de407b9c"]},
"OLAYLAR_2S_0919:1410-01-01:0":{"b": ["Erzincan entra no domínio dos Kara Koyunlu", "5729a50b"], "d": ["Depois de Mutahharten, Erzincan passou para as mãos do soberano dos Kara Koyunlu Kara Yûsuf. Kara Yûsuf nomeou primeiro governador da cidade Pîr Ömer, um dos seus homens de confiança.", "69ef181d"]},
"OLAYLAR_2S_0919:1494-01-01:0":{"b": ["Askiya Muhammed toma Zâgha (Dia)", "24561a8c"], "d": ["Askiya Muhammed, que subira ao trono songai, tomou, no fim do ano 899 da Hégira, por intermédio do seu irmão Kurmina-Fâri Amar Komzâgho, a cidade de Zâgha (Dia), a oeste do delta interior do Níger.", "f6d242d2"]},
"OLAYLAR_2S_0919:1500-01-01:0":{"b": ["Şeybânî Han toma Bucara e Samarcanda", "8f8f40eb"], "d": ["Muhammed Şeybânî Han, aproveitando a confusão entre os Timúridas, tomou Bucara e Samarcanda e fundou a dinastia dos Xaibânidas (uzbeques). Entre 1500 e 1507 apoderou-se de quase todas as cidades da Transoxiana, do Khwarazm e do Horasão.", "0e64ecae"]},
"OLAYLAR_2S_0919:1510-01-01:0":{"b": ["Os espanhóis ocupam Bijaya", "8faa0133"], "d": ["O exército espanhol de 8000 homens, chegado em navios, ocupou Bijaya; a população da cidade, tomada de pânico, abandonou a sua terra.", "364b6234"]},
"OLAYLAR_2S_0919:1515-01-01:0":{"b": ["Agadez ligada aos Songai", "997362b0"], "d": ["Agadez, centro da região de Âir, foi ligada a Gao pelo sultão songai Askiya Muhammed; a cidade manteve esta subordinação até à destruição dos Songai em Tondibi, em 1591.", "b2b437a3"]},
"OLAYLAR_2S_0919:1522-01-01:0":{"b": ["Fundado o Sultanato de Bagirmi", "03829f94"], "d": ["A tribo Kenga, sob a liderança de Birni Besi, fundou um Estado poderoso com centro em Masinya (Massenya), a leste do lago Chade. A fundação da dinastia de Bagirmi é tradicionalmente datada de 1522.", "2bd4497c"]},
"OLAYLAR_2S_0919:1535-11-01:0":{"b": ["Morre o último duque Sforza, Milão passa para Carlos V", "53230b5c"], "d": ["Francesco II Sforza, duque de Milão, morreu sem filhos na noite de 1-2 de novembro de 1535. O ducado passou para o imperador Carlos V e passou a ser governado por um governador espanhol.", "03b908c5"]},
"OLAYLAR_2S_0919:1544-01-01:0":{"b": ["Os genoveses instalam-se na ilha de Tabarka", "0cb474f8"], "d": ["Em virtude do tratado de Carlos V com o senhor de Tunes, que permitia construir uma fortaleza na costa e a pesca do coral, uma comunidade genovesa de Pegli foi instalada na ilha de Tabarka. A ilha tornou-se uma base comercial governada pela família Lomellini.", "74c7ab83"]},
"OLAYLAR_2S_0919:1556-01-01:0":{"b": ["Depois da morte de Hümâyun, os safávidas tomam Kandahar aos Babúridas", "318eabc8"], "d": ["Depois da morte de Hümâyun em Deli, em 1556, Şah Tahmasb aproveitou a disputa entre os governadores babúridas de Kandahar e de Zemindâver; uma força safávida, vinda a convite do governador de Zemindâver, entrou em Kandahar, e Tahmasb nomeou governador da cidade o seu primo Sultan Hüseyin Mirza. A cidade permaneceu em mãos safávidas até 1595.", "87ac27f5"]},
"OLAYLAR_2S_0919:1558-01-01:0":{"b": ["A Rússia invade a Livónia, Dorpat cai", "dcb46a8a"], "d": ["Ivan IV, para obter acesso ao Báltico, invadiu a Livónia e começou a Guerra da Livónia; tomou Narva e Dorpat (Tartu) e sitiou Reval.", "37f1dd66"]},
"OLAYLAR_2S_0919:1579-07-13:0":{"b": ["Fundada a fortaleza de Karlovac", "9b28e6ad"], "d": ["Para proteger a Croácia e os territórios hereditários austríacos contra os otomanos, foi fundada a fortaleza de Karlovac na zona de cheias entre o Kupa e o Korana; a fortaleza foi mandada construir pelo arquiduque Carlos II, comandante da fronteira militar da Croácia.", "edc1a0fd"]},
"OLAYLAR_2S_0919:1580-04-10:0":{"b": ["Documento de fundação (locação) de Zamość", "e1157f3b"], "d": ["Jan Zamoyski, grão-chanceler da Polónia, deu o documento de fundação (locação) da cidade de Zamość.", "90df0b1c"]},
"OLAYLAR_2S_0919:1582-01-15:0":{"b": ["Armistício de Yam Zapolski — a Livónia e Dorpat passam para a Polónia", "7d02d8ad"], "d": ["Foi assinado o armistício de Yam Zapolski entre a Polónia-Lituânia e a Rússia; Moscovo renunciou às suas pretensões sobre a Livónia e restituiu os territórios de Polotsk. Dorpat (Tartu) permaneceu desde 1582 em mãos da Polónia.", "3aa35e5c"]},
"OLAYLAR_2S_0919:1589-07-02:0":{"b": ["A fortaleza de Tsaritsyn é mencionada pela primeira vez em documento", "ddf65b06"], "d": ["O édito do czar Fyodor Ivanovich de 2 de julho de 1589 menciona a fortaleza de Tsaritsyn, fundada para proteger a fronteira sul do Volga; esta data é tida como o dia de fundação da cidade.", "fd3ba360"]},
"OLAYLAR_2S_0919:1590-07-12:0":{"b": ["Fundada a fortaleza de Saratov", "a3ca702c"], "d": ["Saratov foi fundada pelo príncipe Zasekin como fortaleza-posto para proteger a rota do Volga e as fronteiras orientais do Estado contra as incursões nómadas.", "07dcdc66"]},
"OLAYLAR_2S_0919:1593-01-01:0":{"b": ["Fundada a fortaleza de Pelym", "baf3e7eb"], "d": ["O voivoda Pyotr Gorchakov fundou Pelym na margem do rio Tavda; a fortaleza tornou-se um dos pontos de apoio do avanço russo na Sibéria Ocidental.", "7511aeab"]},
"OLAYLAR_2S_0919:1598-01-01:0":{"b": ["Fundada a fortaleza de Verkhoturye", "81be29bb"], "d": ["Na margem do Tura, no lugar do antigo povoado de Neromkar, foi fundado o ponto fortificado de Verkhoturye; a sua fundação está ligada à procura de um caminho mais curto para a Sibéria.", "ac40c773"]},
"OLAYLAR_2S_0919:1600-01-01:0":{"b": ["Fundada a fortaleza de Turinsk nas margens do Tura", "c1d8534e"], "d": ["Em 1600 foi fundada, na atual região de Turinsk, a fortaleza (ostrog) cossaca-yasak russa de Turinsk; a fortaleza é uma das fortificações de passagem do avanço da Rússia na Sibéria Ocidental.", "82075fd3"]},
"OLAYLAR_2S_0919:1611-01-01:0":{"b": ["O xá Abbas I funda a cidade de Ferahâbâd em Mazandaran", "cab4d0fe"], "d": ["O soberano safávida Abbas I mandou fundar a cidade de Ferahâbâd em Mazandaran, num lugar próximo da costa do Cáspio, e instalou aí gente vinda de todos os cantos do país. A construção começou em 1020/1611.", "cc05c705"]},
"OLAYLAR_2S_0919:1631-01-01:0":{"b": ["Fundada a fortaleza russa de Bratsk nas margens do Angara", "e7b4be59"], "d": ["No avanço da Rússia para a Sibéria Oriental, foi fundada a fortaleza de Bratsk no rio Angara.", "eb1a1abd"]},
"OLAYLAR_2S_0919:1658-02-26:0":{"b": ["Tratado de Roskilde — Skåne, Halland, Blekinge e Bornholm passam para a Suécia", "afcae41b"], "d": ["Foi assinado o Tratado de Roskilde, que pôs fim à Primeira Guerra de Carlos Gustavo; a Dinamarca-Noruega cedeu à Suécia Skåne, Halland, Blekinge e Bornholm.", "ac397fd6"]},
"OLAYLAR_2S_0919:1663-01-01:0":{"b": ["A Rússia funda a fortaleza de Penza nas margens do Sura", "49e8d90b"], "d": ["Penza foi fundada como uma grande fortaleza na confluência dos rios Penza e Sura; depois de 1684 formou a extremidade ocidental da linha de defesa de Syzran.", "afba0eaa"]},
"OLAYLAR_2S_0919:1668-01-01:0":{"b": ["Marquette funda a missão francesa de Sault Ste. Marie", "86612bcd"], "d": ["O jesuíta Jacques Marquette fundou uma missão junto às cataratas de Sault Ste. Marie, entre os lagos Superior e Huron.", "e90cdea2"]},
"OLAYLAR_2S_0919:1668-01-01:1":{"b": ["Fundado o primeiro posto da Hudson's Bay Company (Waskaganish)", "07b32d57"], "d": ["Na baía de James, na foz do rio Rupert, Médard Chouart des Groseilliers fundou o povoado depois considerado o primeiro posto da Hudson's Bay Company.", "790b2f93"]},
"OLAYLAR_2S_0919:1700-01-01:0":{"b": ["A administração colonial espanhola funda Pitic (Hermosillo)", "11e5cc04"], "d": ["A administração colonial espanhola fundou uma povoação no lugar de um antigo povoado indígena; a povoação recebeu em 1828 o nome de José María González de Hermosillo.", "4724e13c"]},
"OLAYLAR_2S_0919:1716-01-01:0":{"b": ["Fundada a fortaleza russa de Omsk na confluência do Irtysh e do Om", "13dcce5e"], "d": ["Omsk foi fundada como fortaleza na extremidade oriental da linha de fortificações de Ishim, entre o Tobol e o Irtysh; tornou-se cidade em 1804.", "45facb52"]},
"OLAYLAR_2S_0919:1717-11-30:0":{"b": ["Os Dzungares invadem Lhasa — Lajang Han morto, o Tibete entra sob ocupação dzungar", "65beea29"], "d": ["O exército dzungar, sob o comando de Tsering Döndup, atacou de todos os lados, depois da meia-noite, Lhasa, defendida pelo soberano hoshut Lajang Han; os Dzungares, que encontraram apoio no interior, tomaram e saquearam a cidade e pilharam também o Potala. Lajang Han foi morto durante a fuga; os Dzungares estabeleceram um governo tibetano fantoche chefiado por sTag-rtse-pa.", "b6dcede2"]},
"OLAYLAR_2S_0919:1720-09-24:0":{"b": ["O exército Qing entra em Lhasa — termina a ocupação dzungar, começa a proteção Qing", "083358c1"], "d": ["Dos dois exércitos que Kangxi enviou ao Tibete, a coluna de Sichuan, comandada por Galbi, chegou a Lhasa numa marcha difícil e tomou a cidade sem resistência; os Dzungares tinham concentrado todas as suas forças em Dam contra o exército de Kokonor, que vinha do norte. Com a retirada dos Dzungares do Tibete, os Qing estabeleceram em Lhasa um regime de proteção duradouro.", "e5c9dcf8"]},
"OLAYLAR_2S_0919:1721-01-01:0":{"b": ["A expedição de Aguayo funda o presídio de Los Adaes", "2031793a"], "d": ["A expedição do marquês de Aguayo fundou em Los Adaes um presídio (posto militar) e voltou a povoar a missão; o posto tornou-se o ponto de fronteira da Nova Espanha, no Texas Oriental, contra a Louisiana francesa.", "6ccb0ff2"]},
"OLAYLAR_2S_0919:1722-01-01:0":{"b": ["Fundado o posto russo de Kainsk na estepe de Baraba", "b14552a8"], "d": ["Das três fortificações russas permanentes (pas) fundadas na estepe de Baraba, o pas de Kainsk foi fundado no curso médio do rio Om, onde desagua o ribeiro Kainka.", "17a78ef2"]},
"OLAYLAR_2S_0919:1743-01-01:0":{"b": ["Fundada a fortaleza russa de Troitsk na margem do rio Uy", "623d75f2"], "d": ["Troitsk foi fundada como fortaleza onde o Uvelka se junta ao rio Uy e recebeu em 1784 o diploma de cidade.", "49367d34"]},
"OLAYLAR_2S_0919:1749-12-15:0":{"b": ["Por édito de Elizaveta, fundada a alfândega de Temernik na foz do Don (núcleo de Rostov)", "46519168"], "d": ["A imperatriz Elizaveta Petrovna promulgou o édito de criação de uma alfândega no Don, na foz do rio Temernik; a alfândega de Temernik é o início da história primitiva da cidade de Rostov-na-Donu.", "51a82ea9"]},
"OLAYLAR_2S_0919:1750-01-01:0":{"b": ["Os franceses fundam um posto comercial em Toronto, sobre o Humber", "18975f4c"], "d": ["Os franceses fundaram um segundo posto no rio Humber; no ano seguinte construíram o Fort Rouillé no atual Exhibition Place.", "66aeb450"]},
"OLAYLAR_2S_0919:1751-01-01:0":{"b": ["Ahmed Şah Dürrânî incorpora Balkh no seu país", "12c6bbf1"], "d": ["O soberano afegão Ahmed Şah Dürrânî incorporou Balkh na sua área de soberania.", "e3ef9016"]},
"OLAYLAR_2S_0919:1752-01-01:0":{"b": ["Fundada a fortaleza russa de Petropavlovsk nas margens do Ishim", "5d16ef42"], "d": ["Petropavlovsk foi fundada como fortaleza russa e tornou-se em pouco tempo um importante centro do comércio entre a Rússia e a Ásia Central e a estepe cazaque.", "f0724528"]},
"OLAYLAR_2S_0919:1759-01-01:0":{"b": ["Os tuaregues de Agadez tomam ao Kanem-Bornu as salinas de Bilma", "1a563a74"], "d": ["O Kanem-Bornu, em declínio no século XVIII, perdeu muitos povoados do Saara quando, em 1759, os tuaregues de Agadez lhe tomaram as salinas de Bilma.", "ebfc53c3"]},
"OLAYLAR_2S_0919:1806-01-01:0":{"b": ["O exército de jihad de Osman b. Fûdî toma Zaria", "41279ca7"], "d": ["Durante a jihad iniciada por Osman b. Fûdî, embora o primeiro ataque a Alkalawa, capital de Gobir, tenha falhado, Zaria foi tomada em 1806.", "680cebf3"]},
"OLAYLAR_2S_0919:1808-01-01:0":{"b": ["Fundada a cidade de Sultânâbâd (Erâk)", "674237a0"], "d": ["No período qajar, o general Yûsuf Han Gürcî fundou a atual cidade de Erâk e deu-lhe o nome de Sultânâbâd.", "6ff3f6de"]},
"OLAYLAR_2S_0919:1818-01-01:0":{"b": ["Fundada a povoação de Beaufort (Beaufort West)", "c5cb1776"], "d": ["Na Colónia do Cabo britânica, foi fundada a povoação de Beaufort na quinta de Hooyvlakte, no Karoo.", "70ea5620"]},
"OLAYLAR_2S_0919:1826-01-01:0":{"b": ["Balkh sofre a ocupação do emir de Bucara", "cd255a5d"], "d": ["Balkh, sob domínio afegão durrani, sofreu em 1826 a ocupação do emir de Bucara; a cidade foi retomada em 1841 pelos afegãos.", "a3ecb1be"]},
"OLAYLAR_2S_0919:1830-01-01:0":{"b": ["A Rússia funda a fortaleza de Akmola no Ishim", "6c727ca9"], "d": ["A Rússia construiu a fortaleza de Akmola em Karautkul, no rio Ishim, fazendo dela a povoação central do país dos quirguizes da Sibéria (cazaques).", "9e7d586f"]},
"OLAYLAR_2S_0919:1847-01-01:0":{"b": ["Fundada a fortificação de Kopal — o Semirechye Setentrional começa a ser ligado à Rússia", "8d4c24c6"], "d": ["A Rússia fundou a fortificação de Kopal no sopé do Alatau do Semirechye, a pedido dos cazaques da Horda Maior. Segundo a fonte, isto facilitou a incorporação na Rússia do Semirechye Setentrional até ao rio Ili.", "ebe25fc6"]},
"OLAYLAR_2S_0919:1852-01-01:0":{"b": ["Mercadores da costa instalam-se em Kazeh (Tabora)", "173223b0"], "d": ["Depois de um conflito com um soberano local, os mercadores vindos da costa da África Oriental emigraram para o sul; o chefe de Unyanyembe, Fundikira, deu-lhes um lugar de instalação perto do seu centro, Itetemia. Este povoado tornou-se o núcleo do centro de caravanas de Tabora.", "1261b92f"]},
"OLAYLAR_2S_0919:1861-01-01:0":{"b": ["Os Fûlânîs de el-Hâc Ömer tomam Cenne", "aa4e37f8"], "d": ["Cenne, onde o Estado de Mâsînâ mantinha uma guarnição, passou em 1861 para as mãos dos Fûlânîs sob o comando de el-Hâc Ömer.", "bfbc8ebe"]},
"OLAYLAR_2S_0919:1862-05-16:0":{"b": ["El-Hâc Ömer toma Hamdullahi — fim do Estado de Mâsînâ", "542f1c0d"], "d": ["As tropas aliadas de Mâsînâ, onde se refugiara Bina Ali, fugido de Segu, foram derrotadas; Hamdullahi, o centro de Mâsînâ, passou para as mãos de el-Hâc Ömer, e Bina Ali e Ahmedü Ahmedü foram executados.", "213cc232"]},
"OLAYLAR_2S_0919:1880-06-13:0":{"b": ["Brazza funda Franceville", "d28410d7"], "d": ["Pierre Savorgnan de Brazza fundou, em nome da França, o posto de Franceville numa saliência rochosa que dá para o rio Mpassa.", "c23dd54e"]},
"OLAYLAR_2S_0919:1885-02-14:0":{"b": ["Convenção de fronteira entre o Estado Livre do Congo e Portugal — a margem sul da foz do Congo para Portugal", "08a16627"], "d": ["Pela convenção assinada durante a Conferência de Berlim, a fronteira entre o Estado Livre do Congo e Portugal foi traçada, da foz do rio Congo (Zaire) ao ribeiro Uango-Uango, pelo próprio rio; a margem sul, onde está Soyo, ficou com Portugal, e Cabinda, a norte do rio, ficou também com Portugal.", "947cb572"]},
"OLAYLAR_2S_0919:1888-05-01:0":{"b": ["A costa do Hadramaute (Mukalla) entra na proteção britânica", "dc824725"], "d": ["Foi assinado um tratado de proteção entre a Inglaterra e os Yâfiîs (Kuaytîs), que dominavam a costa do Hadramaute, incluindo Shihr e Mukalla; os ingleses assumiram inteiramente as relações externas da administração yâfiî na costa.", "98bd94ee"]},
"OLAYLAR_2S_0919:1890-01-01:0":{"b": ["Os franceses dominam toda a Colof", "c6d28eaa"], "d": ["Os franceses, que colonizaram a região por acordos com chefes de tribos, dominaram em 1890 toda a Colof.", "15595659"]},
"OLAYLAR_2S_0919:1893-01-01:0":{"b": ["Cenne ocupada pelos franceses", "b207bf62"], "d": ["Cenne, que estava em mãos do Estado fundado por el-Hâc Ömer, foi ocupada em 1893 pelas forças francesas e incorporada no Sudão Francês.", "5739cdc4"]},
"OLAYLAR_2S_0919:1894-01-01:0":{"b": ["Gweru fundada como posto militar", "bd37b323"], "d": ["No centro do atual Zimbabué, a cidade de Gweru foi fundada como posto militar; tornou-se depois centro agrícola e recebeu em 1914 o estatuto de município.", "a8f323b9"]},
"OLAYLAR_2S_0919:1897-01-01:0":{"b": ["O Sultanato de Bagirmi entra na proteção francesa", "59f20c32"], "d": ["Perante a ameaça de Râbih, o soberano de Bagirmi, Gavrang, fez com a França um tratado de proteção forçado. Quando Râbih, reagindo a isso, se dirigiu à ocupação de Bagirmi, Gavrang queimou ele próprio a capital, Masinya.", "fcb0958f"]},
"OLAYLAR_2S_0919:1897-10-01:0":{"b": ["O Reino de Kaffa incorporado na Abissínia — o último rei Gaki Sheroçço feito prisioneiro", "c03c44c5"], "d": ["As forças de Menelik II, comandadas por Ras Walda Giyorgis, entraram em Kaffa em março de 1897. Depois de duros combates, Kaffa foi conquistada; o último rei, Gaki Sheroçço, foi capturado e rendeu-se em outubro de 1897.", "a434cc44"]},
"OLAYLAR_2S_0919:1898-01-01:0":{"b": ["Gao ocupada pelos franceses", "01eabb4c"], "d": ["Gao, antiga capital songai nas margens do Níger, foi ocupada em 1898 pelos franceses; depois da ocupação, a cidade voltou a crescer e tornou-se o centro da região.", "653ce49b"]},
"OLAYLAR_2S_0919:1899-01-01:0":{"b": ["Fundado o depósito de abastecimento de Nairobi da Ferrovia do Uganda", "a3ce3389"], "d": ["Na zona pantanosa, até então em grande parte desabitada, onde hoje se situa Nairobi, os ingleses estabeleceram o depósito de abastecimento da Ferrovia do Uganda, que ligava Mombaça ao Uganda.", "467c7577"]},
"OLAYLAR_2S_0919:1901-01-01:0":{"b": ["Adamawa repartida — Yola permanece na Nigéria do Norte Britânica", "11104686"], "d": ["Adamawa foi repartida entre a Nigéria do Norte, ligada à Inglaterra, e os Camarões, ligados à Alemanha; Bobbo Ahmedü, quarto filho de Adama, tornou-se emir de Yola na zona britânica.", "aabd087e"]},
"OLAYLAR_2S_0919:1903-07-27:0":{"b": ["Batalha de Burmi — termina o domínio político do Califado de Sokoto", "c7d87e2c"], "d": ["O califa Muhammed Tâhir, que fugira depois da ocupação de Sokoto pelos ingleses, foi morto numa nova guerra contra os ingleses; terminou o domínio político do califado de Sokoto, que durara cerca de um século.", "b37ec3fb"]},
"OLAYLAR_2S_0919:1904-01-01:0":{"b": ["Nakuru oficialmente fundada como povoação", "d82a2d76"], "d": ["Graças à sua posição na Ferrovia do Uganda, Nakuru foi oficialmente fundada como povoação e tornou-se o centro dos produtos agrícolas da região.", "bf30445b"]},
"OLAYLAR_2S_0919:1905-01-01:0":{"b": ["Aberta na ferrovia Orenburg-Tashkent a estação do Mar de Aral — fundado o povoado de Aralsk", "85803dcb"], "d": ["Quando a ferrovia do Império Russo que liga Orenburg a Tashkent passou pela extremidade nordeste do Mar de Aral, foi aberta na costa a estação 'Aralskoye More'; junto à estação nasceu um povoado de pescadores. O povoado recebeu em 1938 o estatuto de cidade e o nome de Aralsk.", "99e15bce"]},
"OLAYLAR_2S_0919:1909-06-02:0":{"b": ["Os franceses tomam Abéché — fim do Sultanato de Ouaddaï", "3c9b117b"], "d": ["Os franceses, que prosseguiam o avanço para leste, tomaram Abéché (Ebîşe), capital de Ouaddaï, pondo fim ao Sultanato de Ouaddaï; o último sultão retirou-se sem ter podido salvar a capital.", "1f305da8"]},
"OLAYLAR_2S_0919:1910-05-31:0":{"b": ["Fundada a União Sul-Africana", "7434a47f"], "d": ["Em conformidade com o South Africa Act de 1909, as colónias do Cabo, de Natal, do Transvaal e do Rio Orange uniram-se a 31 de maio de 1910 com o nome de União Sul-Africana, ligada ao Império Britânico; o centro executivo foi Pretória e o centro legislativo Cidade do Cabo.", "4fed5a23"]},
"OLAYLAR_2S_0919:1911-01-01:0":{"b": ["Os franceses ocupam Canet (Djanet)", "f32997c8"], "d": ["Canet, nahiye otomana ligada a Gat, foi ocupada em 1911 pelos franceses. O diretor da nahiye, o xeque Amud, recebera até essa data um salário do Estado Otomano.", "7075093e"]},
"OLAYLAR_2S_0919:1915-01-01:0":{"b": ["Anchorage fundada como centro da Ferrovia do Alasca", "f5014711"], "d": ["Depois de o Congresso ter aprovado o Alaska Railroad Act a 12 de março de 1914, na primavera de 1915 a Comissão de Engenharia do Alasca estabeleceu o estaleiro da ferrovia em Ship Creek; nasceu na costa uma cidade de tendas e, em abril de 1915, a administração dos correios deu à nova povoação o nome de Anchorage. A cidade tornou-se o centro da Ferrovia do Alasca, que se estende para norte até Fairbanks.", "ffe4cba5"]},
"OLAYLAR_7A4170:1856-01-01:0":{"b": ["A ligação de Jaghbub, centro desértico da Senûsiyye, à ordem otomana — o firmão de isenção de Abdülmecid", "039fce6d"], "d": ["Muhammed b. Ali es-Senûsî, que passara muitos anos em Meca, ao regressar a Trípoli de Barbaria fixou-se no oásis de Jaghbub, na fronteira do Egito, e mandou construir uma grande zâviye sobre a rocha dominante; o lugar, que era apenas algumas barracas, converteu-se em pouco tempo numa cidade. Em 1856, por firmão do sultão Abdülmecid, os bens pertencentes aos membros da confraria foram isentados de imposto e foi dada aos discípulos a competência de cobrar a zakat. Este firmão fez do oásis, situado na rota de caravanas que liga a África Ocidental e o Sudão ao Cairo, parte da ordem financeira e administrativa otomana e reforçou Jaghbub como centro comercial. A lealdade da população da região ao califa é também confirmada pelo diário de viagem do coronel Sâdık el-Müeyyed, que visitou o lugar em 1884 e 1893.", "dbe926fd"]},
"OLAYLAR_7A4170:1859-04-25:0":{"b": ["O início da escavação do Canal do Suez e a fundação de Port Said", "cef0be8d"], "d": ["Os trabalhos de escavação do projeto de Lesseps, aprovado pela Sublime Porta a 5 de janeiro de 1856, começaram a 25 de abril de 1859; o canal seria concluído dez anos depois, a 16 de novembro de 1869. Na extremidade mediterrânica da escavação, na faixa costeira entre o lago Menzaleh e o mar, a aldeia de barracas de cinco casas fundada para os operários constituiu o núcleo de Port Said. À cidade, os responsáveis da companhia do canal deram em 1860 este nome, que significa 'porto de Said', em homenagem ao então governador do Egito, Said Paxá. Surgiu assim no mapa otomano um novo porto numa faixa costeira onde antes não havia nenhum povoamento.", "3e95556e"]},
"OLAYLAR_7A4170:1863-04-03:0":{"b": ["A visita do sultão Abdülaziz ao Egito e a fundação de Ismaília no istmo de Suez", "bcfacf38"], "d": ["O sultão Abdülaziz foi ao Egito a 3 de abril de 1863, por incentivo do grão-vizir Yûsuf Kâmil Paxá, e foi recebido com grandes manifestações; o objetivo era reforçar a ligação ao centro da província que, desde a revolta de Mehmed Ali Paxá de Cavala, começara a assumir de facto o aspecto de um Estado separado. No mesmo ano, no istmo, nas colinas de Tilâlülcisr, à beira do lago Timsah, foi fundado o centro administrativo da companhia do canal: primeiro foi estabelecida a aldeia de Karyetüttimsah para os engenheiros e, depois, a de Karyetülarab para os operários. Como o quediva İsmâil Paxá se interessou de perto pelo canal de água doce e mandou construir um palácio nesta colina, o povoamento ficou conhecido pelo seu nome, İsmâiliye. A fundação da cidade data do ano de 1863; o dia exato não é conhecido.", "bab96585"]},
"OLAYLAR_7A4170:1869-01-01:0":{"b": ["O governo de Midhat Paxá em Bagdade e o assentamento das tribos — a fundação de Ramadi e Nasiriya", "0fa98f06"], "d": ["Midhat Paxá, retirado da presidência do Şûrâ-yı Devlet e afastado de Istambul, governou entre 1869 e 1872 a província de Bagdade, que abrangia também Mossul e Bassorá, com amplos poderes e detendo também o comando do Sexto Exército. Aplicando aqui o Código de Terras e a nova lei das províncias, distribuiu as terras com registo predial e ligou as tribos nómadas à vida sedentária e à autoridade do Estado. Como produto desta política de assentamento, em 1869 foi fundada na margem do Eufrates Ramadi, para a tribo Dulaym, e, no sul, Nasiriya, por obra do mutasarrıf dos Müntefik, Nâsır Paxá es-Sa'dûn; ambas nasceram em pontos onde até então não existia povoamento e entraram no mapa pela primeira vez nesta data.", "7babb36f"]},
"OLAYLAR_AMERIKA0920:1511-08-15:0":{"b": ["Fundada Baracoa — a primeira povoação da conquista espanhola de Cuba", "8c033cf1"], "d": ["Diego Velázquez de Cuéllar iniciou em 1511 a conquista de Cuba com a força que trouxe de Hispaniola e fundou Nuestra Señora de la Asunción de Baracoa, a primeira povoação espanhola da ilha. Baracoa foi a região-base das expedições dos vinte anos seguintes dirigidas ao México (Hernández de Córdoba, Grijalva, Cortés).", "e3cd5e94"]},
"OLAYLAR_AMERIKA0920:1519-03-25:0":{"b": ["Batalha de Centla — cai o senhorio maia de Potonchán, fundada Santa María de la Victoria", "8489a7d8"], "d": ["A frota de Cortés, partida de Cuba, desembarcou em Potonchán, cidade maia chontal na foz do rio Grijalva. Os espanhóis, vencedores na batalha da planície de Centla pela superioridade da cavalaria e das armas de fogo, fundaram no lugar da cidade a povoação de Santa María de la Victoria. É o primeiro povoado espanhol duradouro no continente mexicano; Malintzin (doña Marina), que serviria de intérprete a Cortés, esteve entre os presentes aqui oferecidos.", "8bbece52"]},
"OLAYLAR_AMERIKA0920:1519-08-15:0":{"b": ["Fundado o Panamá — a primeira cidade europeia na costa do Pacífico", "c0d86c22"], "d": ["Pedrarias Dávila, governador de Darién, fundou a cidade do Panamá na vertente do istmo voltada para o Pacífico e transferiu para aí a administração colonial, que estava na costa das Caraíbas. A cidade tornou-se o porto de partida das expedições de exploração e conquista dirigidas para o sul; as expedições de Francisco Pizarro ao Peru foram aqui equipadas.", "ce7e51d9"]},
"OLAYLAR_AMERIKA0920:1520-09-04:0":{"b": ["Tomada de Tepeaca — a primeira conquista de Cortés depois da Noche Triste", "a9c27711"], "d": ["Cortés, que se retirara de Tenochtitlan com pesadas perdas na noite de 30 de junho de 1520 (Noche Triste), depois de se refugiar em Tlaxcala, fez o seu primeiro ataque ao senhorio de Tepeaca, ligado à Tríplice Aliança. Tomou a cidade e fundou uma povoação espanhola com o nome de Segura de la Frontera; assim, o caminho entre a costa de Veracruz e Tlaxcala ficou assegurado e preparou-se a base da segunda marcha sobre a capital.", "a7a4b070"]},
"OLAYLAR_AMERIKA0920:1523-07-25:0":{"b": ["Fundada San Sebastián de Colima — a Nova Espanha abre-se à costa do Pacífico", "30332cab"], "d": ["Gonzalo de Sandoval, um dos comandantes de Cortés, submetendo o vale de Colima, no oeste do México, fundou a povoação de San Sebastián de Colima. A povoação tornou-se uma das primeiras bases da Nova Espanha na costa do Pacífico e alimentou nos anos seguintes os estaleiros das expedições de exploração do Mar do Sul.", "f5225860"]},
"OLAYLAR_AMERIKA0920:1534-12-06:0":{"b": ["Fundada San Francisco de Quito — a ordem espanhola na capital incaica do norte", "7bb9f316"], "d": ["O general inca Rumiñahui queimou Quito, a capital do norte, antes de a deixar aos espanhóis. Sebastián de Benalcázar fundou sobre as ruínas San Francisco de Quito; assim, depois de Cuzco, o segundo centro do Estado inca ficou também ligado à administração espanhola e a conquista dos Andes do Norte foi conduzida a partir daqui.", "569e8d50"]},
"OLAYLAR_AMERIKA0920:1535-01-18:0":{"b": ["Fundada Lima — a capital do Peru espanhol transferida para o vale do Rímac", "1f15658c"], "d": ["Francisco Pizarro, por Cuzco, nas montanhas, ficar longe da ligação marítima com a Espanha, fundou no vale costeiro do Rímac a Ciudad de los Reyes (Lima). A cidade tornou-se em pouco tempo a capital do Vice-Reinado do Peru e o centro da administração espanhola na América do Sul.", "97bcf9d0"]},
"OLAYLAR_AMERIKA0920:1537-01-13:0":{"b": ["Fundada Popayán — a ponte entre Quito e o país dos Muisca", "bf451979"], "d": ["Benalcázar, que marchava de Quito para norte, fundou Popayán no vale do Cauca. A cidade tornou-se o extremo norte do avanço espanhol vindo do Peru e abriu o caminho que, no ano seguinte, conduziria ao seu encontro com Quesada no país dos Muisca.", "fe54a6a7"]},
"OLAYLAR_AMERIKA0920:1537-08-01:0":{"b": ["Tomada de Hunza — derrota do zaque Quemuenchatocha", "e8c1b661"], "d": ["Gonzalo Jiménez de Quesada, que subira ao planalto desde o rio Magdalena, invadiu Hunza, centro do zacazgo, uma das duas cabeças da Confederação Muisca, e fez prisioneiro o zaque Quemuenchatocha. O ouro capturado na cidade foi o verdadeiro saque que alimentou o rumor do El Dorado; a metade norte do país dos Muisca entrou assim no domínio espanhol.", "78bf5be1"]},
"OLAYLAR_AMERIKA0920:1537-08-15:0":{"b": ["Fundada Asunción — base espanhola no rio Paraguai", "9a6dfa42"], "d": ["Como a expedição do Río de la Plata não se manteve em Buenos Aires, os espanhóis recuaram rio acima e Juan de Salazar de Espinosa, apoiando-se na aliança estabelecida com as comunidades guaranis, fundou Nuestra Señora de la Asunción. A povoação permaneceu durante um século o centro da administração espanhola na bacia do Río de la Plata.", "451f5b55"]},
"OLAYLAR_AMERIKA0920:1538-08-06:0":{"b": ["Fundada Santa Fe de Bogotá — capital espanhola no país dos Muisca", "3ed6c301"], "d": ["Quesada fundou Santa Fe de Bogotá junto de Bacatá, centro do zipa. Logo depois da fundação, as colunas de conquista vindas de três direções diferentes — Quesada, Benalcázar e o comandante alemão Federmann — encontraram-se no mesmo planalto e acordaram em resolver as suas pretensões em Espanha. A cidade tornou-se a capital do Reino de Nova Granada.", "cd8c76fd"]},
"OLAYLAR_AMERIKA0920:1539-01-09:0":{"b": ["Fundada San Juan de la Frontera de Huamanga — a fechadura da estrada Lima-Cuzco", "3f1cfdbf"], "d": ["A resistência que Manco Inca conduzia a partir de Vilcabamba cortava a estrada entre Lima e Cuzco. Francisco Pizarro, para assegurar esta estrada, fundou San Juan de la Frontera de Huamanga a meio caminho entre as duas capitais; o 'frontera' (fronteira) do nome da povoação diz diretamente o objetivo da fundação.", "fcd683ec"]},
"OLAYLAR_AMERIKA0920:1539-08-06:0":{"b": ["Tunja refundada como cidade espanhola", "c3a12867"], "d": ["Depois do regresso de Quesada a Espanha, Gonzalo Suárez Rendón refundou, no lugar de Hunza, centro do zaque, a cidade de Tunja segundo a ordem espanhola. Assim, a metade norte do país dos Muisca, tal como a de Bogotá, ficou ligada a uma ordem duradoura de município e de encomienda.", "fdbb81cc"]},
"OLAYLAR_AMERIKA0920:1540-10-04:0":{"b": ["Fundada San Francisco de Campeche — terceira e duradoura tentativa da conquista do Iucatão", "62af9901"], "d": ["Depois de duas expedições falhadas para tomar o Iucatão, Francisco de Montejo (o filho) fundou, no lugar da cidade maia de Can Pech, a povoação de San Francisco de Campeche. Este porto tornou-se a base de abastecimento das forças que marchariam para o interior da península e constituiu o ponto de partida da expedição que, dois anos depois, resultaria na fundação de Mérida.", "079bb50a"]},
"OLAYLAR_AMERIKA0920:1541-02-12:0":{"b": ["Fundada Santiago del Nuevo Extremo — começa a conquista do Chile", "04cd7c3b"], "d": ["Pedro de Valdivia, que marchava do Peru para o sul, fundou Santiago del Nuevo Extremo no vale do Mapocho. A povoação foi queimada em setembro do mesmo ano num ataque indígena liderado por Michimalonco e refundada; apesar disso, a conquista espanhola do Chile foi conduzida a partir deste ponto.", "7cfe7c18"]},
"OLAYLAR_AMERIKA0920:1545-01-01:0":{"b": ["O senhorio dos Cocom em Sotuta entra no domínio espanhol", "db6a6487"], "d": ["Sotuta, um dos mais poderosos senhorios maias do interior do Iucatão, resistiu durante muito tempo ao avanço espanhol sob a dinastia Cocom. Nos anos que se seguiram à fundação de Mérida, em 1542, o senhorio aceitou o domínio espanhol; depois de reprimida a grande revolta do leste de 1546-47, esta vassalagem tornou-se duradoura.", "461a3b98"]},
"OLAYLAR_AMERIKA0920:1571-08-15:0":{"b": ["Fundada Villa de Oropesa — povoamento do vale de cereais que alimentaria Potosí", "d6821cbf"], "d": ["Por ordem do vice-rei Francisco de Toledo, foi fundada Villa de Oropesa no vale de Cochabamba. A terra fértil do vale foi organizada como região de cereais para alimentar a numerosa mão de obra das minas de prata de Potosí; a povoação tornou-se o celeiro do Alto Peru colonial.", "52cdfafe"]},
"OLAYLAR_AMERIKA0920:1572-06-24:0":{"b": ["A queda de Vilcabamba — fim do Estado inca independente", "31b5a95d"], "d": ["Depois da queda de Cuzco, em 1533, Manco Inca e os seus sucessores mantiveram durante quarenta anos nas montanhas de Vilcabamba um Estado inca independente. A expedição organizada pelo vice-rei Francisco de Toledo tomou a capital abandonada; o último soberano, Túpac Amaru, que fugira, foi capturado, trazido a Cuzco e aí executado. A existência política da dinastia inca, de quatro séculos, terminou assim no mundo andino.", "957d76a8"]},
"OLAYLAR_AMERIKA0920:1596-09-20:0":{"b": ["Fundada Monterrey — a capital de Nuevo León", "ec6e44bc"], "d": ["Diego de Montemayor, depois de duas tentativas falhadas, fundou junto à nascente de Santa Lucía a Ciudad Metropolitana de Nuestra Señora de Monterrey. Este povoado na fronteira norte tornou-se o ponto de apoio da expansão duradoura da Nova Espanha para nordeste (Nuevo León).", "6bfa991f"]},
"OLAYLAR_AMERIKA0920:1619-01-01:0":{"b": ["Fundada San Francisco de Borja — domínio espanhol em Maynas", "7ee32d19"], "d": ["Diego Vaca de Vega, fundando San Francisco de Borja a jusante do desfiladeiro de Pongo de Manseriche, no rio Marañón, ligou a região de Maynas à administração espanhola. A povoação foi o ponto de partida da rede de missões jesuítas que duraria o século seguinte no alto Amazonas.", "83ae5281"]},
"OLAYLAR_AMERIKA0920:1718-05-01:0":{"b": ["Fundada a missão de San Antonio de Valero — o núcleo do Texas espanhol", "ca9bd147"], "d": ["Em resposta à infiltração dos franceses para oeste a partir da Luisiana, a Espanha decidiu estabelecer uma linha duradoura no Texas. O padre Olivares fundou a missão de San Antonio de Valero nas margens do rio San Antonio; poucos dias depois, o governador Alarcón colocou ao seu lado o presídio de San Antonio de Béxar. O edifício da missão será depois conhecido pelo nome de Alamo.", "74e48544"]},
"OLAYLAR_AMERIKA0920:1774-01-01:0":{"b": ["Fundado Refugio (atual Matamoros) — povoamento da foz do Rio Grande", "f3b86da7"], "d": ["O programa de povoamento de Nuevo Santander, conduzido por José de Escandón desde a década de 1740, encheu a bacia inferior do Rio Grande de quintas e povoações. Nuestra Señora del Refugio de los Esteros foi fundada na margem sul do rio como um dos últimos elos deste programa; recebeu no século XIX o nome de Matamoros.", "913bb307"]},
"OLAYLAR_AMERIKA0920:1821-09-15:0":{"b": ["Ata de Independência da América Central — a Capitania-Geral da Guatemala separa-se da Espanha", "f998089a"], "d": ["Depois do Plano de Iguala no México, a assembleia reunida na Guatemala proclamou a independência da Capitania-Geral em relação à Espanha; o capitão-general Gabino Gaínza permaneceu à frente da administração de transição. Terminou assim o domínio espanhol nos territórios da atual Guatemala, de El Salvador, das Honduras, da Nicarágua e da Costa Rica. A região, depois de ter sido por pouco tempo incorporada no Império Mexicano, fundou em 1823 as Províncias Unidas da América Central.", "c4e39cd1"]},
"OLAYLAR_AMERIKA0920:1839-01-01:0":{"b": ["Fundada Nueva Helvetia — o México abre o vale do Sacramento ao povoamento", "067a1f2a"], "d": ["O imigrante suíço John Sutter, com a licença e a concessão de terras que obteve das autoridades mexicanas, fundou Nueva Helvetia na confluência dos rios Sacramento e American. A quinta fortificada tornou-se o posto mais avançado do México no interior da Alta Califórnia; com a descoberta do ouro em 1848, transformar-se-á no centro da migração para a Califórnia.", "1c5eab3d"]},
"OLAYLAR_EBUKIR0919:1798-08-01:0":{"b": ["Batalha naval de Abukir (do Nilo) — destruição da armada de Napoleão", "be4ad8d8"], "d": ["A armada francesa que transportava o exército de Napoleão para o Egito, enquanto esperava fundeada na baía de Abukir, foi apanhada pela esquadra do almirante inglês Nelson e destruída numa batalha que durou uma noite; a nau-almirante L'Orient explodiu. Nelson privou assim o exército terrestre da França no Egito do apoio naval: o exército não podia nem receber reforços nem regressar. Cinco semanas depois, o Estado Otomano declarou também guerra à França.", "9f27937f"]},
"OLAYLAR_EBUKIR0919:1799-07-25:0":{"b": ["Batalha terrestre de Abukir — derrota de Köse Mustafa Paxá", "35a695f3"], "d": ["Napoleão, que regressava derrotado de diante de Acre, derrotou em Abukir as forças otomanas comandadas por Köse Mustafa Paxá e a Fortaleza de Abukir passou para as mãos dos franceses. Esta costa, onde um ano antes a armada francesa afundara, seria, dois anos depois, o lugar onde desembarcaria o exército inglês que vinha expulsar os franceses do Egito (8 de março de 1801).", "da0b6c57"]},
"OLAYLAR_EK10:1402-07-28:0":{"b": ["Depois do desastre de Ancara, o voivoda da Valáquia Mircea retomou a Dobruja — Silistre, Constança, Babadag, İshakçı", "5eaefc68"], "d": ["A derrota de Bajazeto I para Timur em Ancara abalou o domínio otomano ao longo do Danúbio. O voivoda da Valáquia, Mircea, aproveitando este vazio, entrou de novo na Dobruja; Silistre, Constança, os arredores de Babadag e İshakçı, na margem do Danúbio, ficaram durante os anos do Interregno nas suas mãos. Mircea apoiou Mûsâ Çelebi contra Çelebi Mehmed. Manteve Silistre até à sua morte, em 1418.", "58dabbe8"]},
"OLAYLAR_EK10:1416-01-01:0":{"b": ["A passagem de Babadag e arredores para os otomanos — Mircea e o filho Mihail foram derrotados", "bfda2c60"], "d": ["Çelebi Mehmed, depois de derrotar o voivoda da Valáquia Mircea e o filho Mihail, pôs sob domínio otomano Babadag e os arredores, na Dobruja do Norte. Babadag era uma vila que levava o nome de Saltuk Baba e fora fundada com um povoamento turcomano do século XIII. As fortalezas circundantes de Silistre, Constança e as outras fortalezas da Dobruja permaneceram na Valáquia até 1419; ou seja, Babadag aparece durante três anos como uma ilha (exclave) separada do território otomano.", "b1e2339a"]},
"OLAYLAR_EK10:1419-01-01:0":{"b": ["A reconquista de Silistre e da Dobruja — depois da morte de Mircea", "73eb6ae9"], "d": ["A confusão que surgiu na Valáquia depois da morte do voivoda Mircea, em 1418, deu a Çelebi Sultão Mehmed a oportunidade de recuperar Silistre e a Dobruja. Na primavera de 1419, Silistre, Constança e a maior parte da Dobruja voltaram à administração otomana; as fortalezas de Enisala (Yenisale) e İshakçı foram reparadas e feitas fortalezas de fronteira (serhat); a Dobruja permaneceu depois disso otomana até 1878.", "a2a9ad4e"]},
"OLAYLAR_EK10:1420-01-01:0":{"b": ["O encerramento do Baixo Danúbio — a anexação de Yergöğü, Turnu e Orșova", "331a0b68"], "d": ["Depois de encerrado o Interregno, a iniciativa de Çelebi Mehmed para pôr em ordem a linha do Danúbio deu fruto em 1420. A Fortaleza de Yergöğü, que o voivoda da Valáquia Koca Mircea mandara construir no seu próprio território, cobrindo a despesa com a venda de sal, passou neste ano para as mãos otomanas (a Dobruja fora retomada um ano antes, na primavera de 1419 — TDV silistre) e foram anexadas Turnu (Kule/Holovnik) e Orșova — depois chamada Fethülislâm —, na margem direita do Danúbio. Assim, as duas margens do rio ficaram ao mesmo tempo sob controlo. A importância de Yergöğü decorre da sua geografia: é uma fortaleza otomana estabelecida na margem esquerda, isto é, a da Valáquia, do Danúbio e, juntamente com Ruse, na margem oposta, guarda as duas extremidades da mesma passagem. Os documentos otomanos escrevem explicitamente esta dualidade — para Ruse diz-se 'Yergöğü da margem de cá', para Giurgiu 'Yergöğü da margem de lá'. A fortaleza seria retomada pelos valáquios em 1427, entraria de novo no controlo otomano em 1449 e, com o kaza de Yergöğü ligado ao sanjaco de Nikopol, tornar-se-ia uma ilha governada diretamente dentro do voivodado. A resposta à pergunta, no mapa, de por que razão a margem do Danúbio da Valáquia é de cor escura começa aqui.", "4c3c95d4"]},
"OLAYLAR_EK10:1433-01-01:0":{"b": ["A região de Toplica (Kurşunlu, Ürküp) entrou no domínio otomano", "e22e690d"], "d": ["Considera-se provável que, durante o noivado de Murad II com Mara Branković, a região de Dubočica e Toplica (os arredores de Leskovac, Kurşunlu e Ürküp) tenha passado ao domínio otomano; o registo de recenseamento de 1445-1447 mostra que a região fora dada como timar aos sipahis otomanos. No mapa, Kurşunlu e Ürküp estão sob administração otomana a partir deste ano.", "335352f1"]},
"OLAYLAR_EK10:1448-01-01:0":{"b": ["A anexação da planície de Saray — o estabelecimento da ponta otomana dentro da Bósnia", "be5c0f00"], "d": ["Depois de os reis da Bósnia terem sido sujeitos a tributo em 1428-1429, os otomanos começaram a instalar-se de forma duradoura no interior do reino. Entre 1428 e 1435 foi tomada a vila de Hodidjed; em 852 (1448), a província de Hodidjed, com a planície de Saray, entrou por completo na administração otomana. Trata-se de uma zona de fronteira estabelecida no meio do reino quinze anos antes da conquista da Bósnia e administrada por Îsâ Bey, bei de Üsküp, que tinha o título de voivoda — como à sua volta havia ainda beis bósnios sujeitos aos otomanos, a região estava sob controlo duplo. A própria cidade nasceu também nesta época: antes de 1462, İshak Bey ou o filho Îsâ Bey fundou o primeiro bairro muçulmano, em 862 (1458) foi construída em nome do Conquistador a Mesquita de Hünkâr e, valorizando-se o campo da aldeia de Brodec, surgiu a vila de Saray. A conquista de 1463 aboliu o Reino da Bósnia; a planície de Saray, essa, era já nessa data havia quinze anos terra otomana.", "df377352"]},
"OLAYLAR_EK10:1457-01-01:0":{"b": ["A incorporação de Podgorica nas terras otomanas — o controlo da planície de Zeta", "46e401c5"], "d": ["A vila situada vinte quilómetros a norte do lago de Shkodër, na planície onde se juntam as águas do Morača e do Ribnica, é mencionada nas fontes pela primeira vez em 1216 com o nome de Ribnica e em 1326 com o de Podgorica. Em 1457 foi incorporada nas terras otomanas e o controlo da planície de Zeta saiu assim das mãos das dinastias Balšić-Crnojević. O sultão Maomé II, o Conquistador, mandou construir entre 1474 e 1478, nos rochedos escarpados na confluência dos dois rios, uma fortaleza e uma mesquita; em 1479, depois da conquista de Shkodër, a região foi ligada ao recém-criado sanjaco de Shkodër. Podgorica, que no recenseamento de 1485 era uma vila cristã de quarenta casas, chegou em 1529-30 a 800 pessoas e a uma guarnição de trinta e dois homens às ordens de um dizdar na fortaleza e, em 1582, a 322 casas. Evliya Çelebi contou em 1662, na Fortaleza de Fatih, trezentas casas, armazéns, arsenais e setecentos guardas. Estes registos mostram também a diferença entre a planície e a montanha de Zeta: a planície é um kaza otomano recenseado, tributado e com guarnição — ao passo que no século XVIII a cidade teria de ser fortificada com seis bastiões e muralhas de três portas para impedir as incursões das tribos das montanhas de Montenegro. Podgorica passou para as mãos de Montenegro no fim da guerra de 1876-1878 e ficou aí pelo Tratado de Berlim.", "d0b08ff8"]},
"OLAYLAR_EK10:1465-01-01:0":{"b": ["A tomada de Foča — a abertura da primeira entrada para o Ducado da Herzegovina", "f098a9e6"], "d": ["Depois de abolido o Reino da Bósnia em 1463, chegou a vez das terras de Stjepan Vukčić-Kosača, que se separara do reino e fundara o seu próprio ducado. Foča, no vale do Drina, na encruzilhada da rota comercial que liga Istambul a Dubrovnik, entrou em 1465 na administração otomana. A importância da cidade foi logo compreendida: em 1470 foi feita centro do recém-organizado sanjaco da Herzegovina — isto é, o núcleo administrativo da Herzegovina foi estabelecido em Foča antes de o próprio ducado ter caído. A anexação de todo o ducado prolongar-se-ia até 1483. Foča desenvolveu-se depois como centro comercial e administrativo graças ao clima favorável e à sua posição na encruzilhada de caminhos. No mapa, esta data é o dia em que começa a segunda vaga para sul depois da conquista da Bósnia.", "9acfcdda"]},
"OLAYLAR_EK10:1469-01-01:0":{"b": ["A anexação definitiva de Livno e da Bósnia ocidental — o estabelecimento da fronteira com Veneza", "c14d4283"], "d": ["A fortaleza sobre o planalto que domina a planície de Livno esteve, entre 1448 e 1454, nas mãos do fundador do Ducado da Herzegovina, Stjepan Vukčić-Kosača. Na campanha da Bósnia de 1463 fora ocupada por pouco tempo pelas forças otomanas, mas foi retomada no mesmo ano; em 1466, o senhor da cidade é Ivaniš Vlatković. Nas palavras da TDV, o domínio otomano definitivo realizou-se muito provavelmente em 1468-1469 e o recenseamento de 1485 regista já Livno como terra otomana. Foi o fecho da extremidade ocidental da conquista da Bósnia: Livno, vizinha, ao longo da planície, de terras venezianas a apenas trinta e seis quilómetros, tornou-se uma perigosa vila de fronteira e conservou esta posição até 1521-1522, quando o governador da Bósnia, Gazi Hüsrev Bey, tomou as fortalezas venezianas.", "8e012cb5"]},
"OLAYLAR_EK10:1476-02-01:0":{"b": ["A perda de Böğürdelen para os húngaros — a primeira brecha na linha do Sava", "129fe8f2"], "d": ["No local que passara aos otomanos no tempo do sultão Maomé II, o Conquistador, e antes era conhecido pelo nome de Zaslon, fora construído em 1471 um forte de madeira e terra. Por se situar num ponto que ameaçava Belgrado e de onde se podiam fazer facilmente incursões ao sul da Hungria e da Áustria, a fortaleza tirava o nome também desta função — Böğürdelen significa \"bastião que fere de lado\". O rei húngaro Mátyás Corvin cercou a fortaleza por volta do fim de 1475 e tomou-a em fevereiro de 1476. A epopeia húngara Szabács viadala, que narra o cerco, é um dos mais longos exemplos de poesia histórica húngara do século XV cujo texto chegou até hoje. Os húngaros estabeleceram na região um banado e, refortificando a fortaleza em pedra, fizeram dela um elo da cadeia de fortes de fronteira. Os otomanos tentaram recuperá-la em 1492 e não conseguiram; a fortaleza ficou quarenta e cinco anos nas mãos húngaras.", "87ae8b15"]},
"OLAYLAR_EK10:1479-08-01:0":{"b": ["A conquista das ilhas Jónicas — o fim do ducado de Tocco: Ayamavra, Cefalónia, Zante, Ítaca", "07b27251"], "d": ["O Tratado de Istambul, assinado em janeiro do mesmo ano com Veneza, deixara com os otomanos Shkodër e a costa da Albânia; as ilhas Jónicas, porém, estavam sob a administração não de Veneza, mas da família Tocco, que detinha o condado de Cefalónia-Zante, e foram tomadas numa operação separada. Segundo o artigo Ayamavra da TDV, o último duque, Leonardo Tocco, preservara primeiro a sua fidelidade casando com Milica Branković, parente do Conquistador; quando, em 1464, a esposa morreu, em 1477 casou com Francesca Marzano, da dinastia de Nápoles, e desagradou ao sultão. Dois anos depois, a frota comandada por Gedik Ahmed Paxá, senhor de Avlonya, tomou Ayamavra juntamente com Cefalónia, a sul; Leonardo e Francesca fugiram para Itália. O artigo Gedik Ahmed Paşa regista que na mesma operação foi também tomada Zante (Zanta); Ítaca, dependente do condado de Cefalónia, entrou também por este período na administração otomana. Assim, a rota marítima que se estende da boca do Adriático à Moreia ficou inteiramente sob controlo. Das ilhas, Zante seria deixada a Veneza três anos depois, Cefalónia e Ítaca perder-se-iam em 1500, e apenas Ayamavra permaneceria duzentos anos nas mãos otomanas.", "725a61d9"]},
"OLAYLAR_EK10:1482-01-01:0":{"b": ["A sujeição da Zeta dos Crnojević e a ascensão de Cetinje a centro", "59d20267"], "d": ["Com Shkodër a ficar em 1479 com os otomanos, a região montanhosa de Zeta, no seu quintal, caiu também dentro das fronteiras do império. A família Crnojević, que detinha a região, reconhecendo o governo de Bajazeto II, que subira ao trono depois da morte do Conquistador, e sujeitando-se a tributo, ficou livre nos seus assuntos internos; Ivan Crnojević retirou o seu centro da planície e transferiu-o para Cetinje, ao sopé do monte Lovćen, e fundou a cidade. Dois anos depois, o mosteiro que aí mandou construir tornou-se o centro religioso da região. Assim, Montenegro aparece no mapa não como território otomano direto, mas como região sujeita em tom claro. O artigo Karadağ da TDV recorda a dinastia e o bispado de Cetinje e escreve que o domínio se converteu em 1514, por obra de İskender Bey (da linhagem dos Crnojević, criado na corte otomana), num sanjaco separado; o ano de 1482 não figura na TDV, é a data dada pela historiografia montenegrina. Devido à aspereza da geografia, a administração aqui nunca funcionou tão apertada como nas planícies.", "c61bf059"]},
"OLAYLAR_EK10:1484-07-15:0":{"b": ["A conquista da fortaleza de Kili — a chave da foz do Danúbio", "ef4eca73"], "d": ["A Moldávia era, desde setembro de 1455, um voivodado sujeito que pagava anualmente dois mil ducados de ouro de tributo, mas os dois portos que se abrem para o mar Negro continuavam nas mãos do voivoda e o comércio vindo do Danúbio passava por eles. Bajazeto II fez a primeira grande campanha do seu reinado contra estes dois portos. O comandante da fortaleza de Kili, bombardeada dia e noite durante dez dias, foi obrigado a render-se. A fortaleza foi posta sob administração otomana direta e feita beylik de sanjaco; na segunda metade do século XVI, por causa do perigo cossaco, foi feita kaza e ligada ao sanjaco de Akkirman, dependente do beylerbeylik da Rumélia. A partir daqui, a Moldávia aparece no mapa em dois escalões: no interior, o voivodado permanece em tom claro como terra sujeita; os dois portos da costa são, em tom escuro, sanjaco otomano direto. O artigo Boğdan da TDV refere estes dois como 'as chaves e as portas da Moldávia' e escreve que a região ficou definitivamente ligada aos otomanos no tempo de Bajazeto II.", "8b039ea4"]},
"OLAYLAR_EK10:1484-08-04:0":{"b": ["A conquista de Akkirman — o encerramento da foz do Dniestre e da porta marítima da Moldávia", "7cb20feb"], "d": ["Vinte dias depois da rendição de Kili, o exército chegou diante de Akkirman, na foz do Dniestre, e a fortaleza foi tomada a 4 de agosto. A cidade era o porto mais movimentado da Moldávia; no tempo do Conquistador, quando o voivoda Petru III reconheceu em 1455 o domínio otomano, fora concedida licença de comércio aos comerciantes de Akkirman, e agora o porto passou a pertencer diretamente ao Estado. Akkirman, depois da conquista feita sanjaco dependente do beylerbeylik da Rumélia, foi anexada em 1593 à recém-criada província de Özü. Assim, a casca exterior da Moldávia, cingida a norte por Hotin e a sul por Kili e Akkirman, começou a entrar no controlo direto otomano; o voivodado ficou livre nos seus assuntos internos, mas sem saída para o mar. No mapa não há entre eles uma região vazia — os sanjacos portuários em tom escuro e a terra do voivodado em tom claro tocam-se; a estepe de Bucak, entre os dois, é ainda parte do voivodado até 1538.", "23705829"]},
"OLAYLAR_EK10:1499-08-26:0":{"b": ["A rendição de Lepanto — a boca do golfo de Corinto é tomada a Veneza", "2cfe0777"], "d": ["Lepanto estava nas mãos de Veneza desde 1407 e guardava a boca do golfo de Corinto; toda a costa dentro do golfo dependia do alcance desta fortaleza. Na campanha de 1499 a fortaleza foi cercada por terra e a frota otomana, que combatia a frota veneziana ao largo de Lepanto, ajudou por mar as forças de cerco. Os venezianos da fortaleza entregaram a vila aos otomanos a 26 de agosto. A cidade permaneceu cento e oitenta e oito anos nas mãos otomanas, passou de novo a Veneza em 1687, com a perda da Moreia, e foi recuperada em 1715. A batalha naval do mesmo verão e esta rendição são dois acontecimentos distintos: o combate da frota decorreu na extremidade ocidental da Moreia, nas águas de Sapienza-Zonchio; Lepanto, em contrapartida, caiu à boca do golfo de Corinto, com um cerco terrestre.", "49c0fbd8"]},
"OLAYLAR_EK10:1512-01-01:0":{"b": ["A anexação do banado de Srebrenik — a primeira rutura da linha húngara na Bósnia do Norte", "6d98c725"], "d": ["Depois de o Reino da Bósnia ter sido destruído em 1463, Mátyás Corvin passara ao contra-ataque e criara no norte do reino dois banados que detinham o avanço otomano: a oeste Jajce e a nordeste Srebrenik. Eram a linha de defesa avançada da Hungria na Bósnia e fechavam o corredor entre o Sava e a Bósnia. O banado de Srebrenik foi tomado em 1512; assim, o flanco oriental da linha ruiu e o sanjaco de Zvornik pôde alargar-se para norte. Jajce, no flanco ocidental, resistiria ainda dezasseis anos e só poderia ser tomada em 1528, depois de Mohács.", "0d4ad0e7"]},
"OLAYLAR_EK10:1521-07-07:0":{"b": ["A conquista de Böğürdelen — a primeira fortaleza tomada pelo Legislador e o lugar onde se tomou a decisão de Belgrado", "85177a90"], "d": ["As forças do beylerbeyi da Rumélia Ahmed Paxá, enviadas à região na primeira campanha da Hungria do sultão Solimão, o Legislador, tomaram a fortaleza a 7 de julho de 1521, depois de um violento cerco. Böğürdelen é a primeira fortaleza conquistada no reinado do Legislador. O sultão entrou pessoalmente na fortaleza depois da conquista e ordenou o desenvolvimento da cidade; as decisões sobre a conquista de Belgrado foram também aí tomadas — isto é, o plano de Belgrado, que cairia a 29 de agosto de 1521, foi feito em Böğürdelen. A fortaleza permaneceu depois disso cerca de duzentos anos nas mãos otomanas; foi ligada primeiro à Rumélia, desde 1580 à província da Bósnia, em seguida por pouco tempo ao sanjaco de Semendire e, por fim, ao de Zvornik. No mapa, esta data é o dia em que a linha do Sava se fechou a favor dos otomanos.", "8c0178ad"]},
"OLAYLAR_EK10:1594-08-28:0":{"b": ["Começa a revolta dos três voivodados — a Transilvânia passa à Santa Aliança, os beis pró-otomanos são presos", "68a33800"], "d": ["No segundo ano da Longa Guerra, a faixa de vassalos dos otomanos na Europa Central desfez-se de repente. À Santa Aliança, formada sob a proteção do papa Clemente VIII, passaram no fim do verão a Moldávia e a Transilvânia: o voivoda da Moldávia, Aron Vodâ, oficializou por um documento, a 16 de agosto de 1594, a sua adesão ao lado cristão, e o príncipe da Transilvânia, Zsigmond Báthory, a 28 de agosto de 1594, quebrou a oposição interna liquidando os beis pró-otomanos que se opunham à guerra. O voivoda da Valáquia, Mihail, o Valente, aderiu à aliança no outono do mesmo ano. Assim, os três principados sujeitos dos otomanos a norte do Danúbio — três voivodados que havia cento e cinquenta anos pagavam tributo e cujo voivoda era confirmado por Istambul — passaram todos de uma vez, no mesmo outono, para o lado contrário. A decisão foi oficializada pelo tratado assinado em Praga a 28 de janeiro de 1595. Foi o mais pesado abalo sofrido pela ordem de governação indireta otomana no norte dos Balcãs; a revolta seria reprimida, mas a lealdade dos três principados nunca mais seria tão firme como entre 1526 e 1593.", "32a29f3a"]},
"OLAYLAR_EK10:1594-11-01:0":{"b": ["A revolta de Bucareste e o ataque às fortalezas do Danúbio", "18971100"], "d": ["A decisão da Santa Aliança foi aplicada a sangue um mês depois: Mihail, o Valente, passou a fio de espada em Bucareste a guarnição otomana e os credores levantinos da cidade. A revolta propagou-se, no mesmo inverno, à linha do Danúbio; as forças da Valáquia atacaram Yergöğü, İbrail, Hırsova e Silistre, e, do lado da Moldávia, Aron Vodâ fez o mesmo assalto à guarda otomana de Bender. A escolha dos lugares atingidos não é acidental: eram todos fortalezas e kazas não do território do voivodado, mas dependentes de administração otomana direta ao longo do Danúbio — o kaza de Yergöğü dependia do sanjakbeylik de Nikopol, İbrail, desde 1538, diretamente do Estado, e Bender, também desde 1538, do sanjaco de Bucak. Ou seja, a revolta atingira não o interior vassalo, mas a casca otomana direta que o rodeava. Sem furar esta casca, o triângulo Transilvânia-Valáquia-Moldávia não podia ser ligado à frente habsburga.", "95f2286f"]},
"OLAYLAR_EK10:1595-08-23:0":{"b": ["A Batalha de Călugăreni — a campanha da Valáquia de Koca Sinan Paxá", "201210a1"], "d": ["Com a perda de uma só vez dos três voivodados, o grão-vizir Koca Sinan Paxá atravessou o Danúbio com um grande exército e marchou para submeter de novo a Valáquia. Mihail, o Valente, sabendo que não poderia resistir em batalha campal, esperou o exército na passagem pantanosa do Neajlov, em Călugăreni, e atacou de surpresa as forças comprimidas em terreno estreito. Depois do ataque, não podendo resistir ao exército otomano, superior em número, recuou para norte, para as montanhas; Sinan Paxá ocupou Bucareste e Târgoviște e tentou ligar a Valáquia à administração direta. Călugăreni foi, por isso, para os otomanos não uma derrota, mas um ataque que atrasou a conclusão da campanha; mas o facto de Mihail ter podido preservar o seu exército tornou possível, poucas semanas depois, o contra-ataque com a ajuda vinda da Transilvânia.", "a2263c60"]},
"OLAYLAR_EK10:1595-10-01:0":{"b": ["A retirada da Valáquia e o ataque a Yergöğü — o fracasso da campanha de repressão", "118806e1"], "d": ["Com o contra-ataque de Mihail, o Valente, unido às forças do príncipe da Transilvânia, Sinan Paxá evacuou Târgoviște e Bucareste e recuou para o Danúbio. O momento mais caro da retirada viveu-se na passagem: em outubro de 1595, os akıncıs que perseguiam o exército de regresso da Valáquia foram atacados por Mihail em Yergöğü. A campanha terminou assim sem alcançar o objetivo de ligar a Valáquia à administração direta e o voivodado permaneceu de facto perdido. A autoridade otomana neste triângulo só pôde ser reparada ao longo dos anos e por partes; o regresso da Transilvânia à obediência aguardaria a revolta de Bocskai, em 1604, e o encerramento total da frente o Tratado de Zsitvatorok, de 1606.", "ab33575c"]},
"OLAYLAR_EK10:1713-06-24:0":{"b": ["A separação de Hotin da Moldávia — um sanjaco otomano direto no meio do voivodado", "947517cb"], "d": ["Na campanha do Prut, a passagem do voivoda da Moldávia, Dimitrie Cantemir, para o lado russo mostrou que a fronteira norte do voivodado já não podia ser deixada ao voivoda. Por isso, Hotin, depois de 1711, foi tirada à Moldávia e posta sob administração otomana direta; foi-lhe dado primeiro o estatuto de nahiye e, depois, de sanjaco. Depois da ocupação russa provisória de 1713, a fortaleza foi de novo reparada e alargada sob a supervisão de uma comissão técnica otomana e francesa enviada de Istambul e tornou-se a mais forte fortificação otomana a norte do Danúbio. No mapa, a saída de Hotin, a partir desta data, do tom do voivodado sujeito para a cor otomana direta, e o facto de ficar como uma ilha no meio da Moldávia sujeita, é a correspondência desta separação administrativa — não é um erro de desenho. A mesma estrutura já existia em Bucak desde 1538, e em Kili e Akkirman desde 1484: o voivodado livre nos seus assuntos internos, as fortalezas de fronteira do Estado.", "7c5d350f"]},
"OLAYLAR_EK10:1788-04-24:0":{"b": ["A segunda ocupação austríaca de Böğürdelen — a abertura da frente do Sava", "063b3ad0"], "d": ["Depois de a Áustria ter entrado na guerra, ao lado da Rússia, a 9 de fevereiro de 1788, a linha do Sava voltou a ser frente e Böğürdelen passou ao domínio austríaco a 24 de abril de 1788. A fortaleza fora antes cedida à Áustria sem guerra a 17 de agosto de 1717 e mantida até ao Tratado de Belgrado (1739); nessa altura a população diminuíra tanto que na cidade restavam trinta e quatro casas cristãs e nenhum muçulmano. Durante o período otomano de 1739-1788, a população voltara a subir para 1500-2000. A segunda ocupação terminaria com o Tratado de Sistova (4 de agosto de 1791) e a fortaleza seria devolvida aos otomanos.", "de07456b"]},
"OLAYLAR_EK10:1806-01-26:0":{"b": ["A entrega de Böğürdelen a Karađorđe — a primeira fortaleza na Primeira Insurreição Sérvia", "5c913eb4"], "d": ["Durante a primeira revolução sérvia, iniciada em 1804 como reação à pressão dos dahis e yamaks em Belgrado e que depois ganhou carácter nacionalista, a Fortaleza de Böğürdelen foi entregue a Karađorđe a 26 de janeiro de 1806. Esta fortaleza, sobre o Sava, é a primeira grande fortificação otomana tomada pelos insurretos e anuncia a queda de Belgrado. Quando a insurreição foi reprimida em 1813 e Belgrado foi retomada, a fortaleza voltou também à administração otomana; mas, com a condição de guarnição do firmão de 1830, Böğürdelen foi definida, juntamente com Belgrado, Semendire e Fethülislâm, como uma das quatro fortalezas em que ficaram soldados otomanos dentro da Sérvia autónoma, e permaneceu neste estatuto até a guarnição se retirar em 1867.", "092a75b8"]},
"OLAYLAR_EK10:1832-01-01:0":{"b": ["İzdin (Lamia) ficou dentro das fronteiras da Grécia — a linha Arta-Volos", "930f63b8"], "d": ["A fronteira norte do Estado grego independente foi traçada em 1832 na linha que vai do golfo de Arta ao golfo de Volos. İzdin, que no período otomano (1424-1832) fora centro de kaza dependente do sanjaco de Negroponte, passou à Grécia por ficar a sul desta linha; o resto da Tessália (Yenişehir, Tırhala) permaneceu com os otomanos até 1881.", "577080e0"]},
"OLAYLAR_EK10:1877-04-24:0":{"b": ["A declaração de guerra da Rússia — o início da Guerra de Noventa e Três", "ac548ab8"], "d": ["A repressão da Revolta Búlgara de 1876 suscitara grande indignação na opinião pública europeia, e a Rússia aproveitou-a ao máximo para isolar a Sublime Porta. Quando o Estado Otomano rejeitou a proposta da Conferência de Istambul (do Arsenal) de dividir a Bulgária em duas províncias autónomas e, em seguida, o Protocolo de Londres de 31 de março de 1877, a Rússia declarou guerra a 24 de abril de 1877 e o seu exército entrou no território do Principado da Roménia, que atraíra para o seu lado (o mapa mostra a Valáquia-Moldávia, a partir deste momento até ao Armistício de Edirne, com a cobertura tracejada do avanço russo). Como coincidiu com o ano de 1293 do calendário rûmî, a guerra é conhecida pelo nome de Guerra de Noventa e Três. A operação decorreu em duas frentes, a do Danúbio e a da Anatólia Oriental: no Danúbio, o exército otomano de 180.000 homens tinha considerado a margem esquerda do rio como primeira linha de defesa e as montanhas dos Balcãs como segunda; a leste, os 55.000 soldados de Ahmed Muhtar Paxá estavam posicionados entre Ardahan e Doğubayazıt. Esta guerra é, no mapa, o acontecimento que iniciou o colapso da Rumélia otomana — as atuais fronteiras da Bulgária, da Sérvia, de Montenegro e da Roménia são todas produto destes quinze meses.", "a71008f1"]},
"OLAYLAR_EK10:1877-05-21:0":{"b": ["A proclamação da independência da Roménia — o fim da sujeição da Valáquia-Moldávia", "bdd164b3"], "d": ["Duas semanas depois da declaração da Guerra de 93, o Principado da Roménia proclamou a sua independência e entrou na guerra ao lado da Rússia; a sua participação no cerco de Plevna foi decisiva na derrota otomana. A sujeição da Valáquia e da Moldávia, com mais de quatrocentos anos, terminou assim de facto; a independência obteve reconhecimento internacional no Congresso de Berlim (1878). O mapa mostra, a partir desta data, a Roménia não como sujeita, mas como Estado independente na sua própria cor.", "02d51dee"]},
"OLAYLAR_EK10:1877-06-27:0":{"b": ["A travessia do Danúbio pelo exército russo — a queda de Sistova e Tırnova", "811367b1"], "d": ["Os russos, que com o início da guerra entraram no território romeno e atraíram este principado para o seu lado, avançaram em duas colunas, uma na direção da Dobruja e outra na de Bucareste. O Danúbio foi atravessado entre Ruse e Nikopol e a 27 de junho foi tomada Sistova e, a 1 de julho, a antiga capital búlgara, Tırnova. Como, embora a evacuação tivesse sido ordenada, não se prestou atenção a esta matéria, Nikopol também se rendeu depois de resistir algum tempo. A rutura da primeira linha de defesa numa semana provocou grande pânico em Istambul; chegaram a espalhar-se notícias de que o centro do sultanato seria transferido para Bursa, e a condução da guerra foi entregue a um conselho militar formado na capital.", "f266b11c"]},
"OLAYLAR_EK10:1877-07-19:0":{"b": ["A evacuação do Desfiladeiro de Shipka — a rutura da linha dos Balcãs", "1f45e50a"], "d": ["As forças otomanas em Shipka, a mais estratégica das passagens que atravessam as montanhas dos Balcãs, resistiram violentamente aos ataques russos; mas, convencidas de que seriam vencidas, evacuaram secretamente a passagem a 19 de julho. Assim, também a segunda linha de defesa ficou aberta e o general Gurko tomou Eski Zağra a 22 de julho. Embora Süleyman Paxá, que chegou do lado de Montenegro, tenha derrotado Gurko e retomado os lugares ocupados no sul dos Balcãs, não conseguiu, apesar dos ataques que duraram meses a partir de 21 de agosto, recuperar Shipka. No mapa, isto é o facto de a integridade defensiva entre o norte e o sul da cordilheira dos Balcãs nunca mais ter podido ser restabelecida: a luta na frente do Danúbio ficará daí em diante atada em Plevna.", "3463a17b"]},
"OLAYLAR_EK10:1877-08-23:0":{"b": ["Lovech foi ocupada pelo exército russo", "70e54611"], "d": ["Na Guerra de 93, Lovech fora ocupada pelos russos a 5 de junho de 1877 e as forças otomanas comandadas por Rifat Paxá tinham repelido os russos a 15 de junho; a cidade foi abandonada pelos otomanos a 23 de agosto e passou de novo à ocupação russa. O mapa mostra Lovech, a partir deste dia até ao Tratado de Berlim, sob ocupação russa (tracejado); juridicamente continua a ser território otomano.", "45e61a80"]},
"OLAYLAR_EK10:1877-11-18:0":{"b": ["A queda de Kars — a desagregação da frente oriental e os redutos de Aziziye", "53fc3bf5"], "d": ["Os russos, que na Anatólia Oriental avançavam em três colunas na direção de Kars, Doğubayazıt e Ardahan, tinham tomado Doğubayazıt a 30 de abril e entrado em Ardahan, mas, ao marcharem sobre Erzurum, foram derrotados a 15 de julho e lançados para fora da fronteira. Este êxito, que deu a Ahmed Muhtar Paxá o título de \"Gazi\", inverteu-se quando, em agosto, o general Lazarev passou de novo à ofensiva, e a 18 de novembro Kars caiu. As forças otomanas, que recuaram para Erzurum para uma defesa mais adequada, ofereceram nos redutos de Aziziye, com o incitamento de Nene Hatun à população, uma grande resistência. Kars, Ardahan e Batum seriam cedidas à Rússia oito meses depois, em Berlim, em contrapartida de uma parte da indemnização de guerra.", "07faf844"]},
"OLAYLAR_EK10:1912-10-08:0":{"b": ["O início da Primeira Guerra dos Balcãs — a declaração de guerra de Montenegro", "c0c2697e"], "d": ["Os Estados balcânicos, depois de o Comité de União e Progresso ter resolvido a questão das igrejas pela lei de 3 de julho de 1911, tinham removido o maior obstáculo entre si e, por incitamento da Rússia, tinham assinado ao longo de 1912 tratados de aliança uns com os outros (a 13 de março, Bulgária-Grécia, em agosto Montenegro-Bulgária, a 6 de outubro Montenegro-Sérvia). A Sublime Porta não deu por isso; confiando mesmo na garantia da Rússia, desmobilizou 120 batalhões instruídos da Rumélia. Os quatro Estados apresentaram a 3 de outubro uma nota conjunta exigindo autonomia para a Macedónia, a Albânia e Creta; sem obter resposta, a operação começou a 8 de outubro de 1912 com a declaração de guerra de Montenegro. A 13 de outubro foram entregues os passaportes aos embaixadores da Sérvia e da Bulgária; no dia seguinte, estes dois Estados e, depois, a Grécia declararam guerra. Durante a guerra, as divergências de opinião política dentro do exército tiveram um grande papel na derrota.", "f008aef9"]},
"OLAYLAR_EK10:1912-10-20:0":{"b": ["Nos Ródope, o Destacamento de Kırcaali foi desfeito, Kırcaali caiu", "8cf59b7f"], "d": ["As forças búlgaras, que depois da declaração de guerra búlgara desceram dos Ródope, derrotaram o Destacamento de Kırcaali de Mehmed Yaver Paxá e entraram em Kırcaali. O destacamento derrotado recuou na direção de Gümülcine; a parte oriental dos Ródope perdeu-se na primeira semana de guerra.", "c675e240"]},
"OLAYLAR_EK10:1912-10-23:0":{"b": ["O desastre do Exército do Leste e a retirada para a linha de Çatalca — a perda de Kumanovo e Salónica", "cf95591a"], "d": ["O Exército otomano do Leste foi derrotado a 23 de outubro de 1912 pelo exército búlgaro, três vezes mais numeroso, e recuou até à linha de Çatalca, trinta quilómetros a oeste de Istambul; a capital viu-se diretamente ameaçada no primeiro mês de guerra. Nos mesmos dias, o Exército do Oeste foi derrotado pelos sérvios em Kumanovo, a 23-24 de outubro, e Tahsin Paxá rendeu-se em Salónica aos gregos com o seu exército de 35.000 homens. Com estes desastres, o gabinete de Gazi Ahmed Muhtar Paxá demitiu-se a 29 de outubro; Abdülhamid II, que vivia em exílio em Salónica, foi transferido para Istambul a 1 de novembro. A linha de Çatalca foi mantida até ao fim da guerra — a geografia otomana de quinhentos anos da Rumélia reduziu-se em poucas semanas a esta estreita faixa.", "376c6d31"]},
"OLAYLAR_EK10:1912-10-23:1":{"b": ["O príncipe Aleksandar entrou no centro do sanjaco de Novi Pazar", "326d0616"], "d": ["As forças sérvias tomaram Novi Pazar na primeira semana de guerra e uniram-se às forças montenegrinas vindas do oeste. O sanjaco de Novi Pazar, que separava havia cem anos a Sérvia de Montenegro, converteu-se assim numa ponte entre os dois aliados.", "afe8a034"]},
"OLAYLAR_EK10:1912-10-24:0":{"b": ["Depois da batalha de Kırkkilise, Kırklareli perdeu-se", "eda4c759"], "d": ["Quando o Exército do Leste foi derrotado na batalha de Kırkkilise, na Trácia Oriental, a cidade que Kölemen Abdullah Paxá defendia foi deixada às forças búlgaras. A cidade só foi libertada da ocupação de nove meses na Segunda Guerra dos Balcãs, a 21 de julho de 1913.", "ee5cf8d2"]},
"OLAYLAR_EK10:1912-10-26:0":{"b": ["Escópia, centro da província de Kosovo, foi deixada sem resistência", "455d9b71"], "d": ["Depois do desastre de Kumanovo (23-24 de outubro), Üsküp, centro da província de Kosovo, ficou indefesa. Como a população não queria combates à volta da cidade, as forças sérvias comandadas pelo príncipe Aleksandar, convidadas por intermédio dos cônsules, entraram na cidade sem resistência na noite de 26 de outubro.", "3992a650"]},
"OLAYLAR_EK10:1912-10-28:0":{"b": ["Köprülü (Veles) perdeu-se na margem do Vardar", "73d20b7d"], "d": ["Dois dias depois da queda de Üsküp, o exército sérvio, que descia para sul ao longo do Vardar, tomou Köprülü. A porta do vale do Vardar que se abre para Salónica passou assim para as mãos dos sérvios.", "e762a0e1"]},
"OLAYLAR_EK10:1912-10-29:0":{"b": ["A bacia de Bregalnitsa: o general Stefanović entrou em İştip", "70a84256"], "d": ["As tropas sérvias comandadas pelo general Stefanović tomaram İştip sem encontrar resistência; primeiro entraram na cidade bandos irregulares. Depois de Kumanovo, a bacia de Bregalnitsa, na Macedónia oriental, passou ao controlo sérvio.", "3b2e609b"]},
"OLAYLAR_EK10:1912-10-29:1":{"b": ["Depois da passagem de Sarantaporo, Karaferye passou ao domínio grego", "02a68e02"], "d": ["O exército grego, que avançava para norte desde a Tessália, dominou Karaferye depois de transpor a passagem de Sarantaporo (Kırkgeçit). Parte da população muçulmana da cidade abandonou nessa altura a região.", "a76cea57"]},
"OLAYLAR_EK10:1912-10-31:0":{"b": ["Vodina, na via-férrea Salónica-Monastir, perdeu-se", "fc15b917"], "d": ["Vodina, na via-férrea Salónica-Monastir, caiu nas mãos do exército grego. Com a separação forçada das populações eslava e turca, a população da cidade diminuiu seriamente em pouco tempo.", "e28f0a57"]},
"OLAYLAR_EK10:1912-11-02:0":{"b": ["A Batalha de Yenice — a passagem de Yenice-i Vardar para os gregos", "8f6cb76e"], "d": ["O 8.º Corpo Misto de Hasan Tahsin Paxá foi derrotado pelo exército grego em Yenice, a oeste de Salónica, e recuou para a região de Salónica. Durante a batalha, grande parte da vila ardeu; o caminho de Salónica ficou aberto ao exército grego.", "d0f12da4"]},
"OLAYLAR_EK10:1912-11-03:0":{"b": ["Prizren, no sudoeste do Kosovo, rendeu-se", "bae6b1b9"], "d": ["Prizren, no sudoeste do Kosovo, rendeu-se às forças sérvias. A atitude das unidades que entraram na cidade em relação à população muçulmana foi registada como uma das páginas mais pesadas da guerra no Kosovo.", "8cf0b7ae"]},
"OLAYLAR_EK10:1912-11-05:0":{"b": ["O coronel Mitov declarou a lei marcial em Ustrumca", "bcad75cc"], "d": ["O coronel búlgaro Mitov entrou em Ustrumca e declarou a lei marcial; ao partir, no dia seguinte, deixou a vila a um kaymakam búlgaro e a um comandante sérvio. Ustrumca mudou de mãos entre os aliados durante a guerra e foi ligada à Bulgária em 1913.", "acfc04ac"]},
"OLAYLAR_EK10:1912-11-08:0":{"b": ["Hasan Tahsin Paxá deixou Salónica aos gregos", "1738933c"], "d": ["Hasan Tahsin Paxá, que recuara para Salónica depois da derrota de Yenice, deixou a cidade aos gregos quando o exército búlgaro se aproximava do norte; o exército grego entrou na cidade ao meio-dia de 8 de novembro. Salónica, o maior porto da Rumélia otomana e onde nascera o Comité de União e Progresso, perdeu-se assim.", "e65f92fc"]},
"OLAYLAR_EK10:1912-11-21:0":{"b": ["Gümülcine, centro da Trácia Ocidental, abriu-se aos búlgaros", "96eec25f"], "d": ["Com o recuo do destacamento de Yaver Paxá, retirado de Kırcaali, na direção de Fere, Gümülcine rendeu-se às forças búlgaras. O centro da Trácia Ocidental estava à cabeça dos territórios que seriam deixados à Bulgária no fim da guerra.", "dab74d84"]},
"OLAYLAR_EK10:1912-11-28:0":{"b": ["Os sérvios, que chegaram a Elbasan, entraram no mesmo dia em Debar", "16720246"], "d": ["As forças sérvias que avançavam para oeste a partir de Monastir entraram também em Debar no dia em que chegaram a Elbasan e desceram para o Adriático. No mesmo dia era proclamada, em Avlonya, a independência da Albânia.", "6e52cff7"]},
"OLAYLAR_EK11:1401-01-01:0":{"b": ["Timur ocupou Bagdade pela segunda vez — os bairros abássidas da cidade foram destruídos", "04b68a24"], "d": ["Timur tomou Bagdade duas vezes com oito anos de intervalo. Na primeira ocupação, em 1393, a cidade não sofrera grande dano; a segunda, em 1401, é considerada o segundo golpe pesado infligido à vida cultural de Bagdade — o povo foi passado a fio de espada e a maior parte dos bairros e edifícios que restavam do período abássida foi destruída. Embora o soberano jalayirida Ahmed tenha voltado à cidade em 1405 e procurado reparar as muralhas e os bazares destruídos, não teve tempo; Bagdade passou em 1410 para as mãos dos turcomanos Kara Koyunlu. Estas duas ocupações são um dos passos mais concretos que mostram o quanto Timur se aproximara das fronteiras otomana e mameluca no caminho que levou à Batalha de Ancara.", "b24ba76b"]},
"OLAYLAR_EK11:1422-01-01:0":{"b": ["Cüneyd Bey voltou a pôr-se à frente de Aydın-ili — os Aydınoğulları de novo independentes", "63281658"], "d": ["Çelebi Mehmed tomara em 1414-15 İzmir e, enviando Cüneyd Bey para o sanjakbeylik de Nikopol, ligara Aydın-ili à administração otomana. Cüneyd, depois da morte de Çelebi Mehmed, voltou a entrar em cena ao lado de Mustafa Çelebi, que Bizâncio apresentara como pretendente ao trono, e foi mesmo seu vizir. Murad II separou-o desta aliança com a promessa de lhe devolver o antigo beylik; Cüneyd voltou a İzmir, tomou Ayasuluk, matou Aydınoğlu Mustafa Bey e pôs-se à frente do beylik. Assim, Aydın-ili nasceu, de dentro da crise do Falso Mustafa, saída da administração otomana.", "c5020860"]},
"OLAYLAR_EK11:1426-01-01:0":{"b": ["A execução de Cüneyd Bey e da sua família — o fim do Beylik dos Aydınoğulları", "efa684ba"], "d": ["Cüneyd Bey, que voltara a dominar Aydın-ili, incitou os beis da Anatólia e procurou contacto com Veneza, pelo que Murad II enviou contra ele o beylerbeyi da Anatólia Hamza Bey. Quando o filho Kurd Hasan foi derrotado perto de Akhisar e feito prisioneiro, Cüneyd, que se retirara para İpsili, em frente à ilha de Samos, foi obrigado a render-se quando a ajuda esperada de Karamanoğlu não veio e os genoveses, que agiam com os otomanos, o bloquearam por mar; foi eliminado com toda a sua linhagem. As terras dos Aydınoğulları entraram assim totalmente na administração otomana.", "662b578c"]},
"OLAYLAR_EK11:1502-01-01:0":{"b": ["Erzurum e a bacia de Van passaram para os safávidas — o flanco norte dos Ak Koyunlu ruiu", "b418875f"], "d": ["Xá İsmâil, que derrotara Elvend Bey em Şerûr e entrara em Tabriz no verão de 1501, avançou no ano seguinte na direção noroeste e pôs sob o seu domínio a linha que vai de Erzurum à bacia do lago de Van. O Estado Ak Koyunlu, depois da morte de Uzun Hasan, já estava dividido em dois pelas lutas pelo trono: Elvend Bey detinha o Azerbaijão e Diyarbekir, e o primo Murad o Irâk-ı Acem e Fars. Esta divisão facilitou o avanço safávida; a região mudou de mãos, em dez registos, num ano. Erzurum permaneceu depois dezasseis anos nas mãos safávidas e só entrou no domínio otomano depois de Çaldıran, em 1518-19.", "9c2345ba"]},
"OLAYLAR_EK11:1503-01-01:0":{"b": ["A derrota de Murad Bey em Hemedan: Irâk-ı Acem e Fars passaram para os safávidas", "8de07a31"], "d": ["O segundo pretendente ao trono Ak Koyunlu, o sultão Murad, sofreu uma pesada derrota na batalha travada perto de Hemedan contra o xá İsmâil e fugiu para Bagdade. Com esta única batalha, as regiões de Irâk-ı Acem, Fars e Kirman entraram na administração safávida; no mapa, estas regiões mudam de mãos ao mesmo tempo. É o maior passo isolado na desagregação do Estado Ak Koyunlu — a perda de Tabriz deixara a dinastia sem capital, a derrota de Hemedan deixou-a sem terra.", "f9d2ba4d"]},
"OLAYLAR_EK11:1504-12-06:0":{"b": ["O xá Ismail entrou em Yazd: caiu o último reduto dos restos dos Ak Koyunlu no Irão central", "6f9835df"], "d": ["Depois da derrota de Hemedan, em 1503, embora Irâk-ı Acem e Fars tivessem passado para os safávidas, Yazd permanecera à parte, nas mãos de Bayındırlı Murad Bey, da dinastia Ak Koyunlu. A cidade caiu depois de um cerco de um mês e a última ilha Ak Koyunlu no Irão central fechou-se. O registo da TDV: \"O xá İsmâil entrou na cidade a 28 de Cemâziyelâhir de 910 (6 de dezembro de 1504), depois de um cerco de um mês.\"", "577a0ec7"]},
"OLAYLAR_EK11:1507-01-01:0":{"b": ["A campanha de Diyarbekir do xá Ismail: caíram os últimos centros dos Ak Koyunlu", "b6d8504e"], "d": ["O xá İsmâil, que tomara o Azerbaijão e o planalto iraniano, voltou-se em 1507 para o oeste, para a região de Diyarbekir, onde nascera a dinastia Ak Koyunlu. A linha que vai de Âmid a Mardin, e de Urfa a Harput, entrou em dois lances na administração safávida e os Ak Koyunlu desapareceram de facto. Esta campanha pôs também pela primeira vez a fronteira safávida contra as fronteiras otomana e mameluca; o terreno geográfico da tensão que levou a Çaldıran foi assim estabelecido.", "d0346bf4"]},
"OLAYLAR_EK11:1508-01-01:0":{"b": ["A passagem de Bagdade para os safávidas — Irâk-ı Arab mudou de mãos", "39730186"], "d": ["Atrás do sultão Ak Koyunlu Murad, que se refugiara em Bagdade depois da derrota de Hemedan, o xá İsmâil entrou em 1508 em Irâk-ı Arab e tomou Bagdade. A passagem dos mausoléus de Cerbala e Najaf para a administração safávida era, do ponto de vista da pretensão confessional do movimento, tão importante como a tomada de Tabriz. No mapa, Irâk-ı Arab muda de mãos no mesmo dia; é o último e mais vasto passo geográfico da desagregação. Bagdade permaneceu nas mãos safávidas até à Campanha dos Dois Iraques do Legislador, em 1534.", "10e3e563"]},
"OLAYLAR_EK11:1510-12-02:0":{"b": ["A Batalha de Merv: os uzbeques sofreram uma pesada derrota, Merv e Herat foram tomadas", "f8e45aaf"], "d": ["O xá İsmâil, que completara a herança Ak Koyunlu no oeste, marchou para leste, para o Khorasan, e infligiu uma pesada derrota aos uzbeques diante de Merv; Şeybânî Han morreu no campo de batalha. Merv e Herat entraram no domínio safávida e o Estado Safávida alcançou as suas fronteiras, que se estendem do Eufrates ao Amu Dária. Assim, o processo iniciado com a entrada em Tabriz no verão de 1501 ficou completo em nove anos: a herança Ak Koyunlu passou inteiramente à administração safávida e o Estado Otomano passou a ter a leste, como vizinho, um segundo Estado da sua dimensão.", "ae88b613"]},
"OLAYLAR_EK11:1539-02-24:0":{"b": ["A entrada definitiva de Zabid no domínio otomano", "ddd971c7"], "d": ["A frota que levantou o cerco de Diu a 5 de novembro de 1538 tocou, no regresso, a costa do Iémen e Zabid foi definitivamente ligada à administração otomana; Hadım Süleyman Paxá partiu da cidade a 10 de março de 1539 e chegou a Jidá a 1 de abril. A cidade era governada, desde 1517, em nome dos otomanos, pelos antigos beis mamelucos; com esta data passou à administração direta.", "5718f027"]},
"OLAYLAR_EK11:1581-04-16:0":{"b": ["A União Ibérica: a coroa de Portugal passou para o rei de Espanha", "1cc6dfdc"], "d": ["A luta sucessória aberta com a morte, sem herdeiro, do Cardeal-Rei Henrique encerrou-se a favor da Espanha na Batalha de Alcântara (25 de agosto de 1580), e as Cortes portuguesas, reunidas em Tomar, reconheceram a 16 de abril de 1581 Filipe II como rei de Portugal. Segundo as condições de Tomar, Portugal conservaria as suas próprias instituições, a sua moeda e a sua língua, só portugueses seriam nomeados para a administração e haveria em Madrid um conselho português separado — isto é, a união era uma união pessoal, não uma anexação.", "40bd79df"]},
"OLAYLAR_EK11:1640-12-01:0":{"b": ["A Restauração: Portugal recuperou a independência", "64ec0738"], "d": ["Nos dias em que a revolta da Catalunha ocupava a Espanha, um grupo de nobres em Lisboa assaltou o palácio e derrubou a administração espanhola e proclamou rei o duque de Bragança, com o nome de João IV. A União Ibérica de sessenta anos terminou assim; mas Ceuta escolheu permanecer na Espanha e isto foi reconhecido pelo Tratado de Lisboa de 1668. Esta janela, em que Portugal foi articulado nas guerras dos Habsburgos, é também o quadro das suas perdas na Ásia: Ormuz perdeu-se em 1622, Malaca em 1641, Colombo em 1656; Tânger e Bombaim foram dadas à Inglaterra como preço da independência. Fonte: Britannica, History of Portugal — Restoration.", "bb04bea3"]},
"OLAYLAR_EK11:1662-01-30:0":{"b": ["Tânger foi cedida à Inglaterra", "1f7cad6d"], "d": ["O segundo artigo do tratado de casamento (23 de junho de 1661), feito para assegurar o apoio inglês na guerra de independência de Portugal, deixava Tânger à Inglaterra como dote de Catarina de Bragança. A esquadra do conde de Sandwich fundeou a 29 de janeiro de 1662 e, no dia seguinte, fez-se a entrega oficial com a cerimónia do conde de Peterborough. Os ingleses abandonariam a cidade em 1684.", "9328c723"]},
"OLAYLAR_EK11:1747-06-20:0":{"b": ["O assassinato de Nâdir Xá — a dissolução do domínio afsharida", "19c218c0"], "d": ["Nâdir Xá, que pôs fim ao trono safávida e em 1736 proclamou o sultanato em seu nome, que foi com a campanha da Índia até Deli e que fez três guerras com os otomanos e acabou por fazer a paz com o Tratado de Kerden de 1746, foi morto na sua tenda pela sua própria guarda. A seguir, o Irão não pôde ser governado por uma só mão: os restos dos Afsharidas no Khorasan, os Zand no sul e os Qajar, em ascensão no norte, repartiram o país durante quarenta e nove anos. A fronteira oriental otomana permaneceu, graças a esta dispersão, tranquila durante muito tempo.", "76a3f7ee"]},
"OLAYLAR_EK11:1796-01-01:0":{"b": ["O domínio da dinastia Qajar sobre o Irão", "744b48c5"], "d": ["Ağa Muhammed Han, chefe da tribo Qajar, derrubando o domínio dos Zand e quebrando a última resistência afsharida no Khorasan, reuniu de novo o Irão numa só mão e fez de Teerão a capital. O período de fragmentação de quarenta e nove anos terminou assim; a partir daí, o vizinho oriental dos otomanos seria até 1923 o Irão Qajar.", "15d0cfa9"]},
"OLAYLAR_EK12:1527-09-23:0":{"b": ["Fernando tomou Buda — Szapolyai foi expulso da capital", "99f77c29"], "d": ["Depois de Mohács, tinham surgido dois reis no trono húngaro: uma parte dos nobres elegera János Szapolyai e outra o Habsburgo Fernando. Fernando tomou Buda em 1527 e expulsou Szapolyai da capital; Szapolyai pediu ajuda ao sultão Solimão. Esta é a razão de o primeiro objetivo da campanha de Viena de 1529 ter sido Buda.", "e45db1f0"]},
"OLAYLAR_EK12:1537-01-01:0":{"b": ["A campanha de Barbarossa às ilhas do Egeu — o Ducado de Naxos entrou no controlo otomano", "722b2fea"], "d": ["O Ducado de Naxos, governado desde 1207 por duques latinos sob a tutela de Veneza, passou ao controlo otomano com a campanha às ilhas de Barbaros Hayreddin Paxá. O estatuto da ilha não foi tocado; o ducado continuou como sujeito dos otomanos e, pelo tratado otomano-veneziano de 1540, o direito de soberania foi oficialmente cedido aos otomanos.", "e20e29f9"]},
"OLAYLAR_EK12:1560-03-12:0":{"b": ["A frota cruzada ocupou Djerba — a base de Turgut Paxá perdeu-se", "f41b3f2a"], "d": ["A frota cruzada, formada por navios da Espanha, do Papado, de Malta, de Génova e de Florença, visou Djerba, que Turgut Reis usava como base de incursão desde 1551. Por causa de tempestades e de uma epidemia, só pôde chegar diante da ilha no início de 1560; a 12 de março de 1560 ocupou a ilha e construiu uma fortaleza. Piyâle Paxá, ao saber da notícia, partiu de Istambul a 28 de março com a sua frota de 120 galés. A ocupação não durou muito: a frota otomana derrotou os aliados diante de Djerba em maio e a fortaleza foi retomada no fim de julho. Esta campanha é o início da segunda grande operação naval que, depois de Preveza, consolidou a supremacia otomana no Mediterrâneo.", "a420585e"]},
"OLAYLAR_EK12:1560-07-30:0":{"b": ["A queda da fortaleza de Djerba — a passagem da ilha para a administração otomana", "f1efc0df"], "d": ["Depois da vitória naval de Piyâle Paxá, a 14 de maio de 1560, as forças cruzadas fecharam-se na fortaleza que tinham construído na ilha; as forças de Turgut Paxá, beylerbeyi de Trípoli de Barbaria, cercaram-na por terra. O cerco de dois meses terminou a 30 de julho de 1560 com a queda da fortaleza, e a ilha foi ligada ao beylerbeylik de Trípoli de Barbaria. Entre a vitória naval e a conquista da fortaleza há setenta e sete dias; a ilha mudou de facto de mãos não a 14 de maio, mas a 30 de julho.", "50b148da"]},
"OLAYLAR_EK12:1814-02-04:0":{"b": ["Terminou em Danzig o duplo poder russo-prussiano — a cidade livre de Napoleão voltou à Prússia", "1ccda4d2"], "d": ["As forças de Napoleão abandonaram Danzig, que, separada da Prússia pela paz de Tilsit (9 de julho de 1807), fora feita cidade livre sob proteção francesa, depois do cerco de 1813. Entre 2 de janeiro e 4 de fevereiro de 1814, manteve-se na cidade o duplo poder russo-prussiano; quando o czar Alexandre desistiu do plano de tomar Danzig e a foz do Vístula, a cidade passou à administração prussiana.", "8d215059"]},
"OLAYLAR_EK12:1815-05-03:0":{"b": ["Cracóvia declarada cidade livre, independente e neutra em Viena", "19eea839"], "d": ["No Congresso de Viena, a Rússia, a Áustria e a Prússia fizeram da cidade de Cracóvia, com o seu território circundante, um Estado livre sob a proteção das três potências; a Ata Final de Viena sancionou esta ordem.", "21a6fe2b"]},
"OLAYLAR_EK12:1846-11-11:0":{"b": ["A Cidade Livre de Cracóvia foi abolida e anexada à Áustria", "15548a14"], "d": ["Tomando como pretexto a insurreição de Cracóvia de fevereiro de 1846, a Rússia, a Áustria e a Prússia decidiram, na conferência de Viena, abolir a cidade livre e incorporá-la no território austríaco; os protestos da Inglaterra e da França não tiveram resultado.", "bf12c063"]},
"OLAYLAR_EK12:1893-01-01:0":{"b": ["Bornu passou para o domínio de Râbih b. Zübeyr", "8be4ca96"], "d": ["O senhor da guerra sudanês Râbih b. Zübeyr, que abalara Bagirmi e Vedây, apoderou-se de Bornu; até 1896 tomou todo o país e fez de Dikoa a sua capital.", "466276f3"]},
"OLAYLAR_EK12:1900-04-22:0":{"b": ["Râbih b. Zübeyr derrotado e morto pelos franceses — dissolve-se o seu domínio em Bornu", "fb5a3ace"], "d": ["Derrotado pelo exército colonial francês, Râbih foi morto; o seu filho quis manter o domínio, mas não se sustentou, e Bornu foi repartido em 1902 entre a França, a Inglaterra e a Alemanha.", "15789829"]},
"OLAYLAR_EK12:1913-08-31:0":{"b": ["Foi proclamado o Governo Provisório da Trácia Ocidental, com centro em Gümülcine", "974b2e28"], "d": ["Quando o Tratado de Bucareste (10 de agosto de 1913) deixou a Trácia Ocidental à Bulgária, o povo turco da região proclamou um governo provisório com centro em Gümülcine; depois da tomada de Dedeağaç, o governo anunciou a sua independência com o nome de 'Governo Independente da Trácia Ocidental'. Com a intervenção das grandes potências, o governo otomano não o apoiou; o Tratado de Istambul de 29 de setembro de 1913 deixou a Trácia Ocidental aos búlgaros e o governo viveu apenas cinquenta e sete dias, até 25 de outubro de 1913.", "86d3bfee"]},
"OLAYLAR_EK12:1920-11-15:0":{"b": ["A Cidade Livre de Danzig foi estabelecida sob a proteção da Sociedade das Nações", "bd148fe8"], "d": ["Danzig, separada da Alemanha pelo Tratado de Versalhes, ficou, desde 10 de janeiro de 1920, sob a administração transitória das grandes potências aliadas; a 15 de novembro de 1920 foi estabelecida, sob a proteção da Sociedade das Nações, como cidade livre em união aduaneira com a Polónia.", "c74affc1"]},
"OLAYLAR_EK13:1362-03-01:0":{"b": ["Morte de Orhan Gazi — fim dos quarenta anos que levaram de beilique a Estado", "62c59cfd"], "d": ["Orhan Gazi, que chegou à chefia do beilique com a morte de Osman Gazi em 1324, transformou, em trinta e oito anos de governo, o Estado Otomano de um beilique de fronteira num Estado assente nas duas margens do Mármara: foram tomadas Bursa (1326), Niceia (1331) e Nicomédia (1337), anexou-se o Beilique de Karesi, cunhou-se o primeiro akçe (1327), fundou-se a primeira madraça em Niceia (1331) e a passagem para a Rumélia tornou-se duradoura por Çimpe (1352) e Galípoli (1354). Perdeu em 1357, num acidente de caça, o seu filho mais velho Süleyman Paxá, que conduzia as conquistas na Rumélia; faleceu em Bursa em março de 1362 e foi sucedido pelo filho Murad I.", "9208e381"]},
"OLAYLAR_EK13:1417-01-01:0":{"b": ["As ilhas do Bahrein passam para as mãos dos Jabrids", "6a242b16"], "d": ["O artigo Bahreyn do TDV regista que a ilha esteve \"sucessivamente sob a administração dos Uyûnîs, dos Salgurides, dos Tabîs e dos Jabrids, e que, no tempo dos Jabrids, a maioria passou de xiita a sunita\"; não dá data a nenhum deles. Na literatura geral, a dinastia jabrida foi fundada no início do século XV, derrubando o último soberano jarwânida em Qatif, e no seu apogeu (Acvâd b. Zâmil, m. 1496) controlou toda a costa árabe do golfo Pérsico, Al-Hasa, Qatif e as ilhas do Bahrein. Depois de Acvâd, as ilhas Evâl passaram para Mukrin b. Zâmil — o soberano que seria derrotado pelos portugueses em 1521.", "0c4cdac7"]},
"OLAYLAR_EK13:1471-08-24:0":{"b": ["A tomada de Arzila pelos portugueses — segunda cabeça de ponte na costa de Marrocos", "83444a11"], "d": ["D. Afonso V desembarcou pessoalmente na costa de Marrocos com uma força de 30.000 homens e uma armada de 400 navios e tomou Arzila, sob administração uatácida, a 24 de agosto de 1471. A queda da cidade quebrou a resistência de Tânger; Tânger rendeu-se sem combate quatro dias depois, a 28 de agosto. Portugal estabeleceu assim, depois de Ceuta (1415) e Alcácer Ceguer (1458), a terceira e a quarta posições na costa atlântica de Marrocos; o rei, depois desta expedição, mandou acrescentar ao seu título a expressão \"senhor de África\".", "ec8d27f5"]},
"OLAYLAR_EK13:1488-01-01:0":{"b": ["Safim entra na esfera de influência portuguesa", "765e703e"], "d": ["Safim, o porto de cereais e de pesca mais movimentado da costa atlântica, entrou em 1488 na esfera de influência portuguesa; a cidade foi governada durante algum tempo por governantes locais sob proteção portuguesa e foi ocupada diretamente em 1508. Como as fontes dão pesos diferentes a estas duas fases, a data de início oscila entre 1488 e 1508; ambas são extremos do mesmo processo. Safim permaneceu cinquenta e três anos em mãos portuguesas e foi evacuada em 1541, após a queda de Agadir.", "51aa6746"]},
"OLAYLAR_EK13:1505-01-01:0":{"b": ["Fundação de Santa Cruz do Cabo de Gué — fortaleza portuguesa em Agadir", "cc22c433"], "d": ["A fortaleza de Santa Cruz do Cabo de Gué, fundada por iniciativa privada na costa do Sus, num ponto a que Portugal não chegara até então, foi construída em 1505 e cedida à coroa portuguesa em 1513. A fortaleza, ao controlar o comércio do açúcar e do ouro do vale do Sus, fechava a saída sudoeste de Marraquexe; por isso foi o primeiro grande alvo do movimento saadiano. O cerco de 1533 foi repelido, o de 1541 teve êxito e iniciou o colapso de Portugal em Marrocos.", "6d42d1d3"]},
"OLAYLAR_EK13:1513-09-03:0":{"b": ["A tomada de Azamor — controlo da foz do Umm al-Rabi'", "232acd4b"], "d": ["O exército português comandado por D. Jaime, duque de Bragança, entrou em Azamor, na foz do rio Umm al-Rabi', a 3 de setembro de 1513, sem encontrar resistência. A tomada da cidade deu o controlo tanto da foz do rio como da rota dos cereais que se abria para o interior, e no ano seguinte abriu caminho à fundação da fortaleza de Mazagão, a 12 km a sudoeste. Azamor permaneceu vinte e oito anos em mãos portuguesas.", "8ac983da"]},
"OLAYLAR_EK13:1514-01-01:0":{"b": ["Fundação da fortaleza de Mazagão — a posição portuguesa que mais tempo durará em Marrocos", "786cdb40"], "d": ["No ano seguinte à tomada de Azamor, no verão de 1514, foi construída na costa a fortificação de Mazagão. Depois do colapso geral de 1541, quando Portugal abandonou todas as suas posições em Marrocos, não abandonou Mazagão; pelo contrário, mandou reconstruir a fortaleza de raiz com baluartes à italiana, e a cidade foi mantida durante duzentos e cinquenta e cinco anos. O grande cerco de 1562 foi igualmente repelido. Mazagão seria evacuada em 1769 como a última posição de Portugal em Marrocos.", "fe42a1e2"]},
"OLAYLAR_EK13:1517-05-01:0":{"b": ["Rendição da fortaleza de Mardin — fim da resistência safávida a sul de Diyarbekir", "e6226de5"], "d": ["Quando Bıyıklı Mehmed Paxá, marchando para a região de Diyarbekir depois de Çaldıran, sitiou Mardin, as forças safávidas retiraram-se para a fortaleza em outubro de 1515; embora a cidade tivesse passado para mãos otomanas, a fortaleza resistiu. O contra-ataque do governador safávida Kara Han, com reforços, culminou na Batalha de Koçhisar (Kızıltepe), em maio de 1516 — na batalha que durou todo o dia na planície de Dede Garkın, Kara Han foi decapitado e o seu exército dispersou-se. A fortaleza, essa, nas palavras do TDV, rendeu-se \"só nove meses depois\".", "791d1c1c"]},
"OLAYLAR_EK13:1521-01-01:0":{"b": ["A tomada do Bahrein por Portugal — fim do domínio jabrida", "315a435a"], "d": ["Quando o soberano jabrida Mukrin b. Zâmil se recusou a pagar tributo a Ormuz, a armada portuguesa e as forças do Reino de Ormuz, vassalo de Portugal, desembarcaram na ilha; Mukrin foi derrotado em combate e o Bahrein passou para a administração portuguesa em 1521. A partir daí, durante oitenta anos, a ilha foi governada por intermédio de Ormuz, na maior parte por governadores persas sunitas. A pérola do Bahrein e a sua posição estratégica tornariam a ilha alvo direto da rivalidade otomano-portuguesa no golfo.", "34a37f50"]},
"OLAYLAR_EK13:1541-03-12:0":{"b": ["A queda de Agadir — começa a expulsão de Portugal de Marrocos pelos saadianos", "bb1568f6"], "d": ["O sultão saadiano Muhammad al-Shaykh sitiou a fortaleza de Santa Cruz a 16 de fevereiro de 1541 e tomou-a a 12 de março; cerca de seiscentos portugueses, incluindo o governador Guterre de Monroy, foram feitos prisioneiros.", "af3555a6"]},
"OLAYLAR_EK13:1541-10-01:0":{"b": ["Evacuação de Safim e de Azamor — Portugal retira-se da costa atlântica", "4cb6099a"], "d": ["Com a queda de Agadir a 12 de março de 1541 e a impossibilidade de estabelecer a aliança esperada com o sultão de Marrocos, D. João III ordenou a evacuação das duas grandes posições da costa atlântica; a evacuação de Safim e de Azamor concluiu-se no outono de 1541, nos meses de setembro e outubro. Assim, três posições perderam-se num só ano e a expansão de cinquenta anos de Portugal na costa de Marrocos inverteu-se; restaram Ceuta, Tânger, Arzila, Alcácer Ceguer e a recém-fortificada Mazagão.", "e6d4728d"]},
"OLAYLAR_EK13:1549-01-01:0":{"b": ["Evacuação de Arzila — Portugal reduz a sua costa setentrional", "b5d18373"], "d": ["Pela conjugação da crise financeira com a pressão saadiana, D. João III evacuou Arzila, mantida desde 1471. A presença de Portugal em Marrocos ficou assim reduzida a Ceuta, Tânger e Mazagão. Arzila seria brevemente reocupada em 1577 e abandonada definitivamente em 1589.", "36c1d8e6"]},
"OLAYLAR_EK13:1559-01-01:0":{"b": ["A expedição otomana ao Bahrein — último grande lance contra Portugal no golfo", "14501df3"], "d": ["Instalado na costa árabe do golfo com a anexação de Baçorá em 1546 e a criação da província de Al-Hasa, o Estado Otomano marchou sobre o Bahrein, sob o comando de Mustafa Paxá, beylerbei de Al-Hasa, visando o comércio de pérolas da ilha e a linha portuguesa de Ormuz. O resultado da expedição diverge nas fontes: a Enciclopédia do Islão do TDV escreve que os otomanos \"em 1559 tomaram o Bahrein e estabeleceram ali uma base\" e que as ilhas \"mais tarde voltaram à administração dos portugueses\"; a literatura ocidental, por seu lado, regista que o cerco fracassou, que os reforços portugueses vindos de Ormuz por mar repeliram as forças otomanas e que, depois de uma epidemia de peste que atingiu ambos os lados, os otomanos pediram condições de rendição. As duas narrativas divergem quanto ao próprio resultado; o que têm em comum é que o Bahrein não permaneceu em mãos otomanas de forma duradoura.", "b35d131f"]},
"OLAYLAR_EK13:1569-01-01:0":{"b": ["A tomada de Tunes por Uluç Ali Paxá — fim da ordem hafsida-espanhola", "d4498698"], "d": ["Quando Carlos V tomou Tunes em 1535, não governou a cidade ele próprio, mas repôs no trono o sultão hafsida Mevlây Hasan; nas palavras do TDV, a cidade de Tunes permaneceu \\\"sob a proteção dos espanhóis e sob a administração de Mevlây Ahmed III até à segunda intervenção dos otomanos em 1569\\\". Uluç Ali, nomeado beylerbei de Argel a 27 de junho de 1568, marchou por terra sobre Tunes, derrotou o sultão hafsida em Beja e entrou na cidade; Mevlây Ahmed refugiou-se no presídio espanhol de Halkulvâdî. Assim, o golfo ficou dividido em dois — a cidade otomana, a fortaleza do porto espanhola — e esta divisão durou quatro anos.", "32206b3e"]},
"OLAYLAR_EK13:1573-10-10:0":{"b": ["A reconquista de Tunes por Dom João de Áustria — a única contrapartida terrestre de Lepanto", "a6f044ee"], "d": ["Depois de Lepanto (1571), embora a Santa Liga se tivesse desfeito, a Espanha assumiu sozinha o peso do Norte de África: nas palavras do TDV, \"a 10 de outubro de 1573, os espanhóis empreenderam uma nova campanha com o objetivo de tomar o controlo de Tunes. Tomaram Tunes e deixaram lá 8000 soldados.\" Esta campanha, comandada por Dom João de Áustria, é o único lugar em que a vitória de Lepanto teve correspondência em terra; contudo, não foi duradoura e a cidade foi retomada onze meses depois. O que a ocupação derrubou foi uma administração otomana já instalada: a 2 de Zilhicce de 980 (5 de abril de 1573), o comandante de Tunes era Kılıç Ali Paxá, o seu lugar-tenente Ramazan Paxá e o beylerbei Haydar Paxá.", "f7f9ab56"]},
"OLAYLAR_EK13:1602-01-01:0":{"b": ["Os safávidas tomam o Bahrein a Portugal", "c37d982c"], "d": ["As forças enviadas pelo xá Abbas I, juntando-se aos rebeldes da ilha, fizeram sair a guarnição portuguesa da fortaleza; nas palavras do TDV, as ilhas foram tomadas aos portugueses \"em 1602, por forças ligadas ao Irão\". O Bahrein saiu assim de oitenta e um anos de administração portuguesa e entrou no domínio safávida, permanecendo cento e quinze anos ligado ao Irão. Este é o primeiro elo da desagregação de Portugal no golfo; vinte anos depois, o próprio Ormuz cairia numa operação conjunta anglo-iraniana.", "19e58d88"]},
"OLAYLAR_EK13:1717-01-01:0":{"b": ["A invasão do Bahrein pelos omanitas — fim do domínio safávida", "c9be5820"], "d": ["Durante a desagregação dos últimos anos do Estado Safávida, a armada de Omã, sob a dinastia Ya'rubi, invadiu a ilha e o domínio safávida terminou. Os trinta e cinco anos seguintes são o período mais confuso do golfo: a ilha mudou de mãos várias vezes entre Omã, o Irão e forças árabes locais.", "b0c7f671"]},
"OLAYLAR_EK13:1753-01-01:0":{"b": ["O Bahrein passa para a administração dos Âl-i Mezkûr de Bushehr", "610e2f9d"], "d": ["A família Âl-i Mezkûr, originária de Omã, estabelecida em Bushehr e considerada huwala, tomou o Bahrein sob a sua administração em 1753, a partir das suas bases em Bushehr. A família liderava as comunidades árabes da costa iraniana do golfo e governava a ilha em nome do Irão; o seu último representante, Nasr Âl-i Mezkûr, fora nomeado governador do Bahrein pela administração zand. Esta é a última administração da ilha antes dos Âl-i Halîfe.", "7cc5fed2"]},
"OLAYLAR_EK13:1769-03-11:0":{"b": ["Evacuação de Mazagão — caiu a última posição de Portugal em Marrocos", "f9e9749d"], "d": ["Perante o cerco iniciado no começo de 1769 pelo sultão alauita Muhammad III b. Abdullah, a guarnição de 592 homens não resistiu; a frota de evacuação, que partira de Lisboa a 1 de fevereiro, embarcou os últimos soldados a 11 de março de 1769, e o último governador, Dinis Gregório, foi quem deixou a cidade em último lugar. Assim, a presença de Portugal em Marrocos, iniciada em 1415 com a tomada de Ceuta, terminou ao fim de três séculos e meio. Mazagão foi a única posição da costa atlântica mantida depois do colapso geral de 1541 e, com duzentos e cinquenta e cinco anos, o lugar que Portugal mais tempo conservou em Marrocos.", "c0ad57bc"]},
"OLAYLAR_EK13:1783-01-01:0":{"b": ["A conquista do Bahrein pelos Âl-i Halîfe — fundação da dinastia que dura até hoje", "8773b011"], "d": ["Nasr Âl-i Mezkûr, governador do Bahrein pela administração zand, sitiou Zubara, na península do Catar; as forças utbi comandadas por Ahmed b. Muhammed b. Halîfe quebraram o cerco e, passando ao contra-ataque, tomaram o Bahrein nesse mesmo ano. O registo do TDV é breve: \"O Bahrein, em 1783, passou para o domínio dos Âl-i Halîfe, da tribo dos Utûb.\" Depois desta vitória, Ahmed b. Muhammed passou a ser conhecido pela alcunha de \"al-Fâtih\", e a dinastia que fundou reina na ilha até hoje.", "470bd22f"]},
"OLAYLAR_EK13:1861-05-21:0":{"b": ["Tratado do Bahrein com a Inglaterra — entrada no regime de proteção no golfo", "576796b2"], "d": ["Segundo o registo do TDV, \\\"a 21 de maio de 1861, a Inglaterra e Ali, irmão do xeque Muhammed, em representação do Bahrein, assinaram um acordo que proibia o comércio de escravos e a pirataria na região\\\"; nos documentos britânicos, o mesmo tratado (Perpetual Truce of Friendship and Peace) tem a data de 31 de maio de 1861. O tratado é o primeiro elo do regime de proteção que ligou as relações externas do Bahrein à Inglaterra, e a ilha permaneceu fora deste regime mesmo depois de os otomanos se terem restabelecido em Al-Hasa e Qatif em 1871.", "ab2ad5ff"]},
"OLAYLAR_EK14:1281-01-01:0":{"b": ["Ahî Evran — pîr fundador da organização ahî", "3392e100"], "d": ["Ahî Evran é considerado um dos fundadores da organização ahî na Anatólia e o pîr dos curtidores. A sua zaviye em Kırşehir manteve-se, no período otomano, como centro espiritual da organização dos ofícios/guildas até ao início do século XX; o Estado confirmou oficialmente esta posição em 1780, 1782, 1822-23 e 1842.", "caa063df"]},
"OLAYLAR_EK14:1326-01-01:0":{"b": ["Şeyh Edebâli — o laço fundador entre a organização ahî e a dinastia otomana", "c1186059"], "d": ["Edebâli, que fundou uma zaviye em Bilecik e era também um xeique da organização ahî, interpretou, segundo a tradição, o famoso sonho de Osman Gazi; em seguida, Osman Gazi casou com Mâlhun Hatun, filha de Edebâli. Edebâli é também considerado o primeiro cádi e mufti otomano.", "60c970e5"]},
"OLAYLAR_EK14:1330-06-01:0":{"b": ["Orhan Gazi consagra por waqf um terreno para os jogos de cirit após a conquista de Bursa", "da1becbd"], "d": ["Segundo o artigo Cirit do TDV, Orhan Gazi, depois da conquista de Bursa, consagrou por waqf um terreno nos arredores para corridas de cavalos e jogos de cirit — é um dos primeiros exemplos registados da institucionalização do jogo de cirit no mundo otomano.", "f099d0d8"]},
"OLAYLAR_EK14:1357-06-01:0":{"b": ["Origem tradicionalmente referida das lutas de Kırkpınar", "2d93fa65"], "d": ["Segundo a tradição, a tradição de luta de Kırkpınar teve origem nos combates de luta travados entre os quarenta gazis que passaram à Rumélia com Süleyman Paxá, o conquistador da Rumélia. Os artigos Güreş e Kırkpınar do TDV transmitem esta tradição, mas não dão uma data de fundação precisa.", "a7dedab7"]},
"OLAYLAR_EK14:1362-06-01:0":{"b": ["Fundação do Corpo dos Janízaros", "f4206dce"], "d": ["O sistema, que começou, sob a orientação de Çandarlı Kara Halil e de Molla Rüstem, com a instrução de jovens não muçulmanos tomados entre os prisioneiros de guerra em virtude da lei do pencik, adquiriu carácter institucional no reinado de Murad I, através do Corpo dos Acemi fundado em Galípoli.", "4842eade"]},
"OLAYLAR_EK14:1402-01-01:0":{"b": ["Início da construção da Mesquita Antiga de Edirne (Mesquita Grande)", "da7a22ac"], "d": ["A construção da Eskicami, também conhecida popularmente como Ulucami (Câmi-i Atîk), foi iniciada em 1402-1403 pelo emir Süleyman Çelebi.", "0f5a6b9d"]},
"OLAYLAR_EK14:1414-01-01:0":{"b": ["Início da construção do Complexo da Mesquita Verde de Bursa", "280b8a21"], "d": ["Mehmed I, que reunificou o trono após o Interregno Otomano, iniciou a construção do complexo em 1414 e situou-o num ponto central de Bursa, de modo a distingui-lo dos complexos do seu avô e do seu pai. O seu arquiteto principal foi Hacı İvaz Paxá.", "b820a0dd"]},
"OLAYLAR_EK14:1419-12-01:0":{"b": ["Conclusão do Complexo da Mesquita Verde de Bursa", "bc82821f"], "d": ["O Complexo da Mesquita Verde, conhecido pelo programa de azulejos e de decoração a que também contribuíram mestres de Tabriz, foi concluído em dezembro de 1419. O complexo compõe-se de mesquita, mausoléu (Mausoléu Verde), madraça, imaret e hamam; é um dos exemplos mais ricos da arquitetura otomana primitiva.", "b3e76f7c"]},
"OLAYLAR_EK14:1421-06-01:0":{"b": ["Início da aplicação efetiva do sistema devshirme", "fa835172"], "d": ["O método do devshirme, que não se via nos Estados islâmicos anteriores, começou primeiro como aproveitamento de jovens prisioneiros de guerra não muçulmanos, em virtude da lei do pencik. Segundo o TDV, \"entende-se que foi aplicado no tempo de Çelebi Mehmed, mas que foi codificado no reinado do seu filho Murad II.\"", "be8c415b"]},
"OLAYLAR_EK14:1425-01-01:0":{"b": ["Criação do cargo de xeique do Islão — o muftiado de Bursa de Molla Fenârî", "2a8ee2b9"], "d": ["A nomeação, em 1425, do sábio Molla Fenârî, que foi durante muitos anos cádi de Bursa, para mufti de Bursa é considerada, nas palavras do TDV, \"o início do muftiado e do xeique do Islão entre os otomanos\". O TDV observa, porém, que isto não é idêntico ao cargo de xeique do Islão plenamente institucionalizado, que no século XVI representava toda a organização ilmiye.", "3c8f9c61"]},
"OLAYLAR_EK14:1432-06-01:0":{"b": ["Institucionalização do sistema timar", "dc267780"], "d": ["As primeiras referências documentadas ao timar remontam ao tempo de Orhan Bey; a codificação sistemática, por seu lado, realizou-se no reinado de Murad II. Os registos sumários de timar preparados nesta época mostram que todos os princípios fundamentais do sistema estavam formados; os documentos de cerca de 1432 provam que as leis estavam plenamente em vigor.", "6494e2c1"]},
"OLAYLAR_EK14:1447-01-01:0":{"b": ["Conclusão da Mesquita e Complexo de Üç Şerefeli", "cde6993e"], "d": ["A Mesquita de Üç Şerefeli, mandada construir por Murad II aos mestres Muslihuddin e Şehâbeddin num período de dez anos (1437-1447), é considerada o primeiro exemplo de mesquita de planta centralizada na arquitetura otomana e um dos marcos da arquitetura de transição anterior ao período clássico.", "daf1585b"]},
"OLAYLAR_EK14:1451-06-01:0":{"b": ["Institucionalização do Divan-ı Hümayun pelo código de Maomé II, o Conquistador", "e8443e77"], "d": ["O Divan começou a adquirir o carácter de \"Dîvân-ı Hümâyun\" ao ser submetido a regras regulares em Edirne no reinado de Murad II. A verdadeira transformação veio com o código de Maomé II, o Conquistador: a maior inovação foi que a presidência do divan pelo sultão foi inteiramente abolida e transferida para o grão-vizir.", "e776b01d"]},
"OLAYLAR_EK14:1453-06-01:0":{"b": ["Maomé II, o Conquistador, destina Okmeydanı aos arqueiros", "342a9fd5"], "d": ["Maomé II, o Conquistador, que durante a conquista de Constantinopla estabelecera o seu quartel-general nas colinas de Kasımpaşa, tinha-o usado também como campo de treino para arqueiros; depois de tomar a cidade, destinou de forma permanente o local aos arqueiros. Esta atribuição é o início da transformação de Okmeydanı no centro da tradição otomana de tiro com arco, que duraria séculos.", "0c85baff"]},
"OLAYLAR_EK14:1502-06-01:0":{"b": ["Bursa atinge o auge no comércio da seda iraniana", "f1324cdf"], "d": ["As caravanas vindas de Tabriz transportavam para Bursa as sedas de Gîlân, Esterâbâd e Sârî, onde mercadores genoveses, venezianos, florentinos e judeus as compravam em concorrência. Em 1479, o valor da seda importada do Irão atingiu 150.000 ducados venezianos; em 1502, trabalhavam na cidade mais de 1000 teares.", "0f47c417"]},
"OLAYLAR_EK14:1504-01-01:0":{"b": ["Bajazeto II concede grandes prémios aos lutadores de Kırkpınar", "d745b882"], "d": ["Segundo o artigo Güreş do TDV, Bajazeto II concedeu em 1504 prémios de 3.000 e 1.500 kuruş aos lutadores; é um dos primeiros exemplos registados do patrocínio da corte otomana ao desporto da luta.", "cc00554e"]},
"OLAYLAR_EK14:1505-10-13:0":{"b": ["Conclusão da Mesquita e Complexo de Beyazıt", "eb9ab65b"], "d": ["A construção da Mesquita e Complexo de Beyazıt, mandados fazer para Bajazeto II, começou em 906 (1500), segundo um documento de arquivo, e concluiu-se a 14 de Cemâziyelevvel de 911 (13 de outubro de 1505). O seu arquiteto é discutido: com base no registo de Ayvansarâyî, foi durante muito tempo considerada obra do arquiteto Hayreddin, depois foi atribuída ao arquiteto Kemâleddin, e segundo alguns os dois trabalharam em conjunto; o mesmo documento, porém, mostra que o mestre era Yâkub Şah b. Sultan Şah. A mesquita é considerada um dos monumentos importantes da transição da arquitetura otomana pré-clássica para o período clássico.", "9b7591c4"]},
"OLAYLAR_EK14:1515-01-01:0":{"b": ["Transferência do Tersâne-i Âmire para Istambul (Kasımpaşa/Corno de Ouro)", "f36e3675"], "d": ["No reinado de Selim I, o Severo, o novo estaleiro, cuja construção começara na baía a oeste das muralhas de Gálata, foi concluído em 1515 com 160 docas; assim, as atividades de estaleiro, centradas em Galípoli, foram transferidas para Istambul. A instituição recebeu depois oficialmente o nome de \"Tersâne-i Âmire\" no tempo de Barbaros Hayreddin Paxá.", "baedf596"]},
"OLAYLAR_EK14:1520-01-01:0":{"b": ["Morte de Şeyh Hamdullah e legado da escola de caligrafia", "f5ed4d09"], "d": ["Şeyh Hamdullah de Amasya, como mestre de caligrafia de Bajazeto II, levou à maturidade a escola do aklâm-ı sitte (as seis escritas) e tornou-se o fundador de um estilo caligráfico otomano que viria a dominar todo o mundo islâmico. Quando morreu em 1520, deixou atrás de si um vasto círculo de discípulos.", "26c5c5fc"]},
"OLAYLAR_EK14:1521-01-01:0":{"b": ["Pîrî Reis conclui a primeira versão do Kitâb-ı Bahriye", "fd6cc1ff"], "d": ["Pîrî Reis concluiu em 1521 a primeira versão (em prosa) do Kitâb-ı Bahriye, que compila as costas, os portos e as informações de navegação do Mediterrâneo. Esta primeira versão ainda não fora apresentada ao sultão e tinha o carácter de um esboço a ampliar nos anos seguintes.", "72e9151d"]},
"OLAYLAR_EK14:1526-01-01:0":{"b": ["Pîrî Reis amplia o Kitâb-ı Bahriye e apresenta-o a Solimão, o Legislador", "d4abf0b7"], "d": ["Pîrî Reis ampliou o Kitâb-ı Bahriye, em parte em verso, e apresentou-o em 1526 a Solimão, o Legislador. A obra, nesta forma, difundiu-se como o guia de navegação mais abrangente da marinha otomana.", "7209606f"]},
"OLAYLAR_EK14:1534-01-01:0":{"b": ["Matrakçı Nasuh retrata no Beyân-ı Menâzil o itinerário da campanha dos Dois Iraques", "aa012278"], "d": ["Matrakçı Nasuh, que participou na primeira campanha da Pérsia (dos Dois Iraques) empreendida por Solimão, o Legislador, em 1534, retratou, pela técnica da miniatura-mapa, cada etapa do itinerário do exército, de Istambul a Tabriz e daí a Bagdade. Este trabalho foi reunido na obra intitulada Beyân-ı Menâzil-i Sefer-i Irâkeyn e é o exemplo mais original do género dos menzilname no mundo otomano.", "9ea08eae"]},
"OLAYLAR_EK14:1534-12-04:0":{"b": ["Fuzûlî apresenta uma cassida ao Legislador após a conquista de Bagdade", "1ef0653f"], "d": ["Depois de Solimão, o Legislador, ter conquistado Bagdade em 1534, Fuzûlî apresentou ao sultão otomano cinco cassidas, entre as quais a célebre cassida que começa com o verso \"Geldi burc-ı evliyâya pâdişâh-ı nâmdâr\"; assim, saindo da proteção safávida, procurou o patrocínio dos estadistas otomanos.", "b8e9e300"]},
"OLAYLAR_EK14:1535-01-01:0":{"b": ["Fuzûlî conclui o mesnevi Leylâ vü Mecnûn", "e3ef4085"], "d": ["Leylâ vü Mecnûn, considerado um dos mais belos mesnevis da literatura turca clássica, foi escrito e concluído por Fuzûlî em 1535, a pedido dos poetas de Istambul que participaram na campanha de Bagdade do Legislador.", "bdb0a098"]},
"OLAYLAR_EK14:1538-01-01:0":{"b": ["Nomeação do arquiteto Sinan como arquiteto-chefe da corte", "7a753f0e"], "d": ["Segundo o artigo Sinan da Enciclopédia do Islão do TDV, com a morte em 1537 do arquiteto-chefe da corte Acem Alisi, Sinan, que se distinguira na campanha da Moldávia pela ponte que construiu sobre o rio Prut, foi investido neste cargo por recomendação do grão-vizir Lutfi Paxá. Começou assim o período de arquiteto-chefe de Sinan, que duraria mais de cinquenta anos.", "e99864c8"]},
"OLAYLAR_EK14:1543-06-01:0":{"b": ["Início da construção da Mesquita e Complexo de Şehzade", "1a70ddfd"], "d": ["O sultão Solimão, o Legislador, ordenou em 1543 a construção do complexo em nome do seu filho, o príncipe Mehmed, que perdera numa epidemia de peste; a obra começou em junho de 1543, concluindo-se primeiro o mausoléu e passando-se depois à construção da mesquita. Esta construção é, nas palavras do próprio arquiteto Sinan, a \"obra do meu aprendizado\".", "3f3d7e67"]},
"OLAYLAR_EK14:1547-01-01:0":{"b": ["Conclusão do Complexo de Üsküdar İskele (Mihrimah Sultan)", "3769007f"], "d": ["A construção do complexo da Praça de İskele, em Üsküdar, começou nos primeiros anos da década de 1540 e concluiu-se em 1547. É, cronologicamente, a primeira das duas grandes mesquitas que Mihrimah Sultan mandou construir ao arquiteto Sinan; a segunda (Edirnekapı) seria concluída cerca de vinte anos depois.", "01e5c0ad"]},
"OLAYLAR_EK14:1548-06-01:0":{"b": ["Veneza abre um consulado em Alepo", "3aad8b9e"], "d": ["No século XVI, o centro de gravidade comercial dos europeus deslocou-se de Damasco para Alepo. Como indicação concreta desta mudança, Veneza abriu em 1548 um consulado em Alepo; seguiram-na a França em 1557 e a Inglaterra em 1586. A cidade tornou-se o principal mercado onde se trocavam os tecidos de lã e a prata da Europa, as especiarias da Índia e, no fim do século, a seda iraniana.", "1c077dea"]},
"OLAYLAR_EK14:1548-08-01:0":{"b": ["Abertura ao culto da Mesquita de Şehzade", "2bb3f4b2"], "d": ["Depois de uma construção que durou cerca de cinco anos, a Mesquita de Şehzade foi aberta ao culto em agosto de 1548. Com o seu esquema de planta de cúpula central e dois minaretes, é considerada precursora das grandes obras posteriores do arquiteto Sinan; o complexo compõe-se de mesquita, mausoléu, madraça, imaret, tabhane e caravançarai.", "591f4ecf"]},
"OLAYLAR_EK14:1554-01-01:0":{"b": ["Início da construção da linha de aqueduto de Kırkçeşme", "14124b59"], "d": ["O arquiteto Sinan, por ordem de Solimão, o Legislador, estudou o abastecimento de água a Istambul a partir das florestas de Belgrado, comunicou que era possível, e a construção da grande instalação hidráulica começou em 1554 e foi concluída antes de 1563. O TDV descreve esta obra como a \"obra mais importante de Sinan do ponto de vista da engenharia e a maior em volume\".", "dc29aa04"]},
"OLAYLAR_EK14:1554-06-01:0":{"b": ["Abertura dos primeiros cafés em Istambul", "85c12f9f"], "d": ["A entrada do café na vida urbana otomana começou com os cafés abertos em Tahtakale pelo mercador de Alepo Hakem e por um indivíduo de Damasco chamado Şems. Em pouco tempo, nasceu um novo espaço público onde se reuniam pessoas de todas as camadas da sociedade; no último período do Legislador havia em Istambul cinquenta cafés.", "e1289ca2"]},
"OLAYLAR_EK14:1555-06-01:0":{"b": ["Ebüssuûd Efendi examina juridicamente a questão do gedik (direito de monopólio dos ofícios)", "5d4e2930"], "d": ["A questão do \"gedik\", o direito de monopólio e privilégio reconhecido a um número determinado de pessoas num ofício, voltou à ordem do dia no tempo do Legislador; o xeique do Islão Ebüssuûd Efendi estudou o assunto a fundo em 1555-56 e apresentou ao sultão a legitimidade da prática.", "a4bf6dee"]},
"OLAYLAR_EK14:1557-01-01:0":{"b": ["Seydi Ali Reis conclui em Istambul o Mir'âtü'l-Memâlik", "ee8640e1"], "d": ["Seydi Ali Reis concluiu em Istambul, em janeiro de 1557, a obra de viagens intitulada Mir'âtü'l-Memâlik, que escreveu durante toda a viagem de regresso a partir de Bagdade. A obra é uma fonte de primeira mão que narra o regresso por terra de um marinheiro otomano, do Oceano Índico à pátria, através da Ásia Central.", "3affe91e"]},
"OLAYLAR_EK14:1561-01-01:0":{"b": ["Construção do Complexo (Mesquita) de Rüstem Paxá", "02e30725"], "d": ["O complexo que Rüstem Paxá, genro e grão-vizir de Solimão, o Legislador, mandou construir ao arquiteto Sinan foi edificado entre 1555 e 1561. O edifício é conhecido pela sua arquitetura original, assente numa plataforma elevada sob a qual há lojas de arcadas, e pelos ricos azulejos de İznik.", "3a9a7e0b"]},
"OLAYLAR_EK14:1566-01-01:0":{"b": ["Conclusão da Ponte de Mostar", "e7f434af"], "d": ["A célebre Ponte de Mostar, sobre o rio Neretva, foi construída por volta de 1566-67 pelo arquiteto Hayreddin; a menção da ponte num documento oficial de 1568 confirma que estava concluída. A obra é um dos exemplos mais conhecidos da arquitetura clássica otomana de pontes, com um só arco ogival.", "62de5c2a"]},
"OLAYLAR_EK14:1566-01-01:1":{"b": ["Conclusão da Mesquita de Edirnekapı (Mihrimah Sultan)", "f2d21a82"], "d": ["A construção da mesquita, iniciada depois da confirmação em 1563 da licença de construção para Mihrimah Sultan, filha de Solimão, o Legislador, concluiu-se em 1566; o waqf do complexo foi redigido em 1570-71. O edifício é uma das grandes obras do arquiteto Sinan mais próximas das muralhas de Istambul.", "0f9e5ecd"]},
"OLAYLAR_EK14:1566-09-08:0":{"b": ["Bâkî escreve uma elegia para Solimão, o Legislador", "7aa6665f"], "d": ["Quando chegou a notícia da morte de Solimão, o Legislador, em Szigetvár, Bâkî, o \"sultânü'ş-şuarâ\" (sultão dos poetas) da época, escreveu uma das elegias mais célebres da literatura otomana.", "1328fbfd"]},
"OLAYLAR_EK14:1566-09-30:0":{"b": ["Bâkî apresenta um cülûsiye a Selim II", "6027f034"], "d": ["Logo após a subida ao trono de Selim II, Bâkî apresentou ao novo sultão um \"cülûsiye\" (poema de entronização) — segundo o TDV, imediatamente depois da elegia que escrevera pela morte do Legislador.", "1417fae7"]},
"OLAYLAR_EK14:1567-01-01:0":{"b": ["Conclusão da Ponte de Büyükçekmece", "5f49b3c5"], "d": ["A ponte, iniciada por ordem do sultão Solimão, o Legislador, foi concluída em 1567-68 pelo seu filho Selim II, por morte do sultão durante a campanha de Szigetvár. O arquiteto Sinan reparou também ele próprio os troços da ponte, construída no ponto em que o lago de Büyükçekmece desagua no mar, danificados por uma cheia.", "4478b56a"]},
"OLAYLAR_EK14:1568-01-01:0":{"b": ["Início da construção da Mesquita de Selimiye (Edirne)", "07e18c9e"], "d": ["A construção da Selimiye, a que o arquiteto Sinan chamou \"obra da minha mestria\", começou em 1568 em nome de Selim II e, depois de seis anos, concluiu-se em 1574 (a sua conclusão já está registada na cronologia). As lojas ocidentais da arasta e a escola primária foram concluídas por Dâvud Ağa depois da morte de Selim II, no reinado de Murad III.", "a3d4551b"]},
"OLAYLAR_EK14:1572-01-22:0":{"b": ["Morte de Kınalızâde Ali Çelebi — autor do Ahlâk-ı Alâî, texto clássico da filosofia moral otomana", "dd921873"], "d": ["Kınalızâde Ali Çelebi, autor do Ahlâk-ı Alâî, o texto clássico mais conhecido da filosofia moral otomana, morreu a 22 de janeiro de 1572, sendo kazasker da Anatólia. Da sua obra existem mais de setenta cópias nas bibliotecas de Istambul.", "8aa682b5"]},
"OLAYLAR_EK14:1573-01-01:0":{"b": ["Construção do Complexo de Piyâle Paxá", "75411278"], "d": ["Piyâle Paxá, kapudan-paxá e genro de Selim II, comprou em 1573 o terreno do complexo e mandou o arquiteto Sinan construí-lo. O complexo foi concebido como um vasto conjunto composto de mesquita, madraça, tekke, mausoléu, cemitério, escola primária, fonte, bazar e hamam.", "91e37e16"]},
"OLAYLAR_EK14:1577-01-01:0":{"b": ["Conclusão da Ponte do Drina (Sokullu Mehmed Paxá)", "1d668c73"], "d": ["A ponte, construída pelo arquiteto Sinan sob o patrocínio do grão-vizir Sokullu Mehmed Paxá, foi concluída em 1577-78 segundo a data da sua inscrição; alguns investigadores sustentam que a construção começara em 1571-72. A ponte é o símbolo da ligação de Sokullu a Višegrad, onde nasceu.", "cbbd4b7e"]},
"OLAYLAR_EK14:1577-01-01:1":{"b": ["Construção da Mesquita de Azapkapı (Sokullu Mehmed Paxá)", "f7b57feb"], "d": ["A mesquita, situada junto ao pilar da Ponte de Unkapanı do lado de Şişhane, foi mandada construir ao arquiteto Sinan pelo grão-vizir Sokullu Mehmed Paxá. O edifício é uma das duas mesquitas de Sinan construídas em nome de Sokullu (a outra é a mesquita de Kadırga).", "badb6241"]},
"OLAYLAR_EK14:1578-01-02:0":{"b": ["Murad III ordena por édito a redação do Hünernâme", "b125710d"], "d": ["Murad III ordenou, por édito de 2 de janeiro de 1578, a Seyyid Lokman que escrevesse o Hünernâme, que tem por tema a vida dos sultões desde Osman Gazi até à sua própria época; as miniaturas da obra foram preparadas por Nakkaş Osman e pela sua equipa.", "5b7078bd"]},
"OLAYLAR_EK14:1580-01-01:0":{"b": ["Conclusão da Mesquita de Zal Mahmud Paxá", "732f75bc"], "d": ["Na construção do complexo, iniciada depois do casamento de Zal Mahmud Paxá com Şah Sultan em 1574, a obra da mesquita concluiu-se em 1580; as madraças prolongaram-se até 1582 e a fonte até 1590. O complexo distingue-se pela sua planta original, com dois minaretes simétricos, nas encostas de Eyüp.", "9cf44e2d"]},
"OLAYLAR_EK14:1588-01-01:0":{"b": ["Conclusão do II volume do Hünernâme", "70a1e741"], "d": ["O segundo volume do Hünernâme foi concluído em janeiro de 1588; com 65 miniaturas, tornou-se uma das obras mais valiosas, do ponto de vista documental, da historiografia otomana. Ambos os volumes foram ilustrados na oficina de Nakkaş Osman.", "148989eb"]},
"OLAYLAR_EK14:1592-01-01:0":{"b": ["Dâvud Ağa torna-se arquiteto-chefe da corte", "8cdc7f53"], "d": ["Depois do curto intervalo que se seguiu à morte do arquiteto Sinan em 1588, Dâvud Ağa passou a ser mencionado nos documentos oficiais como arquiteto-chefe da corte a partir de 1592. Dâvud Ağa, que se encarregou de alguns elementos complementares do Complexo de Selimiye e da primeira construção da Mesquita Nova, é um dos arquitetos mais importantes da época.", "cca50071"]},
"OLAYLAR_EK14:1598-04-09:0":{"b": ["Lançamento da primeira pedra da Mesquita Nova (Eminönü)", "d3cddc01"], "d": ["Sob o patrocínio de Safiye Sultan, mãe de Mehmed III, os alicerces da mesquita foram lançados com blocos de pedra, depois de o terreno ter sido consolidado com estacas. Dois artigos distintos do TDV dão datas diferentes para este acontecimento (o artigo Yenicami Külliyesi, 9 de abril de 1598; o artigo Dâvud Ağa, 23 de agosto de 1597); aqui adotou-se a data do artigo específico do próprio edifício.", "744933c0"]},
"OLAYLAR_EK14:1598-09-01:0":{"b": ["Morte de Dâvud Ağa de peste e interrupção da construção da Mesquita Nova", "81f2cd04"], "d": ["Dâvud Ağa, que morreu na epidemia de peste em setembro de 1598, quando a Mesquita Nova se elevava ainda apenas um côvado acima do solo, foi substituído como arquiteto-chefe por Dalgıç Ahmed Çavuş. O TDV observa que a data da morte aparece também como 1599-1600 numa tradição alternativa baseada num poema cronogramático, e que a data exata não pôde ser fixada.", "02ee24e4"]},
"OLAYLAR_EK14:1599-06-01:0":{"b": ["Exportação intensa do sof de Ancara para a Europa", "3f37018d"], "d": ["O sof e o şâlî tecidos em Ancara eram exportados, além dos mercados internos como Istambul, Bursa, Damasco e Alepo, para Veneza, a Polónia, a Inglaterra e a França. No exemplo dado pelo TDV, em 1599, dezoito mercadores compraram 162 cargas de sof no valor de 5.700.000 akçe e expediram-nas para Alepo e Veneza.", "966119b2"]},
"OLAYLAR_EK14:1603-12-20:0":{"b": ["Paragem da construção da Mesquita Nova por morte de Mehmed III", "5acef053"], "d": ["Depois da morte, em 1603, de Mehmed III, filho de Safiye Sultan, sua fundadora, Safiye Sultan foi enviada para o Palácio Velho e a construção da Mesquita Nova ficou inacabada; o edifício aguardou assim, por concluir, cerca de sessenta anos.", "6d8a4c2b"]},
"OLAYLAR_EK14:1633-01-01:0":{"b": ["Kâtib Çelebi começa em Alepo a pesquisa para o Keşfü'z-Zünûn", "094e6870"], "d": ["Kâtib Çelebi começou em 1633, em Alepo, a reunir o material do Keşfü'z-Zünûn, que viria a ser a sua obra-prima bibliográfica. Durante este trabalho, que duraria vinte anos, examinou uma a uma as bibliotecas e as livrarias das cidades por onde passou.", "92278c89"]},
"OLAYLAR_EK14:1635-01-01:0":{"b": ["Nef'î executado por causa das suas sátiras", "5e459c60"], "d": ["Nef'î, poeta de divã conhecido pelas suas sátiras, foi executado em 1635 por ordem de Murad IV por causa da coletânea satírica intitulada Sihâm-ı Kazâ. O grão-vizir Bayram Paxá entregou-o; Nef'î foi estrangulado no depósito de lenha do palácio e o seu corpo foi lançado ao mar.", "e3b52153"]},
"OLAYLAR_EK14:1640-01-01:0":{"b": ["Evliya Çelebi parte na sua primeira viagem — início do Seyahatnâme", "ca3ce3f9"], "d": ["Evliya Çelebi fez em 1640 a sua primeira viagem fora de Istambul, a Bursa, iniciando uma vida de viagens de quarenta anos que formaria a base do seu Seyahatnâme em dez volumes. A obra termina abruptamente, inacabada, no décimo volume, com a morte do autor por volta de 1684.", "1db7969c"]},
"OLAYLAR_EK14:1640-06-01:0":{"b": ["Elaboração do registo abrangente de narh", "6c1e231b"], "d": ["Embora a prática do narh (preço máximo) remonte a tempos muito antigos no mundo otomano, o registo de narh mais abrangente que chegou até nós data de 1640; este registo, que abrange géneros alimentícios, vestuário, serviços, padrões e condições de higiene, \"funcionou, nas palavras do TDV, como uma verdadeira lei de regulação do mercado.\"", "3f704851"]},
"OLAYLAR_EK14:1648-01-01:0":{"b": ["Kâtib Çelebi começa a escrever pela primeira vez o Cihannümâ", "554c6734"], "d": ["Kâtib Çelebi começou em 1648 a primeira redação do Cihannümâ, com o objetivo de preencher a lacuna do conhecimento geográfico otomano perante as descobertas geográficas do Ocidente. Esta primeira versão ficou inacabada por não se terem encontrado fontes suficientes sobre alguns países europeus.", "aa7d5e31"]},
"OLAYLAR_EK14:1650-01-01:0":{"b": ["O sistema iltizam amadurece ao passar para o monopólio da classe militar", "2c587934"], "d": ["O método do iltizam (adjudicação a particulares da cobrança de impostos mediante um preço) era aplicado desde a segunda metade do século XV, mas generalizava-se rapidamente a partir do início do século XVI. Segundo o TDV, o processo em que o setor passou inteiramente para o monopólio dos membros da classe militar concluiu-se em 1650; o iltizam tornou-se assim o principal método financeiro, substituindo o sistema timar.", "d50f2237"]},
"OLAYLAR_EK14:1654-12-01:0":{"b": ["Kâtib Çelebi começa a reescrever o Cihannümâ de raiz", "e9c68110"], "d": ["Kâtib Çelebi, que deixara incompleta a primeira redação, começou no final de 1654 a reescrever o Cihannümâ de raiz. Esta segunda versão também não pôde ser concluída; a obra ficou inacabada com a morte do autor em 1657, quando chegara a Van, e só foi impressa neste estado em 1732 por İbrahim Müteferrika.", "5a96db0a"]},
"OLAYLAR_EK14:1665-10-30:0":{"b": ["Conclusão e abertura ao culto da Mesquita Nova", "d6d86c82"], "d": ["A construção da Mesquita Nova, inacabada durante mais de sessenta anos, foi concluída sob a direção do arquiteto-chefe Meremetçi Mustafa Ağa, que Hatice Turhan Valide Sultan nomeara em 1661, e abriu ao culto a 30 de outubro de 1665 com a oração de sexta-feira aí celebrada.", "0ec54cd6"]},
"OLAYLAR_EK14:1675-01-01:0":{"b": ["Mehmed IV faz jogar cirit durante dias na festa de circuncisão em Edirne", "3638a5b6"], "d": ["Mehmed IV organizou, na festa de circuncisão dos seus príncipes realizada em Edirne em 1675, competições de cirit que duraram dias; este é referido de forma especial no artigo Cirit do TDV como um dos exemplos mais ostentosos do apoio da corte otomana ao desporto do cirit.", "57c8c183"]},
"OLAYLAR_EK14:1679-01-01:0":{"b": ["Hâfız Osman desenvolve o seu estilo caligráfico próprio", "93081cb3"], "d": ["Hâfız Osman, da linhagem de Şeyh Hamdullah, desenvolveu em 1679, no aklâm-ı sitte, um estilo novo e próprio, que depois seria designado \"escola de Hâfız Osman\". Este estilo perdurou até aos nossos dias em dois ramos distintos.", "8d00a956"]},
"OLAYLAR_EK14:1695-01-01:0":{"b": ["Hâfız Osman nomeado mestre de caligrafia de Mustafa II", "d976cda4"], "d": ["Hâfız Osman, considerado o calígrafo mais exímio da época, foi nomeado em 1695 mestre de caligrafia de Mustafa II, que acabava de subir ao trono. Ao longo da vida formou cerca de cinquenta calígrafos e copiou 25 exemplares do Alcorão.", "c70668d5"]},
"OLAYLAR_EK14:1711-01-01:0":{"b": ["Morte de Itrî", "62750526"], "d": ["Buhûrîzâde Mustafa Itrî Efendi, um dos maiores compositores da música turca, morreu em 1711, segundo fontes próximas da época. Com obras como o tekbir de segâh e o na't de rast, deixou as obras-primas da música das mesquitas e dos tekke.", "a2ccc3ba"]},
"OLAYLAR_EK14:1718-01-01:0":{"b": ["Nedîm destaca-se como precursor da poesia da Era das Tulipas", "d3c40dbb"], "d": ["Durante a Era das Tulipas, entre 1718 e 1730, Nedîm desenvolveu um novo estilo poético que se distinguia pela perfeição da expressão, pela busca de simplicidade e por um estilo espirituoso. Este estilo, que se desenvolveu em redor do grão-vizir Nevşehirli Damad İbrahim Paxá, é considerado o maior representante da corrente de nacionalização da poesia de divã.", "0521666a"]},
"OLAYLAR_EK14:1720-01-01:0":{"b": ["Levnî ilustra o Surnâme-i Vehbî", "8c127866"], "d": ["O pintor da corte Levnî ilustrou com 137 miniaturas o Surnâme-i Vehbî, que narra a festa de circuncisão dos príncipes de Ahmed III em 1720. Ao contrário dos exemplos anteriores, não confinou as festividades ao Atmeydanı, mas retratou-as em diferentes recantos da cidade, iniciando assim uma nova conceção na arte da miniatura otomana.", "bd655b91"]},
"OLAYLAR_EK14:1727-06-01:0":{"b": ["O sistema gedik fixa-se oficialmente como ordem de ofícios assente no monopólio", "cd0f79a7"], "d": ["Segundo o TDV, a transformação sistemática em que o direito de gedik adquiriu o sentido de \"monopólio, privilégio e uma espécie de patente\" é observável a partir de 1727; esta ordem, que reconhecia o direito de trabalhar a um número determinado de pessoas num ofício, fixou-se, na maior parte, em lojas de propriedade waqf sob o nome de \"direito de gedik\".", "18446662"]},
"OLAYLAR_EK14:1730-09-25:0":{"b": ["Destruição de Sâdâbâd na revolta de Patrona Halil", "8a30f9a0"], "d": ["Durante a revolta de Patrona Halil, que estalou a 25 de setembro de 1730, centenas de pavilhões e edifícios em Sâdâbâd foram destruídos; este complexo, símbolo da Era das Tulipas, nunca mais recuperou o seu antigo esplendor.", "a26b72e6"]},
"OLAYLAR_EK14:1730-10-28:0":{"b": ["Morte de Nedîm durante a revolta de Patrona Halil", "06bf909e"], "d": ["Nedîm, que era professor na Madraça de Sekban Ali Paxá quando estalou a Revolta de Patrona Halil, morreu nos dias que se seguiram à revolta. O dia da morte não é conhecido; mas, como o kassam hüccet relativo ao seu espólio foi lavrado a 15 de Rebîülâhir de 1143 (28 de outubro de 1730), morreu antes desta data. Há versões diversas sobre a causa da morte: uma parte das fontes escreve que morreu de uma doença do medo (illet-i vehîme) ou de uma doença de tremores contraída por causa da bebida e do ópio, enquanto Müstakimzâde escreve que, durante a revolta, subiu de medo ao telhado da sua casa e morreu ao cair dali. Com a sua morte, o brilho cultural da Era das Tulipas terminou também de facto.", "49085a6c"]},
"OLAYLAR_EK14:1732-01-01:0":{"b": ["Morte de Levnî", "dd48b56e"], "d": ["Levnî, considerado o último grande representante da arte da miniatura otomana, morreu em 1732. A maior parte das suas obras encontra-se hoje no Museu do Palácio de Topkapı.", "25f589a6"]},
"OLAYLAR_EK14:1749-01-19:0":{"b": ["Lançamento da primeira pedra da Mesquita e Complexo de Nuruosmaniye", "397ec798"], "d": ["Os alicerces do Complexo de Nuruosmaniye foram lançados por Mahmud I a 19 de janeiro de 1749. Este edifício é considerado a primeira grande aplicação do estilo barroco europeu na arquitetura otomana e afasta-se claramente do esquema clássico de complexo.", "c1e0698f"]},
"OLAYLAR_EK14:1755-12-05:0":{"b": ["Inauguração da Mesquita e Complexo de Nuruosmaniye", "15d83731"], "d": ["A inauguração do complexo, iniciado por Mahmud I, que não chegou a vê-lo concluído, realizou-se a 5 de dezembro de 1755, no reinado do seu irmão Osman III. A mesquita recebeu o nome, em alusão a Osman III, que realizou a inauguração, no sentido de \"Luz de Osman\".", "4722cd6a"]},
"OLAYLAR_EK14:1775-04-29:0":{"b": ["Abertura da Mühendishâne-i Bahrî-i Hümâyun", "a2fab1cd"], "d": ["A primeira escola moderna de engenharia naval otomana, a Mühendishâne-i Bahrî-i Hümâyun, abriu a 29 de abril de 1775, segundo documentos de arquivo franceses, no reinado de Abdülhamid I, durante o grão-vizirato de Derviş Mehmed Paxá.", "cafb2bf9"]},
"OLAYLAR_EK14:1775-06-01:0":{"b": ["Criação do sistema esham", "eabd8ece"], "d": ["Perante o peso da indemnização de 7,5 milhões de kuruş trazida pelo Tratado de Küçük Kaynarca, o sistema esham foi criado em 1775. Neste método, concebido para ultrapassar os limites do malikâne, o rendimento do mukātaa era dividido em ações e, ao contrário do malikâne, também mulheres, não muçulmanos e gente comum podiam ser titulares de participações.", "01a12eaa"]},
"OLAYLAR_EK14:1778-01-09:0":{"b": ["Nascimento de Hammâmîzâde İsmail Dede Efendi", "c033f039"], "d": ["Hammâmîzâde İsmail Dede Efendi, um dos compositores mais prolíficos da música turca, nasceu a 9 de janeiro de 1778 no bairro de Şehzadebaşı, em Istambul. Ao longo da vida compôs mais de 500 obras; cerca de 294 delas chegaram até aos nossos dias.", "0b7fc673"]},
"OLAYLAR_EK14:1793-07-14:0":{"b": ["Início da construção da Mühendishâne-i Berrî-i Hümâyun", "4f5d521a"], "d": ["A construção da Mühendishâne-i Berrî-i Hümâyun, uma das instituições mais importantes das reformas do Nizâm-ı Cedîd de Selim III, começou a 14 de julho de 1793. O edifício concluiu-se em setembro de 1795 e abriu ao ensino; a instituição foi a segunda escola de engenharia militar otomana, tomando como modelo as academias militares da Europa.", "79c0131c"]},
"OLAYLAR_EK14:1794-06-01:0":{"b": ["Selim III começa a abolir o monopólio de algumas guildas de ofícios", "008f4a7d"], "d": ["Segundo o artigo Esnaf do TDV, na ordem das guildas otomanas, entrelaçada desde a sua origem com a organização ahî, titulares como o \"ahî baba\" e o \"xeique\" exerceram a chefia das guildas até ao início do século XIX; como, no século XVIII, as guildas, com os seus monopólios, elevavam os preços acima do narh e isso criava pressão económica, Selim III começou, a partir de 1794, a abolir o monopólio das guildas de géneros alimentícios básicos.", "35d33c12"]},
"OLAYLAR_EK14:1812-01-01:0":{"b": ["Dede Efendi admitido no palácio como musâhib-i şehriyârî", "0cb99ac3"], "d": ["Dede Efendi, que no reinado de Selim III chamara a atenção do sultão com uma composição em bûselik, foi admitido em 1812 por Mahmud II entre os \"musâhib-i şehriyârî\" (companheiros de conselho privado do sultão), e pouco depois ascendeu a müezzinbaşı.", "15b3c49d"]},
"OLAYLAR_EK14:1830-12-01:0":{"b": ["Realização do primeiro recenseamento regular no Império Otomano", "4f004c6c"], "d": ["Mahmud II mandou fazer pela primeira vez, no final de 1830, um recenseamento regular, com o objetivo de apurar a população a recrutar; foi registada apenas a população masculina e apuraram-se cerca de 7,5 milhões de pessoas na Anatólia-Rumélia. Em algumas regiões, como Erzurum e Van, o recenseamento só pôde ser concluído em 1836.", "af4a7bcf"]},
"OLAYLAR_EK14:1833-06-01:0":{"b": ["Fundação do Feshâne-i Âmire", "971ab85a"], "d": ["Para satisfazer a necessidade de fezes do exército Asâkir-i Mansûre-i Muhammediyye, fundado depois da abolição do Corpo dos Janízaros em 1826, começou-se em 1833 a produzir fezes na Praça Cündî, em Kadırga, com um capital de 1,5 milhões de kuruş. As instalações foram transferidas em 1839 para o Palácio de Hatice Sultan, em Eyüp; o Feshâne constituiu a base da indústria têxtil otomana.", "c8481f41"]},
"OLAYLAR_EK14:1839-05-14:0":{"b": ["A escola de medicina recebe o nome de Mekteb-i Tıbbiyye-i Adliyye-i Şâhâne", "187d60f3"], "d": ["A escola de medicina, transferida para o edifício da Escola dos Aghas do Enderun em Galatasaray, recebeu a 14 de maio de 1839, com a visita de Mahmud II, o nome de \"Mekteb-i Tıbbiyye-i Adliyye-i Şâhâne\"; a instituição ficou assim oficialmente registada com a identidade de escola militar-administrativa.", "6a65292b"]},
"OLAYLAR_EK14:1846-11-29:0":{"b": ["Morte de Dede Efendi em Mina, durante a peregrinação", "c3e613a2"], "d": ["Hammâmîzâde İsmail Dede Efendi, que contraiu cólera em Mina, onde fora cumprir o dever da peregrinação, morreu a 29 de novembro de 1846. Com a morte do artista, que compusera sete ayin mevlevis distintos entre 1824 e 1839, encerrou-se uma época da música otomana clássica.", "fea95526"]},
"OLAYLAR_EK14:1850-06-01:0":{"b": ["Adoção do Código Comercial de 1850", "8ac085fd"], "d": ["No quadro das reformas jurídicas do período do Tanzimat, foram recebidas dos Estados ocidentais, por tradução e adaptação, novas leis: o código penal entrou em vigor em 1840, o código comercial em 1850 e o código agrário em 1857. O Código Comercial foi a primeira codificação moderna do direito comercial otomano.", "2f7aeb1b"]},
"OLAYLAR_EK14:1859-06-01:0":{"b": ["Início da grande vaga de migração dos tártaros da Crimeia e dos povos do Cáucaso para território otomano", "8832c06d"], "d": ["Depois de Şeyh Şâmil ter sido feito prisioneiro pelos russos em 1859, muitos muhacires circassianos e nogais do Cáucaso começaram a emigrar para território otomano, juntamente com os tártaros da Crimeia. Esta vaga de migração prolongou-se com diferentes intensidades até depois da Guerra Otomano-Russa de 1877-78.", "580ce507"]},
"OLAYLAR_EK14:1860-01-16:0":{"b": ["Fundação da Comissão dos Muhâcirîn", "9717e77e"], "d": ["Para gerir a crescente vaga de migração do Cáucaso, o governo otomano fundou a 16 de janeiro de 1860 a Comissão dos Muhâcirîn. A Comissão coordenou os trabalhos de instalação na Anatólia, nos Balcãs e na Síria e funcionou até 1875.", "404d989d"]},
"OLAYLAR_EK14:1863-06-01:0":{"b": ["Reestruturação do Bank-ı Osmanî como Bank-ı Osmanî-i Şâhâne (Banco Otomano)", "c3530456"], "d": ["Em 1856, depois da Guerra da Crimeia, fora fundado o Bank-ı Osmanî, com sede em Londres e capital inglês, para gerir os pagamentos da dívida externa. Em 1863, foi concedida a um grupo conjunto franco-inglês a licença para fundar um novo banco com o nome de Bank-ı Osmanî-i Şâhâne (Banco Otomano); a instituição recebeu mais tarde também a autoridade para emitir notas.", "72227299"]},
"OLAYLAR_EK14:1864-03-30:0":{"b": ["Fundação da Cem'iyyet-i Tedrîsiyye-i İslâmiyye", "77ad553a"], "d": ["A Cem'iyyet-i Tedrîsiyye-i İslâmiyye foi fundada a 30 de março de 1864 com o objetivo de assumir a educação de aprendizes muçulmanos pobres; esta iniciativa de associação civil é um exemplo pioneiro da transformação da tradição das instituições de beneficência num projeto escolar moderno. A associação abrirá a Darüşşafaka nove anos depois.", "2ea443d2"]},
"OLAYLAR_EK14:1864-06-01:0":{"b": ["Regulamentação do sistema de muhtar e do conselho de anciãos pelo Regulamento dos Vilaietes de 1864", "1a2e8cf2"], "d": ["Com o Regulamento dos Vilaietes de 1864, a administração das aldeias foi reorganizada; nas aldeias em que muçulmanos e não muçulmanos viviam juntos, aceitou-se que cada comunidade elegesse o seu próprio muhtar e o seu conselho de anciãos. O conselho de anciãos obteve assim, pela primeira vez, um lugar oficial na administração das aldeias/bairros.", "eee4df7d"]},
"OLAYLAR_EK14:1864-07-01:0":{"b": ["Auge do Grande Exílio dos Circassianos", "b2ab1874"], "d": ["Com a ocupação do Cáucaso pela Rússia entre 1858 e 1878, mais intensamente em 1861-1864, 1,2 a 1,5 milhões de circassianos foram forçados a emigrar para território otomano. Segundo o TDV, muitos investigadores qualificam este acontecimento como \"o primeiro movimento de limpeza étnica da história moderna\".", "d1bb6d70"]},
"OLAYLAR_EK14:1869-09-01:0":{"b": ["Publicação do Regulamento da Instrução Pública de 1869", "787f6022"], "d": ["O Regulamento da Instrução Pública, publicado a 1 de setembro de 1869, foi o primeiro texto abrangente a regular a educação geral nas províncias e no centro. Com o regulamento foi criado o Meclis-i Kebîr-i Maârif; com esta disposição começou a reestruturação das escolas primárias, que deixaram de ser uma fase de ensino puramente religioso para passarem a orientar-se para o ensino da leitura e da escrita.", "51087b3c"]},
"OLAYLAR_EK14:1873-06-28:0":{"b": ["A escola Darüşşafaka começa a ensinar", "525c457c"], "d": ["A Darüşşafaka, fundada pela Cem'iyyet-i Tedrîsiyye-i İslâmiyye, começou efetivamente a ensinar a 28 de junho de 1873, para educar gratuitamente em regime de internato crianças muçulmanas órfãs e pobres; a idade máxima de admissão foi fixada em dez anos.", "c4f863b5"]},
"OLAYLAR_EK14:1894-07-10:0":{"b": ["Terramoto de Istambul de 1894", "7ae7f648"], "d": ["O terramoto ocorrido a 10 de julho de 1894 ao largo do Golfo de İzmit atingiu gravemente Istambul; muitas mesquitas e edifícios históricos, incluindo as muralhas de Istambul, ficaram danificados. O artigo sobre zelzele do TDV conta este terramoto, juntamente com os de 1509, 1719 e 1766, entre os que causaram grandes perdas de vidas e de bens na região do Mármara.", "61236a0f"]},
"OLAYLAR_EK14:1896-02-02:0":{"b": ["Abertura do Dârülaceze", "a30baf31"], "d": ["O Dârülaceze, preparado por ordens dadas por Abdülhamid II a partir de 1890, foi inaugurado a 2 de fevereiro de 1896 pelo grão-vizir Halil Rifat Paxá. A instituição, que albergava crianças sem família, idosos e necessitados, era, com o seu hospital de 200 camas, as suas oficinas e os seus locais de culto separados, como mesquita, igreja e sinagoga, o maior complexo de assistência social da sua época.", "9cf12efa"]},
"OLAYLAR_EK14:1900-08-31:0":{"b": ["Refundação do Dârülfünûn-ı Şâhâne como instituição permanente", "7d6d8fc4"], "d": ["O Darülfünun, depois de duas tentativas fracassadas anteriores (1863 e 1870), foi refundado a 31 de agosto de 1900, com o nome de Dârülfünûn-ı Şâhâne, como instituição permanente; o TDV qualifica esta data como a base direta do atual sistema universitário turco.", "7d7fd7ca"]},
"OLAYLAR_EK15:1337-09-09:0":{"b": ["Os Serbedârîs tomam Sebzevâr — o primeiro Estado pós-ilkhânida no Coração", "af997fec"], "d": ["Quando a autoridade central ilkhânida ruiu com a morte de Ebû Saîd (30 de novembro de 1335), o ressentimento acumulado em Horasão contra os cobradores de impostos explodiu em Bâştîn: Abdürrezzâk revoltou-se a 13 de março de 1337 e, a 9 de setembro de 1337 (12 de Safer de 738), tomou Sebzevâr. \\\"Serbedâr\\\" — \\\"cabeça na forca\\\" — é o nome, expressão das suas próprias palavras, que significa que estavam dispostos a ser enforcados se fossem derrotados.", "c0abed9c"]},
"OLAYLAR_EK15:1359-01-01:0":{"b": ["Os Seyyids Mar'aşî tomam Âmül — domínio dos seyyids em Mazandaran", "c0e03266"], "d": ["O seyyid Kıvâmüddin Mar'aşî, seguindo o caminho aberto pelos Serbedârîs em Horasão, tomou Âmül no ano de 760 (1359) e fundou um Estado de seyyids na costa sul do Cáspio. A dinastia estendeu-se a Sârî, Bârfurûş e arredores; foi abalada nas campanhas de Timur e dissolvida no tempo do safávida Xá Abbas I.", "d93ea1fd"]},
"OLAYLAR_EK15:1371-01-01:0":{"b": ["A dinastia Kârkiyâ fundada em Gîlân — os últimos senhores independentes da costa do Cáspio", "6e5f9db7"], "d": ["Ali Kiyâ regressou a Gîlân com a sua família e fundou em 773 (1371-72) o domínio Kârkiyâ, com centro em Lâhîcan; a dinastia manteve a costa sudoeste do Cáspio durante mais de dois séculos e durou até à anexação da região, em 1592, por Xá Abbas I, o safávida.", "670fc7fd"]},
"OLAYLAR_EK15:1400-01-01:0":{"b": ["O domínio dos Dâcû em Dârfûr passa para os Tuncûr", "6eb22a2a"], "d": ["Segundo o artigo Dârfûr da Enciclopédia do Islão do TDV, os primeiros a estabelecer-se na região e a fundar o primeiro Estado foram a tribo dos Dâcû; os Dâcû, que dominaram a região durante os séculos XIII e XIV, perderam o domínio comercial para os Tuncûr, e no século XV a situação, em especial na região central, inverteu-se inteiramente a favor dos Tuncûr.", "2709880c"]},
"OLAYLAR_EK15:1564-01-01:0":{"b": ["A Espanha retoma o penhasco de Bâdis (Peñón de Vélez)", "0dc52728"], "d": ["O artigo Sa'dîler do TDV regista que a tomada de Bâdis pelos espanhóis foi um golpe pesado para a marinha do Magrebe (1564). Esta posição rochosa na costa norte de Marrocos servia de apoio à pirataria no Mediterrâneo Ocidental e à rivalidade otomano-espanhola.", "110ee39e"]},
"OLAYLAR_EK15:1610-01-01:0":{"b": ["Cedência de al-Arâiş (Larache) à Espanha", "7b8f6e27"], "d": ["Nos anos de guerra civil em que a dinastia saadiana se fragmentava, o porto de al-Arâiş, na costa atlântica, foi cedido à Espanha. O artigo Sa'dîler do TDV regista que nesta época o país estava dividido nos emirados de Marraquexe (sul) e de Fez (norte) e que as partes em luta pelo trono procuravam ajuda externa. O porto permanecerá quase oitenta anos em mãos espanholas e será retomado em 1689 por Mevlây İsmâil.", "597cc620"]},
"OLAYLAR_EK15:1614-01-01:0":{"b": ["A Mamûra (Mehdiye) passa para as mãos dos espanhóis", "c8fd494e"], "d": ["O porto de Mamûra (Ma'mûre / Mehdiye), na foz do rio Sebû, foi tomado em 1614 pelos espanhóis e fortificado com o nome de San Miguel de Ultramar. O artigo Mevlây İsmâil do TDV regista que o porto foi retomado aos espanhóis, num ataque súbito, no ano de 1092 (1681) — isto é, o domínio espanhol durou sessenta e sete anos.", "3f87063c"]},
"OLAYLAR_EK15:1659-01-01:0":{"b": ["Fim da dinastia saadiana — início do período alauita (filalida) em Marrocos", "b1afa579"], "d": ["A Enciclopédia do Islão do TDV define o artigo Sa’dîler como \\\"uma dinastia islâmica que reinou em Marrocos (1511-1659)\\\". A dinastia, que em 1549 pôs fim ao domínio uatácida e unificou todo o Marrocos, que em 1578 aniquilou o exército português em Wâdisseyl e que nunca esteve ligada aos otomanos em nenhum período, terminou em 1659, depois de longas lutas pelo trono. O seu lugar foi tomado pelos xarifes alauitas (filalidas) vindos de Tâfilâlt; Mevlây Reşîd entrou em Fez em 1666 e consolidou a nova dinastia, e o seu irmão Mevlây İsmâil limpou as posições europeias da costa atlântica.", "1e7caacc"]},
"OLAYLAR_EK15:1673-01-01:0":{"b": ["A Espanha ocupa as ilhas de al-Hüseyme (Alhucemas)", "954ca998"], "d": ["As ilhas de al-Hüseyme, na costa mediterrânica, foram ocupadas em 1673 pela armada espanhola. Juntamente com Bâdis e Ceuta, estão entre as posições que a Espanha manteve na costa norte de Marrocos e que continuam em seu poder até hoje. No mesmo ano, Mevlây Reşîd, irmão mais velho de Mevlây İsmâil, entrara em Marraquexe e recebera a bay'a do povo, e o domínio filalida consolidara-se no sul — esta perda na costa mostra que a unificação interna ainda não tinha correspondência na frente externa.", "b67d415f"]},
"OLAYLAR_EK15:1689-01-01:0":{"b": ["Mevlây İsmâil retoma al-Arâiş aos espanhóis", "a54bc6ee"], "d": ["O artigo Mevlây İsmâil do TDV é claro: \"Em 1100 (1689), retomando Arâîş aos espanhóis, apoderaram-se de 200 canhões e, dois anos depois, retomaram também Asîle.\" Este é um dos elos da cadeia de limpeza da costa do sultão filalida — Tânger foi retomada aos ingleses em 1678, Mamûra em 1681, al-Arâiş em 1689, Asîle em 1691. O porto, abandonado oitenta anos antes na guerra civil saadiana, voltou assim a Marrocos.", "cd2b390d"]},
"OLAYLAR_EK15:1695-01-01:0":{"b": ["Fundação do Sultanato de Dârfûr — a dinastia Keyra e Süleyman Solonc", "0fc1c112"], "d": ["Segundo o TDV, a fundação do Sultanato de Dârfûr situa-se depois da confusão que se seguiu à invasão da região por Bumû el-Kasîr nos fins do século XVII. Os Fûr, sob a liderança da dinastia Kîrâ (Keyra), chefiada por Süleyman Solonc, tomaram o poder aos Dâcû e aos Tuncûr e estabeleceram uma administração sólida. Süleyman Solonc reinou entre 1695 e 1715. Os sultões de Dârfûr corresponderam-se nos séculos seguintes com a Sublime Porta; Abdülmecid e Abdülaziz confirmaram os seus reinados.", "58155fc4"]},
"OLAYLAR_EK15:1792-09-22:0":{"b": ["Proclamação da Primeira República em França — fim da monarquia", "d53d49b0"], "d": ["Na primeira sessão da Convenção Nacional, a monarquia foi abolida e, no dia seguinte, foi proclamada a Primeira República; o primeiro ano do novo calendário foi iniciado a partir deste dia. Para os otomanos, o interlocutor não mudou, mas mudou a natureza do interlocutor: nos anos do Nizâm-ı Cedîd de Selim III, a França já não era uma dinastia, mas um regime, e quem desembarcaria no Egito em 1798 era o exército desse regime.", "a16f5b39"]},
"OLAYLAR_EK15:1857-07-11:0":{"b": ["A queda da Grande Cabília — o cativeiro de Lalla Fatma N'Sûmer", "0f61ff08"], "d": ["O artigo Cezayir do TDV regista que, com a ocupação da região montanhosa da Cabília (Bilâdü'l-kabâil) no termo das expedições de 1853, 1854 e 1857, o movimento francês de ocupação da Argélia ficou em grande parte concluído. A expedição de 1857 rompeu a linha de Tîzî Vezzû e Akbû; Lalla Fatma N'Sûmer, símbolo da resistência, foi feita prisioneira. Extinguiu-se assim o último grande foco de resistência que subsistira depois da rendição do emir Abdülkādir em 1847.", "6d14160e"]},
"OLAYLAR_EK15:1899-12-29:0":{"b": ["Ocupação de Aynı Sâlih (Tîdîkelt) pelos franceses", "1e28d1d0"], "d": ["Aynı Sâlih, centro do conjunto de oásis de Tîdîkelt, no meio do Saara, foi tomada pelas forças francesas a 29 de dezembro de 1899. Este é o primeiro grande passo da expansão francesa que descia da costa argelina para o sul a transbordar para o deserto; em dois anos, Tuvât e Gûrâre seguirão o mesmo caminho.", "99e7ecb6"]},
"OLAYLAR_EK15:1901-02-21:0":{"b": ["Anexação à França dos oásis de Tuvât · Gûrâre · Tîdîkelt", "d412838b"], "d": ["A faixa de oásis de Tuvât, Gûrâre e Tîdîkelt, no sudoeste da Argélia, foi oficialmente ligada à França a 21 de fevereiro de 1901. Este nó de rotas de caravanas, a que o sultão de Marrocos reivindicava direitos nominais — incluindo Advâr, Tîmîmûn, Reggân e Benî Abbâs —, foi assim incorporado na Argélia; este é o início da disputa fronteiriça entre Marrocos e a Argélia francesa.", "c50f9569"]},
"OLAYLAR_EK15:1903-11-11:0":{"b": ["Instalação de um posto francês em Beşşâr (Colomb-Béchar)", "4d44d252"], "d": ["O oásis de Beşşâr, na fronteira com Marrocos, foi tomado pelas forças francesas a 11 de novembro de 1903 e transformado em posto avançado com o nome de Colomb-Béchar. Este passo, dado dois anos depois da anexação da faixa de Tuvât, é um dos últimos elos do avanço da França da Argélia em direção a Marrocos; abre o caminho que conduz ao protetorado sobre Marrocos em 1912.", "bd1a7ae2"]},
"OLAYLAR_EK16:1283-01-01:0":{"b": ["Fundação do Principado de Moscovo — Daniil I", "49549309"], "d": ["Daniil, o filho mais novo de Aleksandr Nevsky, começou a governar Moscovo como principado independente. Nessa época, Moscovo era um centro pequeno e insignificante das terras de Vladimir-Suzdal; a historiografia russa toma esta data como ponto de partida da sua ascensão posterior.", "10cf92d1"]},
"OLAYLAR_EK16:1297-01-01:0":{"b": ["Fundação dos beiliques de Karesi e dos Hamîdoğulları", "3905da93"], "d": ["Segundo o artigo Karesioğulları do TDV, Karesi Bey, na organização de fronteira seljúcida que se desagregara com a morte de seu pai Kalem Bey, proclamou a sua independência e, a partir de 696 (1296-97), fez de Balıkesir o seu centro e, em pouco tempo, tomou a Bizâncio toda a Mísia, incluindo Erdek, Biga, Edremit e Bérgamo. No mesmo ano (1297), Hamîd Bey fundou o Beilique dos Hamîdoğulları, fazendo de Uluborlu a sede do governo; Isparta, Burdur, Eğirdir e Yalvaç foram incluídas, da região de fronteira seljúcida desagregada, nos primeiros limites do beilique. Ambos os beiliques são produto do mesmo colapso no Ocidente da Anatólia — a desagregação da autoridade central seljúcida.", "7d297343"]},
"OLAYLAR_EK16:1301-01-01:0":{"b": ["Daniil, príncipe de Moscovo, incorpora Kolomna e Serpukhov em Moscovo", "6d82dccd"], "d": ["Daniil tomou ao principado de Riazan Kolomna (o príncipe de Riazan, feito prisioneiro, cedeu a fortaleza para ser libertado) e Serpukhov; Moscovo chegou ao rio Oka e foi a primeira expansão territorial do Principado de Moscovo.", "f6b7a96c"]},
"OLAYLAR_EK16:1304-01-01:0":{"b": ["Mozhaysk tomada ao Principado de Smolensk e incorporada em Moscovo", "462055a0"], "d": ["O Principado de Moscovo, tomando a Smolensk Mozhaysk, na bacia superior do rio Moscovo, aproximou da Lituânia a sua fronteira ocidental.", "3002aa5d"]},
"OLAYLAR_EK16:1307-01-01:0":{"b": ["O Principado de Polotsk passa para o Grão-Ducado da Lituânia", "04a26a6f"], "d": ["Polotsk, Vitebsk e arredores permaneceram até 1307 na dinastia principesca russa; a expansão para leste da Lituânia anterior a Gediminas tornou-se evidente com esta passagem (data da ficha do atlas 1307; a passagem efetiva de Vitebsk, por volta de 1320, é discutida).", "52bf8042"]},
"OLAYLAR_EK16:1308-01-01:0":{"b": ["Fundação do Beilique dos Aydınoğulları — tomada de İzmir, Ayasuluk e Tire", "69a021ae"], "d": ["Segundo o artigo Aydınoğulları do TDV, Mübârizüddin Gazi Mehmed Bey, tomando esta região a Sâsâ Bey, bei de fronteira dos Germiyanoğulları, dominou em 1308 o Aydın-ili; conquistou a parte muçulmana de İzmir juntamente com Ayasuluk (Selçuk), Tire e Bodemya. Fez de Ayasuluk uma base naval e repartiu os territórios conquistados entre os seus cinco filhos — nas décadas seguintes, em especial no tempo do seu filho Umur Bey, o beilique tornar-se-á uma potência decisiva na navegação do Egeu.", "9c871e7d"]},
"OLAYLAR_EK16:1308-01-01:1":{"b": ["Fim efetivo do Estado dos Seljúcidas da Anatólia — administração direta ilkhânida", "00f85ecb"], "d": ["Segundo o artigo Mesud II do TDV, Gıyâseddin Mesud II, que morreu em 708 (1308) em Kayseri, depois de uma longa doença, é, segundo a opinião geralmente aceite, o último soberano do Estado dos Seljúcidas da Anatólia — os candidatos entronizados depois da sua morte não obtiveram o reconhecimento nem das autoridades internas nem dos ilkhânidas. A região já era de facto administrada por funcionários ilkhânidas durante todo o reinado de Mesud; com a sua morte, esta administração direta perdeu também o seu invólucro formal em centros como Konya, Niğde e Aksaray.", "80f4e444"]},
"OLAYLAR_EK16:1309-01-01:0":{"b": ["Expansão do Beilique dos Candaroğulları a Kastamonu-Çankırı-Bartın-Safranbolu", "64e39ad0"], "d": ["Segundo o artigo Candaroğulları do TDV, o beilique foi fundado no início do século XIV, na região de Kastamonu-Sinope, por Şemseddin Yaman Candar, a quem o soberano ilkhânida Geyhatu dera Eflani e arredores como iqta; por insuficiência das fontes, a data exata da fundação é desconhecida. O sucessor de Candar, Süleyman Bey, é referido como um soberano que ocupou o lugar do Beilique dos Çobanoğulları — isto é, a região de Kastamonu e Çankırı passou dos Çobanoğulları, e a linha Bartın-Safranbolu-Eflani da administração direta ilkhânida, para os Candaroğulları.", "72e44d66"]},
"OLAYLAR_EK16:1310-08-15:0":{"b": ["Conquista de Rodes e do Dodecaneso pelos cavaleiros de São João (Hospitalários)", "67885b4b"], "d": ["O artigo Rodos do TDV regista que a ilha passou em 1309 para as mãos dos cavaleiros de São João (Hospitalários/İsbitâriyye); a história hospitalária padrão (cf. J. Riley-Smith, The Knights Hospitaller) pormenoriza que o cerco começou no verão de 1306 e que a cidade de Rodes, que resistiu muito tempo com reforços bizantinos, só caiu a 15 de agosto de 1310, às forças do Grão-Mestre Foulques de Villaret. A ilha será, a partir desta data e até à conquista otomana de 1522, o centro dos cavaleiros, e o Dodecaneso à sua volta passou também, no mesmo processo, de Bizâncio para o domínio hospitalário.", "c1422e2c"]},
"OLAYLAR_EK16:1313-01-01:0":{"b": ["Os cavaleiros da Livónia retomam à Lituânia a fortaleza de Dünaburg", "92119516"], "d": ["Os lituanos tinham tomado Jersika por volta de 1281 e trocado-a pela fortaleza de Dünaburg da Ordem. A fortaleza voltou em 1313 a mãos dos cavaleiros da Livónia e manteve-se como sede de comenda da Ordem.", "0cdd86e0"]},
"OLAYLAR_EK16:1315-01-01:0":{"b": ["Tomada de İstanköy (Kos) pelos cavaleiros de São João", "445666f7"], "d": ["Segundo o artigo İstanköy do TDV, os cavaleiros de São João, depois de se estabelecerem em Rodes, tomaram também İstanköy (1315) e construíram novas fortalezas. A ilha passou assim ao domínio dos cavaleiros, que durou até 1523; sob que administração esteve Kos depois da queda da cidade de Rodes em 1310 não é pormenorizado no TDV.", "145d1bad"]},
"OLAYLAR_EK16:1325-01-01:0":{"b": ["A sede metropolitana transferida para Moscovo", "d20099f8"], "d": ["O metropolita Petr, chefe da Igreja Ortodoxa Russa, transferiu o seu centro religioso para Moscovo. Foi o início da ascensão de Moscovo não só como centro político, mas também religioso, e reforçou a legitimidade do principado.", "4e31c42f"]},
"OLAYLAR_EK16:1330-01-01:0":{"b": ["A Ordem da Livónia torna-se suserana da cidade de Riga", "21453047"], "d": ["O arcebispado de Riga e a cidade, que combatiam a Ordem com o apoio dos grão-duques lituanos Vytenis e Gediminas, foram derrotados em 1330; a Ordem da Livónia tornou-se suserana da cidade. Com o tratado de Salaspils de 1452, Riga passou para a suserania conjunta da Ordem e do arcebispo.", "28788282"]},
"OLAYLAR_EK16:1335-01-01:0":{"b": ["Fundação do Beilique de Eretna — a Anatólia Central pós-ilkhânida", "a67bacd9"], "d": ["Segundo o artigo Eretnaoğulları do TDV, Alâeddin Eretna, um funcionário ilkhânida de origem uigur, depois da morte, em 1335, do soberano ilkhânida Ebû Said Bahadır Han, transformou de facto o vice-reinado ilkhânida na Anatólia numa administração independente; aparecendo primeiro como naib do sultão mameluco, retirou em 1340 o nome mameluco da khutba e proclamou a sua plena independência por volta de 1341. O beilique, com centro primeiro em Sivas e depois em Kayseri, estabeleceu até à sua morte (1352) um vasto domínio na Anatólia Central, que abrangia Amasya, Tokat, Çorum, Niğde, Aksaray e Erzincan, e foi extinto em 1381 por Kadı Burhâneddin.", "04978a80"]},
"OLAYLAR_EK16:1335-05-01:0":{"b": ["Os Habsburgos apoderam-se da Carniola e da Caríntia (Ljubljana)", "039918d3"], "d": ["Com a morte sem herdeiros, a 2 de abril de 1335, no Castelo de Tirol, de Henrique VI, duque da Caríntia e conde do Tirol, em conformidade com um acordo secreto feito com Luís da Baviera a 23 de novembro de 1330, os irmãos Habsburgos Alberto II e Otão IV receberam, por investidura imperial, o Ducado da Caríntia e a Carniola a ele ligada (a região em que se inclui também a atual Ljubljana); o Tirol, por seu lado, ficou separado por intermédio da filha de Henrique. Foi um dos primeiros grandes passos da expansão dos Habsburgos na região alpina e a Carniola permaneceria (com interrupções) em mãos dos Habsburgos/da Áustria até 1918.", "4dbed85a"]},
"OLAYLAR_EK16:1340-01-01:0":{"b": ["Fundação do Estado Celayírida — o Azerbaijão pós-ilkhânida", "a13ada90"], "d": ["Segundo o artigo Celâyirliler do TDV, Hasan-ı Büzürg, neto do emir ilkhânida Noyan, aproveitando as lutas pelo trono desencadeadas pela morte do soberano ilkhânida Ebû Said Bahadır Han, fundou em 1340 um Estado independente com centro em Tabriz. Os Celayírida tornaram-se assim a primeira grande dinastia a preencher o vazio pós-ilkhânida no Azerbaijão e arredores; no tempo do seu sucessor Üveys (1356-1374), os seus territórios estender-se-ão até Mossul e Diyarbekir.", "224cbb81"]},
"OLAYLAR_EK16:1341-01-01:0":{"b": ["Fundado o Grão-Ducado de Nizhny Novgorod-Suzdal — o Cã concede yarlyk a Konstantin Vasilyevich", "c69f5198"], "d": ["Özbek, cã da Horda de Ouro (Özbek/Canibek na ficha), deu ao príncipe de Suzdal Konstantin Vasilyevich o principado de Nizhny Novgorod-Gorodets; o principado tornou-se rival de Moscovo e foi incorporado em Moscovo em 1392 por Vasili I.", "4b281b04"]},
"OLAYLAR_EK16:1346-01-01:0":{"b": ["A Dinamarca vende a Estónia do Norte (Reval e Narva) à Ordem da Livónia", "6861ba55"], "d": ["O reino da Dinamarca vendeu à Ordem da Livónia os seus territórios na Estónia do Norte, com Reval e Narva. A região permaneceu em mãos da Ordem até à Guerra da Livónia.", "0723514c"]},
"OLAYLAR_EK16:1348-01-01:0":{"b": ["Tratado de Bolotovo — Novgorod reconhece a independência de Pskov", "08eca44d"], "d": ["Novgorod reconheceu Pskov como 'irmã mais nova'; Pskov viveu, com o seu próprio veche e posadnik, como república urbana independente até ser incorporada em Moscovo em 1510.", "12f9ce2f"]},
"OLAYLAR_EK16:1392-01-01:0":{"b": ["Vasili I incorpora em Moscovo o Principado de Nizhny Novgorod-Suzdal", "5ecf441b"], "d": ["Com o yarlyk recebido do cã Toktamış, Vasili I ligou a Moscovo Nizhny Novgorod, Gorodets e Suzdal; começou a abertura de Moscovo à bacia do Volga e do Oka.", "ac83ac55"]},
"OLAYLAR_EK16:1404-01-01:0":{"b": ["Vytautas toma Smolensk — o Principado de Smolensk incorporado na Lituânia", "1a68300c"], "d": ["Vytautas apoderou-se de Smolensk; a cidade permaneceu no Grão-Ducado da Lituânia até passar para Moscovo em 1514.", "3ed5ce14"]},
"OLAYLAR_EK16:1411-01-01:0":{"b": ["Bagdade passa para os Kara Koyunlu — derrota do celayírida Sultão Ahmed", "a42ebe92"], "d": ["Segundo o artigo Karakoyunlular do TDV, Kara Yûsuf infligiu, a 28 de Rebîülâhir de 813 (30 de agosto de 1410), uma pesada derrota ao celayírida Sultão Ahmed perto de Tabriz; depois da morte do Sultão Ahmed, em 814 (1411), proclamou sultão em Tabriz o filho deste, Pîr Budak, e, no mesmo ano, o seu filho mais velho Şah Mehmed conquistou Bagdade. Assim, Bagdade, que fora durante quase um século a capital dos Celayírida, entrou, juntamente com a linha Baçorá-Mossul-Quircuque à sua volta, no domínio dos Kara Koyunlu.", "30b86113"]},
"OLAYLAR_EK16:1422-01-01:0":{"b": ["Erzincan e Kemah passam para os Ak Koyunlu — Karayülük Osman Bey", "122460d4"], "d": ["Depois da morte de Kara Yûsuf, por vontade da população de Erzincan, Yâr Ali, neto de Mutahharten, fora feito governador da cidade. No seu tempo, o bei dos Ak Koyunlu Karayülük Osman tomou Erzincan e juntou-a aos territórios dos Ak Koyunlu. A partir desta data, Erzincan tornou-se um lugar que mudou de mãos ora entre os Ak Koyunlu e os Kara Koyunlu, ora entre os príncipes dos Ak Koyunlu.", "83183da6"]},
"OLAYLAR_EK16:1438-01-01:0":{"b": ["Fundação do Canato de Cazã — Uluğ Muhammed Han separa-se da Horda de Ouro", "335a7408"], "d": ["Segundo o artigo Kazan Hanlığı do TDV, Uluğ Muhammed Han, que perdera o trono em Saray, capital da Horda de Ouro, retirou-se primeiro para Belev com a sua família e cerca de 3000 soldados, lutou em 1437-1438 contra o knez russo Vasili II e depois estabeleceu-se na cidade de Cazã; com o apoio da população local, lançou aí as bases de um novo canato. O TDV observa que o processo de fundação se concluiu entre 1437 e 1445 e que o canato adquiriu estatuto de plena independência a partir de 1445 — o mapa toma como base o início deste processo, o ano de 1438, em que Uluğ Muhammed se estabeleceu em Cazã.", "d65b36b3"]},
"OLAYLAR_EK16:1441-01-01:0":{"b": ["Fundação do Canato da Crimeia — Hacı Giray torna-se independente da Horda de Ouro", "5728223e"], "d": ["Segundo o artigo Kırım do TDV, o Canato da Crimeia surgiu, na segunda metade do século XIV, como produto da fragmentação da Horda de Ouro pelas lutas pelo trono; a moeda mais antiga cunhada por Hacı Giray, o verdadeiro fundador do canato, tem a data de 845 (1441-42) e é considerada a data oficial de fundação do canato. No mesmo ano, Hacı Giray consolidou a sua posição na Crimeia estabelecendo amizade com Moscovo, e as famílias de beis locais, a começar pela tribo dos Şirin, juntaram-se ao seu lado.", "dbd052d0"]},
"OLAYLAR_EK16:1450-01-01:0":{"b": ["Cihan Şah toma Erzincan — domínio dos Kara Koyunlu", "0c928cc4"], "d": ["O soberano dos Kara Koyunlu Cihan Şah enviou em 854 (1450) um exército a Erzincan e tomou a cidade aos Ak Koyunlu. Esta perda levou à rutura entre o bei dos Ak Koyunlu Cihangir Mirza e o seu irmão Hasan Bey (Uzun Hasan).", "203c5c2e"]},
"OLAYLAR_EK16:1452-01-01:0":{"b": ["Cihan Şah dos Kara Koyunlu apodera-se do Irão timúrida (Rey, Isfahan, Fars, Kerman)", "c6fbb3f5"], "d": ["Segundo o artigo Karakoyunlular do TDV, o soberano dos Kara Koyunlu Cihan Şah, aproveitando as lutas pelo trono entre os príncipes timúridas, colocou sob a sua administração, nos anos 856-857 (1452-1453), as províncias de Rey, Isfahan, Fars e Kerman; este é o ponto culminante do processo de expansão iniciado depois da morte de Şâhruh Mirza em 1447 e aberto com a anexação de Sultâniye-Kazvin. Os territórios dos Timúridas no centro-sul do Irão passaram assim para os Kara Koyunlu; o domínio de Cihan Şah atingirá em 1466 uma extensão que abrange o Azerbaijão, Arrân, o Irâk-ı Acem, o Irâk-ı Arab, Fars, Kerman e a Anatólia Oriental.", "3f6a6c37"]},
"OLAYLAR_EK16:1452-10-23:0":{"b": ["Retoma de Bordéus pela Inglaterra — última campanha de John Talbot na Gasconha", "01b2b7be"], "d": ["Bordéus, perdida para os franceses em 1451, rendeu-se na noite de 22-23 de outubro de 1452 ao exército inglês liderado pelo velho comandante John Talbot, depois de a sua população se ter revoltado contra a guarnição francesa e aberto as portas; esta foi a última e efémera vitória da Inglaterra na Gasconha na Guerra dos Cem Anos. Bordéus voltaria definitivamente à França um ano depois, após a Batalha de Castillon.", "f6945d27"]},
"OLAYLAR_EK16:1453-10-19:0":{"b": ["Regresso definitivo de Bordéus à França — fim efetivo da Guerra dos Cem Anos", "b0a86f6c"], "d": ["Com a morte de John Talbot e a aniquilação do seu exército na Batalha de Castillon, a 17 de julho de 1453, a resistência inglesa na Gasconha ruiu; Bordéus, sitiada, rendeu-se às forças francesas a 19 de outubro de 1453. Esta rendição é considerada o momento em que a Guerra dos Cem Anos, que durava havia 116 anos, terminou de facto (nunca foi assinado um tratado de paz oficial) e reduziu o domínio da Inglaterra no continente europeu a Calais.", "1c632d46"]},
"OLAYLAR_EK16:1457-01-01:0":{"b": ["Uzun Hasan retoma Erzincan — de novo Ak Koyunlu", "550d010a"], "d": ["Uzun Hasan, derrotando os Kara Koyunlu, voltou a colocar Erzincan sob o domínio dos Ak Koyunlu. A cidade permaneceu dentro das fronteiras dos Ak Koyunlu também depois da Batalha de Otlukbeli de 1473.", "d778fa85"]},
"OLAYLAR_EK16:1466-10-19:0":{"b": ["Segundo Tratado de Thorn — Danzig (Gdańsk) e a Prússia Ocidental ligadas à Polónia", "e2152dae"], "d": ["O Segundo Tratado de Thorn (Toruń), que pôs fim à Guerra dos Treze Anos, iniciada com a revolta da Confederação Prussiana, em 1454, contra o governo dos Cavaleiros Teutónicos (Teutonic Order), foi assinado a 19 de outubro de 1466; os Cavaleiros cederam ao Reino da Polónia a Pomerânia Oriental, que inclui Danzig (Gdansk), a foz do Vístula, que inclui Elbing (Elbląg), e a região de Kulm — estes territórios receberam o nome de 'Prússia Real'. A Prússia Oriental permaneceria com os Cavaleiros até 1525.", "831685a9"]},
"OLAYLAR_EK16:1474-01-01:0":{"b": ["Ivan III compra a metade restante do Principado de Rostov", "5203244f"], "d": ["A metade que estava em mãos dos príncipes de Rostov foi cedida a Moscovo; com a outra metade, que passara para Moscovo em 1332, a terra de Rostov ficou inteiramente ligada a Moscovo.", "ab0eeae6"]},
"OLAYLAR_EK16:1485-09-12:0":{"b": ["O Grão-Ducado de Tver incorporado em Moscovo — Ivan III toma a cidade", "fa3f924e"], "d": ["Com o cerco do exército de Moscovo, o último grão-duque de Tver, Mikhail Borisovich, fugiu para a Lituânia e Tver rendeu-se a Ivan III; o mais forte rival de Moscovo desapareceu assim.", "b9942526"]},
"OLAYLAR_EK16:1489-02-26:0":{"b": ["A rainha Catarina Cornaro cede Chipre a Veneza — fim do Estado cruzado", "e24d3f3a"], "d": ["Catarina Cornaro, veneziana, que governou Chipre como rainha regente depois da morte do marido, o rei Jacques II, em 1473, por não ter herdeiros e sob pressão do governo veneziano, abdicou a 26 de fevereiro de 1489 e cedeu os direitos de soberania na ilha ao doge e à República de Veneza; em troca, conservou o título de rainha e recebeu o condado de Asolo na Terraferma. Com esta cedência terminaram o domínio da dinastia Lusignan, que durava desde 1192, e o último Estado cruzado, e a ilha permaneceu sob administração veneziana até à conquista otomana de 1570-71.", "7f769951"]},
"OLAYLAR_EK16:1492-01-02:0":{"b": ["A queda de Granada — fim do último Estado muçulmano na Península Ibérica", "46e5201b"], "d": ["Ebû Abdullah (Boabdil), último soberano do Emirado Nasrida de Granada, enfraquecido por um cerco gradual de dez anos e por divisões internas, entregou a 2 de janeiro de 1492 as chaves da cidade aos Reis Católicos Fernando e Isabel, em conformidade com as generosas condições de rendição (Capitulações de Granada) assinadas em novembro de 1491; com a saída de Boabdil da Alhambra, terminou o último Estado muçulmano na Península Ibérica e a Reconquista concluiu-se. No mesmo ano seguir-se-iam a expulsão dos judeus (março) e a viagem de Cristóvão Colombo (agosto).", "5dc28ef8"]},
"OLAYLAR_EK16:1500-07-14:0":{"b": ["Batalha de Vedrosha — Moscovo derrota o exército lituano; as terras de Bryansk e Seversk ficam com Moscovo", "d3f61400"], "d": ["Na guerra Moscovo-Lituânia de 1500-1503, o exército de Moscovo, comandado por Daniil Shchenya, desbaratou no rio Vedrosha, perto de Dorogobuzh, o exército do hetman Konstanty Ostrogski e fez prisioneiro o hetman. As cidades de Bryansk e Seversk, tomadas na primavera do mesmo ano, ficaram em mãos de Moscovo; no final da guerra, cerca de um terço do território lituano passara para Moscovo.", "e5879803"]},
"OLAYLAR_EK16:1503-04-02:0":{"b": ["Trégua entre Moscovo e a Lituânia — a região de Chernigov-Seversk passa para Moscovo", "8e4c56f9"], "d": ["A guerra Moscovo-Lituânia de 1500-1503 terminou com uma trégua de seis anos, mediada por Ladislau II, rei da Hungria-Boémia; o Grão-Ducado da Lituânia teve de ceder ao Grão-Ducado de Moscovo uma vasta extensão que constituía cerca de um terço do Grão-Ducado, incluindo a região de Chernigov-Seversk (arredores de Chernigov, Novgorod-Seversk, Starodub e Bryansk) e alguns territórios nos arredores de Smolensk e Polotsk. Foi um dos maiores ganhos isolados de Moscovo no processo de 'reunião' das terras russas.", "4cb77b9b"]},
"OLAYLAR_EK16:1507-05-24:0":{"b": ["Şeybânî Han toma Herat e o Horasão aos Timúridas", "a81d8575"], "d": ["Segundo o artigo Şeybânî Han do TDV, o soberano uzbeque Şeybânî Han, depois de tomar, entre 1503 e 1505, Andijan, Fergana, Hisâr, Kunduz e Balkh, conquistou também, em 913 (1507), a capital timúrida Herat; o artigo Horasão da Encyclopaedia Iranica dá a data exata desta conquista — a cidade caiu a 8 de Muharrem de 913 (20 de maio de 1507) e, uma semana depois, a 15 de Muharrem (27 de maio), a conquista tornou-se oficial com a leitura da khutba em nome de Şeybânî Han. Todo o Horasão, incluindo Meshed, passou dos Timúridas para os Xaibânidas no mesmo ano; isto significava que a dinastia timúrida perdia, depois da Transoxiana, também a sua última grande fortaleza no Irão.", "cb60730c"]},
"OLAYLAR_EK16:1509-05-17:0":{"b": ["A queda de Orão para a Espanha — expedição do cardeal Cisneros ao Norte de África", "86ed8ac1"], "d": ["Vehrân (Orão), que controlava a rota marítima do Mediterrâneo Ocidental e era o porto de Tilimsân, crescera em 1492 com o refúgio dos muçulmanos e judeus andaluzes fugidos de Granada. O Reino de Castela, que no início do século XVI tomava uma a uma as cidades portuárias da costa do Magrebe, ocupou Vehrân a 17 de maio de 1509; a maior parte da população foi massacrada, os restantes foram feitos prisioneiros e na cidade não restou população muçulmana nem judia. Os espanhóis ampliaram as muralhas e as fortalezas; Vehrân permaneceu em mãos da Espanha até 1708.", "be7b3b1b"]},
"OLAYLAR_EK16:1514-08-01:0":{"b": ["Smolensk rende-se a Moscovo — Vasili III entra na cidade", "46c61446"], "d": ["No terceiro cerco da guerra Moscovo-Lituânia de 1512-1522, a guarnição lituana rendeu-se a 31 de julho; o exército de Moscovo entrou solenemente na cidade a 1 de agosto e a população prestou juramento de fidelidade a Vasili III. Smolensk é o maior ganho de Vasili no Ocidente; a derrota sofrida em Orsha poucas semanas depois não fez com que a cidade fosse recuperada.", "803c9255"]},
"OLAYLAR_EK16:1516-01-23:0":{"b": ["Os Países Baixos ligados à coroa de Espanha — morte de Fernando, subida ao trono de Carlos V", "fbe0dbd2"], "d": ["Com a morte do rei Fernando II de Aragão, a 23 de janeiro de 1516, o seu neto Carlos V, que já governava os Países Baixos (a atual Bélgica-Países Baixos-Luxemburgo e parte do norte de França) desde 1506 como duque da Borgonha, tornou-se também herdeiro dos tronos de Castela e Aragão e foi proclamado rei de Espanha em Bruxelas a 14 de março de 1516. Assim, estes territórios passaram a ser considerados, por via de união pessoal, ligados diretamente à coroa de Espanha e não ao ramo alemão/austríaco da dinastia dos Habsburgos — em 1519, com a eleição de Carlos V como Imperador do Sacro Império Romano-Germânico, estas duas identidades (rei de Espanha e imperador romano-germânico) unir-se-ão na mesma pessoa, e a ligação da região à Espanha durará até 1556, quando Carlos V abdicou e deixou a herança ao seu filho Filipe II.", "61f77359"]},
"OLAYLAR_EK16:1527-01-01:0":{"b": ["O Sultanato de Demak destrói Majapahit e domina a costa de Java", "7da602b5"], "d": ["Segundo o artigo Demak do TDV, o Sultanato de Demak, primeiro Estado muçulmano independente de Java, foi fundado no último quartel do século XV por Raden Patah; segundo as fontes javanesas, o Reino hindu-budista de Majapahit, em declínio, desapareceu com os ataques de Demak. Em 1527, Demak conquistou Tuban, que as fontes chinesas mencionam desde o século XI como um porto importante para os soberanos de Majapahit — este é o ano em que os últimos vestígios de Majapahit ficaram também ligados a Demak, e é o ponto de viragem do processo de islamização de grande parte de Java.", "538d28fb"]},
"OLAYLAR_EK16:1537-01-01:0":{"b": ["A Noruega reduzida a província ligada à coroa dinamarquesa", "8e2f274e"], "d": ["O rei Cristiano III da Dinamarca declarou, na carta de coroação de 1536 (håndfæstning), que a Noruega já não seria considerada um reino separado, mas seria governada como província da Dinamarca, e que o Conselho de Estado da Noruega (riksråd) era abolido; esta decisão tornou-se efetiva em 1537 com a aplicação à Noruega do Regulamento da Igreja Dinamarquesa, e a resistência do bispo escocês-norueguês Olav Engelbriktsson foi quebrada. Embora a Noruega, na prática, tenha conservado ainda durante algum tempo as suas próprias leis e instituições, o seu estatuto político era já não o de um reino independente, mas o de uma província ligada à coroa dinamarquesa — situação que durará até 1814.", "a8c9dee7"]},
"OLAYLAR_EK16:1558-05-01:0":{"b": ["Narva tomada pelos russos — a primeira grande cidade da Guerra da Livónia", "c21130d7"], "d": ["Os exércitos de Ivan IV tomaram Narva; a Rússia chegou à costa do Báltico. Narva permaneceu em mãos russas até passar para a Suécia em 1581.", "8057148b"]},
"OLAYLAR_EK16:1558-07-01:0":{"b": ["Dorpat (Tartu) tomada pelos russos", "f941a504"], "d": ["Os exércitos russos tomaram Dorpat (Tartu) e as fortalezas vizinhas na campanha de verão de 1558; a cidade permaneceu sob administração russa até à Trégua de Jam Zapolski de 1582.", "35503ef9"]},
"OLAYLAR_EK16:1561-06-01:0":{"b": ["Reval (Tallinn) entra na proteção da Suécia — a Estónia do Norte passa para a Suécia", "3c183267"], "d": ["Quando a Confederação da Livónia se dissolvia, o conselho municipal de Reval prestou em 1561 fidelidade ao rei Érico XIV da Suécia; a Estónia do Norte permaneceu na Suécia até à Grande Guerra do Norte (1721).", "cb752659"]},
"OLAYLAR_EK16:1561-11-28:0":{"b": ["Tratado de Vilnius — a Confederação da Livónia dissolve-se, a Curlândia e a Livónia ligadas à Polónia-Lituânia (exceto a cidade de Riga)", "d1ceaad5"], "d": ["Gotthard Kettler, último grão-mestre da Confederação da Livónia, que se dissolvera sob a pressão russa durante a Guerra da Livónia, colocou-se, pelo tratado assinado em Vilnius a 28 de novembro de 1561 (Pacta Subiectionis), sob a proteção de Sigismundo II Augusto, grão-duque da Lituânia e rei da Polónia; a maior parte da Livónia, com exceção da cidade de Riga, foi ligada à Polónia-Lituânia, e Kettler tornou-se o primeiro duque do Ducado da Curlândia. Foi o último ato da Ordem dos Cavaleiros da Livónia na passagem da Idade Média para a Idade Moderna.", "bcd4efe9"]},
"OLAYLAR_EK16:1581-01-01:0":{"b": ["A Suécia toma Narva à Rússia", "5a7f7a6a"], "d": ["Nos últimos anos da Guerra da Livónia, as forças suecas tomaram Narva, que estava em mãos russas desde 1558; a cidade permaneceu na Suécia até 1704.", "5fee4227"]},
"OLAYLAR_EK16:1581-01-01:1":{"b": ["A cidade livre de Riga ligada à Polónia-Lituânia", "77dba329"], "d": ["Riga, que se manteve como cidade livre durante a Guerra da Livónia, foi ligada em 1581 à União Polaco-Lituana; a cidade permaneceu na União até passar para a Suécia em 1621.", "ecdf652d"]},
"OLAYLAR_EK16:1581-07-26:0":{"b": ["Ato de Abjuração (Plakkaat van Verlatinghe) — os Países Baixos declaram a independência da Espanha", "a632aaee"], "d": ["Enquanto prosseguia a Guerra dos Oitenta Anos, a Assembleia Geral (Staten-Generaal) das províncias holandesas aderentes à União de Utreque rejeitou, pelo Ato de Abjuração aprovado a 26 de julho de 1581, a lealdade ao rei Filipe II de Espanha, declarando-o 'tirano'; este documento é considerado a declaração de fundação das Províncias Unidas (República Holandesa), de facto independentes. O reconhecimento definitivo pela Espanha esperaria pela Vestefália de 1648, mas a rutura efetiva é este dia.", "cd96ed5f"]},
"OLAYLAR_EK16:1611-06-13:0":{"b": ["A queda de Smolensk para a Polónia-Lituânia — fim de um cerco de 20 meses", "4e9678e3"], "d": ["No Tempo das Perturbações (Smuta), o exército do rei Sigismundo III da Polónia, que sitiava Smolensk desde setembro de 1609, abriu uma brecha nas muralhas de Smolensk a 13 de junho de 1611, fazendo explodir uma mina, e tomou a cidade; a resistência de 20 meses terminou. Smolensk permaneceu na Polónia-Lituânia até 1654 e esta queda preparou o terreno para a Trégua de Deulino (1618), assinada pouco depois.", "bc44374a"]},
"OLAYLAR_EK16:1611-07-16:0":{"b": ["Novgorod tomada pelo exército sueco — no Tempo das Perturbações, o noroeste da Rússia passa para controlo sueco", "a8ab28bb"], "d": ["O exército sueco de Jacob De la Gardie tomou Novgorod; a cidade tornou-se, até 1617, a capital do 'Estado de Novgorod', sob proteção sueca, e Carlos Filipe foi apresentado como candidato a czar.", "281592c2"]},
"OLAYLAR_EK16:1617-02-27:0":{"b": ["Tratado de Stolbova — a Rússia perde para a Suécia a costa do Báltico (Íngria)", "175dc175"], "d": ["O Tratado de Stolbova, que pôs fim à Guerra da Íngria, foi assinado a 27 de fevereiro de 1617 na aldeia de Stolbova, a sul do lago Ladoga; a Rússia recuperou Novgorod e outros territórios do norte, enquanto a Suécia manteve a Carélia e a Íngria (entre a Estónia e a Finlândia, incluindo as fortalezas de Ivangorod, Yam, Koporye e Oreshek), e o acesso direto da Rússia ao Báltico foi cortado. Este corte duraria até 1703, quando Pedro, o Grande, fundou São Petersburgo na mesma região.", "7e70e3e6"]},
"OLAYLAR_EK16:1617-02-27:1":{"b": ["Tratado de Stolbovo — a Rússia cede a Íngria à Suécia, Novgorod devolvida", "e0bcbc7a"], "d": ["A Rússia cedeu à Suécia as margens do Neva e parte da Carélia (Yam, Koporye, Ivangorod, Oreshek) e ficou separada da costa do Báltico; a Suécia devolveu Novgorod. Esta situação durou até à Grande Guerra do Norte de Pedro I.", "bf517525"]},
"OLAYLAR_EK16:1618-12-11:0":{"b": ["Trégua de Deulino — Smolensk, Chernigov e Novgorod-Seversk cedidas à Polónia", "6880d2c1"], "d": ["A Trégua de Deulino, que pôs fim à Guerra Polaco-Russa de 1609-1618, foi assinada a 11 de dezembro de 1618 e assegurou um armistício de 14,5 anos; a Rússia teve de ceder à União Polaco-Lituana Smolensk (exceto Vyazma) e 29 cidades nas regiões de Chernigov e Novgorod-Seversk — esta foi a perda territorial mais pesada do Tempo das Perturbações (Smuta). A região permaneceria na Polónia até à Trégua de Andrusovo, de 1667.", "5c52de5a"]},
"OLAYLAR_EK16:1625-01-01:0":{"b": ["A Suécia toma Tartu (Dorpat) à Polónia — segunda fase da Campanha da Livónia", "46b7c86a"], "d": ["Gustavo II Adolfo conquistou na campanha de 1625 a Estónia do Sul e a Livónia do Norte; Tartu tornou-se uma cidade sueca, onde em 1632 seria fundada a Academia Gustaviana.", "b58d9bd1"]},
"OLAYLAR_EK16:1654-01-18:0":{"b": ["Rada de Pereyaslav — os cossacos zaporogos prestam juramento de fidelidade ao czar russo", "bcd8f8ef"], "d": ["Bohdan Khmelnytsky, hetman dos cossacos zaporogos, que se revoltava contra a Polónia-Lituânia desde 1648, prestou juramento de fidelidade ao czar Aleksei I Mikhailovich na Rada de Pereyaslav de 18 de janeiro de 1654 (8 de janeiro no calendário juliano), a que assistiu a delegação vinda de Moscovo, presidida por Vasili Buturlin; este é considerado o início da entrada do Hetmanato Cossaco da Ucrânia sob a proteção russa e deslocou da Polónia para a Rússia o controlo efetivo da região de Chernigov-Seversk — a fronteira oficial seria, porém, traçada pela Trégua de Andrusovo de 1667.", "b15d1501"]},
"OLAYLAR_EK16:1654-10-03:0":{"b": ["Retoma de Smolensk pela Rússia", "bf0eca92"], "d": ["Durante a Guerra Polaco-Russa iniciada em 1654, o exército russo, que sitiava Smolensk desde julho, retomou-a a 3 de outubro de 1654 com a rendição da guarnição polaca; a cidade, perdida para a Polónia em 1611, voltou à Rússia 43 anos depois. Foi um dos passos mais importantes do processo de inversão das perdas do Tempo das Perturbações pela Rússia e tornou-se definitivo com a Trégua de Andrusovo, de 1667.", "57ca40e6"]},
"OLAYLAR_EK16:1667-02-09:0":{"b": ["Trégua de Andrusovo — Kiev e a Ucrânia da Margem Esquerda passam para a Rússia", "799be067"], "d": ["A Trégua de Andrusovo, que pôs fim à Guerra Polaco-Russa de 1654-1667, assegurou um armistício de 13,5 anos; a Rússia ganhou Smolensk, a região de Chernigov-Seversk, a Ucrânia da margem esquerda do Dniepre e — a princípio por dois anos, de facto de modo permanente — a cidade de Kiev. Este tratado lançou a base jurídica da divisão do território ucraniano ao longo do Dniepre entre a Polónia e a Rússia (e da permanência de Kiev na Rússia).", "94445e3a"]},
"OLAYLAR_EK16:1702-10-22:0":{"b": ["A Rússia toma Nöteborg (Oreshek) à Suécia — a primeira fortaleza do Neva na Grande Guerra do Norte", "28d180eb"], "d": ["Os exércitos de Pedro I sitiaram e tomaram Nöteborg (em russo Oreshek), à saída do Ladoga, e deram-lhe o nome de Shlisselburg ('Fortaleza-Chave'); isto abriu o caminho para o Neva e, em 1703, para a fundação de São Petersburgo.", "3017c2be"]},
"OLAYLAR_EK16:1703-05-27:0":{"b": ["Fundação de São Petersburgo — a janela da Rússia aberta para o Ocidente", "ba196be0"], "d": ["Na Ilha das Lebres, no delta do Neva, recentemente retomado à Suécia durante a Grande Guerra do Norte, Pedro, o Grande, lançou a 16/27 de maio de 1703 os alicerces da Fortaleza de Pedro e Paulo; este dia é considerado a data de fundação da cidade de São Petersburgo. Pedro concebeu o delta pantanoso como uma 'janela' aberta para o Ocidente e a cidade tornou-se em 1712 a nova capital da Rússia — a região seria oficialmente ligada à Rússia pelo Tratado de Nystad de 1721.", "24c24aaf"]},
"OLAYLAR_EK16:1708-09-29:0":{"b": ["Tomada de Minorca pelas forças anglo-holandesas", "3ca66a83"], "d": ["Durante a Guerra da Sucessão Espanhola, as forças anglo-holandesas, que agiam como aliadas do arquiduque Carlos VI da Áustria, desembarcaram na ilha a 14 de setembro de 1708, sob o comando do general James Stanhope, e a 28-29 de setembro derrubaram a defesa espanhola e tomaram o controlo de Minorca (a rendição oficial da fortaleza principal, Fort St. Philip, chegou a 24 de novembro). Mahón, o porto estratégico de Minorca, seria nos cem anos seguintes o foco da luta anglo-franco-espanhola.", "9188937e"]},
"OLAYLAR_EK16:1714-03-07:0":{"b": ["Tratado de Rastatt — termina a Guerra da Sucessão Espanhola, os Países Baixos Espanhóis e Milão passam para a Áustria", "3c0e086f"], "d": ["O Tratado de Rastatt, que pôs fim à Guerra da Sucessão Espanhola entre a França e a Áustria, foi assinado a 7 de março de 1714 (Utreque, em 1713, regulara as relações entre a Inglaterra e a França); pelo tratado, os Habsburgos da Áustria receberam os Países Baixos Espanhóis (a atual Bélgica) e, em Itália, Nápoles, Milão e a Sardenha. Foi a maior expansão territorial da história da Áustria e acrescentou ao peso da dinastia dos Habsburgos na Europa Central uma nova frente na Europa Ocidental e Meridional.", "b27fb416"]},
"OLAYLAR_EK16:1721-09-10:0":{"b": ["Tratado de Nystad — termina a Grande Guerra do Norte, as costas do Báltico passam para a Rússia", "068ffd06"], "d": ["O Tratado de Nystad, que pôs fim à Grande Guerra do Norte, de 21 anos, foi assinado na Finlândia a 30 de agosto de 1721; a Suécia cedeu à Rússia a Estónia, a Livónia (incluindo Riga), a Íngria e uma parte da Finlândia sudeste (Carélia), recuperando em contrapartida o resto da Finlândia e sendo-lhe paga uma indemnização. O tratado é considerado o fim do estatuto de grande potência da Suécia e o registo oficial da ascensão da Rússia como império europeu — Pedro I tomou depois desta vitória o título de 'Imperador'.", "ff69c190"]},
"OLAYLAR_EK16:1772-08-05:0":{"b": ["Primeira Partilha da Polónia — perda de territórios para a Rússia e a Áustria", "2c56a0d8"], "d": ["Pelo tratado assinado a 5 de agosto de 1772 entre a Rússia, a Prússia e a Áustria, foi repartida cerca de um terço do território da República das Duas Nações Polaco-Lituana: a Rússia tomou parte da atual Bielorrússia e da Letónia (incluindo Dünaburg, Polotsk e Vitebsk), a Áustria anexou a Galícia (incluindo Lvov e a Podólia ocidental e Yazlovets), e a Prússia ficou com a região costeira da Prússia Real. A Dieta polaca só ratificou o tratado, sob pressão, a 30 de setembro de 1773. Foi a primeira das três partilhas que durarão até 1795.", "6f2b4118"]},
"OLAYLAR_EK16:1793-01-23:0":{"b": ["Segunda Partilha da Polónia — perda de territórios para a Rússia e a Prússia", "31750484"], "d": ["Como as reformas constitucionais de 1791 inquietaram a Rússia e a Prússia, os dois Estados repartiram de novo a Polónia pelo tratado assinado em São Petersburgo a 23 de janeiro de 1793: a Rússia tomou a maior parte da Lituânia-Bielorrússia e a Ucrânia ocidental (incluindo Kamianets, Bar e Minsk), e a Prússia anexou a Grande Polónia, que inclui Gdańsk e Poznań — num total de 307.000 km². A Dieta polaca, sob pressão, foi obrigada a ratificar o tratado nesse mesmo ano; foi uma partilha de curta duração, que adiou por dois anos a anexação total da Polónia.", "6ff0e18a"]},
"OLAYLAR_EK16:1795-03-28:0":{"b": ["O Ducado da Curlândia e Semigália ligado à Rússia — o último duque, Peter von Biron, renuncia", "8d0e410f"], "d": ["No processo da Terceira Partilha da Polónia, a nobreza da Curlândia prestou fidelidade a Catarina e o duque Peter von Biron abdicou; a Curlândia tornou-se uma gubernia da Rússia (nas fontes aparece também 24 de outubro de 1795).", "4682774b"]},
"OLAYLAR_EK16:1795-10-24:0":{"b": ["Terceira Partilha da Polónia — desaparecimento total do Estado", "e3c02d6b"], "d": ["A Rússia, a Prússia e a Áustria repartiram totalmente os territórios restantes da República das Duas Nações Polaco-Lituana pela convenção tripartida assinada em São Petersburgo a 24 de outubro de 1795: a Rússia tomou a Lituânia (incluindo Vilnius e Kaunas) e o resto da Bielorrússia, a Prússia anexou a Polónia central, incluindo Varsóvia, e a Áustria a região sul, incluindo Cracóvia. Os três Estados garantiram ainda militarmente os novos territórios uns dos outros e tomaram precauções contra a possibilidade de uma reconstituição da Polónia. Este é o desaparecimento total do Estado polaco-lituano como país independente; não será reconstituído até ao século XX.", "a66df675"]},
"OLAYLAR_EK16:1797-05-12:0":{"b": ["Fim da República de Veneza — o Grande Conselho dissolve-se", "5efed589"], "d": ["Quando o exército da campanha de Itália de Napoleão ocupou o território continental de Veneza e dirigiu um ultimato à república, o Grande Conselho (Maggior Consiglio) aprovou, a 12 de maio de 1797, por 512 votos contra 20, a sua própria dissolução; o último doge, Ludovico Manin, abandonou o cargo e terminou o governo aristocrático da República de Veneza, que se mantinha ininterruptamente havia mais de 1.100 anos. Os seus territórios foram entregues primeiro a uma administração democrática provisória e depois, em outubro de 1797, oficialmente à Áustria pelo Tratado de Campo Formio.", "8852717b"]},
"OLAYLAR_EK16:1797-06-14:0":{"b": ["Fim da República de Génova — Napoleão cria a República da Ligúria", "3d3e59ee"], "d": ["No lugar da República de Génova, que no início de junho de 1797 fora entregue a uma administração provisória por pressão de Napoleão na campanha de Itália, foi proclamada, a 14 de junho de 1797, a 'República da Ligúria', com uma constituição de modelo francês; o centenário Ducado de Génova transformou-se de facto num dos Estados satélites da França. A república seria anexada diretamente à França em 1805 e cedida ao Reino da Sardenha-Piemonte pelo Congresso de Viena de 1815.", "38af1e4b"]},
"OLAYLAR_EK16:1797-10-17:0":{"b": ["Tratado de Campo Formio — Veneza repartida entre a Áustria e a França", "9f29678c"], "d": ["O Tratado de Campo Formio, assinado a 17 de outubro de 1797 entre Napoleão Bonaparte e o representante austríaco conde Cobenzl, aboliu oficialmente a milenar República de Veneza e repartiu os seus territórios: a leste do rio Adige, a Ístria e a costa da Dalmácia (incluindo Split, Zadar, Šibenik e Kotor) foram cedidas à Áustria, enquanto o Dodecaneso e as Ilhas Jónicas (Corfu, Cefalónia, Zante, Lefkada, Preveza e as bases de Veneza na costa albanesa-moreota, incluindo Parga) passaram para a França. A Áustria cedeu ainda à França os seus territórios nos Países Baixos (a atual Bélgica).", "c490738c"]},
"OLAYLAR_EK16:1800-09-05:0":{"b": ["Rendição de Malta à Inglaterra — fim de dois anos de cerco francês", "fedc2867"], "d": ["Malta, que Napoleão tomara em 1798 a caminho da campanha do Egito, ficou pouco depois sob bloqueio naval da armada inglesa, com a revolta da população da ilha; no termo de um cerco de dois anos e da fome, o comandante francês, general Vaubois, rendeu-se a 5 de setembro de 1800 ao general inglês Pigot. Malta passou assim da República Francesa para a proteção inglesa e seria oficialmente ligada à coroa inglesa pelo Tratado de Paris de 1814 — tornou-se a mais importante base naval inglesa no Mediterrâneo.", "6f406ae3"]},
"OLAYLAR_EK16:1802-03-25:0":{"b": ["Tratado de Amiens — Minorca restituída à Espanha", "f341e4b8"], "d": ["O Tratado de Amiens (25 de março de 1802), assinado entre a França, a Espanha, a Holanda e a Inglaterra, pôs fim provisório à Guerra da Segunda Coligação; a Inglaterra restituiu quase todos os territórios que tomara durante a guerra (exceto o Ceilão e Trindade) — um deles era Minorca, tomada à Espanha em 1798. A paz durou apenas um ano, a guerra voltou a rebentar em maio de 1803, mas Minorca, depois deste tratado, nunca mais passou para mãos inglesas.", "7986aead"]},
"OLAYLAR_EK16:1809-09-17:0":{"b": ["Tratado de Fredrikshamn (Hamina) — a Suécia cede a Finlândia à Rússia", "c0d407bc"], "d": ["O Tratado de Fredrikshamn (a atual Hamina), que pôs fim à Guerra Russo-Sueca de 1808-1809, foi assinado a 17 de setembro de 1809; a Suécia cedeu à Rússia toda a Finlândia, incluindo as Ilhas Åland. A Finlândia obteve o estatuto de Grão-Ducado com ampla autonomia ligado ao Império Russo e conservou a fé luterana e o direito sueco. Isto significava o fim efetivo do estatuto de grande potência da Suécia no Báltico.", "4362e6c6"]},
"OLAYLAR_EK16:1810-02-20:0":{"b": ["Anexação do Reino de Imerécia — o rei Salomão II deposto", "5ad36bff"], "d": ["Quando Salomão II, último rei do Reino georgiano ocidental de Imerécia, que fora obrigado em 1804 a aceitar a vassalagem russa pela Convenção de Elaznauri, continuou a resistir à crescente pressão russa, as tropas russas tomaram a capital Kutaisi a 20 de fevereiro de 1810, depuseram Salomão e forçaram a nobreza local a prestar juramento de fidelidade ao czar Alexandre I; o Reino de Imerécia terminou assim de facto e foi ligado à administração direta russa. Salomão fugiu para território otomano e morreu no exílio (1815).", "fdccc40f"]},
"OLAYLAR_EK16:1814-01-14:0":{"b": ["Tratado de Kiel — a Dinamarca cede a Noruega à Suécia", "59ab1601"], "d": ["A Suécia, que atacou a Dinamarca pelo sul depois da derrota de Napoleão em Leipzig, recebeu a Noruega (com exceção da Islândia, das Ilhas Faroé e da Gronelândia) pelo Tratado de Kiel, assinado a 14 de janeiro de 1814 — a união dano-norueguesa, que durava desde 1380, terminou assim oficialmente. Em contrapartida, a Suécia cedeu à Dinamarca os seus territórios na Pomerânia; a Dinamarca cedeu ainda Heligoland à Inglaterra. A Noruega resistiu ao tratado pelas armas e proclamou a sua própria constituição, e a Suécia foi obrigada a reconhecê-la — o resultado foi uma união pessoal (real union) que durará até 1905.", "382397ad"]},
"OLAYLAR_EK16:1815-06-09:0":{"b": ["Ata Final do Congresso de Viena — redesenha-se o mapa da Europa pós-napoleónica", "fca1c676"], "d": ["A Ata Final do Congresso de Viena, assinada entre as grandes potências (Áustria, Rússia, Prússia, Inglaterra, França) que puseram fim às Guerras Napoleónicas, foi adotada a 9 de junho de 1815 (9 dias antes de Waterloo) e redesenhou em conjunto o mapa do continente: os antigos Países Baixos Espanhóis/Austríacos e as Províncias Unidas uniram-se sob o 'Reino Unido dos Países Baixos', a República de Génova foi incorporada no Reino da Sardenha-Piemonte, a maior parte do Ducado de Varsóvia foi ligada à Rússia com o nome de 'Polónia do Congresso' e a Pomerânia Sueca (Stralsund) passou para a Prússia. Este único dia é considerado o início oficial do equilíbrio europeu do pós-guerra (Concert of Europe).", "39c08302"]},
"OLAYLAR_EK16:1820-01-08:0":{"b": ["Tratado Geral Marítimo — os Qawâsim e os outros xeicados do Golfo ligados por tratado à Inglaterra", "fc499e19"], "d": ["Depois de, em 1819, ter bombardeado Ras al-Khaimah e dispersado a armada 'pirata' dos Qasimi, a Inglaterra impôs o Tratado Geral Marítimo, iniciado a 8 de janeiro de 1820 e assinado um a um com os xeicados da região até março; o tratado proibiu a pirataria e a escravatura e tornou obrigatório que os navios arvorassem uma bandeira vermelha e branca semelhante à bandeira inglesa. Com este tratado, a 'Costa dos Piratas' transformou-se com o tempo em 'Costa da Trégua' (Trucial Coast); a hegemonia inglesa, aprofundada pela trégua marítima perpétua de 1853 e pelos tratados exclusivos de 1892, foi o início de uma relação que duraria até 1971.", "0b50923a"]},
"OLAYLAR_EK16:1861-02-13:0":{"b": ["Fim do Cerco de Gaeta — colapso do Reino das Duas Sicílias", "121ae580"], "d": ["Depois do colapso iniciado com o desembarque de Garibaldi na Sicília em maio de 1860, o rei Bourbon Francisco II, que fugira de Nápoles, foi sitiado na sua última fortaleza, Gaeta, a partir de 3 de novembro de 1860; com a retirada da armada francesa da região em janeiro de 1861, o bloqueio naval italiano apertou-se e Gaeta rendeu-se a 13 de fevereiro de 1861. Francisco II abandonou o trono e partiu para o exílio; o último ponto de resistência do Reino das Duas Sicílias, Civitella del Tronto, só cairá a 20 de março de 1861.", "ad1202f1"]},
"OLAYLAR_EK16:1861-03-17:0":{"b": ["Proclamação do Reino de Itália — união da Sardenha, da Toscana e do sul de Itália", "12e52f70"], "d": ["Na primeira sessão do parlamento italiano em Turim, o Reino de Itália foi oficialmente proclamado a 17 de março de 1861, e o rei da Sardenha-Piemonte, Vítor Manuel II, tornou-se o primeiro rei da Itália unida. O novo reino unia ao Reino da Sardenha os territórios da Toscana, da Emília-Romanha, de Nápoles e da Sicília (Duas Sicílias), que se haviam juntado por plebiscitos no ano anterior; Roma (Estados Pontifícios) e Veneza (Áustria) ficavam ainda de fora — juntar-se-ão em 1870 e em 1866, respetivamente.", "d044a9c0"]},
"OLAYLAR_EK16:1866-10-18:0":{"b": ["A queda de Jizzakh para a Rússia — a última fortaleza do Emirado de Bucara na linha do Sir Daria", "21205a6e"], "d": ["No avanço da Rússia na Ásia Central, depois da tentativa falhada do general Chernyayev em fevereiro de 1866, as forças russas comandadas pelo general Dmitri Romanovski, nomeado para o substituir, tomaram em outubro de 1866, após um cerco de sete dias e um violento assalto, Jizzakh, a última grande fortaleza do Emirado de Bucara no vale do Sir Daria; esta queda pôs fim de facto à resistência de Bucara na região e abriu ao exército russo o caminho para Samarcanda.", "b95ba993"]},
"OLAYLAR_EK16:1882-03-10:0":{"b": ["Passagem de Assab para a propriedade do Estado italiano — fundamento da primeira colónia de Itália", "15ab8732"], "d": ["O porto de Assab, na costa do Mar Vermelho, fora comprado em 1869 aos chefes afar locais por uma companhia marítima italiana privada (Rubattino); com a aprovação da Inglaterra, o governo italiano assumiu a 10 de março de 1882 a propriedade estatal direta do porto e, por lei promulgada em julho, declarou oficialmente Assab a primeira colónia de Itália. Foi o ponto de partida da expansão de Itália na costa do Mar Vermelho, que se transformaria depois na Colónia da Eritreia (1890).", "ba606490"]},
"OLAYLAR_EK16:1884-02-08:0":{"b": ["Aniquilação da guarnição de Sinkat — Sinkat passa para as forças do Mahdi", "e175a94e"], "d": ["A guarnição de Sinkat, sitiada havia meses pelas forças de Osman Digna e sem víveres, tentou, com o seu comandante Tevfik Bey, romper o cerco e chegar a Sawakin; a 8 de fevereiro de 1884 foi aniquilada fora da fortaleza e Sinkat passou para as mãos das forças do Mahdi. A notícia chegou a Sawakin a 12 de fevereiro.", "abf8611c"]},
"OLAYLAR_EK16:1884-02-09:0":{"b": ["Lei marcial em Sawakin — a cidade passa para comando britânico", "801f6a81"], "d": ["Depois de a força de Baker para socorrer Tokar ter sido desbaratada em El-Teb a 4 de fevereiro, o almirante Hewett desembarcou fuzileiros navais em Sawakin a 6 de fevereiro. A 9 de fevereiro de 1884 foi declarada a lei marcial na cidade e foi dada aos oficiais britânicos plena autoridade militar e civil sobre a cidade; no dia seguinte, a responsabilidade pela cidade foi oficialmente transferida de Baker para Hewett.", "92798eb8"]},
"OLAYLAR_EK16:1884-02-20:0":{"b": ["Rendição de Tokar às forças do Mahdi", "0e21fd24"], "d": ["A guarnição sitiada de Tokar entrou em negociações com as forças do Mahdi a 19 de fevereiro de 1884 e, no dia seguinte, a 20 de fevereiro, entregou a cidade. A notícia chegou a 24 de fevereiro à força britânica em Trinkitat; a operação de socorro de Graham chegara tarde.", "0ebad590"]},
"OLAYLAR_EK16:1884-07-14:0":{"b": ["A Grã-Bretanha estabelece um protetorado na costa norte da Somália — início da Somalilândia", "f301ea94"], "d": ["Segundo o artigo Somali do TDV, Zeyla, Berberâ e Tâcûre foram colonizadas em 1884 pelos ingleses com o nome de Somalilândia; segundo a fonte académica padrão, este processo começou com o tratado assinado em Berbera com a tribo Habar Awal, correspondente a 21 de Ramadão de 1301 (14 de julho de 1884), e alargou-se entre 1884 e 1886 com a assinatura de tratados semelhantes com as tribos Gadabursi, Habar Toljaala, Habar Gerhajis, Issa e Warsangeli; em contrapartida, a Inglaterra prometeu proteção militar. Esta cadeia de tratados preparou o terreno para a proclamação, em 1887, do Protetorado oficial da Somalilândia Britânica.", "1bce7d3e"]},
"OLAYLAR_EK16:1891-01-01:0":{"b": ["Batalha de Mulayda — fim do Segundo Estado Saudita, Najd passa para os Rashidi", "1cd3b213"], "d": ["Depois de as relações se terem deteriorado por causa de uma disputa sobre a zakat e da detenção de um enviado rashidi, o exército do emir de Jabal Shammar, Muhammad bin Rashid, infligiu a 21 de janeiro de 1891, em Mulayda, na região de Qasim, uma pesada derrota às forças sauditas, lideradas por Abdurrahman bin Faysal, e aos seus aliados; este foi o fim efetivo do Segundo Estado Saudita, a família Al Saud foi para o exílio no Kuwait e todo o Najd passou para o domínio dos Rashidi. O domínio duraria até 1902, quando o jovem Abdulaziz bin Saud retomou Riade (Ataque a Riade, 16 de janeiro de 1902).", "e496bc0f"]},
"OLAYLAR_EK16:1891-02-19:0":{"b": ["Retoma de Tokar pelas forças anglo-egípcias — retirada de Osman Digna", "80a2c26a"], "d": ["Tokar, na costa do Mar Vermelho, que desde 1884 estava nas mãos de Osman Digna, comandante local do movimento do Mahdi, foi retomada em fevereiro de 1891 pela operação das forças anglo-egípcias; Osman Digna teve de retirar para as montanhas. Foi um grande golpe para a presença do Estado do Mahdi na costa do Mar Vermelho e a região ficou sob administração conjunta anglo-egípcia.", "07bd31cf"]},
"OLAYLAR_EK16:1891-03-03:0":{"b": ["A coluna de Grenfell passa por Sinkat — Sinkat sai da administração do Mahdi e volta à administração anglo-egípcia", "b7539a44"], "d": ["Depois da retoma de Tokar em fevereiro de 1891, a coluna anglo-egípcia comandada por Grenfell partiu de Afafit, por Sinkat, a 3 de março de 1891 e chegou a Sawakin a 7 de março; a coluna encontrou a região, onde desde 1884 não se podia entrar, inteiramente evacuada pelo inimigo. A 8 de março, foi declarada uma amnistia geral, em nome do quediva, aos xeques reunidos em Sawakin e Sinkat voltou a ficar ligada à administração anglo-egípcia.", "5e77e2d3"]},
"OLAYLAR_EK16:1905-01-01:0":{"b": ["Passagem da Somália Italiana para a administração direta do Estado — liquidação da Companhia Benadir", "8c7d085b"], "d": ["Segundo o artigo Somali do TDV, a Itália estabelecera o seu domínio na costa sul da Somália (Benâdir) em 1889-1891 por acordos com o Sultanato de Zanzibar e com a Inglaterra, deixando a administração, a princípio, a uma companhia comercial com concessão (Benadir Company); segundo a fonte académica padrão, a concessão desta companhia terminou a 24 de janeiro de 1905 e o Estado italiano, comprando a soberania direta da costa do Benâdir (incluindo Mogadíscio, Merca e Brava), estabeleceu a administração colonial oficial. A expansão efetiva da colónia para o interior (Bardera, Baidoa) concluir-se-á com o decreto de fundação de 1908 e nos anos seguintes.", "3ebbbdd3"]},
"OLAYLAR_EK16:1905-06-07:0":{"b": ["Dissolução da União Noruega-Suécia — declaração unilateral de independência do Storting", "aaba2935"], "d": ["Depois de o rei Oscar II ter vetado o pedido do governo norueguês de criar consulados separados e ter declarado que não podia formar um novo governo, o Storting da Noruega decidiu por unanimidade, a 7 de junho de 1905, que o rei já não exercia de facto funções como rei da Noruega e que a união, que durava desde o Tratado de Kiel de 1814, estava dissolvida. No plebiscito de 13 de agosto de 1905, quase todos os eleitores (371.000 votos contra 184) aprovaram a dissolução; a Suécia reconheceu oficialmente a independência a 26 de outubro de 1905, depois das negociações de Karlstad.", "94eda38c"]},
"OLAYLAR_EK16:1915-05-08:0":{"b": ["Libau (Liepāja) tomada pelas forças alemãs — começa a ocupação da Curlândia", "fdb10548"], "d": ["Na ofensiva alemã de verão de 1915, os alemães entraram na Curlândia; Libau era a base naval russa na costa do Báltico. A maior parte da Curlândia passou para o comando do Ober Ost (até ao fim de 1918).", "98e7ef58"]},
"OLAYLAR_EK16:1915-08-01:0":{"b": ["Mitau (Jelgava) tomada pelas forças alemãs", "eb491281"], "d": ["Mitau, antiga capital do ducado da Curlândia, passou para o controlo alemão; a frente de Riga ficou imobilizada na linha do Daugava até 1917.", "05882415"]},
"OLAYLAR_EK16:1915-08-18:0":{"b": ["A fortaleza de Kovno (Kaunas) tomada pelos alemães — a Lituânia ocupada", "9849405b"], "d": ["O 10.º Exército alemão tomou a maior fortaleza da Rússia sobre o Neman; a Região da Lituânia passou para a administração do Ober Ost e, em 1918, o Taryba proclamou a independência sob esta ocupação.", "1f9a43bc"]},
"OLAYLAR_EK16:1915-09-18:0":{"b": ["Vilna (Vilnius) tomada pelas forças alemãs", "2781858b"], "d": ["Durante a Grande Retirada, Vilna passou para as forças alemãs e foi ligada à Região da Lituânia do Ober Ost; a cidade mudou de mãos até 1919 entre forças alemãs, soviéticas e polacas.", "d9dddcbb"]},
"OLAYLAR_EK16:1916-11-03:0":{"b": ["Tratado anglo-catari — o Catar entra na proteção britânica", "f61c4e49"], "d": ["Com a Primeira Guerra Mundial em curso, pelo tratado assinado a 3 de novembro de 1916 entre o major Percy Cox, representante político britânico no Golfo Pérsico, e o xeque do Catar Abdullah bin Cassim Âl Sânî, o Catar aceitou subordinar as suas relações externas à aprovação da Inglaterra, obtendo em contrapartida a garantia de proteção britânica contra ataques navais; este tratado constituiu a base jurídica da relação de proteção britânica do Catar, que duraria até 1971, e foi oficialmente ratificado em 1918.", "abf30185"]},
"OLAYLAR_EK16:1917-09-03:0":{"b": ["Riga tomada pelo 8.º Exército alemão", "df95df19"], "d": ["As forças alemãs transpuseram o Daugava e tomaram Riga; a cidade permaneceu sob controlo alemão até novembro de 1918 e a independência da Letónia foi proclamada sob esta ocupação (18 de novembro de 1918).", "e0339705"]},
"OLAYLAR_EK16:1918-11-18:0":{"b": ["O Conselho Popular da Letónia proclama a independência", "fc72a7f7"], "d": ["O Conselho Popular da Letónia, reunido no Teatro Nacional em Riga, proclamou a República da Letónia, independente do Império Russo; foi formado um governo provisório presidido por Kārlis Ulmanis. Poucas semanas depois (dezembro de 1918), a Rússia Soviética atacou e começou a Guerra da Independência.", "2858d946"]},
"OLAYLAR_EK16:1919-01-05:0":{"b": ["O Exército Vermelho entra em Vilnius — o governo lituano evacua a cidade", "889a97b3"], "d": ["O governo lituano evacuou Vilnius quando o Exército Vermelho se aproximava; as forças soviéticas entraram na cidade e em fevereiro de 1919 foi daí proclamada a República Soviética da Lituânia-Bielorrússia (Litbel). A cidade seria tomada pelas forças polacas em abril de 1919.", "c3a0c216"]},
"OLAYLAR_EK16:1919-04-21:0":{"b": ["As forças polacas tomam Vilnius (Wilno) aos soviéticos", "32d36c4a"], "d": ["As tropas de Józef Piłsudski tomaram Wilno ao Exército Vermelho em abril de 1919; a Lituânia continuou a reivindicar a cidade e a questão de Vilnius envenenou as relações lituano-polacas no período entre as duas guerras.", "85e7c434"]},
"OLAYLAR_EK16:1920-10-12:0":{"b": ["Żeligowski proclama a Lituânia Central — Vilnius torna-se capital de um Estado fantoche apoiado pela Polónia", "11400510"], "d": ["O general Lucjan Żeligowski tomou Vilnius com a sua 'revolta' e proclamou a República da Lituânia Central; o Estado durou até 24 de março de 1922.", "d8050fe5"]},
"OLAYLAR_EK16:1922-03-24:0":{"b": ["A Lituânia Central incorporada na Polónia — Vilnius passa a ser da Polónia", "e929fa20"], "d": ["A Dieta de Wilno votou a incorporação a 20 de fevereiro de 1922; a Dieta polaca ratificou-a a 24 de março de 1922. A Conferência dos Embaixadores reconheceu a fronteira em 1923; a Lituânia não a reconheceu.", "4a067568"]},
"OLAYLAR_EK16:1939-03-22:0":{"b": ["A Lituânia aceita o ultimato alemão — a Região de Memel cedida à Alemanha", "149fb0b2"], "d": ["Pelo ultimato de Ribbentrop, a Lituânia cedeu à Alemanha a Região de Klaipėda (Memel); Hitler entrou em Memel a 23 de março. A região foi tomada pelo Exército Vermelho a 28 de janeiro de 1945.", "75afd979"]},
"OLAYLAR_EK16:1939-09-19:0":{"b": ["O Exército Vermelho ocupa Vilnius", "5b25d037"], "d": ["O Exército Vermelho, que entrara no leste da Polónia a 17 de setembro, entrou, na noite de 18-19 de setembro, em Vilnius, que estava em mãos polacas. Com o pacto soviético-lituano de assistência mútua de 10 de outubro, a cidade seria cedida à Lituânia, e o exército lituano entraria a 28 de outubro.", "285aa71c"]},
"OLAYLAR_EK16:1939-10-28:0":{"b": ["A Lituânia recebe Vilnius — o preço do pacto soviético-lituano de assistência mútua", "37ba5976"], "d": ["Vilnius, tomada pelo Exército Vermelho a 19 de setembro de 1939, foi cedida à Lituânia pelo pacto de assistência mútua de 10 de outubro de 1939; o exército lituano entrou na cidade a 28 de outubro. Em contrapartida, guarnições soviéticas instalaram-se na Lituânia e, em 1940, seguiu-se a anexação.", "60d2f2bf"]},
"OLAYLAR_EK16:1941-06-23:0":{"b": ["A Alemanha ocupa Grodno", "b7ca9378"], "d": ["Frente Leste: Barbarossa de 1941 e Bagration de 1944.", "c6101096"]},
"OLAYLAR_EK16:1941-06-23:1":{"b": ["A Alemanha ocupa Brest-Litovsk", "25898c65"], "d": ["Frente Leste: Barbarossa de 1941 e Bagration de 1944.", "c6101096"]},
"OLAYLAR_EK16:1941-07-09:0":{"b": ["Pskov tomada pelo Exército alemão — começa a ocupação do território russo", "d9822e30"], "d": ["Na terceira semana da Barbarossa, a Wehrmacht entrou em Pskov; a cidade permaneceu sob administração militar alemã até 23 de julho de 1944. Fonte: cronologia da cidade de Pskov, memorialmuseums.org «Memorials in Pskov» — resumo da pesquisa [resumo].", "c875c7b2"]},
"OLAYLAR_EK16:1941-07-11:0":{"b": ["Vitebsk tomada pelo Exército alemão", "e1e4d7d0"], "d": ["O Grupo de Exércitos Centro tomou Vitebsk nas primeiras semanas da Barbarossa; a cidade permaneceu sob administração militar alemã até junho de 1944 e a maior parte da sua população desapareceu.", "aeb95ab0"]},
"OLAYLAR_EK16:1941-07-16:0":{"b": ["Smolensk tomada pelo Exército alemão", "5a7f4e2a"], "d": ["O Grupo de Exércitos Centro tomou Smolensk; esta cidade, no caminho de Moscovo, permaneceu ocupada 26 meses, até 25 de setembro de 1943, e sofreu grande destruição.", "1cff2f04"]},
"OLAYLAR_EK16:1941-07-26:0":{"b": ["Mogilev tomada pelo Exército alemão", "4362b7a1"], "d": ["Mogilev passou para as mãos da Wehrmacht depois de uma defesa de 23 dias; a cidade permaneceu ocupada até 28 de junho de 1944.", "082ca73b"]},
"OLAYLAR_EK16:1941-07-28:0":{"b": ["Criado o Reichskommissariat Ostland — os países bálticos e a Bielorrússia passam para a administração civil alemã", "052d4c08"], "d": ["Por decisão de Hitler de 17 de julho de 1941, os territórios ocupados do Leste foram entregues à administração civil; o Ostland, presidido por Hinrich Lohse, abrangeu a Estónia, a Letónia, a Lituânia e a Bielorrússia (centro em Riga). A administração civil da Estónia foi estabelecida a 5 de dezembro de 1941; o leste da Bielorrússia permaneceu sob administração militar.", "83f60be8"]},
"OLAYLAR_EK16:1941-08-17:0":{"b": ["Narva tomada pelas forças germano-estónias", "60fc2b6a"], "d": ["Na Guerra de Verão, os voluntários estónios e a Wehrmacht tomaram Narva; a cidade foi incluída no Ostland e permaneceu sob administração alemã até 26 de julho de 1944.", "0f32445c"]},
"OLAYLAR_EK16:1941-08-19:0":{"b": ["Novgorod tomada pelo Exército alemão", "4f599b62"], "d": ["O Grupo de Exércitos Norte tomou Novgorod; uma das cidades mais antigas da Rússia permaneceu ocupada até janeiro de 1944 e foi em grande parte destruída.", "ac0d4ff0"]},
"OLAYLAR_EK16:1941-08-19:1":{"b": ["Gomel tomada pelo Exército alemão", "9d78eb92"], "d": ["Três dias depois do ataque da Wehrmacht a Gomel, o Exército Vermelho retirou-se completamente da cidade; a cidade permaneceu ocupada até 26 de novembro de 1943.", "56a11e36"]},
"OLAYLAR_EK16:1941-08-28:0":{"b": ["Tallinn tomada pelo 18.º Exército alemão", "a855ad0d"], "d": ["Com a sangrenta evacuação da Frota Soviética do Báltico para Kronstadt, Tallinn caiu; a Estónia tornou-se Generalbezirk Estland dentro do Ostland (administração civil a 5 de dezembro de 1941).", "859cfaf1"]},
"OLAYLAR_EK16:1941-10-03:0":{"b": ["Orel tomada pelo Exército alemão", "3127f454"], "d": ["Na operação Bryansk-Vyazma, o 2.º Exército Panzer alemão tomou Orel; a cidade permaneceu ocupada até 5 de agosto de 1943.", "f5465227"]},
"OLAYLAR_EK16:1941-10-06:0":{"b": ["Bryansk tomada pelo Exército alemão", "20fa93f8"], "d": ["No final da Batalha de Bryansk, as forças alemãs entraram na cidade; a cidade permaneceu ocupada até 17 de setembro de 1943.", "f4a24f91"]},
"OLAYLAR_EK16:1941-11-03:0":{"b": ["Kursk tomada pelo Exército alemão", "a723a00a"], "d": ["Por ordem do comando soviético, Kursk foi evacuada e o 2.º Exército alemão entrou na cidade; a cidade permaneceu ocupada até 8 de fevereiro de 1943.", "0d07184e"]},
"OLAYLAR_EK16:1943-02-08:0":{"b": ["Kursk libertada pelo Exército Vermelho", "1ac03fba"], "d": ["No final da ofensiva soviética de inverno (a direção Kursk-Kharkov que se seguiu à operação Voronezh-Kastornoye), Kursk foi retomada; em julho do mesmo ano, o nome da cidade foi dado à Batalha de Kursk.", "68d51be4"]},
"OLAYLAR_EK16:1943-08-05:0":{"b": ["Orel retomada pelo Exército Vermelho — a primeira salva soviética depois de Kursk", "80bfc68d"], "d": ["A captura do saliente de Orel e, juntamente com Belgorod, a primeira salva de artilharia disparada em Moscovo.", "5714054b"]},
"OLAYLAR_EK16:1943-09-17:0":{"b": ["Bryansk retomada pelo Exército Vermelho", "d0f2a35f"], "d": ["Com a Operação de Bryansk, a cidade foi retomada a 17 de setembro de 1943.", "e6b7799d"]},
"OLAYLAR_EK16:1943-09-25:0":{"b": ["Smolensk libertada pelo Exército Vermelho", "6516d85a"], "d": ["No auge da Operação de Smolensk, de 7 de agosto a 2 de outubro de 1943, a cidade foi retomada; Smolensk recebeu em 1985 o título de 'cidade heroína'.", "e355d898"]},
"OLAYLAR_EK16:1943-11-26:0":{"b": ["Gomel libertada pelo Exército Vermelho", "280268c2"], "d": ["A Frente Bielorrussa retomou a cidade na operação Gomel-Rechitsa; é uma das primeiras grandes libertações de cidades da Bielorrússia.", "3402c1b4"]},
"OLAYLAR_EK16:1944-01-20:0":{"b": ["Novgorod libertada pelo Exército Vermelho", "52962012"], "d": ["Durante a operação Leningrado-Novgorod, Veliki Novgorod foi retomada a 20 de janeiro de 1944.", "75ea1a61"]},
"OLAYLAR_EK16:1944-06-26:0":{"b": ["Vitebsk libertada pelo Exército Vermelho — Operação Bagration", "b06be69c"], "d": ["A 1.ª Frente do Báltico e a 3.ª Frente Bielorrussa cercaram e tomaram Vitebsk; foi a primeira grande libertação de cidade da Operação Bagration.", "9b4d6042"]},
"OLAYLAR_EK16:1944-06-28:0":{"b": ["Mogilev libertada pelo Exército Vermelho — Operação Bagration", "52fa985d"], "d": ["A 2.ª Frente Bielorrussa tomou Mogilev e transpôs a linha do Dniepre.", "22c05c20"]},
"OLAYLAR_EK16:1944-07-03:0":{"b": ["O Exército Vermelho retoma Minsk — Operação Bagration", "87dc1fb5"], "d": ["Na Operação Bagration, iniciada a 22 de junho, as frentes bielorrussas romperam o Grupo de Exércitos Centro e cercaram Minsk; a cidade foi retomada a 3 de julho e cerca de 50 mil soldados alemães ficaram cercados no leste. A administração civil alemã da Bielorrússia (Generalbezirk Weißruthenien) ruiu.", "1c35549f"]},
"OLAYLAR_EK16:1944-07-13:0":{"b": ["O Exército Vermelho toma Vilnius", "0172450e"], "d": ["Na Operação de Vilnius, de 5 a 13 de julho, a 3.ª Frente Bielorrussa cercou a guarnição alemã e tomou a cidade (a operação «Ostra Brama» do Exército da Pátria polaco foi simultânea). Vilnius tornou-se a capital da RSS da Lituânia.", "aaf124b7"]},
"OLAYLAR_EK16:1944-07-16:0":{"b": ["O Exército Vermelho liberta Grodno da ocupação alemã", "1d134151"], "d": ["Frente Leste: Barbarossa de 1941 e Bagration de 1944.", "c6101096"]},
"OLAYLAR_EK16:1944-07-23:0":{"b": ["Pskov retomada pelo Exército Vermelho", "f18103aa"], "d": ["Depois de mais de três anos de ocupação alemã, Pskov foi retomada pelo Exército Vermelho.", "b6fb3c84"]},
"OLAYLAR_EK16:1944-07-26:0":{"b": ["O Exército Vermelho toma Narva", "64854ae3"], "d": ["Narva, que desde fevereiro de 1944 jazia em ruínas na linha da frente, foi tomada pelas forças soviéticas na Operação de Narva de julho de 1944; o nordeste da Estónia saiu das mãos da administração civil alemã (Generalbezirk Estland).", "74009a05"]},
"OLAYLAR_EK16:1944-07-27:0":{"b": ["Rēzekne tomada pelo Exército Vermelho — liberta-se o leste da Letónia", "e9efd12d"], "d": ["A 2.ª Frente do Báltico tomou Rēzekne; a região de Latgale, na Letónia, saiu da administração alemã.", "eac95aa6"]},
"OLAYLAR_EK16:1944-07-27:1":{"b": ["Daugavpils libertada pelo Exército Vermelho", "b4ee6622"], "d": ["A 360.ª Divisão de Infantaria da 2.ª Frente do Báltico tomou Daugavpils (Dünaburg); a segunda maior cidade de Latgale saiu da administração alemã.", "b8a7bd0d"]},
"OLAYLAR_EK16:1944-07-27:2":{"b": ["Šiauliai tomada pelo Exército Vermelho — operação de Šiauliai", "ccb20729"], "d": ["A 1.ª Frente do Báltico tomou Šiauliai, nó ferroviário no norte da Lituânia; a operação durou de 5 de julho a 29 de agosto de 1944 e chegou-se ao Golfo de Riga.", "444f3101"]},
"OLAYLAR_EK16:1944-07-28:0":{"b": ["O Exército Vermelho liberta Brest-Litovsk da ocupação alemã", "6d5a837a"], "d": ["Frente Leste: Barbarossa de 1941 e Bagration de 1944.", "c6101096"]},
"OLAYLAR_EK16:1944-08-01:0":{"b": ["Kaunas tomada pelo Exército Vermelho — a capital provisória da Lituânia sai da administração alemã", "5c2b2c16"], "d": ["A 3.ª Frente Bielorrussa tomou Kaunas; a ordem do dia de Estaline de 1 de agosto anunciou a tomada. A cidade foi a capital provisória da Lituânia de 1919 a 1939.", "795fab27"]},
"OLAYLAR_EK16:1944-08-25:0":{"b": ["Tartu tomada pelo Exército Vermelho — operação de Tartu", "cc8069ab"], "d": ["A 3.ª Frente do Báltico rompeu a defesa do 18.º Exército alemão e tomou Tartu; a cidade ficou algumas semanas na linha da frente e a operação de Tartu terminou a 6 de setembro de 1944.", "3e9ef2ba"]},
"OLAYLAR_EK16:1944-09-22:0":{"b": ["O Exército Vermelho entra em Tallinn — as forças alemãs abandonam a cidade", "41ae1ec5"], "d": ["Durante a Operação de Tallinn, os alemães abandonaram a cidade; o governo do Comité Nacional da Estónia, que tomara os edifícios governamentais a 18 de setembro, não conseguiu manter a administração quando o Exército Vermelho entrou. A Estónia voltou a ficar sob administração soviética.", "a229e09c"]},
"OLAYLAR_EK16:1945-01-28:0":{"b": ["O Exército Vermelho toma Memel (Klaipėda)", "d01ad3dc"], "d": ["Na operação soviética dirigida à Prússia Oriental e à costa do Báltico, o porto de Memel (Klaipėda) foi tomado à Alemanha e ligado à RSS da Lituânia. A região, cedida à Alemanha em 1939, saiu assim da administração alemã.", "65cf6a00"]},
"OLAYLAR_EK16:1945-05-08:0":{"b": ["A Bolsa da Curlândia rende-se — o Grupo de Exércitos da Curlândia assina a rendição a Govorov", "3c88889b"], "d": ["O Grupo de Exércitos alemão da Curlândia, cercado desde outubro de 1944 na região de Liepāja-Ventspils, rendeu-se; o oeste da Letónia passou para controlo soviético.", "a7bfcc52"]},
"OLAYLAR_EK17:1369-01-01:0":{"b": ["Fortalezas de Istranca: conquista de Pınarhisar, Kırkkilise (Kırklareli) e Vize", "c6b1a9c1"], "d": ["Murad I, que passou o inverno de 1369 no Palácio de Edirne, voltou na primavera a pôr-se em movimento contra Bizâncio e tomou as fortalezas de Pınarhisar, Kırkkilise e Vize, no sopé das montanhas de Istranca. Estas conquistas causaram pânico em Constantinopla e o imperador João V decidiu ir ao papa em busca de ajuda.", "61aac0e3"]},
"OLAYLAR_EK17:1485-01-01:0":{"b": ["Tashkent passa para a administração de Yûnus Han, cã de Moghulistan", "a37ee010"], "d": ["Durante a luta pelo trono entre os príncipes timúridas, Tashkent e arredores passaram para as mãos de Yûnus Han, cã do Chagatai Oriental (Moghulistan). Dois anos depois, quando Yûnus Han morreu, foi sucedido pelo seu filho Mahmud Han; a cidade permaneceu com os cãs mogóis até que, em 1503, os uzbeques de Şeybânî Han a tomaram.", "07459832"]},
"OLAYLAR_EK17:1504-01-01:0":{"b": ["Bâbür cede Fergana aos uzbeques e vai para Cabul", "69df593c"], "d": ["O timúrida Bâbür, filho de Ömer Şeyh Mirza, depois das guerras com Muhammed Şeybânî Han, cedeu aos uzbeques Fergana, onde reinava desde 1494, e, atravessando o Hindu Kush, estabeleceu-se em Cabul.", "21d1ed8c"]},
"OLAYLAR_EK17:1513-01-01:0":{"b": ["Pîrî Reis desenha o mais antigo mapa-múndi que chegou até nós", "6ef941f5"], "d": ["Pîrî Reis desenhou em Galípoli o mapa-múndi datado de 919 (1513); segundo a Enciclopédia do Islão do TDV, entre as fontes do mapa contam-se também 'os mapas antigos que lhe chegaram do mundo oriental e ocidental e o mapa de Cristóvão Colombo' — isto é, pensa-se que leva vestígios da carta de navegação original de Colombo, então tida por perdida. Ofereceu o mapa em 923 (1517), no Cairo, a Selim I, o Severo. Chegou até nós apenas um fragmento que mostra as costas ocidentais/atlânticas (Espanha, Portugal, África Ocidental, costa oriental da América do Sul); este fragmento foi redescoberto no Palácio de Topkapı em 1929 e consta do registo Memória do Mundo da UNESCO.", "78561b0b"]},
"OLAYLAR_EK17:1534-06-01:0":{"b": ["Integração da região de Kars: Şüregel, Arpaçay e Digor entram na administração otomana", "10f16b5c"], "d": ["Durante a Campanha dos Dois Iraques, as fortalezas de Pasin, Şüregel e Oltu passaram para as mãos dos otomanos; é muito provável que a Fortaleza de Kars tenha sido também anexada nessa altura. A região de Arpaçay e Digor, a norte e a leste de Kars, entrou no controlo otomano na mesma operação.", "f8a4288a"]},
"OLAYLAR_EK17:1538-10-01:0":{"b": ["Fim dos Şirvanşahs: Elkas Mirza faz Şâhruh prisioneiro, Şirvan torna-se província safávida", "e6d64114"], "d": ["Elkas Mirza, enviado por Şah Tahmasb, saqueou Şirvan, tomou a Fortaleza de Baykurd e, tendo feito prisioneiro o Şirvanşah Şâhruh, de quinze anos, levou-o para Tabriz. A administração dos Şirvanşahs, que durante muito tempo mantivera o domínio na região, terminou assim; Şirvan tornou-se uma província do Estado Safávida.", "47532c27"]},
"OLAYLAR_EK17:1552-01-01:0":{"b": ["Expansão do Odjak de Argel para o Saara — Tuggurt-Ouargla sujeitas a tributo, conquista definitiva de Tilimsan", "705ec920"], "d": ["Segundo o artigo Tilimsan do TDV, em 960 (1553) um grande exército enviado de Argel, sob o comando de Salih Reis, tomou definitivamente a cidade e pôs fim à dinastia Zayyânida, com três séculos. Na mesma época (1552), Salih Reis organizou uma expedição contra os sultanatos independentes de Tuggurt e Vargla; as forças otomanas tomaram Tuggurt, avançaram para Vargla, os dois sultanatos foram sujeitos a tributo; em Biskra, no caminho, foi deixada uma guarnição otomana permanente. Assim, a fronteira do Odjak de Argel ultrapassou pela primeira vez o Atlas Telliano e chegou à costa do Saara. A grande batalha diante de Mostaganem, por seu lado, deu-se não neste ano, mas em 1558: Hasan Paxá derrotou aí o conde espanhol Alcaudete e pôs fim às ofensivas espanholas no Norte de África.", "da55aa7d"]},
"OLAYLAR_EK17:1557-01-01:0":{"b": ["Fundação da Província da Abissínia — a costa do Mar Vermelho entra na administração otomana", "7dd470ec"], "d": ["A província, criada para impedir a infiltração de Portugal no Mar Vermelho através da Abissínia, foi oficialmente fundada, segundo o artigo Habeş Eyaleti do TDV, a 15 de Şâban de 962 (5 de julho de 1555), e o centro do sanjaco foi Sawakin. Özdemir Paxá iniciou a operação no outono de 1555; tomou as ilhas Dahlak, que controlam o Porto de Massawa, e a 2 de abril de 1557 tomou a cidade de Massawa e, a seguir, Arkîko. A continuação da conquista prosseguiu com a entrada da província de Tigré, em 1558, e de Debârva, em 1559, no domínio otomano.", "7bb5b28b"]},
"OLAYLAR_EK17:1606-10-11:0":{"b": ["Sedefkâr Mehmed Ağa nomeado arquiteto-chefe — o arquiteto da Mesquita do Sultão Ahmed", "27b66fce"], "d": ["Mehmed Ağa, que foi levado para o palácio por devshirme nos anos de 1562-63, vindo da vila de Elbasan, na Albânia, formou-se junto do arquiteto Sinan e foi nomeado arquiteto-chefe otomano a 11 de outubro de 1606. A Enciclopédia do Islão do TDV transmite que uma fonte contemporânea o descreve como 'de génio brando, humilde, homem de palavra, devoto e inteligente'. Mehmed Ağa, que três anos depois, por ordem de Ahmed I, iniciaria a construção da Mesquita do Sultão Ahmed, assinou uma vasta obra, desde as reparações da Caaba até numerosas fontes e mesquitas em Istambul e Edirne. É uma narrativa popular corrente que os seis minaretes deram origem a uma discussão sobre 'igualdade' com a Caaba de Meca; as fontes enciclopédicas não o confirmam e qualificam a disposição apenas como 'não experimentada até então'.", "a4c538fd"]},
"OLAYLAR_EK17:1617-11-22:0":{"b": ["O novo sultão Mustafa I: um prisioneiro do 'kafes', de rosto pálido e olhar distraído, no trono", "c487b0d1"], "d": ["Mustafa I, que subiu ao trono com a morte de Ahmed I, vivera durante anos fechado no palácio sob apertada vigilância, como o primeiro príncipe que o irmão deixara com vida; a Enciclopédia do Islão do TDV descreve-o como 'de rosto pálido, barba rala, grandes olhos negros e olhar inexpressivo' e regista que esta longa reclusão agravou o seu estado psicológico. Neste primeiro reinado, que durou noventa e seis dias, não conseguiu conduzir os assuntos do Estado; em contrapartida, conta-se que saía frequentemente à caça, visitava o estaleiro e até atirava ouro à água para ver os peixes. Os janízaros e os ulemás, por o considerarem inapto para reinar, depuseram-no a 26 de fevereiro de 1618 e colocaram no seu lugar o sobrinho Osman II, de catorze anos.", "f2d36b20"]},
"OLAYLAR_EK17:1630-08-19:0":{"b": ["O sonho de viagem de Evliya Çelebi — querendo dizer 'Şefaat', disse 'Seyahat'", "2d863e22"], "d": ["Segundo a Enciclopédia do Islão do TDV, Evliya Çelebi liga o início da sua vida de viagens de quarenta anos a um sonho que teve na noite de Aşure do Muharrem do ano 1040 (19 de agosto de 1630): no sonho, vê o Profeta com uma numerosa congregação na Mesquita de Ahî Çelebi, em Istambul, e, de emoção, em vez de dizer 'şefaat yâ Resûlellah' (intercessão, ó Mensageiro de Deus), diz 'seyahat yâ Resûlellah' (viagem, ó Mensageiro de Deus). Segundo a tradição, o Profeta, sorrindo deste lapso de língua, deu-lhe a boa-nova da intercessão, da viagem e da peregrinação. Nunca casou e consagrou a vida a esta promessa de 'viagem'.", "ede1feb4"]},
"OLAYLAR_EK17:1632-01-01:0":{"b": ["As contradições de Murad IV: a proibição do álcool do sultão dado à bebida, o pulso de lutador, o ouvido de compositor", "3d2ea5e0"], "d": ["Nos primeiros anos de Murad IV, que subiu ao trono com onze anos, a influência de sua mãe Kösem Sultan foi decisiva; a Enciclopédia do Islão do TDV transmite que Kösem, receando a inclinação para o poder do filho, o 'encaminhou para a diversão, entretendo-o com presentes e festas'. Quando tomou de facto a administração nas suas mãos, por volta dos vinte anos, era um soberano alto, de ombros largos, imponente — conta-se que levantava um homem forte pelo cinto e o fazia dar algumas voltas na Câmara Privada. A contradição impressionante que o TDV regista é esta: o sultão, que se dizia detestar o tabaco e o ópio, era excessivamente dado à bebida, e, apesar disso, antes da campanha proibiu o café, o tabaco e, mais tarde, o próprio álcool; ao mesmo tempo, possuía conhecimentos de música suficientes para compor segundo a tradição dos makam.", "f2aba572"]},
"OLAYLAR_EK17:1632-01-01:1":{"b": ["O voo de foguetão de Lâgarî Hasan Çelebi — uma tradição cuja única fonte é Evliya Çelebi", "1f02e3f2"], "d": ["Segundo o Seyahatnâme de Evliya Çelebi, Lâgarî Hasan Çelebi construiu, na presença de Murad IV, em Sarayburnu, com cinquenta oka de pólvora, um engenho de foguete de sete braços e subiu para o foguete dizendo 'Meu sultão, encomendo-te a Deus, vou falar com o profeta Jesus'. Segundo a tradição, Hasan Çelebi, que subiu cerca de 250 metros, planou até ao mar com engenhos semelhantes a asas de falcão, nadou e regressou ao sultão, ganhando em troca um cargo de sipahi com jornal de setenta akçe.", "ef620ef6"]},
"OLAYLAR_EK17:1638-12-24:0":{"b": ["Kemankeş Kara Mustafa Paxá torna-se grão-vizir — começa o período de reforma financeira", "583846a4"], "d": ["Kemankeş Kara Mustafa Paxá, que se tornou grão-vizir a 17 de Şâban de 1048 (24 de dezembro de 1638) após a morte como mártir de Tayyar Mehmed Paxá na Campanha de Bagdade, aplicou no reinado do sultão Ibrahim uma severa disciplina financeira: reduziu a um terço os efetivos de janízaros e sipahis, corrigiu o título da moeda e apertou o sistema do narh. Com o número dado pelo TDV, esta poupança chegou a 6000 bolsas por ano — mas esta apertada fiscalização granjeou-lhe inimigos no círculo do palácio.", "2de299c2"]},
"OLAYLAR_EK17:1639-01-20:0":{"b": ["Mustafa I morre depois de quinze anos de esquecimento", "b4c872cd"], "d": ["Mustafa I, deposto pela segunda vez a 10 de setembro de 1623, viveu, durante os quinze anos que decorreram até à sua morte, num quarto em que foi mantido fechado; sobre esses anos não há qualquer informação nas fontes. Morreu a 15 de Ramazan de 1048 (20 de janeiro de 1639) — uma parte das fontes considera-o morte natural, outra sustenta que houve dedo de Murad IV.", "f153eced"]},
"OLAYLAR_EK17:1644-01-01:0":{"b": ["'Ibrahim, o Louco' ou uma doença flutuante?", "2abc230f"], "d": ["A Enciclopédia do Islão do TDV rejeita expressamente a alcunha 'Ibrahim, o Louco', difundida no século XX; transmite que o sultão, nas suas próprias cartas, se queixa de dores, de inapetência, de fraqueza nas pernas, de sensação de névoa na cabeça, de aperto no peito e de crises de desmaio. Em contrapartida, as respostas coerentes e razoáveis que deu durante o processo de deposição contradizem a alegação de um desequilíbrio permanente; conclui que o quadro seguiu um curso 'não constante, de gravidade variável'. Nesta época, as responsabilidades de Kösem Sultan foram aumentando progressivamente e o facto de Cinci Hoca, chamado ao palácio, oferecer ao sultão consolo espiritual 'com orações eficazes' aumentou o seu poder de interferir na política.", "f3705d31"]},
"OLAYLAR_EK17:1647-01-01:0":{"b": ["O Incidente das Zibelinas — o imposto de peles do grão-vizir Ahmed Paxá prepara o fim de Ibrahim", "a2a47d62"], "d": ["Enquanto a paixão do sultão Ibrahim por peles de zibelina e âmbar crescia no palácio, o grão-vizir Ahmed Paxá iniciou, por volta de 1647-1648, uma prática que cobrava à força aos dignitários do Estado o preço de peles de zibelina; a Enciclopédia do Islão do TDV regista que os funcionários a viam como um 'haraç' claro. Quando os oficiais janízaros recusaram em conjunto o pagamento, esta resistência foi o desencadeador direto do processo que conduziu à deposição do sultão — na manhã de 7 de agosto de 1648, os funcionários reunidos mataram primeiro Ahmed Paxá e, no dia seguinte, depuseram Ibrahim.", "596c6d08"]},
"OLAYLAR_EK17:1648-05-01:0":{"b": ["'O Estado é governado por mulheres' — a revolta de Varvar Ali Paxá a partir de Sivas", "5b027357"], "d": ["O beylerbei de Sivas, Varvar Ali Paxá, recusou pagar os 30.000 kuruş que Istambul exigia com o nome de 'bayramiye', dizendo que 'o rendimento anual de Sivas não cobre esta quantia'; segundo a Enciclopédia do Islão do TDV, a justificação da sua revolta era a alegação de que, por causa da doença do sultão, os assuntos do Estado tinham passado para as mãos das mulheres e de que isso gerava instabilidade com as frequentes mudanças de governadores. Embora em maio de 1648 tenha obtido primeiro êxito militar, foi derrotado por İpşir Mustafa Paxá, foi executado a 20 de maio de 1648 e a sua cabeça foi enviada a Istambul.", "e45166db"]},
"OLAYLAR_EK17:1686-08-30:0":{"b": ["Perda de Anabolu (Nauplion) para Veneza — ponto de viragem da Guerra da Moreia", "9d400557"], "d": ["Segundo o artigo Anabolu do TDV, os sobreviventes da população muçulmana da cidade durante o cerco fugiram para as ilhas vizinhas e para a Anatólia (1686). Segundo a fonte académica padrão (Setton, Venice, Austria, and the Turks in the Seventeenth Century), as forças de Königsmarck repeliram durante duas semanas os ataques do exército de socorro otomano; quando, a 29 de agosto, a ofensiva de İsmail Paxá terminou numa pesada derrota, a fortaleza rendeu-se em poucos dias. Anabolu era território otomano recebido por tratado em 1540; com a sua perda acelerou-se a passagem da península da Moreia para Veneza.", "592908a0"]},
"OLAYLAR_EK17:1687-08-01:0":{"b": ["Mehmed IV renuncia à caça — o último esforço na véspera da sua deposição", "7daa904b"], "d": ["Depois do desastre de Mohács (agosto de 1687), o exército, a quem não se pagava o soldo, revoltou-se e marchou sobre Istambul. Mehmed IV mandou matar Süleyman Paxá, que fugira com o selo do grão-vizirato, mostrou a sua cabeça aos soldados e declarou arrepender-se, dispersando os apetrechos de caça e os galgos — mas este gesto não bastou para salvar o seu trono, e poucos meses depois foi deposto.", "3f079bcd"]},
"OLAYLAR_EK17:1688-01-17:0":{"b": ["Rendição à Áustria da fortaleza de Munkács (Mukacheve) depois de um cerco de três anos", "ca2efc3d"], "d": ["A fortaleza de Munkács, sitiada pelas forças imperiais no fim de 1685, resistiu durante três anos sob o comando de Ilona Zrínyi, esposa de Imre Thököly; segundo muitas obras de referência publicadas, a fortaleza foi entregue ao general Antonio Caraffa a 17 de janeiro de 1688. Foi a queda de uma das últimas grandes fortalezas da resistência pró-otomana na Hungria, na frente otomano-habsburga.", "d72ac109"]},
"OLAYLAR_EK17:1711-07-21:0":{"b": ["Baltacı Mehmed Paxá e a tradição da czarina Catarina", "c1b739f1"], "d": ["A narrativa popular que atribui a salvação do exército russo cercado no Prut aos presentes/subornos enviados por Catarina I a Baltacı Mehmed Paxá foi repetida ao longo de séculos.", "f28badd1"]},
"OLAYLAR_EK17:1711-07-21:1":{"b": ["A discussão da 'oportunidade perdida' no Prut — duas opiniões", "61ee699c"], "d": ["Que, tendo o exército otomano cercado totalmente o exército russo, se tenha ficado pela paz tornou-se, logo a seguir ao tratado, objeto de discussão entre os historiadores — nas palavras do próprio TDV, 'entendeu-se que se perdera uma grande oportunidade e esta tese foi intensamente desenvolvida pelos que eram da opinião contrária.' Segundo os críticos, o czar poderia ter sido feito prisioneiro e as armas do exército russo tomadas; segundo os defensores, em contrapartida, enfraquecer a Rússia de modo limitado, para impedir o fortalecimento da Suécia no Norte da Europa, era uma 'política mais inteligente'. O TDV transmite as duas opiniões e não toma partido.", "d9f3213c"]},
"OLAYLAR_EK17:1725-01-01:0":{"b": ["Fundada uma comissão de trinta e duas pessoas para o saber/tradução", "0e3a713c"], "d": ["No período do grão-vizirato de Damad İbrahim Paxá, foi fundada em Istambul uma comissão de trinta e dois sábios-escribas, que, nas palavras do TDV, 'se pode considerar a academia da época'. A comissão traduziu para turco, do árabe, do persa, do grego e do latim, obras de história, filosofia e geografia — entre elas, a tradução da Física de Aristóteles por Yanyalı Esad Efendi com uma equipa de vinte e cinco pessoas e a presidência pelo poeta Nedim de uma comissão de tradução de história. O dia não é indicado no TDV, o ano é declarado.", "69ac19ac"]},
"OLAYLAR_EK17:1730-11-25:0":{"b": ["Mahmud I convida Patrona Halil ao palácio e apanha-o numa armadilha", "6147059f"], "d": ["Sete semanas depois de subir ao trono, Mahmud I, por intermédio dos homens da sua confiança — no palácio, Hacı Beşir Ağa, e fora, o cã da Crimeia Kaplan Giray I —, atraiu para o seu lado os principais dos soldados e quebrou a influência de Patrona Halil. A 25 de novembro de 1730, Patrona Halil, chamado a uma reunião na Câmara da Circuncisão do Palácio de Topkapı, foi admitido com Muslu Beşe e Kel Mehmed Ağa; ao sinal do grão-vizir Silâhdar Mehmed Paxá, trinta e dois homens armados, previamente escondidos, surgiram e mataram os três. Mahmud I tomou assim totalmente o controlo da revolta.", "e3d9bb3d"]},
"OLAYLAR_EK17:1731-01-01:0":{"b": ["Humbaracı Ahmed Paxá (Bonneval) posto à frente do Corpo dos Humbaracı", "27b0b1d7"], "d": ["O oficial de origem francesa, cujo nome verdadeiro era Claude-Alexandre Comte de Bonneval, depois de servir primeiro nos exércitos da França e da Áustria, converteu-se ao Islão em Saraievo, tomando o nome de Ahmed, e refugiou-se em 1729 no Estado Otomano. Ahmed Paxá, posto em 1731, no reinado de Mahmud I, à frente do Corpo dos Humbaracı, instruiu cerca de 300 soldados trazidos da Bósnia no quartel que mandou construir em Üsküdar Ayazma; o seu número ultrapassou em pouco tempo os 600 e ele próprio deu também aulas de matemática. A tentativa de revolta que empreendeu na Hungria com Rákóczi, a favor da França, abalou a sua influência e foi exilado em 1738 em Kastamonu. Morreu em Istambul a 23 de maio de 1747 e o seu túmulo está no cemitério do Mevlevîhâne de Gálata.", "5bfbc961"]},
"OLAYLAR_EK17:1738-08-01:0":{"b": ["Retoma de Semendire aos Habsburgos (coroa do Reino da Hungria) — Guerra de 1737-39", "63dcf604"], "d": ["Segundo o artigo Semendire do TDV, a fortaleza, cedida à Áustria em 1717 por Passarowitz, foi retomada com o avanço otomano na frente Danúbio-Sava da guerra otomano-austríaca iniciada em 1737; as forças dos Habsburgos (coroa do Reino da Hungria) puderam manter-se na região até agosto de 1738, data a partir da qual Semendire voltou a entrar na administração otomana. O Tratado de Belgrado (18-09-1739), assinado um ano depois, registaria este ganho — juntamente com Belgrado e o norte da Sérvia.", "9ca857ec"]},
"OLAYLAR_EK17:1738-08-01:1":{"b": ["Regresso do vale do Morava à administração otomana — Yagodina, Kragujevac e Čačak", "b219d3c9"], "d": ["Com a retomada de Semendire em agosto de 1738, também o vale do Morava, que ficava entre Semendire e o corpo principal otomano, voltou à administração otomana: Yagodina, Kragujevac e Čačak são consideradas otomanas a partir desta data. As fontes não datam nem mencionam em separado o regresso destes três lugares; o mapa trabalha com a data de Semendire. O Tratado de Belgrado (1739-09-18) registou esta situação.", "4b38fa55"]},
"OLAYLAR_EK17:1789-04-07:0":{"b": ["Abdülhamid I morre, atingido por uma paralisia, ao ler a notícia da queda de Özi", "6ac60365"], "d": ["Segundo o artigo abdulhamid-i da Enciclopédia do Islão do TDV, Abdülhamid I, cuja saúde se agravara muito com o curso difícil da guerra russo-austríaca, morreu de uma paralisia súbita ao ler a carta do grão-vizir que anunciava a ocupação da Fortaleza de Özi pelos russos (11 de Receb de 1203 / 7 de abril de 1789). O seu corpo foi sepultado em Istambul, em Bahçekapı, no mausoléu que mandara construir. No mesmo dia, o seu sobrinho Selim III subiu ao trono.", "e0b9fc27"]},
"OLAYLAR_EK17:1800-03-21:0":{"b": ["Fundada a República das Sete Ilhas — as ilhas Jónicas sob proteção russo-otomana", "08839694"], "d": ["Em 1799, a armada conjunta russo-otomana expulsara os franceses das ilhas Jónicas (a fortaleza de Corfu caiu a 5 de março de 1799); por uma convenção de doze artigos, de 21 de março de 1800, as ilhas foram constituídas como Cezâyir-i Seb'a-i Müctemia Cumhuru (República das Sete Ilhas), autónoma nos assuntos internos e ligada ao Império Otomano nos assuntos externos. O período entre 1799-03-05 e este dia é o da ocupação conjunta.", "a9d3379e"]},
"OLAYLAR_EK17:1807-07-07:0":{"b": ["Tilsit — os direitos russos sobre a República das Sete Ilhas cedidos à França", "98a78beb"], "d": ["Pelo acordo alcançado em Tilsit entre a Rússia e a França, a Rússia cedeu à França os seus direitos sobre as Sete Ilhas; as tropas francesas instalaram-se nas ilhas no verão de 1807 e a República das Sete Ilhas desapareceu.", "4561dfb9"]},
"OLAYLAR_EK17:1815-11-05:0":{"b": ["Passagem de Santa Maura e das ilhas Jónicas para a proteção britânica — ordem pós-napoleónica", "0af821dc"], "d": ["Santa Maura e as outras ilhas Jónicas, que tinham passado para a França em 1797, foram, depois da derrota definitiva de Napoleão, deixadas em 5 de novembro de 1815, por um tratado especial assinado em Paris entre a Inglaterra, a Rússia, a Áustria e a Prússia, sob a proteção britânica, com o nome de 'Estados Unidos das Ilhas Jónicas' — este é um documento distinto do Tratado geral de Paris de 20 de novembro de 1815. A proteção duraria até 1864, e depois as ilhas seriam cedidas à Grécia.", "b76e9e11"]},
"OLAYLAR_EK18:1455-06-20:0":{"b": ["Conquista de Prizren — centro de sanjaco otomano no Kosovo", "f84c220f"], "d": ["A 4 de Receb de 859 (20 de junho de 1455), o exército otomano comandado por Maomé II, o Conquistador, tomou Prizren depois de uma guerra com o déspota sérvio Đurađ Branković — chamado Vılkoğlu nas fontes otomanas. A cidade passara de Bizâncio para o Reino da Sérvia em meados do século XIII e fora residência real nos reinados do rei Milutin, do czar Dušan e do rei Uroš; depois da morte de Dušan, a sua importância diminuíra. Depois da conquista foi feita centro de um sanjaco e manteve esta qualidade durante quatro séculos e meio, até 1912. Antes da desagregação da Jugoslávia, Prizren era a única cidade dos Balcãs onde se falavam em conjunto três línguas — albanês, turco e sérvio.", "82ab4141"]},
"OLAYLAR_EK19:1789-07-14:0":{"b": ["A queda da Bastilha — início da Revolução Francesa", "96e931f1"], "d": ["No meio da cólera causada pela demissão, pelo rei Luís XVI, do ministro das Finanças Necker (11 de julho de 1789) e da crise económica, o povo de Paris marchou sobre a fortaleza da Bastilha exigindo armas e pólvora. No combate iniciado à tarde, a fortaleza, onde havia só uma centena de guardas contra mais de três mil insurretos, rendeu-se por volta das 17:00; alguns funcionários, incluindo o governador da fortaleza Bernard-René de Launay, foram mortos e sete prisioneiros foram libertados. A fortaleza, quase vazia e cuja demolição já estava planeada, era o símbolo da tirania real — diz-se que a sua queda foi comunicada a Luís XVI com as palavras 'Não, senhor, não é uma revolta, é uma revolução'. O 14 de julho é hoje a festa nacional da França e o acontecimento é considerado o começo simbólico do movimento popular que rapidamente se estendeu a todo o país e da Revolução Francesa (1789-1799) — a revolução, na década seguinte, derrubando a monarquia absoluta, mudaria de forma duradoura o mapa político da Europa e os equilíbrios internacionais em que se incluía também o Império Otomano.", "ecc8db63"]},
"OLAYLAR_EK20:1315-04-28:0":{"b": ["O exército mameluco entra em Malatya — a cidade passa do domínio ilkhânida para o mameluco", "2540363d"], "d": ["Os mamelucos enviaram sobre Malatya um exército comandado por Seyfeddin Tengiz, naib de Damasco; o exército entrou na cidade a 22 de Muharrem de 715 (28 de abril de 1315). Malatya estivera até então sob domínio ilkhânida e era o ponto-chave da linha em que, a oeste do Eufrates, se tocavam as esferas de influência ilkhânida e mameluca. A mudança de mãos da cidade mostra, na longa disputa entre os dois Estados, o avanço dos mamelucos para o Alto Eufrates. Malatya entrará depois desta data, durante algum tempo, na administração dos Eretnaoğulları e, a partir de 1338, voltará ao domínio mameluco.", "e762cf2c"]},
"OLAYLAR_EK20:1326-10-09:0":{"b": ["Fim do Beilique dos Eşrefoğulları — Beyşehir e Seydişehir passam para os Hamîdoğulları", "e4e70846"], "d": ["Demirtaş, filho do emir Çoban, governador-geral do Estado Ilkhânida na Anatólia, pôs-se em campanha contra os beiliques turcomanos que tinham proclamado a sua independência e, entrando em Beyşehir, mandou matar Eşrefoğlu Süleyman Şah, que outrora se queixara dele (9 de outubro de 1326). O Beilique dos Eşrefoğulları, fundado no fim do século XIII na região de Beyşehir e Seydişehir, terminou assim. O artigo Hamîdoğulları do TDV dá a sequência: Beyşehir, Seydişehir, Akşehir e Doğanhisar, que pertenciam aos Eşrefoğulları eliminados por Demirtaş, foram incluídas nos limites do beilique de Hamîd. No mesmo ano, também Dündar Bey, dos Hamîdoğulları, foi entregue a Demirtaş e morto. Estes territórios serão vendidos em 1381 a Murad I por 80.000 moedas de ouro e passarão para a administração otomana.", "af867ff8"]},
"OLAYLAR_EK20:1338-01-01:0":{"b": ["Malatya volta ao domínio mameluco — fim da administração dos Eretnaoğulları", "08b80aa2"], "d": ["Malatya, que passara para a administração mameluca em 1315, caíra durante algum tempo nas mãos dos Eretnaoğulları nos anos de desagregação do Estado Ilkhânida. O artigo Malatya do TDV dá o regresso numa só frase: a partir de 1338, os mamelucos voltaram a dominar a cidade. Este é um corte transversal dos anos em que o vazio pós-ilkhânida no sudeste da Anatólia foi partilhado entre os mamelucos e os Eretna.", "fdd56a26"]},
"OLAYLAR_EK20:1344-10-28:0":{"b": ["Perda do Porto de İzmir para a armada cruzada — quebrado o poder naval dos Aydınoğulları", "775c65fe"], "d": ["A armada cruzada, formada, por incentivo do papa Clemente VI, por navios de Veneza, de Génova, do Reino de Chipre, dos cavaleiros de Rodes e do duque de Naxos, tomou o Porto de İzmir aos Aydınoğulları (28 de outubro de 1344). O porto fora tomado em 1328-1329 pelo pai de Umur Bey, Mehmed Bey, ao genovês Martino Zaccaria e era a base do poder naval dos Aydınoğulları no Egeu. Em setembro de 1334, uma frota cruzada vinda com o mesmo objetivo fora obrigada a retirar-se; esta segunda expedição teve êxito. Umur Bey prosseguiu a resistência e, juntando-se aos outros beiliques turcos, derrotou a armada cruzada a 17 de janeiro de 1345, mas o porto não foi recuperado.", "de5df043"]},
"OLAYLAR_EK20:1366-01-01:0":{"b": ["Alâeddin Bey dos Karamanoğulları incorpora Konya, Aksaray e Niğde nos territórios de Karaman", "2b8b0f70"], "d": ["Alâeddin Bey dos Karamanoğulları, querendo aproveitar o facto de o Sultanato Mameluco ter posto fim ao Reino Arménio e anexado toda a Çukurova, e a confusão surgida no Estado de Eretna, na Anatólia Central, incorporou nos territórios de Karaman, a começar por Konya (1366-1367), Niğde Karahisarı (Yeşilhisar), Aksaray, Akşehir, Ilgın, İshaklı e Kayseri. Konya, pelo peso que tinha como capital seljúcida, era para os Karamanoğulları não apenas uma cidade, mas uma reivindicação de legitimidade.", "986c1d2e"]},
"OLAYLAR_EK20:1467-01-01:0":{"b": ["Uzun Hasan põe fim ao Estado dos Kara Koyunlu — a bacia do lago Van passa para os Ak Koyunlu", "d8d6c2e8"], "d": ["O soberano dos Ak Koyunlu Uzun Hasan, apanhando desprevenido em 1467 o seu implacável inimigo, o soberano dos Kara Koyunlu Cihan Şah, que marchava contra ele, pôs fim ao Estado dos Kara Koyunlu. Com o desaparecimento de Cihan Şah, que reinava desde 1438, a bacia do lago Van — Van, Bitlis, Bargiri (Muradiye), Hoşap e Kotur — passou da administração dos Kara Koyunlu para a dos Ak Koyunlu. Esta vitória fez do Estado dos Ak Koyunlu a única grande potência na Anatólia Oriental e no Irão e pôs Uzun Hasan no caminho que, uma geração depois, o poria frente a frente com os otomanos.", "4d0ea428"]},
"OLAYLAR_EK20:1489-03-04:0":{"b": ["Cem Sultan levado para Roma — diplomacia de reféns e 40.000 ducados por ano", "1c6715a8"], "d": ["O papa Inocêncio VIII, em acordo com Pierre d'Aubusson, chefe dos cavaleiros de Rodes, mandou trazer Cem Sultan para Roma (4 de março de 1489). Cem refugiara-se em Rodes a 29 de julho de 1482 e dali passara a território de Saboia e, por fim, à custódia papal. Bajazeto II aceitara pagar aos cavaleiros 40.000 ducados por ano em troca de manterem o irmão sob custódia e conceder-lhes direito de comércio livre em território otomano. Este pagamento não era um tributo, mas o preço de manter imobilizado na Europa o legítimo rival do trono: se Cem fosse libertado, poderia reunir um exército na Anatólia e, além disso, tornar-se fonte de legitimidade de uma cruzada. Assim, uma questão dinástica tornou-se durante trinta anos o principal constrangimento da política externa otomana — é essa a razão da prudência de Bajazeto no Ocidente. Com a morte de Cem em 1495, este constrangimento desapareceu.", "60ca67f8"]},
"OLAYLAR_EK20:1490-01-01:0":{"b": ["O Reino da Geórgia dividido em três — Kartli, Kakheti e Imerécia, com centro em Kutaisi", "f9c5f798"], "d": ["O Reino da Geórgia unificado, governado pela dinastia Bagrationi, depois de uma longa luta interna, dividiu-se oficialmente em três reinos: Kartli, com centro em Tbilisi, a leste, Kakheti, a nordeste, e Imerécia, com centro em Kutaisi, a oeste. O artigo Gürcistan do TDV confirma a divisão — 'a Geórgia dividiu-se em três reinos (Kartliya, Kahetya, İmeretiya) e cinco beiliques'. A divisão foi decisiva na rivalidade otomano-safávida do século seguinte: segundo o Tratado de Amasya de 1555, İmeret, Dadyan, Güryel e Daveli foram deixados aos otomanos; Kartli, Kahet e Mosuk aos safávidas. Isto é, o facto de o atlas ligar a Geórgia ocidental e a oriental a senhores diferentes nasce desta divisão. Selim I, o Severo, quando ainda era governador de Trebizonda, sujeitara em 1508 o Reino de İmeret (Açıkbaş) à obediência e ao tributo.", "6b0aaa55"]},
"OLAYLAR_EK20:1510-07-25:0":{"b": ["Ocupação de Trípoli de Barbaria pelos espanhóis — fim do domínio hafsida", "de319d23"], "d": ["Depois dos Ammâroğulları, o domínio dos Hafsidas em Trípoli de Barbaria durou até ao ano de 1510. Nesse ano, a cidade foi ocupada pelos espanhóis comandados por Don Pedro Navarro, conde de Oliveto; os muçulmanos que escaparam ao massacre abandonaram a cidade. A ocupação foi a extremidade oriental da cadeia de fortalezas que a Espanha tinha na costa do Norte de África, de Melilla a Trípoli. A população de Trípoli de Barbaria enviará em 925 (1519) uma delegação a Istambul para pedir ajuda aos otomanos contra a invasão espanhola, e a cidade será tomada em 1551 por Turgut Reis e Sinan Paxá e passará para a administração otomana.", "f65b0ba2"]},
"OLAYLAR_EK20:1530-03-24:0":{"b": ["Malta e Trípoli entregues aos cavaleiros de São João — a nova base da ordem expulsa de Rodes", "2595729e"], "d": ["Os cavaleiros de São João (Hospitalários), que Solimão, o Legislador, expulsara de Rodes em 928 (1522), depois de oito anos sem pátria, foram instalados em Malta por Carlos V, rei de Espanha-Alemanha; com a mesma doação, a defesa de Trípoli de Barbaria foi também entregue à ordem. Malta, com os seus portos ideais, tornou-se uma base favorável aos cavaleiros, influentes nos mares: instalaram-se primeiro em Birgu, fortificaram o Forte Saint Angelo e construíram o Forte Saint Michel na ponta de Senglea. Este estabelecimento criou, no meio do Mediterrâneo, uma base inimiga permanente que cortava as rotas marítimas otomanas; os combates iniciados com a incursão de Turgut Reis a Gozo, em 947 (1540), prolongar-se-iam até ao cerco de Malta de 1565.", "3992bdbc"]},
"OLAYLAR_EK20:1648-10-24:0":{"b": ["Paz da Vestefália — terminam as guerras dos Trinta Anos, dissolve-se a unidade do Sacro Império", "d7719f05"], "d": ["Os tratados que puseram fim às guerras dos Trinta Anos (1618-1648) foram assinados no mesmo dia em Münster e Osnabrück (24 de outubro de 1648). Os cerca de trezentos principados do Sacro Império Romano-Germânico ganharam o direito de conduzir a sua própria política externa; o império deixou de ser um Estado e passou a ser um telhado. A Suécia tomou a Pomerânia Ocidental e Stettin, Brandemburgo ganhou a Pomerânia Oriental e a expectativa do arcebispado de Magdeburgo — aqui começa a acumulação de territórios com que os Hohenzollern marcharão para o reino em 1701. A independência dos Países Baixos e da Suíça foi oficialmente reconhecida. Para os otomanos, a importância é indireta mas grande: quando os Habsburgos se retiraram da frente ocidental, surgiu uma potência que podia voltar-se de novo para o leste na Europa Central.", "21478661"]},
"OLAYLAR_EK20:1701-01-18:0":{"b": ["Proclamado o Reino da Prússia — Frederico I coroado em Königsberg", "337a9f74"], "d": ["Frederico III, eleitor de Brandemburgo, com o consentimento do imperador Leopoldo I, coroou-se em Königsberg e tomou o título de «Rei na Prússia» (18 de janeiro de 1701). O título foi tomado da Prússia Oriental, porque esta ficava fora do Sacro Império Romano-Germânico e um eleitor submetido ao imperador só podia ser rei fora das fronteiras imperiais. Os territórios dispersos da dinastia Hohenzollern passaram a ser designados, a partir desta data, com um só nome de Estado.", "203ac1b3"]},
"OLAYLAR_EK20:1720-02-24:0":{"b": ["A Sardenha passa da Espanha para a dinastia de Saboia — nasce o Reino da Sardenha", "adf778b7"], "d": ["No último elo dos arranjos que encerraram a Guerra da Sucessão Espanhola, a ilha da Sardenha foi tomada à Espanha e entregue à dinastia de Saboia; o duque de Saboia deixou em troca a Sicília e tomou o título de Rei da Sardenha. Cagliari e Sassari saíram assim de dois séculos de administração espanhola. O Reino da Sardenha que nasceu é o núcleo do Estado que, século e meio depois, fundará a unidade italiana — isto é, a raiz do Reino de Itália que entrou em Roma em 1870 desce até aqui.", "a73abd0e"]},
"OLAYLAR_EK20:1768-05-15:0":{"b": ["A Córsega vendida por Génova à França — Tratado de Versalhes", "770343df"], "d": ["A República de Génova cedeu à França a Córsega, que mantinha havia séculos, mas que por causa das revoltas não conseguia de facto controlar. O artigo Korsika do TDV dá o acontecimento numa só frase: Génova vendeu em 1768 à França esta ilha, que não conseguia reivindicar como sua. A cedência assinala a retirada de Génova da sua última grande presença territorial no Mediterrâneo; a ilha passará em 1796, durante algum tempo, para mãos inglesas e depois será restituída à França. O facto de a ilha ser território francês fez de Napoleão Bonaparte, que nasceria no ano seguinte em Ajaccio, um súbdito francês.", "c80ca3a4"]},
"OLAYLAR_EK20:1807-07-09:0":{"b": ["Tratado de Tilsit — a Prússia perde metade do seu território, fundado o Ducado de Varsóvia", "d30bb2cc"], "d": ["Depois do desastre de Jena-Auerstedt, a Prússia foi obrigada a aceitar com Napoleão, em Tilsit, uma paz pesada (9 de julho de 1807). Cedeu todos os territórios a oeste do Elba e os territórios polacos que obtivera nas partilhas de 1793 e 1795; destes últimos foi fundado o Ducado de Varsóvia e a região de Białystok foi dada à Rússia. A Prússia perdeu cerca de metade da sua população e do seu território, e o seu exército foi limitado a 42.000 homens. No atlas, Poznań e Toruń passam, a partir deste dia, para o Ducado de Varsóvia, e Białystok para a Rússia.", "4fc1c2ee"]},
"OLAYLAR_EK20:1870-09-20:0":{"b": ["As tropas italianas entram em Roma — fim dos Estados Pontifícios e conclusão da unidade italiana", "a3689f2e"], "d": ["Quando, com a queda de Napoleão III na Guerra Franco-Prussiana, a guarnição francesa que protegia Roma foi retirada, as tropas italianas entraram na cidade e o papa retirou-se para o Vaticano. Terminaram assim os Estados Pontifícios, que existiam havia mais de mil anos, e o Reino de Itália, que incorporou também Roma na união, surgiu como força política no cenário europeu e mundial. É um acontecimento com consequências diretas para o último meio século do atlas: a Itália unificada é o Estado que, em 1911, tomará aos otomanos Trípoli de Barbaria e o Dodecaneso.", "6d9c3e10"]},
"OLAYLAR_EK20:1887-01-07:0":{"b": ["Batalha de Çelenko — fim do Emirado de Harar e ocupação abissínia", "5671a0d9"], "d": ["Quando Dâvûd se tornou imame de Aussa, Harar, que ficava no meio das terras governadas pelos oromos, voltou a ser um emirado independente e manteve esta condição até à ocupação abissínia de 1887. O emir Abdullah, que declarara a jihad, enfrentou os abissínios com 5000 homens em Şeleneko (Çelenko) a 7 de janeiro de 1887; ao ver que seria derrotado, fugiu para a região de Ogaden, no sul de Harar. A batalha mostrou o desequilíbrio entre o exército abissínio, equipado com armas de fogo, e as forças do emirado, e eliminou um dos últimos emirados muçulmanos independentes para lá do Mar Vermelho. Harar, Cîcîga e Dagahbûr foram assim ligadas à Abissínia.", "73175130"]},
"OLAYLAR_EK21:1509-01-01:0":{"b": ["Şah İsmâil toma Derbent — o domínio safávida chega à porta do Cáucaso", "305542c4"], "d": ["Com a derrota e a morte do Şirvanşah Ferruh Yesâr em 1500, Baku e Şemâhî tinham passado para mãos safávidas, enquanto Derbent permanecera ainda algum tempo separada. Şah İsmâil tomou a cidade em 1509 e instalou aí uma das tribos Rumlu; assim, o domínio safávida chegou à porta setentrional do Cáucaso, a este estreito desfiladeiro entre o Cáspio e as montanhas. Em 1538, com a entrada de Şirvan na administração safávida direta, a ligação tornou-se duradoura. Derbent passará para mãos otomanas na campanha de 1578 e será até 1607 o centro de um beylerbeylik de sete sanjacos. O registo do TDV é este: \\\"A fundação e o desenvolvimento do Estado Safávida constituíram o início de uma nova época em Derbent. Şah İsmâil tomou a cidade em 1509 e instalou aí uma das tribos Rumlu. Quando, em 1538, Şirvan passou para o domínio safávida direto...\\\"", "e301b4f1"]},
"OLAYLAR_EK21:1537-01-01:0":{"b": ["Incorporação definitiva de Kars no território otomano — o prego da fronteira oriental", "6235c85a"], "d": ["Depois da destruição do Estado dos Ak Koyunlu pelos safávidas, Kars ficara algum tempo nas mãos de Sevündük Han Kurçibaşı, dos turcomanos Avşar. Quando, durante a Campanha dos Dois Iraques do Legislador (940/1534), foram tomadas as fortalezas de Pasin, Şüregel e Oltu, é muito provável que a Fortaleza de Kars tenha também sido ligada aos otomanos; mas a incorporação definitiva da cidade é três anos depois. O registo do TDV é este: \\\"Kars foi definitivamente incluída no território otomano em 944 (1537) por Mehmed Han, dos Dulkadır, que entrara ao serviço otomano.\\\" Como a cidade e a fortaleza estavam em grande parte em ruínas por causa das longas lutas, iniciou-se uma rápida reparação; em 955 (1548), enquanto a fortaleza era reparada, os safávidas atacaram a cidade e destruíram de novo a fortaleza. Kars permanecerá depois disso, durante trezentos e quarenta anos, como a fechadura da fronteira nordeste otomana e será cedida à Rússia depois da guerra de 1877-78.", "dff46f96"]},
"OLAYLAR_EK21:1811-04-01:0":{"b": ["Retoma de Nicópolis — termina a ocupação russa de seis meses", "7fb299d7"], "d": ["As forças russas, que na guerra otomano-russa de 1806-1812 passaram para a margem sul do Danúbio, tinham tomado Nicópolis em outubro de 1810, sob o comando do general Kutuzov. Seis meses depois, vendo que não poderiam manter a linha do Danúbio, evacuaram a cidade; antes de partir, fizeram explodir uma parte importante da fortaleza. O registo do TDV é este: \\\"Em outubro de 1810 (período da guerra turco-russa de 1808-1812), Nicópolis foi tomada pelas forças do célebre general russo Mikhail Kutuzov. Os russos, antes de abandonar a cidade, fizeram explodir em abril de 1811 uma parte importante da fortaleza e causaram grande dano à cidade.\\\" Depois da retirada das forças russas, os otomanos mandaram reconstruir a fortaleza; a inscrição de 1813-1814 é o registo desta reparação.", "7237449c"]},
"OLAYLAR_EK21:1811-05-01:0":{"b": ["Evacuação de Silistra — a fortaleza central do Danúbio abandonada com as muralhas demolidas", "561628bb"], "d": ["Silistra, uma das mais fortes fortalezas otomanas do Danúbio, foi bombardeada em 1810 pela artilharia russa, e com a explosão de um depósito de armas a fortaleza e o arrabalde sofreram graves danos. Depois de tomarem a cidade, os russos, em vez de a manter, escolheram destruir as suas fortificações: o general Kutuzov ordenou a demolição das muralhas e, em maio de 1811, comunicou ao czar que as muralhas de Silistra tinham sido feitas explodir. O registo do TDV: \\\"Em 1810, a cidade foi bombardeada pelos russos… Depois de os russos terem tomado a cidade e antes da sua retirada, o general Kutuzov ordenou a destruição de Silistra. Em maio de 1811, comunicou ao czar que as muralhas de Silistra tinham sido feitas explodir.\\\" A mesma fortaleza será retomada pelos russos na guerra de 1827-1828 e Helmuth von Moltke narrará esse cerco em pormenor.", "d18dd90e"]},
"OLAYLAR_EK22:1794-01-01:0":{"b": ["Fim da dinastia zand — domínio qajar no Irão", "5dda30a4"], "d": ["Com a derrota de Lutf Ali Han, último soberano da dinastia zand, terminou a dinastia fundada em 1751 e todo o Irão passou para as mãos de Ağa Muhammed Han. A fundação oficial do Estado Qajar data de dois anos depois, da coroação de Ağa Muhammed Han como xainxá em Teerão (1796); mas a posse foi assumida em 1794.", "793d45c6"]},
"OLAYLAR_EK2:1327-01-01:0":{"b": ["Cunhagem do primeiro akçe otomano", "38d2d638"], "d": ["O primeiro akçe de prata, cunhado em nome de Orhan Gazi, é a proclamação monetária da soberania independente do beylik; o akçe permaneceu durante cinco séculos a unidade monetária básica.", "8729ab5b"]},
"OLAYLAR_EK2:1362-09-01:0":{"b": ["Criado o Beylerbeylik da Rumélia", "ffa16089"], "d": ["As conquistas na margem europeia foram reunidas sob um único teto militar-administrativo; a ordem dos beylerbeyliks tornou-se a espinha dorsal da organização provincial do império.", "9c13c8c3"]},
"OLAYLAR_EK2:1390-01-15:0":{"b": ["Casamento de Yıldırım Bayezid com Despina Hatun", "4b10dc6c"], "d": ["A vassalagem estabelecida com o despotado sérvio depois do Kosovo foi selada com o casamento de Olivera, filha de Lazar, com Bayezid — exemplo típico da diplomacia matrimonial do período inicial.", "7d87810a"]},
"OLAYLAR_EK2:1393-01-01:0":{"b": ["Criado o Beylerbeylik da Anatólia", "5ef8d3a7"], "d": ["Foi organizado o Beylerbeylik da Anatólia para a administração dos territórios dos beyliks anexados; a ordem administrativa de duas asas, Rumélia-Anatólia, ficou completa.", "55429c02"]},
"OLAYLAR_EK2:1399-06-01:0":{"b": ["Concluída a Grande Mesquita de Bursa", "27bcc4a5"], "d": ["A grande mesquita de vinte cúpulas, mandada construir com o espólio de Niğbolu, é o exemplo monumental da arquitetura otomana primitiva e um museu aberto da caligrafia.", "b0e811e6"]},
"OLAYLAR_EK2:1453-06-01:0":{"b": ["Destituição e execução de Çandarlı Halil Paşa", "5e19438f"], "d": ["Depois da conquista, foi executado o grão-vizir da antiga família Çandarlı, que se mantivera distante do cerco; era a primeira vez que um grão-vizir era morto por ordem do sultão, e abria-se a era dos vizires de origem devshirme.", "557b77f5"]},
"OLAYLAR_EK2:1456-06-01:0":{"b": ["Sujeição da Moldávia a tributo", "25bd3693"], "d": ["O voivodado da Moldávia aceitou pagar tributo; com a Valáquia e a Transilvânia, o tríplice cinturão vassalo a norte do Danúbio tornou-se o tampão setentrional do império. Outros lugares incorporados na mesma data: Yaş.", "7cea09ea"]},
"OLAYLAR_EK2:1459-03-07:0":{"b": ["Tributo de Dubrovnik (Ragusa)", "d127c78a"], "d": ["A república mercantil de Ragusa assegurou, em troca de tributo, a sua autonomia e privilégios comerciais; enriqueceu como janela dos otomanos no Adriático. A ilha de Mljet, território da república, partilhou também este estatuto.", "812b9f2b"]},
"OLAYLAR_EK2:1462-06-01:0":{"b": ["Campanha da Valáquia: o Voivoda Empalador", "fd4530bb"], "d": ["Com a campanha organizada contra Vlad Țepeș, que recusara pagar o tributo e matara os enviados, a Valáquia foi reconduzida à vassalagem; o ataque noturno e as cenas de terror dos empalamentos tornaram-se lendários na Europa. Outros lugares incorporados na mesma data: Bükreş.", "6ae089b4"]},
"OLAYLAR_EK2:1470-12-01:0":{"b": ["Inaugurado o Complexo de Maomé II, o Conquistador", "a150ea55"], "d": ["Com as suas oito madraças (Sahn-ı Semân), o complexo foi o primeiro grande passo do programa de transformação de Istambul em centro do saber do mundo islâmico.", "cbec7a2f"]},
"OLAYLAR_EK2:1472-01-01:0":{"b": ["Ali Kuşçu em Istambul", "8508229d"], "d": ["Ali Kuşçu, último grande representante do observatório de Samarcanda, por convite de Maomé II, o Conquistador, tornou-se professor na Madraça de Santa Sofia; fundou em Istambul a tradição da matemática-astronomia.", "fd325f60"]},
"OLAYLAR_EK2:1477-01-01:0":{"b": ["Kanunnâme de Maomé II, o Conquistador", "b08944c9"], "d": ["O primeiro kanunnâme consuetudinário abrangente, que compila a organização do Estado, o protocolo e as penas; é discutido pelo seu célebre artigo que permite o fratricídio 'para a ordem do mundo'.", "0e654de1"]},
"OLAYLAR_EK2:1478-06-01:0":{"b": ["Cunhado o primeiro ouro otomano (sultanî)", "2fd5c0dd"], "d": ["Foi cunhada a primeira moeda de ouro otomana, equivalente ao ducado veneziano; as finanças do império integraram-se na ordem monetária internacional.", "cac00614"]},
"OLAYLAR_EK2:1478-09-01:0":{"b": ["Mudança para o Palácio de Topkapı", "b9cd6a5e"], "d": ["Com a conclusão do Novo Palácio (Topkapı), o centro da administração do Estado passou para aí; o palácio permaneceu durante quatro séculos como o cérebro do império.", "748ada37"]},
"OLAYLAR_EK2:1532-04-27:0":{"b": ["A República de Florença transformou-se em ducado — Alessandro de' Medici", "c08764e1"], "d": ["Sob pressão do Papa Clemente VII, a comissão governante de Florença (Balìa) adotou uma nova constituição; o regime republicano de cinco séculos foi abolido, Alessandro de' Medici foi proclamado duque hereditário e subiu de facto ao trono em 1 de maio. Florença passou assim de república citadina independente a ducado hereditário da dinastia Médici.", "92da65c9"]},
"OLAYLAR_EK2:1534-01-01:0":{"b": ["Casamento do Legislador com Hürrem Sultan", "abc05f26"], "d": ["A celebração por Kanunî do casamento oficial com Hürrem mudou radicalmente a tradição palaciana; nasceu a instituição da 'Haseki Sultan' e abriu-se a porta da era das mulheres na política dinástica.", "db1f832b"]},
"OLAYLAR_EK2:1536-02-18:0":{"b": ["Primeiras capitulações abrangentes à França", "e2264e48"], "d": ["Como parte da aliança com a França contra o cerco habsburgo, foram assinados entre Jean de la Forest e Makbul İbrâhim Paşa privilégios comerciais; as capitulações, então um instrumento diplomático, tornar-se-iam ao longo dos séculos a porta da dependência financeira.", "e7c6fd84"]},
"OLAYLAR_EK2:1538-06-13:0":{"b": ["Campanha do oceano Índico: cerco de Diu", "fcd1217a"], "d": ["A armada que partiu de Suez atravessou o mar Vermelho e sitiou Diu, no Guzerate; embora a fortaleza não tenha sido tomada, o poder otomano estendeu-se pela primeira vez ao oceano Índico e o monopólio português foi abalado.", "ce118bf7"]},
"OLAYLAR_EK2:1553-12-07:0":{"b": ["Viagem de Seydi Ali Reis à Índia", "e5da3b2c"], "d": ["Seydi Ali Reis, encarregado de trazer para o Egito a armada de Baçorá, foi arrastado pelas tempestades até à Índia; o Mir'âtü'l-memâlik, em que narra a aventura do regresso, é um dos primeiros relatos de viagem otomanos.", "bb472cec"]},
"OLAYLAR_EK2:1554-01-01:0":{"b": ["Execução de Pîrî Reis", "63026444"], "d": ["O grande navegador-cartógrafo, que regressou da campanha de Ormuz deixando a armada em Baçorá, foi executado aos 84 anos — uma das decisões mais discutidas da nossa história da ciência.", "e3d1ac3f"]},
"OLAYLAR_EK2:1557-10-16:0":{"b": ["Inaugurado o Complexo de Süleymaniye", "1c6458b2"], "d": ["Complexo que o arquiteto Sinan chamou 'a minha obra de oficial'; com as suas madraças, o seu dârüşşifâ (hospital) e a sua biblioteca, tornou-se o maior complexo educativo e de beneficência do período clássico.", "0c203c6b"]},
"OLAYLAR_EK2:1565-05-18:0":{"b": ["Cerco de Malta", "f57f6a85"], "d": ["Malta, fecho do Mediterrâneo, foi sitiada durante quatro meses; Turgut Reis morreu mártir e o cerco foi levantado. Foi o primeiro grande recuo da marinha do tempo do Legislador.", "860ee1bc"]},
"OLAYLAR_EK2:1575-03-01:0":{"b": ["Concluída a Mesquita de Selimiye", "3b0484e1"], "d": ["A Selimiye, que Sinan chamou 'a minha obra de mestre' e em que uma única cúpula domina o espaço, é considerada o apogeu da arquitetura clássica otomana (Património Mundial da UNESCO).", "9d7cd43c"]},
"OLAYLAR_EK2:1577-01-01:0":{"b": ["Fundado o Observatório de Istambul", "169bdf5d"], "d": ["O observatório de Takiyyüddin, um dos mais bem equipados da época, foi demolido em 1580 após as discussões surgidas depois do cometa de 1577; a astronomia institucional atrasou-se três séculos.", "7fb471aa"]},
"OLAYLAR_EK2:1578-08-09:0":{"b": ["Vitória de Çıldır — começou a guerra do Oriente", "13125a54"], "d": ["Com a derrota do exército safávida em Çıldır, abriram-se as portas do Cáucaso; Tbilisi foi tomada e a Geórgia passou ao domínio otomano.", "0bf34d05"]},
"OLAYLAR_EK2:1583-05-09:0":{"b": ["Batalha das Tochas — Şirvan definitivamente otomana", "3bbc23bc"], "d": ["Na batalha, assim chamada por ter prosseguido de noite à luz de tochas, os safávidas foram definitivamente derrotados; o domínio otomano em Şirvan e em Baku ficou consolidado.", "e2aa6d1e"]},
"OLAYLAR_EK2:1585-01-01:0":{"b": ["Grande depreciação — crise do akçe", "9205c3d4"], "d": ["Sob a pressão das longas guerras e da prata americana, o teor de prata do akçe foi reduzido para metade; a revolução dos preços alimentou a dissolução da ordem dos sipahis e a desordem celali.", "bd2a508f"]},
"OLAYLAR_EK2:1585-09-25:0":{"b": ["Conquista de Tabriz", "6506bdb9"], "d": ["O serdar Özdemiroğlu Osman Paşa entrou em Tabriz; a antiga capital dos safávidas foi tomada pela administração otomana. Osman Paşa morreu no acampamento poucas semanas depois.", "e54b35bd"]},
"OLAYLAR_EK2:1590-03-21:0":{"b": ["Tratado de Ferhad Paşa — as fronteiras mais vastas no Oriente", "c429972f"], "d": ["Depois da chegada a Istambul do enviado do xá Abbas, Haydar Mirza (18 de janeiro de 1590), com o tratado, feito sob a condição de que os lugares conquistados ficassem com os otomanos, e que pôs fim a uma guerra de 12 anos, Tabriz, Karabakh, Şirvan, a Geórgia e o Luristão ficaram com os otomanos; o império alcançou no Oriente as fronteiras mais vastas da sua história.", "41d8b058"]},
"OLAYLAR_EK2:1603-10-21:0":{"b": ["Começou a Guerra Otomano-Safávida (1603-1612) — contraofensiva do xá Abbas, perda de Tabriz", "abf27dd8"], "d": ["O xá Abbas, que reorganizara o seu exército, passou à ofensiva aproveitando as desordens celalis; Tabriz caiu, os ganhos no Cáucaso perderam-se em poucos anos. Mesma campanha e outros povoamentos perdidos em seguida: Nahçıvan, Hoy, Merend, Selmâs; os beys de Karacadağ (Ahar) e de Mukrî passaram também para o lado safávida.", "b1757da9"]},
"OLAYLAR_EK2:1611-03-25:0":{"b": ["Nasceu Evliya Çelebi", "2b6051ff"], "d": ["Evliya Çelebi, que reuniu no Seyahatnâme, em dez volumes, as suas viagens de mais de cinquenta anos, deixou um panorama sem igual do mundo otomano do século XVII.", "bbd451a3"]},
"OLAYLAR_EK2:1612-11-20:0":{"b": ["Tratado de Nasuh Paşa", "bb69e388"], "d": ["Com o tratado que pôs fim à guerra que durava desde 1603, renunciou-se aos ganhos de 1590 e regressou-se à fronteira de Amásia de 1555; o equilíbrio na frente oriental foi restabelecido.", "f3ce47a7"]},
"OLAYLAR_EK2:1616-06-09:0":{"b": ["Inaugurada a Mesquita do Sultão Ahmed", "e39dfd43"], "d": ["Com as suas seis minaretes e os azulejos azuis de İznik, a 'Mesquita Azul' é o último grande complexo sultanino do período clássico.", "c3e55fc5"]},
"OLAYLAR_EK2:1648-08-18:0":{"b": ["Assassinato do sultão İbrahim", "bc4eb452"], "d": ["A aliança do corpo e dos ulemás depôs İbrahim, alegando prodigalidade e crise de governo; dez dias depois foi estrangulado por fetua. Subiu ao trono Mehmed IV, de sete anos; o poder passou de facto para as mãos da grande valide Kösem Sultan.", "b90693f4"]},
"OLAYLAR_EK2:1657-10-06:0":{"b": ["Morte de Kâtib Çelebi", "e167e89d"], "d": ["Figura cimeira da história do saber otomano com a bibliografia Keşfü'z-zunûn e a geografia Cihannümâ; é conhecido pela abordagem pioneira que utilizou fontes europeias.", "786ec8d5"]},
"OLAYLAR_EK2:1703-08-22:0":{"b": ["Incidente de Edirne — deposição de Mustafa II", "0291c1cd"], "d": ["A residência do sultão em Edirne e a ira contra a influência de Feyzullah Efendi transformaram-se numa grande revolta de exército e artesãos; o xeique do Islão foi linchado, o sultão foi deposto e o palácio regressou a Istambul.", "e8740499"]},
"OLAYLAR_EK2:1720-10-08:0":{"b": ["Embaixador em Paris: Yirmisekiz Mehmed Çelebi", "26312a3f"], "d": ["A grande embaixada enviada à França foi a primeira observação sistemática do Ocidente no local; o seu Sefâretnâme inspirou a renovação da Era das Tulipas.", "aa11c96a"]},
"OLAYLAR_EK2:1727-07-05:0":{"b": ["Fundada a primeira tipografia otomana", "4943f7e5"], "d": ["Foi concedida licença para imprimir livros em turco; a primeira obra, o Dicionário de Vankulu, foi impressa em 1729. A tipografia é o legado mais duradouro da renovação da Era das Tulipas.", "a33e45d0"]},
"OLAYLAR_EK2:1740-05-30:0":{"b": ["As capitulações tornadas permanentes", "d044a79e"], "d": ["Os privilégios concedidos à França deixaram de estar limitados ao sultão e foram ligados a um tratado duradouro; o regime das capitulações, que se tornou impossível de rescindir unilateralmente, só pôde ser abolido em Lausana.", "d50899dc"]},
"OLAYLAR_EK2:1773-01-01:0":{"b": ["Fundada a Mühendishâne-i Bahrî-i Hümâyun", "9bf3f439"], "d": ["A escola de engenharia, fundada após o desastre de Çeşme para formar oficiais de marinha modernos, é a primeira instituição duradoura de ensino técnico ao estilo ocidental; a escola de engenharia terrestre seguiu-se em 1795.", "b73b2ce6"]},
"OLAYLAR_EK2:1793-06-01:0":{"b": ["Primeira embaixada permanente em Londres", "6b5630eb"], "d": ["Como parte do programa do Nizâm-ı Cedîd, abriram-se embaixadas permanentes nas capitais europeias; a diplomacia otomana passou ao princípio da reciprocidade.", "0321b899"]},
"OLAYLAR_EK2:1808-11-16:0":{"b": ["Morte de Alemdar Mustafa Paşa", "4426534e"], "d": ["Na revolta dos janízaros iniciada na noite de 15 de novembro de 1808, o grão-vizir reformista, cercado na Sublime Porta, como o socorro que esperava não chegou, incendiou no dia seguinte o paiol e morreu com centenas de atacantes; a ordem do Sened-i İttifak e a primeira tentativa de reforma foram enterradas com ele.", "04420a26"]},
"OLAYLAR_EK2:1831-11-01:0":{"b": ["Primeiro jornal oficial: Takvîm-i Vekāyi", "c637f623"], "d": ["Começou a ser publicado o jornal oficial do Estado; é o início da tradição da opinião pública moderna e do comunicado oficial.", "b4f1f627"]},
"OLAYLAR_EK2:1838-08-16:0":{"b": ["Tratado Comercial de Balta Limanı", "e790b383"], "d": ["Foi concedida à Inglaterra a posição mais privilegiada, mesmo no comércio interno, e o sistema do yed-i vahit (monopólio) foi abolido; enquanto a produção local ficava desprotegida, o tratado tornou-se o documento da abertura plena do mercado otomano ao comércio livre.", "14089a77"]},
"OLAYLAR_EK2:1842-01-01:0":{"b": ["Fim do Emirado do Líbano — destituição de Beşîr III Şihâb", "f85ae454"], "d": ["O emir Beşîr II, que não conseguia controlar a disputa cristão-drusa e os equilíbrios internos da região de Şûf, foi destituído em janeiro de 1842; a ordem emiral local, que durava desde 1516 (através dos Ma'noğulları e depois dos Şihâboğulları), chegou ao fim e a região passou à administração otomana direta e depois ao sistema de duplo kaymakam.", "205abc18"]},
"OLAYLAR_EK2:1844-01-01:0":{"b": ["Tashîh-i sikke: ordem Mecidiye", "c77be809"], "d": ["Com a reforma monetária foram recolhidas as moedas de título adulterado; foi estabelecida uma ordem bimetálica estável baseada na lira de ouro (Mecidiye).", "e0642ec8"]},
"OLAYLAR_EK2:1850-01-01:0":{"b": ["Fim do domínio local da família Harfûş em Baalbek", "8438f4ae"], "d": ["A influência da família Harfûş, que reinava desde 1521 (depois da revolta de Canbirdi Gazâlî) como pequena dinastia local em Baalbek, terminou com o novo ordenamento administrativo da Sublime Porta; a cidade foi feita um simples centro de kaza ligado à província de Damasco.", "106eabb2"]},
"OLAYLAR_EK2:1851-01-01:0":{"b": ["Fundada a Şirket-i Hayriyye", "462830e7"], "d": ["A companhia, fundada para explorar vapores no Bósforo, é considerada a primeira sociedade anónima otomana; os cais dos vapores marcaram a vida da cidade.", "b4203b61"]},
"OLAYLAR_EK2:1854-08-24:0":{"b": ["Primeiro contrato de dívida externa", "9017c579"], "d": ["Para o financiamento da Guerra da Crimeia, contraiu-se o primeiro empréstimo externo no mercado de Londres; o ponto a que se chegou com 15 empréstimos em 21 anos foi a moratória de 1875 e a Düyûn-ı Umûmiyye.", "1c4f9949"]},
"OLAYLAR_EK2:1855-09-14:0":{"b": ["Linha telegráfica em Istambul", "d320f39f"], "d": ["A primeira linha telegráfica, instalada pelas necessidades da Guerra da Crimeia, foi posta em serviço; o império obteve em poucas décadas uma das mais vastas redes telegráficas do mundo.", "f59439a3"]},
"OLAYLAR_EK2:1858-06-06:0":{"b": ["Código das Terras", "6bae243a"], "d": ["O kanunnâme, que modernizou o direito fundiário, ligou ao título de propriedade o usufruto efetivo das terras mîrî; é um dos documentos fundamentais da ordem de propriedade do atual Médio Oriente.", "395494dc"]},
"OLAYLAR_EK2:1863-01-13:0":{"b": ["Primeiras aulas no Dârülfünun", "08f74066"], "d": ["O Dârülfünun, que ministraria ensino de nível universitário, começou a funcionar com aulas públicas; a instituição, que continuou com interrupções, abriu de forma duradoura em 1900 e tornou-se o núcleo da Universidade de Istambul.", "6218d070"]},
"OLAYLAR_EK2:1864-11-08:0":{"b": ["Regulamento das Províncias", "ad20853b"], "d": ["Em lugar da ordem dos eyalets foi criada a organização provincial segundo o modelo francês; tomando como exemplo a aplicação de Midhat Paşa na Província do Danúbio, foi estendida a todo o país.", "665b97d3"]},
"OLAYLAR_EK2:1867-06-21:0":{"b": ["Viagem de Abdulaziz à Europa", "9ff0fa1e"], "d": ["A primeira viagem de um sultão otomano à Europa com fins pacíficos; a exposição de Paris e as visitas a Londres serviram ao mesmo tempo de montra da diplomacia e da modernização.", "bd58ae5d"]},
"OLAYLAR_EK2:1868-09-01:0":{"b": ["Inaugurado o Galatasaray Mekteb-i Sultânîsi", "f9688524"], "d": ["O liceu com ensino em francês, com a sua composição de alunos sem distinção de religião e de comunidade, tornou-se o símbolo do ideal de igualdade na educação do Tanzimat.", "c9d5821d"]},
"OLAYLAR_EK2:1869-04-01:0":{"b": ["Entra em vigor o primeiro livro da Mecelle", "6475461c"], "d": ["A Mecelle, que compilou com técnica legislativa moderna o domínio das obrigações e dos bens do direito islâmico, é considerada o primeiro código civil islâmico; a comissão presidida por Cevdet Paşa concluiu os 16 livros em 1876.", "9669c96e"]},
"OLAYLAR_EK2:1876-05-30:0":{"b": ["Deposição de Abdulaziz", "eb7397ea"], "d": ["Os estadistas constitucionalistas e os dignitários militares depuseram Abdulaziz com um golpe silencioso; a sua morte suspeita cinco dias depois e os incidentes de Çırağan que se seguiram deram origem a ajustes de contas que durariam anos.", "9523e81b"]},
"OLAYLAR_EK2:1878-05-20:0":{"b": ["Ataque a Çırağan (caso Ali Suâvi)", "d2a9ac87"], "d": ["O jornalista Ali Suâvi assaltou Çırağan para repor Murad V no trono; o ataque foi reprimido com sangue e o regime de Abdulhamide apertou de forma permanente o cerco de segurança.", "8bd8ba3f"]},
"OLAYLAR_EK2:1884-01-01:0":{"b": ["Criada a Administração da Régie (monopólio do tabaco)", "bad9b030"], "d": ["Os rendimentos do tabaco foram transferidos para a companhia Régie, de capital estrangeiro, no seio da Düyûn-ı Umûmiyye; os conflitos do 'contrabando da Régie' entre os camponeses e os guardas prolongaram-se por décadas. Outros povoamentos perdidos na mesma data: Zeyla.", "19e84e39"]},
"OLAYLAR_EK2:1898-10-18:0":{"b": ["Visita do Kaiser Guilherme II a Istambul e a Jerusalém", "2988cd06"], "d": ["A segunda visita do imperador alemão consolidou a aproximação otomano-alemã; abriu-se o caminho da concessão da ferrovia de Bagdade e em Damasco foi proferido o discurso do 'amigo de trezentos milhões de muçulmanos'.", "2e385229"]},
"OLAYLAR_EK2:1908-09-01:0":{"b": ["Ferrovia do Hejaz em Medina", "95009b9c"], "d": ["A linha de 1464 km, construída apenas com donativos muçulmanos e engenharia local, chegou a Medina; a viagem de peregrinação passou de semanas a dias. É a maior obra de infraestrutura do tempo de Abdulhamide II.", "a1c98c4c"]},
"OLAYLAR_EK2:1909-04-13:0":{"b": ["Incidente de 31 de Março", "1d7c2bb2"], "d": ["A grande revolta antiparlamentar tomou Istambul; o Exército de Ação, vindo de Salónica, reprimiu a revolta e Abdulhamide II foi deposto.", "4885dfd1"]},
"OLAYLAR_EK2:1912-10-26:0":{"b": ["Começou o cerco de Edirne", "234d9b28"], "d": ["A defesa de cinco meses de Şükrü Paşa tornou-se a epopeia da resistência no meio do desastre balcânico; a cidade caiu pela fome e foi recuperada em julho de 1913.", "3c3ca395"]},
"OLAYLAR_EK2:1913-01-23:0":{"b": ["Ataque à Sublime Porta", "b304d02d"], "d": ["O governo, que se preparava para entregar Edirne, foi derrubado por um assalto armado dos unionistas; o ministro da Guerra, Nâzım Paşa, foi morto. Começou o período de poder pleno do Comité de União e Progresso.", "a8a7af44"]},
"OLAYLAR_EK2:1915-07-11:0":{"b": ["Abolição do Mutasarrifato do Monte Líbano", "b5639051"], "d": ["A ordem autónoma do mutasarrifato, estabelecida pelo Règlement Organique de 1861 e assente no protocolo internacional renovado em 1864, foi rescindida unilateralmente pelo Estado otomano durante a Primeira Guerra Mundial; o Ministério do Interior começou a nomear diretamente mutasarrifs muçulmanos para a região. O período de autonomia, em que serviram oito mutasarrifs entre 1861 e 1915, ficou assim encerrado.", "83ff35bc"]},
"OLAYLAR_EK3:1402-08-01:0":{"b": ["Partilha do país entre os príncipes", "82f26bfb"], "d": ["Depois do desastre de Ancara, Süleyman Çelebi passou à Rumélia e proclamou-se sultão em Edirne; İsa Çelebi manteve Bursa e Çelebi Mehmed a região de Amásia-Tokat-Sivas. No mapa, estas três partes são mostradas em cores distintas.", "08baaa0b"]},
"OLAYLAR_EK3:1403-02-01:0":{"b": ["Tratado de Galípoli: costa do mar Negro até Misivri deixada a Bizâncio", "a4164eca"], "d": ["O emir Süleyman, que queria manter-se na Rumélia depois do desastre de Ancara, assinou em Galípoli um tratado com o imperador bizantino Manuel. Deixou a Bizâncio Kartal, Pendik e Gebze e algumas ilhas, na Rumélia Salónica e a Tessália, e no mar Negro a faixa costeira que se estende até Misivri; foi também abolido o imposto que Bizâncio pagava aos otomanos. Ahtapolu, İğneada e Rezve, na costa de Istranca, permaneceram assim vinte e um anos sob administração bizantina; Murad II recuperou a maior parte destes lugares com a paz de 1424.", "ad1af28a"]},
"OLAYLAR_EK3:1403-03-09:0":{"b": ["Morte de Yıldırım Bayezid no cativeiro", "7e968d83"], "d": ["O sultão, prisioneiro de Tamerlão, morreu em Akşehir; o seu corpo foi levado para Bursa e sepultado. A sua morte tornou irreversível a luta pelo trono entre os príncipes.", "af68bc4d"]},
"OLAYLAR_EK3:1403-06-15:0":{"b": ["Tratado de Galípoli — concessões a Bizâncio", "dfacbd00"], "d": ["Süleyman Çelebi, que queria assegurar a sua posição na Rumélia, chegando a acordo com Bizâncio e os Estados latinos, restituiu Salónica, as costas do Mármara e algumas ilhas; aceitou mesmo pagar tributo.", "0d91820c"]},
"OLAYLAR_EK3:1403-09-01:0":{"b": ["Combate de Ulubat — derrota de İsa Çelebi", "500c5d24"], "d": ["İsa Çelebi, que mantinha Bursa, foi derrotado em Ulubat diante do seu irmão Mehmed; várias tentativas de recuperação resultaram também em nada.", "624072ce"]},
"OLAYLAR_EK3:1406-06-01:0":{"b": ["Desaparecimento de İsa Çelebi", "0effa11e"], "d": ["İsa Çelebi, que regressou várias vezes à Anatólia com o apoio de Süleyman Çelebi, desapareceu depois da sua última derrota; a sua parte passou a Çelebi Mehmed e, no mapa, a área de Mehmed alargou-se para oeste.", "d164b447"]},
"OLAYLAR_EK3:1406-06-18:0":{"b": ["Musa Çelebi passou à Valáquia", "8441267a"], "d": ["Çelebi Mehmed, que perdera Bursa e Ancara diante de Süleyman Çelebi e se retirara para Tokat-Amásia, incitou o seu irmão Musa a ir para a Rumélia. Musa, aceitando o convite do voivoda da Valáquia, Mircea, chegou à Valáquia por mar; daqui iniciaria uma luta que deixaria Süleyman entre duas frentes.", "e7866931"]},
"OLAYLAR_EK3:1410-05-06:0":{"b": ["Çelebi Mehmed retomou Bursa e Ancara — a parte da Anatólia saiu das mãos de Süleyman Çelebi", "bfb69f12"], "d": ["Com os êxitos de Mûsâ Çelebi na Rumélia (Yambol, 13 de fevereiro de 1410), o emir Süleyman Çelebi, que se encontrava na Anatólia, passou à Rumélia. Depois da saída de Süleyman da Anatólia, Mehmed Çelebi tomou de novo a região de Bursa, incluindo Ancara, e mandou cunhar moeda datada de 813 como sinal da sua subida ao trono. No mapa, a margem anatólica do Mármara passa da parte do emir Süleyman para a cor de Çelebi Mehmed.", "bc148b8e"]},
"OLAYLAR_EK3:1410-06-15:0":{"b": ["Batalha de Cosmídion", "0efc2caa"], "d": ["Na batalha travada diante das muralhas de Constantinopla com apoio bizantino, Süleyman Çelebi derrotou o seu irmão Musa; contudo, o seu apoio na Rumélia começara já a desvanecer-se rapidamente.", "ece5fe6b"]},
"OLAYLAR_EK3:1411-01-01:0":{"b": ["Cerco de Constantinopla por Musa Çelebi", "4932f586"], "d": ["Musa Çelebi, que queria castigar Bizâncio por apoiar Süleyman, sitiou Constantinopla; este cerco empurrou Bizâncio para uma aliança com Çelebi Mehmed.", "b52f942c"]},
"OLAYLAR_EK3:1411-02-17:0":{"b": ["Morte do emir Süleyman — Musa domina a Rumélia", "325c1549"], "d": ["Süleyman Çelebi, apanhado quando fugia de Edirne, foi morto; toda a Rumélia passou às mãos de Musa Çelebi. No mapa, a Rumélia passa de azul a roxo.", "48aa849a"]},
"OLAYLAR_EK3:1413-07-05:0":{"b": ["Batalha de Çamurlu — restabelecimento da unidade", "0b23173e"], "d": ["Çelebi Mehmed, que obteve o apoio de Bizâncio, do despotado sérvio e dos beys da Rumélia, derrotou decisivamente o seu irmão Musa em Çamurlu; Musa foi morto quando fugia. A Rumélia, que estava nas mãos de Musa, passou com Edirne a Mehmed, e Mehmed Çelebi proclamou-se em Edirne o único soberano do Estado otomano. O Fetret Devri de onze anos terminou e as partes dos príncipes no mapa reuniram-se num só corpo.", "649e53b7"]},
"OLAYLAR_EK3:1683-01-01:0":{"b": ["Decisão da campanha de Viena — a paz de Vasvár não foi renovada, o objetivo foi mudado de Győr para Viena", "1bf278f2"], "d": ["O imperador Leopoldo I queria a renovação do Tratado de Vasvár, cujo prazo ainda não expirara, e Mehmed IV parecia também favorável à paz. O grão-vizir Kara Mustafa Paşa de Merzifon, porém, invocando as queixas de Imre Thököly, a quem fizera proclamar rei da Hungria central, não deixou renovar a paz; pôs em movimento os pregadores, com Vânî Mehmed Efendi à cabeça, e persuadiu o sultão à guerra. Na consulta realizada decidiu-se que o sultão permaneceria em Belgrado e que o serdâr-ı ekrem avançaria para tomar Győr; porém, na consulta de Belgrado, apesar da objeção do cã da Crimeia Murad Giray e do governador de Buda, Uzun İbrâhim Paşa, o objetivo foi mudado para o cerco de Viena.", "7a572168"]},
"OLAYLAR_EK3:1683-07-14:0":{"b": ["Começou o II Cerco de Viena — o exército diante de Viena", "bb542e49"], "d": ["O exército otomano sob o comando do grão-vizir Kara Mustafa Paşa chegou diante de Viena em 14 de julho de 1683. O imperador Leopoldo I deixou a guarda da cidade a Starhemberg e retirou-se para o interior da Áustria. Este segundo cerco, preparado visando diretamente Viena, ao contrário do primeiro, prolongar-se-ia até 12 de setembro.", "ecea5576"]},
"OLAYLAR_EK3:1683-10-09:0":{"b": ["Desastre de Párkány e perda de Esztergom", "a7366740"], "d": ["O exército, que se retirara de Viena, foi pela segunda vez desbaratado em Párkány; em seguida caiu Esztergom, uma das fortalezas-chave da Hungria. A retirada começou a transformar-se em colapso.", "13a860f4"]},
"OLAYLAR_EK3:1683-12-25:0":{"b": ["Execução de Kara Mustafa Paşa de Merzifon", "ce8b10ac"], "d": ["O grão-vizir, tido como responsável pelo desastre de Viena, foi estrangulado em Belgrado; contudo, a sua execução nem corrigiu a frente nem restituiu o prestígio abalado do Estado.", "23449e61"]},
"OLAYLAR_EK3:1684-03-05:0":{"b": ["Constituída a Santa Aliança", "060280d0"], "d": ["Sob a liderança do papado foi constituída entre a Áustria, a Polónia e Veneza a Santa Aliança (Mukaddes İttifak) contra os otomanos; em 1686 aderiu também a Rússia. O império entrou assim numa guerra em várias frentes que duraria dezasseis anos.", "5f02a851"]},
"OLAYLAR_EK3:1684-07-14:0":{"b": ["Primeira defesa de Buda", "ccc43630"], "d": ["O primeiro cerco de Buda pelo exército da Santa Aliança foi repelido pela defesa obstinada, de quatro meses, da fortaleza; contudo, as fortalezas da Hungria continuavam a cair uma a uma.", "fb62dd75"]},
"OLAYLAR_EK3:1685-08-19:0":{"b": ["Perda de Uyvar", "689ab78c"], "d": ["A fortaleza de Uyvar, que permanecera vinte e dois anos em mãos otomanas e se tornara provérbio na Europa, caiu; a presença otomana na Alta Hungria desfez-se.", "559f5062"]},
"OLAYLAR_EK3:1685-10-15:0":{"b": ["Prisão de Thököly em Várad — dissolução do Reino da Hungria Central, rendição das fortalezas da Alta Hungria", "1741aaaf"], "d": ["Depois do desastre de Viena, os otomanos tinham começado a ver Thököly também entre os responsáveis pela guerra e pela derrota. Em 15 de outubro de 1685, por ordem do serdar Melek İbrâhim Paşa, o beylerbei de Várad, Ahmed Paşa, mandou prender Thököly, que vinha em auxílio; esperava-se obter melhores condições de paz entregando-o aos Habsburgos. Quando se espalhou a notícia da prisão, todas as fortalezas e cidades do Reino da Hungria Central, exceto Munkács, defendida pela sua mulher Ilona Zrínyi, se renderam aos Habsburgos; a maioria dos soldados kuruc passou para o exército habsburgo. Quando Thököly foi libertado em Belgrado em 2 de janeiro de 1686, o reino já deixara de existir.", "1a00b9f3"]},
"OLAYLAR_EK3:1686-09-02:0":{"b": ["Perda de Buda — capital húngara de 145 anos", "70800e2b"], "d": ["Buda caiu no termo de um cerco de setenta e oito dias; o último beylerbei, Abdurrahman Abdi Paşa, morreu mártir nas muralhas. A perda da cidade, que estava sob administração otomana desde 1541, é considerada o símbolo da perda da Hungria. Outros povoamentos perdidos na mesma data: Peşte.", "e66f909f"]},
"OLAYLAR_EK3:1687-08-12:0":{"b": ["Segundo desastre de Mohács (Harsány) — perda da Transilvânia e de Mohács", "a7922681"], "d": ["Na planície em que se ganhara a grande vitória de 1526, sofreu-se desta vez uma pesada derrota; o exército dispersou-se, os soldados revoltosos fizeram destituir o grão-vizir. A derrota conduziu também à perda da Transilvânia.", "6b95b7d0"]},
"OLAYLAR_EK3:1687-09-26:0":{"b": ["Perda de Atenas e explosão do Pártenon", "b6691730"], "d": ["Uma granada lançada pela artilharia veneziana fez explodir o Pártenon, que os otomanos usavam como paiol; o templo de dois mil anos ficou em ruínas. A cidade passou para mãos venezianas (será recuperada em 1688).", "e28ad137"]},
"OLAYLAR_EK3:1687-11-08:0":{"b": ["Deposição de Mehmed IV e subida ao trono de Süleyman II", "9f53037c"], "d": ["Perante os desastres na frente e a revolta do exército, Mehmed IV foi deposto após um reinado de 39 anos; foi colocado em seu lugar o seu irmão Süleyman II, que estava havia quarenta anos no kafes.", "6a7bb845"]},
"OLAYLAR_EK3:1688-09-06:0":{"b": ["Primeira perda de Belgrado — cerco da Santa Aliança", "c6b9b19a"], "d": ["Belgrado, que estava em mãos otomanas desde 1521, rendeu-se ao exército da Santa Aliança; as portas da Sérvia abriram-se ao inimigo e o perigo chegou à linha Niš-Sófia.", "33c7db1f"]},
"OLAYLAR_EK3:1689-08-01:0":{"b": ["Baden atravessou o Morava diante de Pasarofça — Pasarofça caiu para a Áustria", "bcf3fc59"], "d": ["O margrave Ludwig von Baden, em agosto de 1689, atravessou o Morava em Pasarofça e avançou na direção de Niš; a cidade permaneceu em mãos austríacas até ao verão de 1690 (o TDV suleyman-ii diz que Pasarofça foi recuperada em 1690). A leitura de Gün e de Röder não foi reverificada nesta sessão.", "28e54b6c"]},
"OLAYLAR_EK3:1689-09-24:0":{"b": ["Perda de Niš — avanço dos Habsburgos (coroa do Reino da Hungria), ano mais crítico", "c5e27b3f"], "d": ["O avanço dos Habsburgos (coroa do Reino da Hungria) tomou também Niš à administração otomana; as incursões estenderam-se até Üsküp e Priština. Vidin, por seu lado, caiu depois disto, em outubro de 1689 (item separado). No ano mais sombrio da guerra, o Estado sentiu a sua própria capital ameaçada.", "77de2b1f"]},
"OLAYLAR_EK3:1689-10-25:0":{"b": ["Orsova e Fethülislâm postas sob guarnição austríaca", "ee8dd875"], "d": ["Depois da tomada de Vidin sem combate (outubro de 1689, TDV vidin), Baden reparou e guarneceu Orsova e Fethülislâm em 25 de outubro de 1689; Orsova permaneceu com a Áustria até ao outono de 1690. O dia assenta em Bánlaky/Röder e não foi reverificado nesta sessão.", "4c6ebd2c"]},
"OLAYLAR_EK3:1690-09-27:0":{"b": ["Niš de novo otomana", "0c4f44eb"], "d": ["Fâzıl Mustafa Paşa partiu em campanha em julho de 1690; depois de tomadas Şehirköy, Pasarofça e Güvercinlik, Niš, sitiada, passou em 27 de setembro de 1690 para as mãos dos otomanos (TDV semendire). Ao mesmo tempo, Vidin tinha sido também recuperada.", "f252f3ae"]},
"OLAYLAR_EK3:1690-10-01:0":{"b": ["Rendição das tropas austríacas em Semendire", "90da20c4"], "d": ["Depois da tomada de Niš em 27 de setembro de 1690, com um cerco de quatro dias as tropas austríacas em Semendire renderam-se (TDV semendire). Bánlaky/Röder dá 24 de setembro; as fontes contradizem-se, adotou-se o TDV.", "9034a37d"]},
"OLAYLAR_EK3:1690-10-08:0":{"b": ["Belgrado recuperada", "ab435838"], "d": ["O grão-vizir Köprülüzâde Fâzıl Mustafa Paşa recuperou Belgrado à Áustria em 8 de outubro de 1690; a cidade perdida em 1688 voltou assim aos otomanos (TDV suleyman-ii).", "c93eeef6"]},
"OLAYLAR_EK3:1691-08-19:0":{"b": ["Desastre de Slankamen — Fâzıl Mustafa Paşa mártir", "10d626f1"], "d": ["Numa das batalhas campais mais sangrentas do século, o grão-vizir caiu mártir, atingido na testa; o exército dispersou-se. A esperança de recuperação extinguiu-se com esta batalha.", "36dfe6ea"]},
"OLAYLAR_EK3:1694-09-21:0":{"b": ["Perda da ilha de Quios", "07c084f8"], "d": ["A armada veneziana ocupou Quios; o domínio otomano no Egeu ficou ameaçado. A ilha será recuperada no ano seguinte.", "f5f59c77"]},
"OLAYLAR_EK3:1695-02-11:0":{"b": ["Decisão de Mustafa II de ir pessoalmente em campanha", "61c3ba9c"], "d": ["O novo sultão, seguindo o caminho dos seus antepassados, declarou que partiria em campanha à frente do exército; esta decisão criou moral no exército e iniciou um período de campanhas pessoais que duraria dois anos.", "2794ae0f"]},
"OLAYLAR_EK3:1695-02-22:0":{"b": ["Recuperação de Quios", "6b496fca"], "d": ["Mezomorto Hüseyin Paşa, que derrotara a armada veneziana nas batalhas navais das Ilhas Oinousses, recuperou Quios; foi sinal de um breve renascimento na marinha otomana.", "7638e074"]},
"OLAYLAR_EK3:1695-09-22:0":{"b": ["Vitória de Lugoj — campanha de II Him", "6527cee3"], "d": ["Na primeira campanha em que o sultão participou pessoalmente, Lipova foi recuperada e as forças austríacas foram derrotadas em Lugoj; deu-se a primeira quebra na cadeia de derrotas que durava havia anos.", "54aa0f54"]},
"OLAYLAR_EK3:1696-07-19:0":{"b": ["Perda da fortaleza de Azov", "2b78b5cd"], "d": ["Pedro I, que visava a saída para o mar Negro, tomou Azov no seu segundo cerco; a Rússia estabeleceu-se pela primeira vez de forma duradoura numa fortaleza otomana e deu o primeiro passo para se tornar potência naval.", "b765c903"]},
"OLAYLAR_EK3:1696-08-27:0":{"b": ["Vitória de Ulaş (Olašin)", "02ac9ca8"], "d": ["A vitória ganha nas margens do Danúbio na segunda campanha do sultão frustrou o plano austríaco de tomar Timișoara; contudo, não alterou o equilíbrio geral da guerra.", "b6e2d27a"]},
"OLAYLAR_EK3:1697-09-11:0":{"b": ["Desastre de Zenta — decidido o destino da guerra", "475c4a7b"], "d": ["O exército, quando atravessava o rio Tisza, sofreu o ataque súbito do príncipe Eugénio; as forças divididas nas duas margens do rio foram aniquiladas em poucas horas, e morreram milhares de soldados e de estadistas, incluindo o grão-vizir Elmas Mehmed Paşa. Zenta, um dos desastres mais pesados da história otomana, tornou inevitável a mesa da paz.", "ced10fdc"]},
"OLAYLAR_EK3:1698-11-13:0":{"b": ["Começaram as negociações de paz de Karlowitz", "1f395cf3"], "d": ["Nas conversações iniciadas com a mediação da Inglaterra e dos Países Baixos, a delegação otomana foi pela primeira vez obrigada a aceitar o princípio do 'uti possidetis' (permanência do que se detém); as negociações, que duraram setenta e duas sessões, são consideradas o nascimento da diplomacia otomana moderna.", "1d41e9e8"]},
"OLAYLAR_EK4:1801-03-08:0":{"b": ["Mehmed Ali de Kavala desembarcou no Egito", "514c943f"], "d": ["No exército otomano enviado para recuperar o Egito, ocupado pelos franceses, havia também um contingente de voluntários reunidos em Kavala. Mehmed Ali, na casa dos trinta anos, era o segundo comandante deste contingente; pôs pé no Egito não como governador, mas como oficial de uma companhia.", "b7e3bb36"]},
"OLAYLAR_EK4:1803-05-01:0":{"b": ["Soldados albaneses derrubaram o governador do Egito", "c76a0ec2"], "d": ["As tropas albanesas, a quem não eram pagos os soldos, revoltaram-se e obrigaram o governador Hüsrev Paşa a fugir da cidadela. No vazio criado pela retirada dos franceses, os beys mamelucos, o corpo albanês e os governadores nomeados pela Sublime Porta entraram numa luta a três; Mehmed Ali destacou-se estabelecendo equilíbrios neste triângulo. Outros povoamentos perdidos na mesma data: Tâif.", "669d61a0"]},
"OLAYLAR_EK4:1805-05:0":{"b": ["Os ulemás do Cairo proclamaram Mehmed Ali governador", "a16752f2"], "d": ["Os artesãos e os ulemás do Cairo, exasperados com a pressão fiscal, sob a liderança do nakîbüleşraf Ömer Mekrem, revoltaram-se, declararam que não reconheciam o governador Hurşid Paşa e instalaram Mehmed Ali no cargo de governador. A eleição de um governador pelo povo é um acontecimento raro na história otomana.", "1572b66f"]},
"OLAYLAR_EK4:1805-07-03:0":{"b": ["A Sublime Porta aceitou o facto consumado: firmão de governador do Egito", "b86736a3"], "d": ["A Sublime Porta, sem força para sustentar no Egito o seu candidato, enviou a Mehmed Ali o firmão de governador do Egito com a patente de vizir. No mapa, o Egito passa, a partir desta data, ao estrato vassalo (tom claro): juridicamente território otomano, de facto país da dinastia de Kavala. Outros lugares que passam ao estrato vassalo na mesma data: Kahire, İskenderiye, Dimyat, Asyut, Asvan, İbrim, Süveyş, Reşîd (Rosetta).", "e769c607"]},
"OLAYLAR_EK4:1807-03-17:0":{"b": ["A expedição inglesa de Fraser desembarcou em Alexandria", "4d6c31be"], "d": ["Em resposta à aproximação otomana da França, a Inglaterra enviou ao Egito uma força de desembarque. Mehmed Ali estava então no Alto Egito a braços com os mamelucos; regressando rapidamente, organizou a defesa.", "fd5f278f"]},
"OLAYLAR_EK4:1807-04-21:0":{"b": ["Desastre de Rashid (Rosetta) — os ingleses repelidos", "3636004c"], "d": ["A coluna inglesa que entrou na vila de Rashid sofreu pesadas perdas em combates de rua; em setembro as forças evacuaram totalmente o Egito. Esta vitória consolidou o prestígio de Mehmed Ali tanto no Egito como em Istambul.", "68a2ba26"]},
"OLAYLAR_EK4:1811-03-01:0":{"b": ["Massacre da Cidadela: liquidação dos beys mamelucos", "84030b97"], "d": ["Os beys mamelucos, convidados para o cortejo cerimonial organizado para a campanha do Hejaz, foram eliminados, encurralados na estreita passagem da Cidadela do Cairo. A influência mameluca de cinco séculos chegou assim ao fim e Mehmed Ali ficou sem rival no Egito.", "1ca00e33"]},
"OLAYLAR_EK4:1811-09-03:0":{"b": ["Começou a campanha do Hejaz — o exército marchou para Yanbu por mar a partir de Suez e por terra pela rota da peregrinação", "1c05c159"], "d": ["Recuperar os Haremeyn, sob administração saudita-wahhabita desde 1803, era a maior questão de legitimidade de Mahmud II; como a Sublime Porta não tinha força, a missão foi dada ao governador do Egito. Mehmed Ali enviou o seu filho Tosun, de dezasseis anos, à frente do exército.", "5e614d69"]},
"OLAYLAR_EK4:1811-10-01:0":{"b": ["Yanbu tomada — primeira base costeira da campanha do Hejaz", "179bc78d"], "d": ["Cerca de dois mil soldados de infantaria albaneses, que partiram de Suez em navios recém-construídos, desembarcaram em outubro de 1811 perto de Yanbu; a vila rendeu-se após dois dias de fraca resistência. A cavalaria sob o comando de Tosun, seguindo por terra a rota da peregrinação, só chegou a Yanbu duas semanas depois, por Aqaba e Wajh. Yanbu foi a primeira base no Hejaz do exército egípcio que marcharia sobre Medina e Meca.", "cfc2ed8a"]},
"OLAYLAR_EK4:1812-01-01:0":{"b": ["Primeiro desastre no desfiladeiro de Safra-Cedîde", "99ef804d"], "d": ["A vanguarda egípcia, apanhada numa emboscada em estreitas passagens de montanha, foi dispersada. A derrota foi a lição tática da campanha: percebeu-se que não era possível marchar no Hejaz sem obter o apoio das tribos beduínas.", "765dd19d"]},
"OLAYLAR_EK4:1812-12-03:0":{"b": ["Medina recuperada", "6f6a5d55"], "d": ["Após um longo cerco, Medina rendeu-se. A recuperação da cidade do Profeta foi celebrada em Istambul com festejos de canhão; como recompensa, foi dado também a Mehmed Ali o governo de Jidá.", "45cc4c79"]},
"OLAYLAR_EK4:1813-01-23:0":{"b": ["Meca recuperada — aberta a rota da peregrinação", "3d6d66a0"], "d": ["As forças egípcias que entraram em Meca mandaram ler de novo a hutba na Caaba em nome do sultão otomano. As caravanas de peregrinos, interrompidas havia dez anos, puderam voltar a partir. No mapa, o Hejaz regressa ao domínio otomano, mas, como a sua administração está no Cairo, é mostrado em tom vassalo. Outro lugar que passou à administração vassala na mesma data: Cidde.", "f0970e28"]},
"OLAYLAR_EK4:1813-05-02:0":{"b": ["Recuperação de Tâif — conclusão da campanha do Hejaz", "6315fb31"], "d": ["Depois de Medina (dezembro de 1812) e de Meca (janeiro de 1813), o exército egípcio sob o comando de Tosun Paşa recuperou por último Tâif aos wahhabitas. O domínio saudita de dez anos terminou e os três centros sagrados do Hejaz voltaram a ficar sob controlo otomano-egípcio.", "374bf563"]},
"OLAYLAR_EK4:1813-08-28:0":{"b": ["Mehmed Ali passou pessoalmente ao Hejaz", "fda0ea2d"], "d": ["Vendo que a campanha se arrastava, o governador tomou diretamente a administração nas mãos; negociando com os chefes tribais, procurou dissolver a frente saudita a partir do interior. A parte do Egito no comércio do mar Vermelho cresceu também com esta campanha.", "aeb051d1"]},
"OLAYLAR_EK4:1815-01-20:0":{"b": ["Batalha de Bisel: forças sauditas desbaratadas", "9c9ab91f"], "d": ["Os sauditas, que sofreram uma pesada derrota em batalha campal, retiraram-se para o interior. O armistício feito não foi duradouro; dois anos depois a operação seria levada para o coração de Najd.", "4a8ae0e2"]},
"OLAYLAR_EK4:1816-09-01:0":{"b": ["İbrâhim Paşa partiu em campanha para Najd", "d5ed80d1"], "d": ["İbrâhim Paşa, que assumiu o comando com a morte do seu irmão Tosun, empreendeu no deserto uma pesada marcha de dois anos. O exército, avançando de poço em poço e eliminando uma a uma as tribos, chegou à capital saudita.", "e84c2cef"]},
"OLAYLAR_EK4:1818-09-09:0":{"b": ["Cai Diriyah — fim do primeiro Estado saudita", "aa96206d"], "d": ["Após um cerco de seis meses, Diriyah rendeu-se e foi arrasada. O emir Abdullah b. Suud foi enviado a Istambul e executado. A bandeira otomana chegava pela primeira vez tão fundo ao interior da Arábia; a guarnição de Najd permaneceu até 1824. Outros lugares incorporados na mesma data: Dir'iye (Necid).", "4b161cf5"]},
"OLAYLAR_EK4:1820-07-20:0":{"b": ["Começou a campanha do Sudão", "b1fc6905"], "d": ["O objetivo de Mehmed Ali era triplo: recrutar soldados para o seu exército, chegar ao ouro de Sennar e destruir os restos dos mamelucos em fuga. A força sob o comando do seu filho İsmâil Paşa desceu para sul seguindo o Nilo.", "478563e9"]},
"OLAYLAR_EK4:1821-01-04:0":{"b": ["Dongola tomada — dispersos os restos dos mamelucos", "ba6bc24b"], "d": ["O exército, que entrou em Dongola, na grande curva do Nilo, liquidou o último grupo mameluco que ali se refugiara. No mapa, o Sudão aparece, a partir desta data, no estrato vassalo: quem o conquistou é o Cairo, e quem o governará será também o Cairo.", "bca7d521"]},
"OLAYLAR_EK4:1821-06-14:0":{"b": ["O Sultanato de Sennar (Funj) rendeu-se", "3cac7dd2"], "d": ["A dinastia Funj, de três séculos, rendeu-se sem combate. No mesmo ano, o acampamento estabelecido no ponto de confluência dos dois braços do Nilo transformou-se rapidamente em Cartum, centro administrativo do Sudão. Outros lugares incorporados na mesma data: Sennar.", "1ad105c1"]},
"OLAYLAR_EK4:1821-08-19:0":{"b": ["Kordofan capturado", "06440602"], "d": ["A segunda coluna enviada para ocidente derrotou em Bâre as forças de Darfur e tomou Kordofan. O domínio egípcio sobre o Sudão estendeu-se assim do vale do Nilo às estepes ocidentais.", "e18d449a"]},
"OLAYLAR_EK4:1822-06-28:0":{"b": ["Forças egípcias desembarcaram em Creta", "835aee90"], "d": ["Quando a revolta grega alastrou a Creta, a Sublime Porta pediu que fosse enviada uma força egípcia à ilha. A influência de Mehmed Ali na ilha começou com esta intervenção e resultou, oito anos depois, na concessão do governo de Creta.", "8d651366"]},
"OLAYLAR_EK4:1822-10-24:0":{"b": ["Morte de İsmâil Paşa em Shendi", "223860c9"], "d": ["O emir local Nemir, irado com as pesadas exigências de impostos e soldados, incendiou a casa em que estava alojado e queimou İsmâil Paşa e a sua comitiva. A expedição de represália transformou a região num lago de sangue; a administração do Sudão assentou daí em diante na dureza.", "722af711"]},
"OLAYLAR_EK4:1824-07-19:0":{"b": ["Mahmud II pediu ajuda a Mehmed Ali para a Moreia", "03594a42"], "d": ["Para a revolta da Moreia, que o exército dos janízaros não conseguira reprimir em três anos, o sultão recorreu ao exército egípcio instruído à europeia. Em troca prometeram-se-lhe o governo da Moreia e Creta. Este pedido foi a primeira confissão aberta de que o império passara a precisar da própria província.", "1b0ee342"]},
"OLAYLAR_EK4:1825-02-24:0":{"b": ["İbrâhim Paşa desembarcou em Modon", "9c993dba"], "d": ["A força de desembarque, protegida pela armada egípcia, pôs pé na extremidade sudoeste da Moreia. Este exército, equipado com infantaria nizamî e artilharia de campanha, obteve rapidamente superioridade sobre os bandos rebeldes.", "edf38fca"]},
"OLAYLAR_EK4:1825-06-22:0":{"b": ["Tripolitsa recuperada — caiu o centro da Moreia", "8a478c11"], "d": ["Com a queda de Tripolitsa, centro administrativo da revolta, a maior parte da Moreia voltou ao controlo. No mapa, a península aparece em tom vassalo por estar nas mãos das forças egípcias.", "e7d9b818"]},
"OLAYLAR_EK4:1826-04-22:0":{"b": ["Caiu Missolonghi (Mesolongi)", "07257f87"], "d": ["A cidade foi tomada após um cerco de um ano. Contudo, o eco que a defesa criou na imprensa europeia levou ao auge a simpatia pela causa grega e preparou o terreno para a intervenção das grandes potências.", "9bf1efc2"]},
"OLAYLAR_EK4:1827-06-05:0":{"b": ["Acrópole de Atenas tomada", "3b19f946"], "d": ["Com a queda da Acrópole, a revolta grega estava quase terminada em termos militares. Precisamente neste ponto, a questão deixou de ser uma revolta interna e passou a ser matéria da diplomacia europeia.", "e096fc52"]},
"OLAYLAR_EK4:1827-07-06:0":{"b": ["Tratado de Londres: três potências impuseram a autonomia grega", "7ce46fd8"], "d": ["A Inglaterra, a França e a Rússia decidiram agir em conjunto para fazer aceitar entre os otomanos e os gregos o armistício e a condição de autonomia; foi declarado que, em caso de recusa, as suas armadas interviriam. A Sublime Porta rejeitou a proposta.", "8382f516"]},
"OLAYLAR_EK4:1828-08-06:0":{"b": ["Convenção de Alexandria: decisão de retirada do Egito da Moreia", "cc978f37"], "d": ["Mehmed Ali, que perdera a armada em Navarino, entendendo-se diretamente com o almirante inglês sem consultar Istambul, aceitou retirar as suas forças da Moreia. O facto de um governador concluir um acordo independente com as grandes potências foi presságio da crise futura.", "9430ea24"]},
"OLAYLAR_EK4:1828-10-05:0":{"b": ["Forças egípcias evacuaram a Moreia", "8fb742dd"], "d": ["As últimas unidades foram embarcadas; a península perdeu-se de facto e, com o Protocolo de Londres de 1830, tornou-se o núcleo da Grécia independente. Mehmed Ali não obtivera o governo da Moreia que lhe fora prometido e perdera em troca uma grande armada e um grande exército. Outros povoamentos perdidos na mesma data: Modon, Koron.", "7bfbefe0"]},
"OLAYLAR_EK4:1830-11-01:0":{"b": ["Administração de Creta deixada a Mehmed Ali", "7f76396d"], "d": ["Como compensação pela perda da Moreia, foi dado a Mehmed Ali o governo de Creta. A ilha foi administrada a partir do Cairo durante dez anos; no mapa, aparece em tom vassalo durante esse período. Outros lugares incorporados na mesma data: Kandiye (Girit).", "5b000d2b"]},
"OLAYLAR_EK4:1831-10-31:0":{"b": ["İbrâhim Paşa entrou na Síria — começou a primeira crise", "1a5cc386"], "d": ["O pretexto foi o governador de Acre, que não devolvia os felás fugidos do Egito; a verdadeira causa era a necessidade que Mehmed Ali tinha da madeira, dos portos e dos recursos humanos da Síria. O exército atravessou o Sinai e tomou rapidamente a costa da Palestina.", "9d41b0f9"]},
"OLAYLAR_EK4:1831-11-26:0":{"b": ["Começou o cerco de Acre", "b211d96d"], "d": ["A fortaleza que detivera Napoleão em 1799 resistiu durante seis meses. O cerco foi a primeira grande prova da artilharia moderna do exército egípcio.", "97d9816b"]},
"OLAYLAR_EK4:1832-05-27:0":{"b": ["Acre caiu", "0f47917b"], "d": ["A fortaleza foi tomada quando as baterias que batiam as muralhas abriram brecha. A porta da Síria estava aberta; a Sublime Porta, nesses mesmos dias, declarou Mehmed Ali rebelde e aboliu o seu governo.", "f92b4224"]},
"OLAYLAR_EK4:1832-06-16:0":{"b": ["Damasco rendeu-se", "48da3b62"], "d": ["A cidade rendeu-se sem combate. İbrâhim Paşa procurou ganhar o apoio local proclamando a ordem fiscal e a igualdade concedida aos não muçulmanos; as mesmas políticas seriam, poucos anos depois, a causa de revoltas contra ele. Outros lugares incorporados nos mesmos dias: Beyrut, Trablusşam, Sayda.", "c67bd97e"]},
"OLAYLAR_EK4:1832-07-08:0":{"b": ["Batalha de Homs", "867810ee"], "d": ["O exército otomano enviado para salvar a Síria foi desbaratado em campo aberto. Viu-se que o novo exército, criado seis anos depois da abolição dos janízaros, ainda não estava pronto.", "f429ba2e"]},
"OLAYLAR_EK4:1832-07-15:0":{"b": ["Alepo capturada", "9c0ead76"], "d": ["Caiu também o centro comercial e administrativo da Síria setentrional. O exército egípcio chegou assim ao sopé do Tauro e orientou-se para as passagens que abrem a Anatólia.", "b8b4a1bd"]},
"OLAYLAR_EK4:1832-07-29:0":{"b": ["Desastre da Passagem de Belen (Beylan) — aberta Çukurova", "4bae872b"], "d": ["A linha de defesa foi rompida no estreito desfiladeiro dos montes Amanos. Antioquia, Adana e Tarso passaram às forças egípcias (a ocupação de Maraş, segundo o TDV, é de 1833, item separado); no mapa, Çukurova regressa ao tom vassalo. O caminho para o interior da Anatólia ficou indefeso.", "73cb1c5e"]},
"OLAYLAR_EK4:1832-09-13:0":{"b": ["Caiu a Garganta de Gülek — costa de İçil (Mersin, Silifke) passa ao controlo egípcio", "d9049b5b"], "d": ["A Garganta de Gülek, porta de Çukurova no Tauro, passou para as mãos do exército egípcio. İbrâhim Paşa nomeou o seu próprio mütesellim para o Sanjaco de İçil e todos os cais da costa passaram ao controlo egípcio. No mapa, Mersin e Silifke aparecem ligadas ao Egito a partir deste dia (limite inferior; o dia da nomeação não consta da fonte); como na decisão de Kütahya só passou a muhassıllık de Adana, este controlo termina com a evacuação da Anatólia.", "fa650158"]},
"OLAYLAR_EK4:1832-09-13:1":{"b": ["Konya Ereğlisi sob ocupação egípcia — entrada do Tauro na rota Konya–Adana", "fb908900"], "d": ["Ereğli, na rota para Konya do exército egípcio que transpôs a Garganta de Gülek, entrou em 1832 sob ocupação de İbrâhim Paşa e, evacuada com o ordenamento de Kütahya de 1833, foi de novo ligada à província de Karaman. No mapa, é o ponto intermédio com fonte da linha de ocupação entre Adana e Konya; para Ulukışla e Karapınar não se encontrou testemunho ao nível da cidade.", "c5c7c153"]},
"OLAYLAR_EK4:1832-11-21:0":{"b": ["O exército egípcio entrou em Konya", "13952a2d"], "d": ["O exército, que transpôs o Tauro, chegou à Anatólia central. As forças de um governador otomano avançavam pela primeira vez no território central do império. Outros lugares incorporados na mesma data: Karaman.", "569bd202"]},
"OLAYLAR_EK4:1832-12-21:0":{"b": ["Batalha de Konya: grão-vizir feito prisioneiro", "ec82cc9a"], "d": ["O exército otomano, dispersado pelo nevoeiro, sofreu uma pesada derrota e o grão-vizir Reşid Mehmed Paşa foi feito prisioneiro. O exército central do Estado já não existia; não restava nenhuma força que se interpusesse entre Istambul e as forças egípcias.", "30e73138"]},
"OLAYLAR_EK4:1833-01-01:0":{"b": ["Maraş sofreu ocupação egípcia", "f558e383"], "d": ["Segundo o TDV, Maraş sofreu em 1833 a ocupação de İbrâhim Paşa de Kavala e permaneceu quase dezanove meses sob a sua administração. Como Maraş ficou fora dos limites provinciais do ordenamento de Kütahya, esta administração não é jurídica, mas de facto.", "3d3c898a"]},
"OLAYLAR_EK4:1833-01-01:1":{"b": ["Karahisâr-ı Sâhib (Afyon) sofreu ocupação egípcia — rota Konya–Kütahya", "ae0c2c78"], "d": ["Karahisâr-ı Sâhib, na rota do exército egípcio que avançava para Kütahya depois da batalha de Konya, permaneceu em 1833 algum tempo em mãos de İbrâhim Paşa. No mapa, é o ponto intermédio com fonte da linha de ocupação entre Konya e Kütahya; para Akşehir, Ilgın e İshaklı não se encontrou testemunho ao nível da cidade, e elas estão na cor otomana.", "bce0b466"]},
"OLAYLAR_EK4:1833-02-02:0":{"b": ["O exército egípcio chegou a Kütahya", "214f8df6"], "d": ["İbrâhim Paşa parou em Kütahya, a três etapas de Istambul. O facto de não ter avançado foi não militar, mas político: a intervenção russa e a reação da Europa tinham sido tomadas em conta.", "0f1c5f03"]},
"OLAYLAR_EK4:1833-02-20:0":{"b": ["Armada russa diante de Büyükdere", "6f836d61"], "d": ["Mahmud II, que não obteve auxílio da Inglaterra e da França, recorreu à Rússia, inimiga da véspera. Esta decisão, recordada pelo dito do sultão \"quem cai ao mar agarra-se à serpente\", resultou na chegada dos soldados russos aos estreitos e fez soar os alarmes na Europa.", "3e402e00"]},
"OLAYLAR_EK4:1833-05-06:0":{"b": ["Convenção de Kütahya — Síria e Adana para o de Kavala", "c16c5a94"], "d": ["A Sublime Porta deixou a Mehmed Ali, além do Egito, Creta e Hejaz, os governos de Damasco, Alepo, Trípoli da Síria e Sayda, e a İbrâhim Paşa a muhassıllık de Adana. Em contrapartida, o exército retirou-se para sul do Tauro. Não foi um tratado, mas sob a forma de firmões dados pelo sultão a um governador — a questão não ficou resolvida, foi adiada.", "4160e4f4"]}
});
